; =============== S U B	R O U T	I N E =======================================

; изменение углов поворота и скорости для печати на экране

CalcAngSpeed4Prn:			; CODE XREF: GameMain+6p
		ld	hl,  AngleLeftRight+1 ;	угол поворота
					; 7,n знак (лево/право)
					; #0000..#0FFF
		ld	a, (hl)
		ld	(HighAngleLR), a ; старший байт	угла поворота
					; 7,n знак (лево/право)
					; #00..#0F
		bit	7, a
		jr	nz, loc_708E
		add	a, 15h
		jr	loc_7094
; ---------------------------------------------------------------------------

loc_708E:				; CODE XREF: CalcAngSpeed4Prn+9j
		and	7Fh ; ''
		ld	c, a
		ld	a, 15h
		sub	c

loc_7094:				; CODE XREF: CalcAngSpeed4Prn+Dj
		ld	(RotateLR), a	;   +0 - текущее значение
					;   -1 - отображенное на экране
		inc	hl
		inc	hl
		ld	a, (hl)
		ld	(HighAngleDU), a ; старший байт	угла поворота
					; 7,n знак (верх/вниз)
					; #00..#0F
		bit	7, a
		jr	nz, loc_70A5
		add	a, 15h
		jr	loc_70AB
; ---------------------------------------------------------------------------

loc_70A5:				; CODE XREF: CalcAngSpeed4Prn+20j
		and	7Fh ; ''
		ld	c, a
		ld	a, 15h
		sub	c

loc_70AB:				; CODE XREF: CalcAngSpeed4Prn+24j
		ld	(RotateDU), a	;   +0 - текущее значение
					;   -1 - отображенное на экране
		inc	hl
		inc	hl
		ld	a, (hl)
		ld	(HighDeltaSpeed), a ; старший байт скорости
					; #00..#1F
		ld	b, a
		add	a, a
		add	a, a
		add	a, b
		add	a, 5
		ld	(Speed), a	;   +0 - текущее значение
					;   -1 - отображенное на экране
		ret
; End of function CalcAngSpeed4Prn


; =============== S U B	R O U T	I N E =======================================


GoDocking:				; CODE XREF: GameMain+3Fp
		ld	a, (byte_7C39)	; =#01 нажата G	или H (прыжок)
		and	a
		ret	nz
		ld	a, (ManualDocking) ; =0	при вылете с планеты
					; <>0 начата ручная стыковка????
		and	a
		jr	z, loc_70CF	; обработка стыковочного компьютера
		xor	a
		ld	(ManualDocking), a ; =0	при вылете с планеты
					; <>0 начата ручная стыковка????
		jr	loc_70FB
; ---------------------------------------------------------------------------

loc_70CF:				; CODE XREF: GoDocking+9j
		ld	a, (ControlKey3) ; обработка стыковочного компьютера
		ld	b, a
		and	80h ; 'А'
		res	7, b
		ld	a, b
		ld	(ControlKey3), a ; 7,=1	- C	-- Docking Computer
					; 6,=1 - Q     -- Escape Pod
					; 5,=1 - W     -- Energy Bomb
					; 4,=1 - E     -- ECM System
					; 3,=1 - U     -- UnTarget
					; 2,=1 - F     -- Fire Missile
					; 1,=1 - T     -- Target Missile
					; 0,=1 - A     -- Fure Laser
		ret	z
