ControlKeyIfMapOn:			; CODE XREF: GameMain+24p GameMain+6Dp
		ld	a, (WhatOnScreen) ; Что	изображено на экране
					;  =0..3 в полете номер	обзорного экрана (front, rear, left, right)
					;  =#04	меню покупки товаров
					;  =#05	меню продажи товаров
					;  =#06	меню покупки оборудования
					;  =#07	глобальная карта
					;  =#08	локальная карта
					;  =#09	инфо о планете еще не выведено
					;  =#0A	прайс планеты
					;  =#0B	инфо о пилоте
					;  =#0C	Инвентрь
					;  =#20	инфо о планете
		cp	7
		ret	c
		cp	9
		ret	nc
		ld	a, (JumpDocking) ; =1 межпланетный прыжок/стыковка
					; =2 межгалактический прыжок
		and	a
		ret	nz
		ld	a, (ControlKeyMove) ; 7,=1 -	     --	не используется
					; 6,=1 -	 -- не используется
					; 5,=1 - SymbolS -- Decrease Speed
					; 4,=1 - Space	 -- Increase Speed
					; 3,=1 - S	 -- Up
					; 2,=1 - X	 -- Down
					; 1,=1 - M	 -- Right
					; 0,=1 - N	 -- Left
		and	0Fh
		ld	c, a
		ld	a, (ControlKeyInMap) ; 7,	    -- не используется
					; 6,=1 - R     -- Find Planet
					; 5,=1 - D     -- Cursor to Near Planet
					; 4,=1 - B     -- Cursor to Present System
					; 3-0,	       -- не используется
		and	70h ; 'p'
		or	c
		ret	z
		ld	b, 8

loc_7158:				; CODE XREF: ControlKeyIfMapOn+20j
		inc	b
		srl	a
		jr	nc, loc_7158
		ld	a, b
		call	Call_Function	; Вызов	функции	по номеру из любой страницы с возвратом	в эту страницу
					; Вх:  a - номер функции в кернале
					; Вых: в зависимости от	функции
		xor	a
		ld	(ControlKeyInMap), a ; 7,	    -- не используется
					; 6,=1 - R     -- Find Planet
					; 5,=1 - D     -- Cursor to Near Planet
					; 4,=1 - B     -- Cursor to Present System
					; 3-0,	       -- не используется
		ld	(ControlKeyMove), a ; 7,=1 -	     --	не используется
					; 6,=1 -	 -- не используется
					; 5,=1 - SymbolS -- Decrease Speed
					; 4,=1 - Space	 -- Increase Speed
					; 3,=1 - S	 -- Up
					; 2,=1 - X	 -- Down
					; 1,=1 - M	 -- Right
					; 0,=1 - N	 -- Left
		ret
; End of function ControlKeyIfMapOn


