PrnSunPlanet:				; CODE XREF: GameMain+80p
					; LaunchDocking+FAp
		xor	a
		ld	(TypeOfPrint), a ; коррекция п/п печати	в зависимости от расстояния до солнца
					;  =#00	or c
					; <>#00	xor c
		ld	hl, SunCrd	; данные для печати солнца длина 9 байт
					; crd low x planet
		ld	de, CircleCrdXlow ; расстояние до солнца/планеты по оси	X
					;   high 7,=1 отрицательное значение
		ld	bc, 9
		ldir
		call	CalcPrnCrdSun	; Расчёт экранных координат проекции солнца/планеты
					; Вх:  (CircleCrdXlow) 9 байт описателя	планеты/солнца
					; Вых: a =0 печать невозможна
					;      a =1 печать возможна, переменные	установлены
		push	af
		call	CorrData4Nova	; коррекция данных, если выдана	1я миссия
		pop	af
		and	a
		jr	z, loc_74E7
		call	PrnCircle_Fill	; Печать окружности на экране/в	буфере
					; Вх:  (CircleFlg) - флаги
					;      (CircleRadius) -	радиус
					;      (CircleCrdY)  - координаты центра
