					;		    =1 рисовать	круг без заливки
					; Вых: окружность напечатана
		ld	a, (CircleRadius) ; радиус окружности
		cp	28h ; '('
		jr	c, loc_74E7
		ld	a, 1
		ld	(TypeOfPrint), a ; коррекция п/п печати	в зависимости от расстояния до солнца
					;  =#00	or c
