; =============== S U B	R O U T	I N E =======================================

; коррекция данных, если выдана	1я миссия

CorrData4Nova:				; CODE XREF: GameMain:loc_72EBp
					; PrnSunPlanet+13p
		ld	a, (PilotMission1_1) ; =1 - выдана(взята) 1я миссия
		and	a
		ret	z
		ld	a, (SunRadiusNova) ; радиус солнца при взрыве сверхновой (1я миссия)
		and	a
		jr	nz, loc_7508
		ld	a, (CircleRadius) ; радиус окружности

loc_7508:				; CODE XREF: CorrData4Nova+9j
		ld	hl, Temperature	;   +0 - текущее значение
					;   -1 - отображенное на экране
		inc	(hl)
		add	a, 2
		jr	z, loc_7512
		jr	nc, loc_7518

loc_7512:				; CODE XREF: CorrData4Nova+14j
