					;  =0..3 в полете номер	обзорного экрана (front, rear, left, right)
					;  =#04	меню покупки товаров
					;  =#05	меню продажи товаров
					;  =#06	меню покупки оборудования
					;  =#07	глобальная карта
					;  =#08	локальная карта
					;  =#09	инфо о планете еще не выведено
					;  =#0A	прайс планеты
					;  =#0B	инфо о пилоте
					;  =#0C	Инвентрь
					;  =#20	инфо о планете
		and	a
		jp	nz, loc_75D3	; не front
		ld	a, (CircleCrdZhigh) ; front view
		bit	7, a
		jp	nz, loc_7766
		and	7Fh ; ''
		ld	(CircleCrdZhigh), a
		ld	hl, (CircleCrdZmed)
		ex	de, hl
		ld	hl, (CircleCrdXmed)
		ld	a, (CircleCrdZlow) ; расстояние	до солнца/планеты по оси Z
					;   high 7,=1 отрицательное значение
