		ld	a, (CircleCrdXlow) ; расстояние	до солнца/планеты по оси X
					;   high 7,=1 отрицательное значение
		ld	c, a
		ld	a, h
		bit	7, a
		jr	nz, loc_7550
		exx
		set	0, b		; центр	в правой половине
		exx

