; Изменение координат солнца и планеты при перемещении игрока

CalcCrdSunPlanet:			; CODE XREF: GameMain+45p
					; LaunchDocking+F1p
		ld	ix, SunCrd	; данные для печати солнца длина 9 байт
					; crd low x planet
		call	CalcNewCrdObj_Pl ; Изменение координат объекта от перемещения игрока
					; вх:  ix - адрес начала слота объекта
					; вых: hl.a - crd Z
		ld	ix, PlanetCrd	; Координаты планеты в пространстве
		jp	CalcNewCrdObj_Pl ; Изменение координат объекта от перемещения игрока
; End of function CalcCrdSunPlanet	; вх:  ix - адрес начала слота объекта
					; вых: hl.a - crd Z

