		jr	nz, loc_77B0	; изменяем координаты coriolis от передвижения игрока
		ld	a, (ix+22h)
		and	a
		ret	nz
		dec	a
		ld	(J_Drive_Coriolis), a ;	=#FF J-	можно использовать

loc_77B0:				; CODE XREF: CalcCrdCoriolis+8j
		call	ReCalcCrdObj	; изменяем координаты coriolis от передвижения игрока
		ld	a, (ix+2)
		and	7Fh ; ''
		ret	nz
		ld	a, (ix+5)
		and	7Fh ; ''
		ret	nz
		ld	a, (ix+8)
		and	7Fh ; ''
		ret	nz
