byte_77D4:	db 1			; DATA XREF: Use_Y_Cloackingo
					; Use_Y_Cloacking+Cw

; =============== S U B	R O U T	I N E =======================================

; Использование	Cloacking Device

Use_Y_Cloacking:			; CODE XREF: GameMain+9Ep
		ld	hl, byte_77D4
		dec	(hl)
		ld	hl, ControlKey1	; 7,=1 - Y	 -- Cloaking Device
					; 6,=1 - 0	 -- ???
					; 5,=1 - I	 -- Global Map
					; 4,=1 - O	 -- Local Map
					; 3,=1 - P	 -- Planet Info
					; 2,=1 - K	 -- Planet Price
					; 1,=1 - L	 -- Commander Info
					; 0,=1 - Enter	 -- Inventory
		res	7, (hl)
		ret	nz
		ld	a, 2
		ld	(byte_77D4), a
		halt
		bit	7, (hl)
		ret	z		; если клавиша еще нажата продолжить
		ld	hl, PilotExtWeapon ; +93 наличие доп вооружения
					;   7,=1 - ECM Jammer
					;   6,=1 - Cloaking device
					;   5,=1 - нельзя купить товары(в трюме	беженцы)
					;   4
					;   3 =1 3я миссия была	выполнена
					;   2 =1 - третья миссия выполнена
					;   1 =1 - второя миссия выполнена
					;   0 =1 - первая миссия выполнена
		bit	6, (hl)
		ret	z
		ld	hl, CloakingDeviceOn ;	=1 включен Cloaking Device
					;  =1 расход энергии при использовании
		dec	(hl)
		jr	z, loc_780A	; paper	0, ink 7
		ld	a, (ShieldUnit3) ; проверка энергии
		cp	28h ; '('
		ret	c
		ld	a, 1		; энергии мало
		ld	(hl), a
		ld	hl, byte_6069	;  2,=1	кориолис агрессивна
		res	2, (hl)
		xor	a
		ld	(PlayerPirate),	a ; =1 игрок атаковал мирного торговца/станцию/полицию.	включаем агрессию
					;
					;
					; =0 станция не	агрессивна
					; =0 мало энергии выключаем шапку невидимку
					; =0 шапка невидимка выключена
					; =1, если 6-7,(ix+#21)<>00
					; =1 рядом аггресивны объект

loc_7806:				; CODE XREF: Use_Y_Cloacking+47j
		ld	l, 1111b	; paper	1, ink 7
		jr	loc_780C
; ---------------------------------------------------------------------------

loc_780A:				; CODE XREF: Use_Y_Cloacking+1Dj
		ld	l, 111b		; paper	0, ink 7

loc_780C:				; CODE XREF: Use_Y_Cloacking+33j
					; Use_Y_Cloacking+40j
		jp	SetAtrViewScr	; печать атрибутов обзорного экрана
					; вх:  l - атрибут
					; вых: b=#00
					;      a=#00
					;      hl - ????
; ---------------------------------------------------------------------------
		ld	a, (PilotMission1) ; байт первой миссии
					;  =0 миссия не	выдана
					; <>0 1я миссия	выдана
		and	a

loc_7813:				; CODE XREF: SetViewScrAtr+Aj
		ld	l, 2		; paper	0, ink 2 обзорного экрана
		jr	nz, loc_780C
		ret
; ---------------------------------------------------------------------------
		ld	a, (CloakingDeviceOn) ;	 =1 включен Cloaking Device
					;  =1 расход энергии при использовании
		and	a
		jr	nz, loc_7806	; paper	1, ink 7
		ret
; End of function Use_Y_Cloacking


; =============== S U B	R O U T	I N E =======================================

; установка атрибутов обзорного	экрана с учётом	выдачи 1й миссии и включения
;   CloackingDevice

SetViewScrAtr:				; CODE XREF: LaunchDocking+90p
		ld	a, (PilotMission1) ; байт первой миссии
					;  =0 миссия не	выдана
					; <>0 1я миссия	выдана
		and	a
		ret	z
		ld	a, 1
		ld	(PilotMission1_1), a ; =1 - выдана(взята) 1я миссия
		jr	loc_7813	; paper	0, ink 2 обзорного экрана
; End of function SetViewScrAtr


; =============== S U B	R O U T	I N E =======================================

; Выдача/завершение 3й миссии, если доступно

GoMission3:				; CODE XREF: LaunchDocking+65p
		ld	a, (PilotMission3) ; +92 >0 - выдана 3я	миссия
					;  =1 при стыковке будет выдана	3я миссиия ( =1	пора выдавать миссию будет =2 после прыжка)
					;  =2 при стыковке будет выдана	3я миссиия
					;  =3 выдана 3я	миссия (можно уничтожить станцию ракетой) (из станции вылетают таргоны)
					;  =4 выдана 3я	миссия,	корабль	находится в системе с целью (можно уничтожить станцию ракетой) (из станции вылетают таргоны)
					;  =5 3я миссия	выполнена, будет поздравление при стыковке
					;
					;
					;  =4 корабль захватили	пираты,	(сообщить при стыковке)	будет =3 после прыжка
					; 3,=1 станция уничтожена
		dec	a
		jr	z, loc_7832
		dec	a

loc_7832:				; CODE XREF: GoMission3+4j
		jp	z, GiveMission3	; Предложение 3й миссии
		sub	3
		jp	z, EndMission3	; Успешное завершение 3й миссии
		inc	a
		ld	a, 0D4h	; '╘'
		jr	z, loc_7848
		ret
; End of function GoMission3


; =============== S U B	R O U T	I N E =======================================

; захват корабля пиратами, если	нужно

