		xor	a
		ld	(WhatOnScreen),	a ; Что	изображено на экране
					;  =0..3 в полете номер	обзорного экрана (front, rear, left, right)
					;  =#04	меню покупки товаров
					;  =#05	меню продажи товаров
					;  =#06	меню покупки оборудования
					;  =#07	глобальная карта
					;  =#08	локальная карта
					;  =#09	инфо о планете еще не выведено
					;  =#0A	прайс планеты
					;  =#0B	инфо о пилоте
					;  =#0C	Инвентрь
					;  =#20	инфо о планете
		call	PrnCocpit_Ifn	; при необходимости печать рамки и панели
		ld	sp, (SaveSP2)
		jp	loc_718F	; NewGame
; End of function GoPirates


