					; sub_8E95+3Cp
		ld	a, (InFreeSpace) ; <>0 между системами (перехват F)
		and	a
		ret	nz
		ld	hl, byte_7AF0
		ld	(loc_7A06+1), hl
		ld	a, 8
		ld	(NumOfCircle), a ; кол-во концентрических кругов
		ld	a, 30h ; '0'
		ld	(loc_7A32+1), a
		ld	a, 40h ; '@'
		ld	(byte_7ADF), a
		ld	hl, 101h
		ld	(JumpDocking), hl ; =1 межпланетный прыжок/стыковка
					; =2 межгалактический прыжок
		ld	a, (IndDanger)	; <>0 в	полете (он же цвет индикатора опасности)
					; =0 пристыкован
					; =#04=%00 000 100 вылет со станции, в полёте (зелёный)
					; =#63=%01 100 011 4й энергоблок не полный (мигающий красный))
					; =#02=%00 000 010 один	из щитов front/rear пустой (красный)
					; =#06=%00 000 110 что-то рядом	(желтый)
		and	a
		jr	z, BeginLaunch	; Вылет	с планеты

BeginDocking:				; стыковка со станцией
		ld	a, 38h ; '8'
		ld	(loc_7A37+1), a	; jr c,7A4E для	прыжка
					; jr c,7A71 для	стыковки
					; jr c,7A6b для	взлёта
		ld	a, 0Ch
		ld	(HighDeltaSpeed), a ; старший байт скорости
					; #00..#1F
		xor	a
		ld	(HighAngleDU), a ; старший байт	угла поворота
					; 7,n знак (верх/вниз)
					; #00..#0F
		ld	(HighAngleLR), a ; старший байт	угла поворота
					; 7,n знак (лево/право)
					; #00..#0F
		ld	(TimeWorkECM), a ; оставшееся время работы системы
					; =0 ECM выключена
					;
		inc	a
		ld	(BlockControl),	a ; =0 после вылета со станции
					; =1 при стыковке
		ld	hl, PilotECMSystem ; ECM System
					; 7,=1 система включена
		res	7, (hl)
		call	ClearScrBuffer	; Быстрая очистка экранного буфера
		call	PrnDockingTonnel ; Визуализация	стыковки/взлёта	(прямоугольник 2x1/2x0.75)
					; Вх:  (JumpDocking) =1
					;      (FlgJumpDocking)	= #01 взлет/стыковка
					; Вых: hl,de,bc,a - не определены
		ld	b, 2Fh ; '/'

loc_7B43:				; CODE XREF: LaunchDocking+56j
		push	bc
		call	ClearScrBuffer	; Быстрая очистка экранного буфера
