					; Вых: hl,de,bc,a - не определены
		call	CopyBuf2Screen	; копирование буфера на	экран
		pop	bc
		djnz	loc_7B43
		call	FX_Launch	; звук
		xor	a
		ld	(IndDanger), a	; <>0 в	полете (он же цвет индикатора опасности)
					; =0 пристыкован
					; =#04=%00 000 100 вылет со станции, в полёте (зелёный)
					; =#63=%01 100 011 4й энергоблок не полный (мигающий красный))
					; =#02=%00 000 010 один	из щитов front/rear пустой (красный)
					; =#06=%00 000 110 что-то рядом	(желтый)
		call	SaveCocpitInBuffer ; Сохранение	кокпита
