					;
		call	GoMission3	; Выдача/завершение 3й миссии, если доступно
		call	GoPirates	; захват корабля пиратами, если	нужно
		ld	a, 7		; L - pilot Info
		jp	Call_Function	; Вызов	функции	по номеру из любой страницы с возвратом	в эту страницу
					; Вх:  a - номер функции в кернале
					; Вых: в зависимости от	функции
; ---------------------------------------------------------------------------

BeginLaunch:				; CODE XREF: LaunchDocking+24j
		ld	a, 4		; Вылет	с планеты
		ld	(IndDanger), a	; <>0 в	полете (он же цвет индикатора опасности)
					; =0 пристыкован
					; =#04=%00 000 100 вылет со станции, в полёте (зелёный)
					; =#63=%01 100 011 4й энергоблок не полный (мигающий красный))
					; =#02=%00 000 010 один	из щитов front/rear пустой (красный)
					; =#06=%00 000 110 что-то рядом	(желтый)
		call	FX_Launch	; звук
		xor	a
		ld	(ManualDocking), a ; =0	при вылете с планеты
					; <>0 начата ручная стыковка????
		ld	(WhatOnScreen),	a ; Что	изображено на экране
					;  =0..3 в полете номер	обзорного экрана (front, rear, left, right)
					;  =#04	меню покупки товаров
					;  =#05	меню продажи товаров
					;  =#06	меню покупки оборудования
					;  =#07	глобальная карта
					;  =#08	локальная карта
					;  =#09	инфо о планете еще не выведено
					;  =#0A	прайс планеты
					;  =#0B	инфо о пилоте
					;  =#0C	Инвентрь
					;  =#20	инфо о планете
		ld	(J_Drive_Coriolis), a ;	=0 при вылете с	планеты
		ld	(CloakingDeviceOn), a ;	 =1 включен Cloaking Device
					;  =1 расход энергии при использовании
		ld	a, 32h ; '2'    ; jr 7a6b
		ld	(loc_7A37+1), a	; jr c,7A4E для	прыжка
					; jr c,7A71 для	стыковки
