		call	PrnCocpit_Ifn	; при необходимости печать рамки и панели
		call	InitVarLaunch	; Печать ракет,	инициализация переменных, печать атрибутов кокпита с учётом
					; наличия Escape Pod
		call	SetViewScrAtr	; установка атрибутов обзорного	экрана с учётом	выдачи 1й миссии и включения
					;   CloackingDevice
		ld	hl, PlanetCrd	; установка координат планеты
					; crd x	=0
					; crd y	=0
					; crd z	= 0180.00
		ld	b, 7
		call	ClearMemory	; Зануление области памяти
					;  hl -	адрес
					;  b - длина
		ld	(hl), 80h ; 'А'
		inc	hl
		ld	(hl), 1
		ld	a, (SunCrdZ_hi)	; crd high Z sun
		xor	80h ; 'А'
		ld	(SunCrdZ_hi), a	; crd high Z sun
		ld	hl, objCoriolis	; длина	27h
		ld	b, 1Bh
		call	ClearMemory	; Зануление области памяти
					;  hl -	адрес
					;  b - длина
		ld	ix, objCoriolis	; установка координат и	углов поворота станции
		ld	a, 0F0h	; 'Ё'
		ld	(ix+6),	a
		ld	a, 80h ; 'А'
		ld	(ix+8),	a
		dec	a
		ld	(ix+0Eh), a
		ld	(ix+12h), a
		ld	(ix+16h), a
		ld	a, 0F0h	; 'Ё'
		ld	(ix+22h), a
		call	ClearAroundObj	; Зануляем список близлежащих объектов
					; Вх:  ---
