		call	ClearScrBuffer	; Быстрая очистка экранного буфера
		call	PrnDockingTonnel ; Визуализация	стыковки/взлёта	(прямоугольник 2x1/2x0.75)
					; Вх:  (JumpDocking) =1
					;      (FlgJumpDocking)	= #01 взлет/стыковка
					; Вых: hl,de,bc,a - не определены
		ld	b, 24h ; '$'

