		ret
; End of function ClearMemory


; =============== S U B	R O U T	I N E =======================================

; Зануляем список близлежащих объектов
; Вх:  ---
; Вых: b =#00
;      a =#00
;      de =#LenSlotObj
;      ix - не определен

ClearAroundObj:				; CODE XREF: GameMain+FCp sub_79A3+8p	...
		ld	ix, objCoriolis	; длина	27h
		res	2, (ix+21h)	; станция больше не враждебна
		xor	a
		ld	(PlayerPirate),	a ; =1 игрок атаковал мирного торговца/станцию/полицию.	включаем агрессию
					;
					;
					; =0 станция не	агрессивна
					; =0 мало энергии выключаем шапку невидимку
					; =0 шапка невидимка выключена
					; =1, если 6-7,(ix+#21)<>00
					; =1 рядом аггресивны объект
		ld	de, 27h	; '''
		ld	b, 7

loc_7C25:				; CODE XREF: ClearAroundObj+16j
		add	ix, de
		ld	(ix+22h), a
		djnz	loc_7C25
		ret
; End of function ClearAroundObj


; =============== S U B	R O U T	I N E =======================================

; Восстановление данных	пилота из памяти
