RestorePilotFromMemory:			; CODE XREF: InitGame+3p sub_D3FF+17p
		ld	hl, PilotDataSaved ; для сохранения в памяти последней загруженной игры
		ld	de, PilotName	; 1..11	имя пилота
		ld	bc, 66h	; 'f'   ; 102 байта
		ldir
		ret
; End of function RestorePilotFromMemory

