					;      (DirectionPrnCircle) =0 печатать	вверх /	=1 печать вниз
					; вых: hl,de,bc,hl',de',bc',a - ????
		jp	half_rClip_Fill	; Печать полукруга с заливкой по OR (круг выходит за правую границу по X)
