; Вх:  (CircleFlg) - флаги
;      (CircleRadius) -	радиус
;      (CircleCrdY)  - координаты центра
;      (FillCircle) =0 рисовать	круг с заливкой
;		    =1 рисовать	круг без заливки
; Вых: окружность напечатана

PrnCircle_Fill:				; CODE XREF: PrnSunPlanet+1Ap
					; PrnExplodeObj+49p
		ld	a, (CircleRadius) ; радиус окружности
		cp	9
		ret	c
		di
		xor	a
		ld	(FillCircle), a	; =1 рисовать круг без заливки
					; =0 с заливкой
		jp	loc_7D09
; ---------------------------------------------------------------------------

PrnCircle_NoFill:			; CODE XREF: PrnSunPlanet+39j
					; PrintCircleMap+47p
		ld	a, (CircleRadius) ; радиус окружности
		cp	9
		ret	c

PrnCircle_NoFill_NoRadius:		; CODE XREF: sub_79A3+79p
		ld	a, 1
		ld	(FillCircle), a	; =1 рисовать круг без заливки
					; =0 с заливкой

loc_7D09:				; CODE XREF: PrnCircle_Fill+Bj
		call	PrnCircle_Clip	; Печать окружности на экране/в	буфере
					; Вх:  (CircleFlg) - флаги
					;      (CircleRadius) -	радиус
