; Возведение в квадрат
; вх  A	- число
; вых DE=A^2

Sqr_DE_A:				; CODE XREF: PrnCircle_Clip+7Bp
					; PrnCircle_Clip+81p ...
		push	hl
		ld	h, 0BEh	; '╛'
