sub_7DE8:				; CODE XREF: PrnCircle_Clip+4Ej
		call	CalcAddr_noClip	; Определение данных крайних байт и адресов печати
					; вх:  ---
					; вых: b  - левый байт для печати
					;      c  - правый байт	для печати
					;      hl - адрес печати правого байта
					;      he - адрес печати левого	байта
					;      c' - 0-радиус
					;      e' - =0
		call	half_NoClip_Up	; Печать полукруга по OR (круг не выходит за границы по	X)
					; вх:  b - левый байт для печати
					;      c - правый байт для печати
					;      hl - адрес печати правого байта
					;      he - адрес печати левого	байта
					;      e' =0
					;      c' =0-радиус
					; вых: hl,de,bc,hl',de',bc' - ????
		call	CalcAddr_noClip	; Определение данных крайних байт и адресов печати
					; вх:  ---
					; вых: b  - левый байт для печати
					;      c  - правый байт	для печати
					;      hl - адрес печати правого байта
					;      he - адрес печати левого	байта
					;      c' - 0-радиус
					;      e' - =0
		jp	half_NoClip_Down ; Печать полукруга по OR (круг	не выходит за границы по X)
; End of function sub_7DE8		; вх:  b - левый байт для печати
					;      c - правый байт для печати
					;      hl - адрес печати правого байта
					;      he - адрес печати левого	байта
					;      e' =0
					;      c' =0-радиус
					; вых: hl,de,bc,hl',de',bc' - ????

; =============== S U B	R O U T	I N E =======================================

; Определение данных крайних байт и адресов печати
; вх:  ---
; вых: b  - левый байт для печати
;      c  - правый байт	для печати
;      hl - адрес печати правого байта
;      he - адрес печати левого	байта
;      c' - 0-радиус
;      e' - =0

CalcAddr_noClip:			; CODE XREF: sub_7DE8p	sub_7DE8+6p
		ld	bc, (CircleCrdY_prn) ; Печатная	координата Y центра круга
		ld	de, (CircleFlg)	; флаги	круга
					;   0,=0 -x координата X отрицательная
					;     =1 +x координата X положительная
					;   1,=0 -y координата Y отрицательная
					;     =1 +y координата Y положительная
					;   2,=? инвертированный старший бит координаты	X
					;   3,=? инвертированный старший бит координаты	Y
		ld	a, d
		neg			; d - радиус
		exx
		ld	c, a		; c' - 0-радиус
		ld	e, 0		; e' =0
		exx
		ld	a, b
		sub	d		; a = crdX - радиус
		call	CalcLeftAddrCircle ; Определение данных	левого байта и адреса печати
					; вх:  c - crdY	(координата центра круга)
					;      a - crdX-радиус (координата левой границы круга)
					; вых: b - левый байт для печати
					;      hl - адрес печати
					;      e - младший байт	адреса печати левого байта
		ld	a, (CircleCrdY_prn) ; Печатная координата Y центра круга
		ld	c, a
		ld	a, (CircleCrdX_prn) ; Печатная координата X центра круга
		add	a, d
		jp	CalcRightAddrCircle ; Определение данных правого байта байта и адреса печати
; End of function CalcAddr_noClip	; вх:  c - crdY	(координата центра круга)
					;      a - crdX+радиус (координата правой границы круга)
					;      b - левый байт для печати
					;      e - младший байт	адреса печати левого байта
					; вых: b - левый байт для печати
					;      c - правый байт для печати
					;      hl - адрес печати правого байта
					;      he - адрес печати левого	байта

; =============== S U B	R O U T	I N E =======================================


