		call	CalcAddr_lrClip1
		call	CalcAddr_lrClip2
		ld	a, (CircleFlg)	; флаги	круга
					;   0,=0 -x координата X отрицательная
					;     =1 +x координата X положительная
					;   1,=0 -y координата Y отрицательная
					;     =1 +y координата Y положительная
					;   2,=? инвертированный старший бит координаты	X
					;   3,=? инвертированный старший бит координаты	Y
		bit	0, a
		call	z, half_lClip_Up ; Печать полукруга по OR (круг	выходит	за левую границу по X)
					; вх:  b - левый байт для печати
					;      c - правый байт для печати
					;      hl - адрес печати правого байта
					;      he - адрес печати левого	байта
					;      e' =0
					;      c' =0-радиус
					; вых: hl,de,bc,hl',de',bc' - ????
		call	nz, half_rClip_Up ; Печать полукруга по	OR (круг выходит за правую границу по X)
					; вх:  b - левый байт для печати
					;      c - правый байт для печати
					;      hl - адрес печати правого байта
					;      he - адрес печати левого	байта
					;      e' =0
					;      c' =0-радиус
					; вых: hl,de,bc,hl',de',bc' - ????
		ld	a, (CircleDeltaY) ; точка пересечения окружностью левого/правого края экрана относительно центра координат
		ld	b, a
		ld	a, (CircleCrdY_prn) ; Печатная координата Y центра круга
		call	Fill_Down	; Заливка/Холостой прогон обзорного экрана от заданной координаты Y вниз
					; вх:  b - высота окна в пикселях
					;      a - координата Y	в пикселях
					; вых: hl - адрес верхней границы окна
		call	CalcAddr_lrClip1
		call	CalcAddr_lrClip2
		ld	a, (CircleFlg)	; флаги	круга
					;   0,=0 -x координата X отрицательная
					;     =1 +x координата X положительная
					;   1,=0 -y координата Y отрицательная
					;     =1 +y координата Y положительная
					;   2,=? инвертированный старший бит координаты	X
					;   3,=? инвертированный старший бит координаты	Y
		bit	0, a
		call	z, half_lClip_Down ; Печать полукруга по OR (круг выходит за левую границу по X)
					; вх:  b - левый байт для печати
					;      c - правый байт для печати
					;      hl - адрес печати правого байта
					;      he - адрес печати левого	байта
					;      e' =0
					;      c' =0-радиус
					; вых: hl,de,bc,hl',de',bc' - ????
		call	nz, half_rClip_Down ; Печать полукруга по OR (круг выходит за правую границу по	X)
					; вх:  b - левый байт для печати
					;      c - правый байт для печати
					;      hl - адрес печати правого байта
					;      he - адрес печати левого	байта
					;      e' =0
					;      c' =0-радиус
					; вых: hl,de,bc,hl',de',bc' - ????
		ret
; End of function sub_7E14


