; Определение данных крайних байт и адресов печати
; вх:  ---
; вых: b  - левый байт для печати
;      c  - правый байт	для печати
;      hl - адрес печати правого байта
;      he - адрес печати левого	байта
;      c' - 0-радиус
;      e' - =0

CalcAddr_lClip:				; CODE XREF: sub_7EAE:loc_7ECCp
					; sub_7EAE+24p
		call	SetVars4Circle	; Установка регистров для печати круга
					; вх:  ----
					; вых: d - радиус
					;      e - флаги печати
					;      c - расстояние по Y от центра экрана
					;      b - расстояние по X от центра экрана
					;      c' =0-радиус
					;      e' =0
		ld	a, (CircleCrdY_prn) ; Печатная координата Y центра круга
		ld	c, a
		ld	a, 80h ; 'А'
		add	a, d
		sub	b
		call	CalcRightAddrCircle ; Определение данных правого байта байта и адреса печати
					; вх:  c - crdY	(координата центра круга)
					;      a - crdX+радиус (координата правой границы круга)
					;      b - левый байт для печати
					;      e - младший байт	адреса печати левого байта
					; вых: b - левый байт для печати
					;      c - правый байт для печати
					;      hl - адрес печати правого байта
					;      he - адрес печати левого	байта
		ld	a, l
		and	0E0h ; 'р'

loc_7FD2:				; DATA XREF: RAM:8517o
		or	1
		ld	e, a
		ld	b, a
		ld	a, (FillCircle)	; =1 рисовать круг без заливки
					; =0 с заливкой
		and	a
		ld	a, b
		jr	nz, loc_7FE0
		ld	b, 0FFh
		ret
; ---------------------------------------------------------------------------

loc_7FE0:				; CODE XREF: CalcAddr_lClip+1Aj
		ld	b, 80h ; 'А'
		ret
; End of function CalcAddr_lClip


; =============== S U B	R O U T	I N E =======================================

; Установка регистров для печати круга
; вх:  ----
; вых: d - радиус
;      e - флаги печати
;      c - расстояние по Y от центра экрана
;      b - расстояние по X от центра экрана
;      c' =0-радиус
;      e' =0

SetVars4Circle:				; CODE XREF: CalcAddr_rClipp
					; CalcAddr_lClipp
		ld	bc, (CircleCrdY_temp) ;	временно: расстояние до	центра экрана по Y
		ld	de, (CircleFlg)	; флаги	круга
					;   0,=0 -x координата X отрицательная
					;     =1 +x координата X положительная
					;   1,=0 -y координата Y отрицательная
					;     =1 +y координата Y положительная
					;   2,=? инвертированный старший бит координаты	X
					;   3,=? инвертированный старший бит координаты	Y
		ld	a, d
		neg
		exx
		ld	c, a
		ld	e, 0
		exx
		ret
; End of function SetVars4Circle


; =============== S U B	R O U T	I N E =======================================

; Определение данных левого байта и адреса печати
; вх:  c - crdY	(координата центра круга)
;      a - crdX-радиус (координата левой границы круга)
; вых: b - левый байт для печати
