					; =0 с заливкой
		and	a
		ld	a, b
		jp	nz, CalcLeftAddrCircle_2 ; продолжение CalcLeftAddrCircle
		ld	b, 0FFh
		inc	a

loc_8008:				; CODE XREF: CalcLeftAddrCircle+17j
