; =============== S U B	R O U T	I N E =======================================

; Печать на карте галактики круга радиуса полета на который хватает горючего
; Вх:  (PrnCrdXCursor) - координаты центра окружности
;      (RadiusCircleMap) - радиус окружности
; Вых: a =#00
;      hl,de,bc	- не определены

PrintCircleMap:				; CODE XREF: Cmd_O_LocalMap+6Fp
					; Cmd_I_GlobalMap+2Fp ...
		ld	b, 1100b
		ld	a, (PrnCrdXCursor) ; координата	X малого курсора на экране
		ld	c, a
		sub	80h ; 'А'
		jr	c, loc_846F
		set	0, b
		jr	loc_8472
; ---------------------------------------------------------------------------

loc_846F:				; CODE XREF: PrintCircleMap+8j
		ld	a, 80h ; 'А'
		sub	c

loc_8472:				; CODE XREF: PrintCircleMap+Cj
		ld	(CircleCrdX), a	; расстояние от	центра окружности до центра экрана по X
		ld	a, (PrnCrdYCursor) ; координата	Y малого курсора на экране
		ld	c, a
		sub	60h ; '`'
		jr	nc, loc_8482
		set	1, b
		ld	a, 60h ; '`'
		sub	c

loc_8482:				; CODE XREF: PrintCircleMap+1Aj
		ld	(CircleCrdY), a	; расстояние от	центра окружности до центра экрана по Y
		ld	a, b
		ld	(CircleFlg), a	; флаги	круга
					;   0,=0 -x координата X отрицательная
					;     =1 +x координата X положительная
					;   1,=0 -y координата Y отрицательная
					;     =1 +y координата Y положительная
					;   2,=? инвертированный старший бит координаты	X
					;   3,=? инвертированный старший бит координаты	Y
		ld	a, (RadiusCircleMap)
		ld	(CircleRadius),	a ; радиус окружности
		di
		ld	(SaveSPcircle),	sp
