J_Drive_Ready2:	db 0			; DATA XREF: PrintCompass+1w
					; PrintCompass+26w ...
					; =1 J недоступен (солнце рядом)
J_Drive_Ready3:	db 0			; DATA XREF: PrintCompass+4Fw
					; PrintCompass+77w ...
					; =1 J недоступен (планета рядом)
CompasPointerCrdX:db 0			; DATA XREF: PrintCompass+B9w
					; PrintCompass2+15w ...
					; 88DE 7,=1 влево
					;      7,=0 вправо
					;      0-6 =приращение координаты X
					;
CompasPointerCrdY:db 0			; DATA XREF: PrintCompass2:loc_89D4w
					; RenewCompass+1Dr
					; 88DF 7,=1 DownScrAdr
					;      7,=0 UpScrAdr
					;      0-6 =приращение координаты Y
					;
CompasPointerType:db 0			; DATA XREF: PrintCompass2:loc_89E2w
					; RenewCompass+9r
					; =0 компасс печатать с	заполнением

; =============== S U B	R O U T	I N E =======================================

; Расчет параметров печати и печать компаса с указателем на экране
; Вх:  ---
; Вых: b=#00
;      hl,de,c,a - не определены

PrintCompass:				; CODE XREF: GameMain:loc_732Bp
		xor	a
		ld	(J_Drive_Ready2), a ; =1 J недоступен (солнце рядом)
		ld	ix, SunCrd	; данные для печати солнца длина 9 байт
					; crd low x planet
		ld	a, (ix+2)
		and	7Fh ; ''
		jr	nz, loc_892F
		ld	a, (ix+5)
		and	7Fh ; ''
		jr	nz, loc_892F
		ld	a, (ix+8)
		and	7Fh ; ''
		jr	nz, loc_892F
		call	CalcLenVectorCrd ; Рассчёт расстояния до объекта по его	координатам (длина вектора)
					; Вх:  ix - адрес начала слота объекта
					; Вых: hl - расстояние до объекта
					;	  =#0000 более #FFFF
					;      de,bc,a - не определены
		ld	a, h
		or	l
		jr	z, loc_892F
		ld	a, 1
		ld	(J_Drive_Ready2), a ; =1 J недоступен (солнце рядом)
		ex	de, hl
		ld	hl, 0
		sbc	hl, de
		ex	de, hl
		ld	hl, 4000h
		and	a
		sbc	hl, de
		jp	c, GameOver
		ld	hl, 2000h
		xor	a
		sbc	hl, de
		jr	nc, loc_8924
		ld	a, 1

loc_8924:				; CODE XREF: PrintCompass+3Fj
		ld	(FuelScoopsOn),	a ; <>0	рядом с	солнцен, работает fuel scoops
		ex	de, hl
		call	CalcTempAltitude ; Расчет температуры/высоты от	близости солнца/планеты	и установка цвета
					;   индикатора опасности
					; Вх:  hl = 0 -	расстояние (длина вектора)
					; Вых: hl = hl*2.5
					;      de,b,a -	не определены
		ld	a, h
		ld	(Temperature), a ;   +0	- текущее значение
					;   -1 - отображенное на экране

loc_892F:				; CODE XREF: PrintCompass+Dj
					; PrintCompass+14j ...
		xor	a
		ld	(J_Drive_Ready3), a ; =1 J недоступен (планета рядом)
		ld	ix, PlanetCrd	; Координаты планеты в пространстве
		ld	a, (ix+2)
		and	7Fh ; ''
		cp	2
		jr	nc, PrintCompass2
		ld	b, a
		ld	a, (ix+5)
		and	7Fh ; ''
		cp	2
		jr	nc, PrintCompass2
		or	b
		ld	b, a
		ld	a, (ix+8)
		and	7Fh ; ''
		cp	2
		jr	nc, PrintCompass2
		or	b
		ld	a, 1
		ld	(J_Drive_Ready3), a ; =1 J недоступен (планета рядом)
		jr	nz, loc_897E
		call	CalcLenVectorCrd ; Рассчёт расстояния до объекта по его	координатам (длина вектора)
					; Вх:  ix - адрес начала слота объекта
					; Вых: hl - расстояние до объекта
					;	  =#0000 более #FFFF
					;      de,bc,a - не определены
		ld	a, h
		or	l
		jr	z, loc_897E
		ex	de, hl
		ld	hl, 0
		sbc	hl, de
		ex	de, hl
		ld	hl, 4000h
		and	a
		sbc	hl, de
		jp	c, GameOver
		ex	de, hl
		call	CalcTempAltitude ; Расчет температуры/высоты от	близости солнца/планеты	и установка цвета
					;   индикатора опасности
					; Вх:  hl = 0 -	расстояние (длина вектора)
					; Вых: hl = hl*2.5
					;      de,b,a -	не определены
