; =============== S U B	R O U T	I N E =======================================

; Расчет температуры/высоты от близости	солнца/планеты и установка цвета
;   индикатора опасности
; Вх:  hl = 0 -	расстояние (длина вектора)
; Вых: hl = hl*2.5
;      de,b,a -	не определены

CalcTempAltitude:			; CODE XREF: PrintCompass+47p
					; PrintCompass+94p
		push	hl
		add	hl, hl
		pop	de
		srl	d
		rr	e
		add	hl, de		; hl=hl*2.5
		ld	a, (IndDanger)	; <>0 в	полете (он же цвет индикатора опасности)
					; =0 пристыкован
					; =#04=%00 000 100 вылет со станции, в полёте (зелёный)
					; =#63=%01 100 011 4й энергоблок не полный (мигающий красный))
					; =#02=%00 000 010 один	из щитов front/rear пустой (красный)
					; =#06=%00 000 110 что-то рядом	(желтый)
		ld	b, a
		ld	a, h
		cp	50h ; 'P'
		jr	c, loc_8A30
		cp	78h ; 'x'
		jr	nc, loc_8A2C
		ld	a, b
		cp	63h ; 'c'
		ret	z
		ld	a, 2
		jr	loc_8A36
; ---------------------------------------------------------------------------

loc_8A2C:				; CODE XREF: CalcTempAltitude+13j
		ld	a, 63h ; 'c'
		jr	loc_8A36
; ---------------------------------------------------------------------------

loc_8A30:				; CODE XREF: CalcTempAltitude+Fj
		ld	a, b
		cp	4
		ret	nz
		ld	a, 6

loc_8A36:				; CODE XREF: CalcTempAltitude+1Bj
					; CalcTempAltitude+1Fj
		ld	(IndDanger), a	; <>0 в	полете (он же цвет индикатора опасности)
					; =0 пристыкован
					; =#04=%00 000 100 вылет со станции, в полёте (зелёный)
					; =#63=%01 100 011 4й энергоблок не полный (мигающий красный))
					; =#02=%00 000 010 один	из щитов front/rear пустой (красный)
					; =#06=%00 000 110 что-то рядом	(желтый)
		ret
; End of function CalcTempAltitude


