		ld	c, 0
		srl	a
		jr	c, loc_8ECB	; вылет	с планеты/front	view
		inc	c
		srl	a
		jr	c, loc_8EB2	; купить товары/rear view
		inc	c
		srl	a
		jr	c, loc_8EB2	; продать товары/left view
		inc	c

