byte_8F67:	db 0			; DATA XREF: BeginGame:loc_7219w
					; sub_8FF6+4r ...

; =============== S U B	R O U T	I N E =======================================

; проверка нажатия паузы и опрос клавиатуры с изменением режимов игры
; вх:  ----
; вых: cy=1 - конец игры

ScanKeyInPause:				; CODE XREF: GameMain+Cp
		ld	a, (ControlKey2) ; 7,=1	- CapsS	 -- Pause
					; 6,=1 - J	-- Jump	Drive
					; 5,=1 - G	-- Galactic Hyper Drive
					; 4,=1 - H	-- Hyper Drive
					; 3,=1 - 4	-- Right View/Equip Ship
					; 2,=1 - 3	-- Left	View/Sell Cargo
					; 1,=1 - 2	-- Rear	View/Buy Cargo
					; 0,=1 - 1	-- Front View/Launch
		and	80h ; 'А'
		ret	z
		ld	hl, FlagsSetUp	; 0-1,=00 управление SXNMA (LLFC0F)<>0 сброс CS,F,c
					;     =01 управление от	Kempston'а
					;     =10 управление от	курсора	76850
					;     =11 управление от	Sinclair right
					;   2,=1  управление приближено	к реальному (reaction)
					;   3,=1  вкл. инерционность поворота
					;   4,=1  управление инвертировано
					;   5,=1  вверх/вниз инвертировано
					;   6,=1  вкл. перехват	таргонов
					;   7,=1  звук включен

loc_8F71:				; CODE XREF: ScanKeyInPause+Ej
					; ScanKeyInPause+4Cj
		halt
		ld	a, (PressKeyPrnSymbol) ; Печатный символ нажатой клавиши
					;  =#FE	- BackSpace
					;  =#FF	- ничего не нажато
		inc	a
		jr	nz, loc_8F71

loc_8F78:				; CODE XREF: ScanKeyInPause+16j
		halt
		ld	a, (PressKeyPrnSymbol) ; Печатный символ нажатой клавиши
					;  =#FE	- BackSpace
					;  =#FF	- ничего не нажато
		cp	0FFh
		jr	z, loc_8F78
		cp	42h ; 'B'
		call	z, InvertControl ; инвертировать управление
		cp	44h ; 'D'
		call	z, InertionOnOff ; инерционность поворота
		cp	46h ; 'F'
		call	z, TagroidOnOff	; перехват таргонов
		cp	4Bh ; 'K'
		call	z, sub_8FF6	; смена	управления
		cp	51h ; 'Q'
		call	z, SFX_OFF	; выключение звука
		cp	52h ; 'R'
		call	z, ReactionOnOff ; система приближения управления к реальному (Reaction)
		cp	53h ; 'S'
		call	z, SFX_ON	; включение звука
		cp	59h ; 'Y'
		call	z, InvertUpDown	; инвертировать	вверх/вниз
		cp	31h ; '1'
		jr	z, NewGame	; завершить игру
		cp	20h ; ' '
		jr	z, PauseOff	; сброс	таблицы	нажатых	клавиш
		and	a
		call	z, sub_9009	; звуковой сигнал
					; вх:  ----
					; вых: ----
		jr	loc_8F71
; End of function ScanKeyInPause


; =============== S U B	R O U T	I N E =======================================

; сброс	таблицы	нажатых	клавиш

PauseOff:				; CODE XREF: ScanKeyInPause+46j
					; NewGamep
		ld	hl, ControlKey1	; 7,=1 - Y	 -- Cloaking Device
					; 6,=1 - 0	 -- ???
					; 5,=1 - I	 -- Global Map
					; 4,=1 - O	 -- Local Map
					; 3,=1 - P	 -- Planet Info
					; 2,=1 - K	 -- Planet Price
					; 1,=1 - L	 -- Commander Info
					; 0,=1 - Enter	 -- Inventory
		xor	a
		ld	(hl), a
		inc	hl
		ld	(hl), a
		inc	hl
		ld	(hl), a
		inc	hl
		ld	(hl), a
		inc	hl
		ld	(hl), a
		ret
; End of function PauseOff


; =============== S U B	R O U T	I N E =======================================

; завершить игру

NewGame:				; CODE XREF: ScanKeyInPause+42j
		call	PauseOff	; сброс	таблицы	нажатых	клавиш
		scf
		ret
; End of function NewGame


; =============== S U B	R O U T	I N E =======================================

; инвертировать	управление

InvertControl:				; CODE XREF: ScanKeyInPause+1Ap
		ld	a, (hl)
		xor	10000b
		ld	(hl), a
		xor	a
		ret
; End of function InvertControl


; =============== S U B	R O U T	I N E =======================================

; инерционность	поворота

InertionOnOff:				; CODE XREF: ScanKeyInPause+1Fp
		ld	a, (hl)
		xor	1000b
		ld	(hl), a
		xor	a
		ret
; End of function InertionOnOff


; =============== S U B	R O U T	I N E =======================================

; перехват таргонов

TagroidOnOff:				; CODE XREF: ScanKeyInPause+24p
		ld	a, (hl)
		xor	1000000b
		ld	(hl), a
		xor	a
		ret
; End of function TagroidOnOff


; =============== S U B	R O U T	I N E =======================================

; выключение звука

SFX_OFF:				; CODE XREF: ScanKeyInPause+2Ep
		ld	a, (hl)
		and	1111111b
		ld	(hl), a
		xor	a
		ret
; End of function SFX_OFF


; =============== S U B	R O U T	I N E =======================================

; система приближения управления к реальному (Reaction)

ReactionOnOff:				; CODE XREF: ScanKeyInPause+33p
		ld	a, (hl)
		xor	100b
		ld	(hl), a
		xor	a
		ret
; End of function ReactionOnOff


; =============== S U B	R O U T	I N E =======================================

; включение звука

SFX_ON:					; CODE XREF: ScanKeyInPause+38p
		ld	a, (hl)
		or	10000000b
		ld	(hl), a
		xor	a
		ld	(nBeepFX), a	; какой	звук надо включить
					; =#00 звуков нет(не звучат)
					;  0,=1	взорвана энерго	бомба
					;  1,=1	запущена ракета
					;  2,=1	врезаемся в объект/объект уничтожен
					;  3,=1	выстрел	из лазера
					;  4,=1	выстрелили из дазера
					;  5,=1	ECM работает
					;  6,=1	попадание из лазера по игроку/повреждения при стыковке
					;  7,=1
		ret
; End of function SFX_ON


; =============== S U B	R O U T	I N E =======================================

; инвертировать	вверх/вниз

InvertUpDown:				; CODE XREF: ScanKeyInPause+3Dp
		ld	a, (hl)
		xor	100000b
		ld	(hl), a
		xor	a
		ret
; End of function InvertUpDown


