; Взрыв	энерго бомбы

UseEnergyBomb:				; CODE XREF: Process_MissBombEPod+Fp
		ld	a, (ControlKey3) ; 7,=1	- C	-- Docking Computer
					; 6,=1 - Q     -- Escape Pod
					; 5,=1 - W     -- Energy Bomb
					; 4,=1 - E     -- ECM System
					; 3,=1 - U     -- UnTarget
					; 2,=1 - F     -- Fire Missile
					; 1,=1 - T     -- Target Missile
					; 0,=1 - A     -- Fure Laser
		bit	5, a
		ret	z
		ld	hl, PilotEnergyBomb ; Energy bomb
		ld	a, (hl)
		and	a
		ret	z
		xor	a
		ld	(hl), a
		inc	a
		ld	(EnergyBombUsed), a ; <>0, =1, =#FF взорвана энергобомба
					;
		ld	hl, nBeepFX	; какой	звук надо включить
					; =#00 звуков нет(не звучат)
					;  0,=1	взорвана энерго	бомба
					;  1,=1	запущена ракета
					;  2,=1	врезаемся в объект/объект уничтожен
					;  3,=1	выстрел	из лазера
					;  4,=1	выстрелили из дазера
					;  5,=1	ECM работает
					;  6,=1	попадание из лазера по игроку/повреждения при стыковке
					;  7,=1
		set	0, (hl)
		ld	c, 18h		; мерцание обзорного экрана

loc_9279:				; CODE XREF: UseEnergyBomb+1Dj
		call	loc_9280	; paper	5, ink 0
		dec	c
		jr	nz, loc_9279
		ret
; ---------------------------------------------------------------------------

loc_9280:				; CODE XREF: UseEnergyBomb:loc_9279p
		ld	l, 101000b	; paper	5, ink 0
		call	FastSetAtrInViewScr ; Быстрая установка	атрибутов на обзорном экране
					;  l - атрибут
		ld	l, 1111b	; paper	7, ink 1
; End of function UseEnergyBomb


; =============== S U B	R O U T	I N E =======================================

; печать атрибутов обзорного экрана
; вх:  l - атрибут
; вых: b=#00
;      a=#00
;      hl - ????

SetAtrViewScr:				; CODE XREF: GameMain+BBp
					; PrnCocpit+34p ...
		ld	a, (CloakingDeviceOn) ;	 =1 включен Cloaking Device
					;  =1 расход энергии при использовании
		and	a
		jr	nz, FastSetAtrInViewScr	; Быстрая установка атрибутов на обзорном экране
					;  l - атрибут
		ld	a, l
		and	111b		; Paper	0
					; Ink без изменений
		ld	l, a
; End of function SetAtrViewScr


; =============== S U B	R O U T	I N E =======================================

; Быстрая установка атрибутов на обзорном экране
;  l - атрибут

FastSetAtrInViewScr:			; CODE XREF: UseEnergyBomb+22p
					; SetAtrViewScr+4j
		ld	a, (PilotMission1) ; байт первой миссии
					;  =0 миссия не	выдана
					; <>0 1я миссия	выдана
		and	a
		jr	z, loc_929B
		ld	a, l		; первая миссия	выдана
					; paper	без изменений
					; ink 2/0
		and	111010b
		ld	l, a

loc_929B:				; CODE XREF: FastSetAtrInViewScr+4j
		halt
		ld	(SaveSP4), sp
		ld	h, l
