StarsFastScroll:db 0			; DATA XREF: Use_J_Drive:loc_99A0w
					; PrintStarsr ...
					; только для звёзд
					; =1 J-drive работает, звёзды быстро перемещаются

; =============== S U B	R O U T	I N E =======================================

; Движение на J-приводе

Use_J_Drive:				; CODE XREF: GameMain+42p
		ld	a, (ControlKey2) ; 7,=1	- CapsS	 -- Pause
					; 6,=1 - J	-- Jump	Drive
					; 5,=1 - G	-- Galactic Hyper Drive
					; 4,=1 - H	-- Hyper Drive
					; 3,=1 - 4	-- Right View/Equip Ship
					; 2,=1 - 3	-- Left	View/Sell Cargo
					; 1,=1 - 2	-- Rear	View/Buy Cargo
					; 0,=1 - 1	-- Front View/Launch
		bit	6, a
		push	af
		and	10111111b
		ld	(ControlKey2), a ; 7,=1	- CapsS	 -- Pause
					; 6,=1 - J	-- Jump	Drive
					; 5,=1 - G	-- Galactic Hyper Drive
					; 4,=1 - H	-- Hyper Drive
					; 3,=1 - 4	-- Right View/Equip Ship
					; 2,=1 - 3	-- Left	View/Sell Cargo
					; 1,=1 - 2	-- Rear	View/Buy Cargo
					; 0,=1 - 1	-- Front View/Launch
		pop	af
		ret	z
		ld	a, (J_Drive_Ready2) ; =1 J недоступен (солнце рядом)
		dec	a
		ret	z
		ld	a, (J_Drive_Ready3) ; =1 J недоступен (планета рядом)
		dec	a
		ret	z
		ld	a, (J_Drive_Ready4) ; =1 рядом объект блокирующий J drive
					; <>0 J	недоступен
		and	a
		ret	nz
		ld	a, (J_Drive_Coriolis) ;	=0 J недоступен
		and	a
		ret	z
		xor	a
		ld	(PilotMission2), a ; =3	asp из 2й миссии уничтожен/в пространстве есть контейнер с шапкой-невидимкой
					; =2 у asp невидимость выключена
					; =1 выдана 2й миссия
					; =0 при движении на J
		ld	ix, objCoriolis	; лишнее
		call	ClearAroundObj	; Зануляем список близлежащих объектов
					; Вх:  ---
					; Вых: b =#00
					;      a =#00
					;      de =#LenSlotObj
					;      ix - не определен
		ld	a, (StarsRndCrd) ; байт	для вариации генерации координат новой звезды
		rrca
		ld	(StarsRndCrd), a ; байт	для вариации генерации координат новой звезды
		ld	a, 1
		jr	c, loc_99A0
		ld	(FrameCounter),	a ; счетчик появления корабля????
					; счетчик кадров

loc_99A0:				; CODE XREF: Use_J_Drive+35j
		ld	(StarsFastScroll), a ; только для звёзд
					; =1 J-drive работает, звёзды быстро перемещаются
		ld	ix, SunCrd	; данные для печати солнца длина 9 байт
					; crd low x planet
		call	sub_99B5	; быстрое удаление/приближение к солнцу/планете/станции
					; меняется только crd z
		ld	ix, PlanetCrd	; Координаты планеты в пространстве
		call	sub_99B5	; быстрое удаление/приближение к солнцу/планете/станции
					; меняется только crd z
		ld	ix, objCoriolis	; длина	27h
; End of function Use_J_Drive


; =============== S U B	R O U T	I N E =======================================

; быстрое удаление/приближение к солнцу/планете/станции
; меняется только crd z

sub_99B5:				; CODE XREF: Use_J_Drive+41p
					; Use_J_Drive+48p
		ld	bc, 20h	; ' '
		ld	h, (ix+8)	; crd z
		ld	l, (ix+7)
		ld	d, l
		bit	7, h
		jr	nz, loc_99CA
		and	a
		sbc	hl, bc
		jr	c, loc_99D4
		jr	loc_99CD
; ---------------------------------------------------------------------------

loc_99CA:				; CODE XREF: sub_99B5+Cj
		add	hl, bc
		jr	c, loc_99E9

loc_99CD:				; CODE XREF: sub_99B5+13j
		ld	(ix+8),	h
		ld	(ix+7),	l
		ret
; ---------------------------------------------------------------------------

loc_99D4:				; CODE XREF: sub_99B5+11j
		ld	hl, 2000h
		ld	e, (ix+6)
		and	a
		sbc	hl, de
		ld	a, 80h ; 'А'
		ld	(ix+8),	a
		ld	(ix+7),	h
		ld	(ix+6),	l
		ret
; ---------------------------------------------------------------------------

loc_99E9:				; CODE XREF: sub_99B5+16j
		ld	a, 7Fh ; ''
		ld	(ix+8),	a
		ld	a, 0FFh
		ld	(ix+7),	a
		ld	(ix+6),	a
		ret
; End of function sub_99B5

