; =============== S U B	R O U T	I N E =======================================

; Печать ракет,	инициализация переменных, печать атрибутов кокпита с учётом
; наличия Escape Pod

InitVarLaunch:				; CODE XREF: LaunchDocking+8Dp
		call	PrintMissiles	; Печать ракет на кокпите
					; Вх:  ---
					; Вых: b= #00
					;      hl,de,c,a - не определены
		call	ResetBattleMessages ; Обнуление	всех сообщений во время	полёта
					; Вх: ---
					; Вых: a =#00
					;      b =#00
					;      hl,MissileJammed+9
		xor	a
		ld	(Missile1), a	; =0 ракета не нацелена
					; =1 ракета готова к захвату цели
					; =2 ракета на что-то нацелена
		ld	(TempLaser), a	; температура лазера
					;   +0 - текущее значение
					;   -1 - отображенное на экране
					; >#90 не стреляем
		ld	(Temperature), a ;   +0	- текущее значение
					;   -1 - отображенное на экране
		ld	(AutoDocking), a ; <>0(=#01) включена стыковка
		ld	a, 0A0h	; 'а'
		ld	(ShieldFront), a ; передний щит
					;   +0 - текущее значение
					;   -1 - отображенное на экране
		ld	(ShieldRear), a	; задний щит
					;   +0 - текущее значение
					;   -1 - отображенное на экране
		ld	(Altitude), a	;   +0 - текущее значение
					;   -1 - отображенное на экране
		ld	hl, ShieldUnit1	;   +0 - текущее значение
					;   -1 - отображенное на экране
		ld	b, 4

loc_9A69:				; CODE XREF: InitVarLaunch+26j
		ld	(hl), a
		inc	hl
		inc	hl
		djnz	loc_9A69
; End of function InitVarLaunch


; =============== S U B	R O U T	I N E =======================================

; Установка атрибутов кокпита на экране/в буфере
; в зависимости	от наличия Escape Pod

SetAtrCocpitDevice:			; CODE XREF: DecEnergyShieldFR+5Dp
		ld	hl, 5A23h
		ld	a, (WhatOnScreen) ; Что	изображено на экране
					;  =0..3 в полете номер	обзорного экрана (front, rear, left, right)
					;  =#04	меню покупки товаров
					;  =#05	меню продажи товаров
					;  =#06	меню покупки оборудования
					;  =#07	глобальная карта
					;  =#08	локальная карта
					;  =#09	инфо о планете еще не выведено
					;  =#0A	прайс планеты
					;  =#0B	инфо о пилоте
					;  =#0C	Инвентрь
					;  =#20	инфо о планете
		cp	4
		jr	c, loc_9A79
		inc	h

loc_9A79:				; CODE XREF: SetAtrCocpitDevice+8j
		ld	c, 17h
		ld	a, (PilotEscapePod) ; Escape pod
		and	a
		jr	z, loc_9A83
		ld	c, 1Fh

loc_9A83:				; CODE XREF: SetAtrCocpitDevice+11j
		ld	de, 1Bh
		push	hl
		call	loc_9A8F	; Установка атрибутов индикаторов кокпита
					;  C - Атрибут
					;  HL -	адрес в	области	атрибутов
					;  DE =1Bh
		pop	hl
		ld	a, l
		add	a, 15h
		ld	l, a

loc_9A8F:				; CODE XREF: SetAtrCocpitDevice+19p
		ld	b, 7		; Установка атрибутов индикаторов кокпита
					;  C - Атрибут
					;  HL -	адрес в	области	атрибутов
					;  DE =1Bh

loc_9A91:				; CODE XREF: SetAtrCocpitDevice+2Cj
		push	bc
		ld	b, 5

loc_9A94:				; CODE XREF: SetAtrCocpitDevice+28j
		ld	(hl), c
		inc	hl
		djnz	loc_9A94
		pop	bc
		add	hl, de
		djnz	loc_9A91
		ret
; End of function SetAtrCocpitDevice

