; =============== S U B	R O U T	I N E =======================================

; Обработка и печать звезд с учётом движения игрока, в том числе на J-приводе
; Вх:  ---
; Вых: hl,de,bc,hl',de',bc,a - не определены

PrintStars:				; CODE XREF: GameMain+83p GameMain+D3p ...
		ld	a, (StarsFastScroll) ; только для звёзд
					; =1 J-drive работает, звёзды быстро перемещаются
		dec	a
		jr	nz, CalcAndPrnStars ; Обработка	и печать звезд с учётом	движения игрока
					; Вх:  ---
					; Вых: hl,de,bc,hl',de',bc,a - не определены
		ld	(StarsFastScroll), a ; только для звёзд
					; =1 J-drive работает, звёзды быстро перемещаются
		ld	a, 1Eh
		ld	(HighDeltaSpeed), a ; старший байт скорости
					; #00..#1F
		call	CalcAndPrnStars	; Обработка и печать звезд с учётом движения игрока
					; Вх:  ---
					; Вых: hl,de,bc,hl',de',bc,a - не определены
		ld	a, 10h
		ld	(HighDeltaSpeed), a ; старший байт скорости
					; #00..#1F
		call	CalcAndPrnStars
; End of function PrintStars


