					;   7,=1 CrdX отрицательная
					;   6,=1 CrdY отрицательная
					;   5,=1 =0/1 front/rear
					;   4,=1 вращение отрицательное
					;     =0 вращение положительное
					;   3,=1 движение вниз
					;     =0 движение вверх
		ld	b, a
		ld	a, (wrkStarCrdXh) ; +0 DataStars
		ld	l, a
		ld	a, (wrkStarCrdYh) ; +1 DataStars
		ld	h, a
		ld	a, 80h ; 'А'
		bit	7, b
		jr	nz, loc_A306
		add	a, l
		jr	loc_A307
