		ld	d, a
		ld	a, h
		and	38h ; '8'
		add	a, a
		add	a, a
		ld	e, a
		ld	a, l
		rra
		rra
		rra
		and	1Fh
		or	e
		ld	e, a
		ld	a, l
		and	7
		ld	c, b
		inc	a
		ld	b, a
		ld	a, 1

loc_A32F:				; CODE XREF: StarCrd2AdrPrn+41j
		rrca
		djnz	loc_A32F
		ld	c, a
		ret
; End of function StarCrd2AdrPrn


