; Обмен	местами	координат каждой звезды
; Вх:  ---
; Вых: de =#0005
;      b =#00
;      hl,c,a -	не определены

Exchange_CrdX_Y:			; CODE XREF: CalcAndPrnStars+31p
		ld	a, (StarsMax)	; максимальное отображаемое кол-во звёзд
		ld	b, a
		ld	hl, DataStars	; данные 16 звёзд

loc_A453:				; CODE XREF: Exchange_CrdX_Y+16j
		ld	d, h
		ld	e, l
		inc	de
		ld	a, (de)
		ld	c, a
		ld	a, (hl)
		ld	(de), a
		ld	(hl), c
		ld	a, l
		add	a, 5
		jr	nc, loc_A461
		inc	h

loc_A461:				; CODE XREF: Exchange_CrdX_Y+12j
		ld	l, a
		djnz	loc_A453
		ret
; End of function Exchange_CrdX_Y


