; a=b=l	= CY + hвх*2
; h = CY + hвх*2 + lвх

InRnd_A_HL:				; CODE XREF: CalcNewStar:loc_A355p
					; CalcNewStar+28p ...
		ld	a, h
		adc	a, a
		ld	b, a
		adc	a, l
		ld	h, a
		ld	l, b
		ret
; End of function InRnd_A_HL

