DataStars:	db 0, 10h, 0FFh, 38h, 4Bh ; DATA XREF: CalcStarsForTonnel+15o
					; CalcAndPrnStars+3Co ...
		db 90h,	10h, 0C8h, 1, 41h ; данные 16 звёзд
		db 90h,	0, 0B4h, 17h, 1
		db 90h,	90h, 0A0h, 2, 3
		db 0, 90h, 0D2h, 4, 39h
		db 10h,	90h, 0DCh, 59h,	6
		db 10h,	0, 28h,	22h, 78h
		db 10h,	10h, 32h, 64h, 15h
		db 2, 12h, 23h,	63h, 79h
		db 82h,	6, 8Ch,	3, 79h
