		db 6Eh,	78h, 3Ch, 2, 22h
		db 4, 96h, 4Ch,	64h, 0Ch
		db 5, 20h, 0EAh, 2Bh, 66h
		db 64h,	38h, 5,	69h, 17h
		db 4, 43h, 38h,	0F3h, 0E7h
byte_A4BC:	db 0			; DATA XREF: PrintIndDanger+1Eo
					; счетчик для мигания индикатора опасности

; =============== S U B	R O U T	I N E =======================================

; Печать индикатора опасности и	индикатора ракеты
; Вх:  (IndDanger) - состояние индикатора
; Вых: b =#00
;      hl,de,c,a - не определены

PrintIndDanger:				; CODE XREF: PrnMess_A_Inidcator+3p
					; Cmd_L_PilotInfo+Ap ...
		ld	hl, IndDanger	; <>0 в	полете (он же цвет индикатора опасности)
					; =0 пристыкован
					; =#04=%00 000 100 вылет со станции, в полёте (зелёный)
					; =#63=%01 100 011 4й энергоблок не полный (мигающий красный))
					; =#02=%00 000 010 один	из щитов front/rear пустой (красный)
					; =#06=%00 000 110 что-то рядом	(желтый)
		ld	a, (hl)
		and	a
		ret	z
		ld	a, (ShieldFront) ; передний щит
					;   +0 - текущее значение
					;   -1 - отображенное на экране
		and	a
		jr	z, loc_A4CF
		ld	a, (ShieldRear)	; задний щит
					;   +0 - текущее значение
					;   -1 - отображенное на экране
		and	a
		jr	nz, loc_A4D6

loc_A4CF:				; CODE XREF: PrintIndDanger+Aj
		ld	a, (hl)
		cp	63h ; 'c'
		jr	z, loc_A4D6
		ld	(hl), 2

loc_A4D6:				; CODE XREF: PrintIndDanger+10j
					; PrintIndDanger+15j
		ld	a, (hl)
		cp	63h ; 'c'
		jr	nz, loc_A4E8
		ld	hl, byte_A4BC	; счетчик для мигания индикатора опасности
		inc	(hl)
		bit	1, (hl)
		jr	nz, loc_A4E6
		xor	a
		jr	loc_A4E8
; ---------------------------------------------------------------------------

loc_A4E6:				; CODE XREF: PrintIndDanger+24j
		ld	a, 2

loc_A4E8:				; CODE XREF: PrintIndDanger+1Cj
					; PrintIndDanger+27j
		ld	d, a
		ld	a, (WhatOnScreen) ; Что	изображено на экране
					;  =0..3 в полете номер	обзорного экрана (front, rear, left, right)
					;  =#04	меню покупки товаров
					;  =#05	меню продажи товаров
					;  =#06	меню покупки оборудования
					;  =#07	глобальная карта
					;  =#08	локальная карта
					;  =#09	инфо о планете еще не выведено
					;  =#0A	прайс планеты
					;  =#0B	инфо о пилоте
					;  =#0C	Инвентрь
					;  =#20	инфо о планете
		cp	4
		jr	nc, loc_A511	; отображено меню
		ld	hl, 5A28h	; включен обзорный экран
					; цвет индикатора опасности
		ld	(hl), d
		inc	hl
		ld	(hl), d
		ld	hl, 5A48h
		ld	(hl), d
		inc	hl
		ld	(hl), d
		call	loc_A553
		ld	a, (Missile1)	; =0 ракета не нацелена
					; =1 ракета готова к захвату цели
					; =2 ракета на что-то нацелена
		cp	1
		jr	nz, loc_A508
		ld	a, 4		; =1 ->	paper 4

loc_A508:				; CODE XREF: PrintIndDanger+47j
		add	a, a
		add	a, a
		add	a, a
		add	a, 7
		ld	(5AE7h), a
		ret
; ---------------------------------------------------------------------------

loc_A511:				; CODE XREF: PrintIndDanger+31j
		ld	hl, loc_BBBF	; отображено меню
		ld	(hl), 0
		ld	hl, 11Bh
		ld	(CrdXPrnSymbol), hl ; Координаты печати	символа
		cp	9
		jr	nc, loc_A53C
		ld	a, d
		and	a
		jr	z, loc_A536
		cp	2
		jr	nz, loc_A538
		ld	a, 21h ; '!'
		call	PrintMessage1_A	; Печать сообщения из группы 1 в буфере/на экране
					; вх: A	- номер	сообщения
		ld	a, 22h ; '"'
		call	PrintMessage1_A	; Печать сообщения из группы 1 в буфере/на экране
					; вх: A	- номер	сообщения
		ld	d, 17h
		jr	loc_A548
; ---------------------------------------------------------------------------

loc_A536:				; CODE XREF: PrintIndDanger+65j
		ld	d, 2

loc_A538:				; CODE XREF: PrintIndDanger+69j
		ld	a, 10h
		add	a, d
		ld	d, a

loc_A53C:				; CODE XREF: PrintIndDanger+61j
		push	de
		ld	a, 23h ; '#'
		call	PrintMessage1_A	; Печать сообщения из группы 1 в буфере/на экране
					; вх: A	- номер	сообщения
		ld	a, 24h ; '$'
		call	PrintMessage1_A	; Печать сообщения из группы 1 в буфере/на экране
					; вх: A	- номер	сообщения
		pop	de

loc_A548:				; CODE XREF: PrintIndDanger+77j
		ld	hl, 583Ch
		ld	(hl), d
		inc	hl
		ld	(hl), d
