loc_A553:				; CODE XREF: PrintIndDanger+3Fp
		ld	a, 4
		ld	(IndDanger), a	; <>0 в	полете (он же цвет индикатора опасности)
					; =0 пристыкован
					; =#04=%00 000 100 вылет со станции, в полёте (зелёный)
					; =#63=%01 100 011 4й энергоблок не полный (мигающий красный))
					; =#02=%00 000 010 один	из щитов front/rear пустой (красный)
					; =#06=%00 000 110 что-то рядом	(желтый)
		ret
; End of function PrintIndDanger


; =============== S U B	R O U T	I N E =======================================

; Управление ракетами, бомбами,	спасательной капсулой

Process_MissBombEPod:			; CODE XREF: GameMain+A1p
		ld	a, (WhatOnScreen) ; Что	изображено на экране
					;  =0..3 в полете номер	обзорного экрана (front, rear, left, right)
					;  =#04	меню покупки товаров
					;  =#05	меню продажи товаров
					;  =#06	меню покупки оборудования
					;  =#07	глобальная карта
					;  =#08	локальная карта
					;  =#09	инфо о планете еще не выведено
					;  =#0A	прайс планеты
					;  =#0B	инфо о пилоте
					;  =#0C	Инвентрь
					;  =#20	инфо о планете
		cp	4
		ret	nc
		call	PrnDangerEcmDock ; Печать индикаторов: опасности, станции, ECM на кокпите
		call	UseMissile	; Использование	ракеты
		call	UseEscapePod	; использование	спасательной капсулы
		call	UseEnergyBomb	; Взрыв	энерго бомбы
		ld	hl, ControlKey3	; 7,=1 - C     -- Docking Computer
					; 6,=1 - Q     -- Escape Pod
					; 5,=1 - W     -- Energy Bomb
					; 4,=1 - E     -- ECM System
					; 3,=1 - U     -- UnTarget
					; 2,=1 - F     -- Fire Missile
					; 1,=1 - T     -- Target Missile
					; 0,=1 - A     -- Fure Laser
		ld	a, (hl)
		and	10010001b
		ld	(hl), a
; End of function Process_MissBombEPod


; =============== S U B	R O U T	I N E =======================================

; Нанесение урона кораблю игрока
; Вх:  ---
; Вых: hl,de,bc,a - не определены

Damage2Pilot:				; CODE XREF: GameMain+61p
		ld	hl, IndDanger	; <>0 в	полете (он же цвет индикатора опасности)
					; =0 пристыкован
					; =#04=%00 000 100 вылет со станции, в полёте (зелёный)
					; =#63=%01 100 011 4й энергоблок не полный (мигающий красный))
					; =#02=%00 000 010 один	из щитов front/rear пустой (красный)
					; =#06=%00 000 110 что-то рядом	(желтый)
		xor	a
		cp	(hl)
		ret	z
		ld	a, (ShieldUnit4) ;   +0	- текущее значение
					;   -1 - отображенное на экране
		cp	0A0h ; 'а'
		jr	z, loc_A584
		ld	a, 63h ; 'c'
		ld	(IndDanger), a	; <>0 в	полете (он же цвет индикатора опасности)
					; =0 пристыкован
					; =#04=%00 000 100 вылет со станции, в полёте (зелёный)
					; =#63=%01 100 011 4й энергоблок не полный (мигающий красный))
					; =#02=%00 000 010 один	из щитов front/rear пустой (красный)
					; =#06=%00 000 110 что-то рядом	(желтый)

loc_A584:				; CODE XREF: Damage2Pilot+Bj
		call	EnergyRecovery	; Восстановление энергии корабля
					; Вх:  ---
					; Вых: hl,b,a -	не определены
		ld	hl, ShieldFront	; передний щит
					;   +0 - текущее значение
					;   -1 - отображенное на экране
		ld	a, (DamageFrontShield) ; урон передним щитам
		call	DecEnergyShieldFR ; Уменьшение энергии переднего/заднего щита и	энергоблоков
					; Вх:  hl - адрес щита
					;	a - урон щиту
					; Вых: hl,b,a -	не определены
		ld	hl, ShieldRear	; задний щит
					;   +0 - текущее значение
					;   -1 - отображенное на экране
		ld	a, (DamageRearShield) ;	урон задним щитам
		call	DecEnergyShieldFR ; Уменьшение энергии переднего/заднего щита и	энергоблоков
					; Вх:  hl - адрес щита
					;	a - урон щиту
					; Вых: hl,b,a -	не определены
		ld	a, (CloakingDeviceOn) ;	 =1 включен Cloaking Device
					;  =1 расход энергии при использовании
		and	a
		ld	a, (DamageEnergyUnit) ;	урон энергоблокам
		jr	z, loc_A5A3
		inc	a

loc_A5A3:				; CODE XREF: Damage2Pilot+2Ej
		ld	c, a
		ld	b, 4
; End of function Damage2Pilot


; =============== S U B	R O U T	I N E =======================================

; Уменьшение энергии корабля
;   энергия=энергия-(b*c)
; Вх:  c - значение на которое уменьшится энергия игрока
;      b - коэффициент уменьшения энергии
; Вых: hl,d,b,a	- не определены

DecEnergyPlayer:			; CODE XREF: DecEnergyShieldFR+23p
		ld	hl, ShieldUnit1	;   +0 - текущее значение
					;   -1 - отображенное на экране
		ld	d, 4

loc_A5AB:				; CODE XREF: DecEnergyPlayer+Ej
					; DecEnergyPlayer+17j
		ld	a, (hl)
		sub	c
		jr	nc, loc_A5BC
		ld	(hl), 0
		inc	hl
		inc	hl
		dec	d
		jr	nz, loc_A5AB
		ld	a, 1
		ld	(PlayerGameOver), a ; <>0 энергоблоки пустые
					; игрок	уничтожен
		ret
; ---------------------------------------------------------------------------

loc_A5BC:				; CODE XREF: DecEnergyPlayer+7j
		ld	(hl), a
		djnz	loc_A5AB
		ret
; End of function DecEnergyPlayer


; =============== S U B	R O U T	I N E =======================================

; Уменьшение энергии переднего/заднего щита и энергоблоков
; Вх:  hl - адрес щита
;	a - урон щиту
; Вых: hl,b,a -	не определены

DecEnergyShieldFR:			; CODE XREF: Damage2Pilot+1Bp
					; Damage2Pilot+24p
		ld	c, a
		and	a
		jr	nz, loc_A5CC
		ld	hl, IntensityDamage ; интенсивность урона
					; если урон опустошает передний/задний щит, то +5
					; если при этом	>=#0D то увероятность уничтожения груза/устройств
		ld	a, (hl)
		and	a
		ret	z
		dec	(hl)
		ret
; ---------------------------------------------------------------------------

loc_A5CC:				; CODE XREF: DecEnergyShieldFR+2j
		push	bc
		push	hl
		cp	46h ; 'F'
		call	nc, HeavyDamage	; сильный урон.	уничтожение чего-либо (топливо/груз и т.п.)
		pop	hl
		pop	bc
		ld	b, 5

loc_A5D7:				; CODE XREF: DecEnergyShieldFR+1Cj
		ld	a, (hl)
		sub	c
		jr	c, loc_A5DF
		ld	(hl), a
		djnz	loc_A5D7
		ret
; ---------------------------------------------------------------------------

loc_A5DF:				; CODE XREF: DecEnergyShieldFR+19j
		ld	(hl), 0
		dec	b
		ret	z
		call	DecEnergyPlayer	; Уменьшение энергии корабля
					;   энергия=энергия-(b*c)
					; Вх:  c - значение на которое уменьшится энергия игрока
					;      b - коэффициент уменьшения энергии
					; Вых: hl,d,b,a	- не определены
		ld	hl, IntensityDamage ; интенсивность урона
					; если урон опустошает передний/задний щит, то +5
					; если при этом	>=#0D то увероятность уничтожения груза/устройств
		ld	a, (hl)
		add	a, 5
		ld	(hl), a
		cp	0Dh
		ret	c

HeavyDamage:				; CODE XREF: DecEnergyShieldFR+10p
					; RAM:A8A7j
		ld	a, (msgNumber)	; сильный урон.	уничтожение чего-либо (топливо/груз и т.п.)
		cp	0FDh ; '¤'
		ret	z
		ld	a, (RndWord)	; случайное число
		rrca
		rrca
		and	3Fh ; '?'
		jp	z, SetFuelZero	; Обнуление топлива
					; Вх:  ---
					; Вых: b,a - не	определены
		cp	11h
		ret	nc
		dec	a
		cp	6
		jr	nc, loc_A626
		ld	hl, PilotECMSystem ; ECM System
					; 7,=1 система включена
		and	a
		jr	z, loc_A610
		add	a, 2

loc_A610:				; CODE XREF: DecEnergyShieldFR+4Cj
		call	Calc_HLaddA	; Вых: d =0
					;      e=a
		ld	a, (hl)
		and	a
		ret	z
		ld	(hl), d
		ld	a, e
		add	a, 6Ch ; 'l'

loc_A61A:				; CODE XREF: DecEnergyShieldFR+77j
		ld	(nMsgDamage), a	; номер	ссобщения что повреждено в бою
		call	SetAtrCocpitDevice ; Установка атрибутов кокпита на экране/в буфере
					; в зависимости	от наличия Escape Pod
		ld	hl, DestDeviceCargo ; 7,=1 уничтожено какое-то оборудование/груз
					;   -> в nMsgDamage номер сообщения
		set	7, (hl)
		ret
; ---------------------------------------------------------------------------

loc_A626:				; CODE XREF: DecEnergyShieldFR+46j
		ld	hl,  PilotCash2+1 ; 19-20 деньги пилота	(количество целых тысяч)
					;  CASH	0..65535 - 0000..65535000
					;
		call	Calc_HLaddA	; Вых: d =0
					;      e=a
		ld	a, (hl)
		and	a
		ret	z
		dec	(hl)
		ld	hl, PilotFreeCargo ; Оставшаяся	грузоподъемность корабля
		inc	(hl)
		ld	a, 0CCh	; '╠'
		add	a, e
		jr	loc_A61A
; End of function DecEnergyShieldFR

