; =============== S U B	R O U T	I N E =======================================

; Печать индикаторов: опасности, станции, ECM на кокпите

PrnDangerEcmDock:			; CODE XREF: Process_MissBombEPod+6p
		ld	hl, loc_BBBF
		ld	(hl), 0		; nop
		ld	hl, 1108h	; верхняя-правая четверть
		ld	(CrdXPrnSymbol), hl ; Координаты печати	символа
		ld	a, 26h ; '&'
		call	PrintMessage1_A	; Печать сообщения из группы 1 в буфере/на экране
					; вх: A	- номер	сообщения
		ld	hl, 1208h	; нижняя-правая	четверть
		ld	(CrdXPrnSymbol), hl ; Координаты печати	символа
		ld	a, 24h ; '$'
		call	PrintMessage1_A	; Печать сообщения из группы 1 в буфере/на экране
					; вх: A	- номер	сообщения
		ld	hl, 1607h
		ld	a, (TimeWorkECM) ; оставшееся время работы системы
					; =0 ECM выключена
					;
		and	a
		jr	z, loc_A689
		ld	de, dataECMon	; ECM on (4 байта)
		jr	loc_A68C
; ---------------------------------------------------------------------------

loc_A689:				; CODE XREF: PrnDangerEcmDock+22j
		ld	de, dataECMoff	; ECM off (4 байта)

loc_A68C:				; CODE XREF: PrnDangerEcmDock+27j
		call	loc_A6A9	; Печать состояния ECM системы,	значка станции и т.д. в	зависимости от сообщения и координат
					; HL - координаты печати
					; DE - адрес сообщения
		ld	hl, 1615h
		ld	a, (CoriolisNear) ; <>0	вблизи станции,	можно стыковаться
		and	a
		jr	z, loc_A69D
		ld	de, dataDocking	; символ значка	присутствия вблизи станции (4 байта)
		jr	loc_A6A0
; ---------------------------------------------------------------------------

loc_A69D:				; CODE XREF: PrnDangerEcmDock+36j
		ld	de, dataNoDocking ; символ значка отсутствия вблизи станции (4 байта)

loc_A6A0:				; CODE XREF: PrnDangerEcmDock+3Bj
		call	loc_A6A9	; Печать состояния ECM системы,	значка станции и т.д. в	зависимости от сообщения и координат
					; HL - координаты печати
