		ld	hl, loc_BBBF
		ld	(hl), 0A9h ; 'й' ; xor c
		ret
; ---------------------------------------------------------------------------

loc_A6A9:				; CODE XREF: PrnDangerEcmDock:loc_A68Cp
					; PrnDangerEcmDock:loc_A6A0p
		call	loc_A6AC	; Печать состояния ECM системы,	значка станции и т.д. в	зависимости от сообщения и координат
					; HL - координаты печати
					; DE - адрес сообщения

loc_A6AC:				; Координаты печати символа
		ld	(CrdXPrnSymbol), hl
