; =============== S U B	R O U T	I N E =======================================

; Использование	ракеты

UseMissile:				; CODE XREF: Process_MissBombEPod+9p
		ld	a, (PilotMissiles) ; Колво ракет
		and	a
		ret	z
		ld	a, (Missile1)	; =0 ракета не нацелена
					; =1 ракета готова к захвату цели
					; =2 ракета на что-то нацелена
		cp	1
		jr	nz, loc_A72E
		ld	hl, nObjMissile	;  =0 было включено нацеливание	ракеты
					; <>0 обратный номер объекта на	который	нацелена ракета	(8 - 0й	слот)
		ld	a, (hl)
		and	a
		jr	nz, loc_A72E
		ld	a, (ObjInTarget) ; <>0 в прицеле что-то	есть (номер объекта???)
		and	a
		jr	z, loc_A72E
		ld	(hl), a
		ld	hl, Missile1	; =0 ракета не нацелена
					; =1 ракета готова к захвату цели
					; =2 ракета на что-то нацелена
		ld	(hl), 2
		ld	hl, 70h	; 'p'   ; звук захвата цели
		ld	de, 60h	; '`'
		call	3B5h

loc_A72E:				; CODE XREF: UseMissile+Aj
					; UseMissile+11j ...
		ld	hl, ControlKey3	; 7,=1 - C     -- Docking Computer
					; 6,=1 - Q     -- Escape Pod
					; 5,=1 - W     -- Energy Bomb
					; 4,=1 - E     -- ECM System
					; 3,=1 - U     -- UnTarget
					; 2,=1 - F     -- Fire Missile
					; 1,=1 - T     -- Target Missile
					; 0,=1 - A     -- Fure Laser
		ld	a, (hl)
		ld	hl, Missile1	; =0 ракета не нацелена
					; =1 ракета готова к захвату цели
					; =2 ракета на что-то нацелена
		srl	a
		srl	a
		jr	c, MissileTarget ; попытка нацеливания ракеты (кнопка T)
		srl	a
		jr	c, MissileFire	; попытка запуска ракеты (кнопка F)
		srl	a
		jr	c, MissileUntarget ; снятие нацеливания	ракеты (кнопка U)
		ret
; ---------------------------------------------------------------------------

MissileTarget:				; CODE XREF: UseMissile+33j
		ld	a, (hl)		; попытка нацеливания ракеты (кнопка T)
		cp	2
		ret	z
		ld	(hl), 1
		xor	a
		ld	(nObjMissile), a ;  =0 было включено нацеливание ракеты
					; <>0 обратный номер объекта на	который	нацелена ракета	(8 - 0й	слот)
		ret
; ---------------------------------------------------------------------------

MissileUntarget:			; CODE XREF: UseMissile+3Bj
		ld	(hl), 0		; снятие нацеливания ракеты (кнопка U)
		ret
; ---------------------------------------------------------------------------

MissileFire:				; CODE XREF: UseMissile+37j
		ld	a, (hl)		; попытка запуска ракеты (кнопка F)
		cp	2
		ret	nz
		ld	a, (nObjMissile) ;  =0 было включено нацеливание ракеты
					; <>0 обратный номер объекта на	который	нацелена ракета	(8 - 0й	слот)
		add	a, a
		add	a, a
		add	a, a
		add	a, a
		or	2		; a=xxxx0010=#x2
		push	hl
		call	CallFunctionObj	; вх: А	- бит 3-0 номер	функции-обработчика?
					; =0 SetRndShip
					; =1 Set3_4Targons
					; =2 SetObjMissile
					; =3 *not used
					; =4 ShipSetShip
					; =5 Set2Alloys
					; =6 SetCargo
					; =7 SetShipEscapePod
					; =8 Set2Minerals
					; =9 SetShip4Intro
					;
					;	  бит 7-4 номер	=0 - slave
					;			=1 - alloys
					;			=2 - контейнер
					;			=3 - alien items
					;			=4 - астероид
					;			=5 - астероид
					;			=6 - полисмен
					;			=7 - кобра
					;			=8 - питон
					;			=9 - питон
					;			=A - кобра
					;			=B - асп
					;			=C - ферделанс
					;			=D - таргон
					;			=E - сидевиндер
					;			=F - крайт
					;
		pop	hl
		jr	z, loc_A76C	; если успешно
		ld	hl, MissileJammed ; 7,=1 ракету	не получилось запустить
					; 6-0,=	координата Y печти сообщения
					;
					; +1 номер сообщения
		set	7, (hl)
		ret
; ---------------------------------------------------------------------------

loc_A76C:				; CODE XREF: UseMissile+5Ej
		ld	(hl), 0
		ld	hl, nBeepFX	; какой	звук надо включить
					; =#00 звуков нет(не звучат)
					;  0,=1	взорвана энерго	бомба
					;  1,=1	запущена ракета
					;  2,=1	врезаемся в объект/объект уничтожен
					;  3,=1	выстрел	из лазера
					;  4,=1	выстрелили из дазера
					;  5,=1	ECM работает
					;  6,=1	попадание из лазера по игроку/повреждения при стыковке
					;  7,=1
		set	1, (hl)
		ld	hl, PilotMissiles ; Колво ракет
		dec	(hl)
		jp	PrintMissiles	; Печать ракет на кокпите
; End of function UseMissile		; Вх:  ---
					; Вых: b= #00
					;      hl,de,c,a - не определены
; ---------------------------------------------------------------------------
byte_A77A:	db 0			; DATA XREF: UseEscapePodo
					; UseEscapePod+1Fw

; =============== S U B	R O U T	I N E =======================================

; использование	спасательной капсулы

UseEscapePod:				; CODE XREF: Process_MissBombEPod+Cp
		ld	hl, byte_A77A
		ld	a, (hl)
		and	a
		jr	z, loc_A788	; Запуск Escape	Pod
		dec	a
		ld	(hl), a
		jp	z, loc_7102
		ret
; ---------------------------------------------------------------------------

loc_A788:				; CODE XREF: UseEscapePod+5j
		ld	a, (ControlKey3) ; Запуск Escape Pod
		bit	6, a
		ret	z
		ld	a, (PilotEscapePod) ; Escape pod
		and	a
		ret	z
		ld	a, (InFreeSpace) ; <>0 между системами (перехват F)
		and	a
		ret	nz
		ld	a, 18h
		ld	(byte_A77A), a
		ld	hl, 10h
		ld	(DeltaSpeed), hl ; скорость
					; #0000..#1FFF
		xor	a
		ld	(PilotLegalStatus), a ;	Правовой статус	пилота
					;  0 - clean
					;  1..31h offender
					;  32h..FFh fugitiv
		ld	(PilotEscapePod), a ; Escape pod
		ld	hl, PilotRnd	; 23 ????
		ld	b, 11h

loc_A7AF:				; CODE XREF: UseEscapePod+36j
		ld	(hl), a
		inc	hl
		djnz	loc_A7AF
		ld	hl, PilotExtWeapon ; +93 наличие доп вооружения
					;   7,=1 - ECM Jammer
					;   6,=1 - Cloaking device
					;   5,=1 - нельзя купить товары(в трюме	беженцы)
					;   4
					;   3 =1 3я миссия была	выполнена
					;   2 =1 - третья миссия выполнена
					;   1 =1 - второя миссия выполнена
					;   0 =1 - первая миссия выполнена
		ld	a, (hl)
		and	11011111b
		ld	(hl), a
		ld	hl, PilotFreeCargo ; Оставшаяся	грузоподъемность корабля
		ld	a, (PilotLargeCargo) ; +49 large cargo bay
					;   =#59 если взята 1я миссия
		and	a
		ld	a, 14h
		jr	z, loc_A7C7
		ld	a, 23h ; '#'

loc_A7C7:				; CODE XREF: UseEscapePod+48j
		ld	(hl), a
		ld	a, 17h
		call	CallFunctionObj	; вх: А	- бит 3-0 номер	функции-обработчика?
					; =0 SetRndShip
					; =1 Set3_4Targons
					; =2 SetObjMissile
					; =3 *not used
					; =4 ShipSetShip
					; =5 Set2Alloys
					; =6 SetCargo
					; =7 SetShipEscapePod
					; =8 Set2Minerals
					; =9 SetShip4Intro
					;
					;	  бит 7-4 номер	=0 - slave
					;			=1 - alloys
					;			=2 - контейнер
					;			=3 - alien items
					;			=4 - астероид
					;			=5 - астероид
					;			=6 - полисмен
					;			=7 - кобра
					;			=8 - питон
					;			=9 - питон
					;			=A - кобра
					;			=B - асп
					;			=C - ферделанс
					;			=D - таргон
					;			=E - сидевиндер
					;			=F - крайт
					;
		ld	a, (Pilot_CrdXSystem) ;	координата X текущей системы
		ld	(Pilot_CrdXTarget), a ;	координата X малого курсора на большой карте
		ld	a, (Pilot_CrdYSystem) ;	координата Y текущей системы
		ld	(Pilot_CrdYTarget), a ;	+103 (последний	байт для сохранения)
					; координата Y малого курсора на большой карте
		ret
; End of function UseEscapePod

