					; координата Y малого курсора на большой карте
MissileJammed:	db 8			; DATA XREF: UseMissile+60o
					; SetPrnMsgOnVS+17o ...
					; 7,=1 ракету не получилось запустить
					; 6-0,=	координата Y печти сообщения
					;
					; +1 номер сообщения
		db 0C9h
ShipLaunchMisile:db 7			; DATA XREF: ReactionObject+7Co
					; 7,=1 противник выпустил ракету
		db 78h
UntargetMissile:db 9			; DATA XREF: OffTargetMissiles+39o
					; 7,=1 ракета снята с нацеливания (не игроком)
		db 0C8h	; ╚
DestDeviceCargo:db 2			; DATA XREF: DecEnergyShieldFR+60o
					; 7,=1 уничтожено какое-то оборудование/груз
					;   -> в nMsgDamage номер сообщения
		db 0FDh	; ¤
CashBonus:	db 0Ch			; DATA XREF: AddCashObj+Ao
					; 7,=1 был уничтожен объект
					;   =1 был получен денежный бонус (размер бонуса в LastBonusCash)
		db 0E2h	; т
CargoFound:	db 0Bh			; DATA XREF: AddFoundCargo:loc_A8CAo
					;  7,1 =1 подобран груз	в космосе
		db 0			; номер	сообщения подобранного груза
RatingRightOn:	db 6			; DATA XREF: IncBattleRating+Do
					; 7,=1 было увеличение боевого рейтинга
					; выдача сообщения right on commander
		db 65h
FlgPrnNumber:	db 1			; DATA XREF: PrintNumber_A+Cw
					; PrintNumber_A+2Dr ...
					; =#00 печатать	число с	ведущими нулями	(иначе с пробелами)
DigitsInNumber:	db 0			; DATA XREF: PrintFuelToPlanet+Ew
					; PrnOneProduct+22w ...
					; ;количество печатаемых знаков	числа (дополняется слева пробелами или нулями)
NoFuel:		db 0Ah			; DATA XREF: SetFuelZero+5o
					; 7,=1 - топлива было обнулено
		db 1Fh			; номер	сообщения об обнулении топлива
FlgPrnSym1:	db 0			; DATA XREF: SetFlgPrn_1xx:loc_B942w
					; PrintSymbol_A+9r ...
					; флаг печати =1 - печатать заглавными буквами
					;
					; ;флаги регистра печати
					; 1xx все заглавными
					; 2x0 все строчными
					; 2x1 первая буква сообщения заглавная
					;
					; 000 первое слово строчное, остальные с заглавной
					; 001 каждое слово с заглавной
					; 010 каждое слово с заглавной
					; 011 каждое слово с заглавной
					;
FlgPrnSym2:	db 1			; DATA XREF: PrintNameOnLocalMap+5Ew
					; PrnCrd_CRLF+2w ...
					; флаг печати
					; =1 был перевод строки
FlgPrnSym3:	db 0			; DATA XREF: SetFlgPrn_xx1+2w
					; PrintSymbol_A+10r ...
					; флаг печати =1 - первая буква	заглавная
FlgPrnDescr:	db 0			; DATA XREF: PrintSymbol_A:loc_BB4Fr
					; ClearDescrMsg+2w ...
					; =1 генерим строку с описанием	планеты
		db 0
		db 0
; ---------------------------------------------------------------------------
		jp	SetFuelZero	; Обнуление топлива
					; Вх:  ---
					; Вых: b,a - не	определены
; ---------------------------------------------------------------------------
nObjMissile:	db 0			; DATA XREF: UseMissile+Co
					; UseMissile+45w ...
					;  =0 было включено нацеливание	ракеты
					; <>0 обратный номер объекта на	который	нацелена ракета	(8 - 0й	слот)
; ---------------------------------------------------------------------------
		jp	AddFoundCargo	; Добавить найденный контейнер к грузу
					; Вх:  a - тип груза в контейнере
					;	=#FF cloaking device
					;	=0..16 груз
					; Вых: hl,de,b,a - не определены
; ---------------------------------------------------------------------------
		jp	AddCashObj	; Увеличение суммы денег
					; Вх:  de - количество денег (от 0.1 до	6553.5)
					; Вых: hl,de - не определены
; ---------------------------------------------------------------------------
		jp	IncBattleRating	; Увеличение боевого рейтинга
					; Вх:  de - приращение рейтинга
					; Вых: hl,de - не определены
; ---------------------------------------------------------------------------
		db 0A7h	; з
		db 0CDh	; ═
		db 0E4h	; ф
; ---------------------------------------------------------------------------
		jp	HeavyDamage	; сильный урон.	уничтожение чего-либо (топливо/груз и т.п.)

; =============== S U B	R O U T	I N E =======================================

; наден	Cloaking device

sub_A8AA:				; CODE XREF: AddFoundCargo+3j
		ld	hl, PilotExtWeapon ; +93 наличие доп вооружения
					;   7,=1 - ECM Jammer
					;   6,=1 - Cloaking device
					;   5,=1 - нельзя купить товары(в трюме	беженцы)
					;   4
					;   3 =1 3я миссия была	выполнена
					;   2 =1 - третья миссия выполнена
					;   1 =1 - второя миссия выполнена
					;   0 =1 - первая миссия выполнена
		set	6, (hl)
		ld	hl, PilotRating2
		inc	(hl)
		ld	a, 7Dh ; '}'    ; номер сообщения
		jr	loc_A8CA
; End of function sub_A8AA


; =============== S U B	R O U T	I N E =======================================

; Добавить найденный контейнер к грузу
; Вх:  a - тип груза в контейнере
;	=#FF cloaking device
;	=0..16 груз
; Вых: hl,de,b,a - не определены

AddFoundCargo:				; CODE XREF: RAM:A89Bj
					; CollisionWithObj:loc_EAD5j
		push	af
		cp	0FFh
		jr	z, sub_A8AA	; наден	Cloaking device
		ld	hl, PilotFreeCargo ; Оставшаяся	грузоподъемность корабля
		dec	(hl)
		ld	e, a
		ld	d, 0
		ld	hl, PilotCargo	; 24 Наличие груза в корабле (17 байт)
					; +00 Food
		add	hl, de
		inc	(hl)
		add	a, 0D0h	; '╨'   ; номер сообщения

loc_A8CA:				; CODE XREF: sub_A8AA+Bj
		ld	hl, CargoFound	;  7,1 =1 подобран груз	в космосе
		set	7, (hl)
		inc	hl
		ld	(hl), a
		pop	af		; изменение правового статуса если нужно
		ld	b, 1

SetLegalStatCargo:			; CODE XREF: sub_B3A1+38p
		cp	0Ah
		jr	z, loc_A8E1
		cp	3
		jr	z, loc_A8DF
		cp	6
		ret	nz

loc_A8DF:				; CODE XREF: AddFoundCargo+23j
		sla	b

loc_A8E1:				; CODE XREF: AddFoundCargo+1Fj
		sla	b
		ld	hl, PilotLegalStatus ; Правовой	статус пилота
					;  0 - clean
					;  1..31h offender
					;  32h..FFh fugitiv
		ld	a, (hl)
		add	a, b
		jr	nc, loc_A8EC
		ld	a, 0FFh

loc_A8EC:				; CODE XREF: AddFoundCargo+31j
		ld	(hl), a
		ret
; End of function AddFoundCargo


; =============== S U B	R O U T	I N E =======================================

; Увеличение боевого рейтинга
; Вх:  de - приращение рейтинга
; Вых: hl,de - не определены

IncBattleRating:			; CODE XREF: RAM:A8A1j
					; MoveAllObjects+140p ...
		ld	hl, PilotRating0 ; 13 Боевой рейтинг пилота
					;  0,0,0...255,8,0 Harmless
					;  0,9,0...255,8,0 M.Harmless
					;  0,17,0...255,16,0 Poor
					;  0,33,0...255,32,0 Average
					;  0,65,0...255,64,0 Above Average
					;  0,129,0...255,128,0 Competent
					;  0,0,3...255,255,2 Dangerous
					;  0,0,11...255,255,10 Deadly
					;  0,0,26...255,255,25 Elite
		ld	a, (hl)
		add	a, e
		ld	(hl), a
		inc	hl
		ld	a, (hl)
		adc	a, d
		ld	(hl), a
		ret	nc
		inc	hl
		inc	(hl)
		ld	hl, RatingRightOn ; 7,=1 было увеличение боевого рейтинга
					; выдача сообщения right on commander
		jr	loc_A90D
; End of function IncBattleRating


; =============== S U B	R O U T	I N E =======================================

; Увеличение суммы денег
; Вх:  de - количество денег (от 0.1 до	6553.5)
; Вых: hl,de - не определены

AddCashObj:				; CODE XREF: RAM:A89Ej
					; MoveAllObjects+133p
		ld	a, d
		or	e
		ret	z
		ld	(LastBonusCash), de ; денежное вознаграждение за уничтожение в бою
		call	IncCASH		; Добавление денег
					; Вх:  de - количество денег (от 0.1 до	6553.5)
					; Вых: hl,de - не определены
		ld	hl, CashBonus	; 7,=1 был уничтожен объект
					;   =1 был получен денежный бонус (размер бонуса в LastBonusCash)

loc_A90D:				; CODE XREF: IncBattleRating+10j
		set	7, (hl)
		ret
; End of function AddCashObj

