					; MenuSaveLoad+101o
		db 0, 0, 0, 0, 0, 0, 0,	0 ; для	сохранения в памяти последней загруженной игры
		db 0, 0, 0, 0, 0E8h, 3,	0, 0
		db 0, 0, 0, 0, 0, 0, 0,	0
		db 0, 0, 0, 0, 0, 0, 0,	0
		db 14h,	1, 0, 0, 0, 0, 46h, 3
		db 0, 0, 0, 0, 0, 0, 0,	0
		db 0, 0, 0, 0, 4Ah, 5Ah, 48h, 2
		db 53h,	0B7h, 38h, 0ADh, 9Ch, 14h, 1Dh,	15h
		db 5, 3, 11h, 12h, 1Ah,	0Eh, 27h, 8
		db 0, 0, 0Ah, 19h, 0, 0, 3Dh, 0Eh
		db 11h,	0Ch, 0,	0, 0
byte_A96D:	db 27h,	8, 1		; DATA XREF: InitGame+2Co
		db 2Ah,	4Dh, 8Fh	; координаты солнца при	вылете со станции
		db 0F2h, 88h, 5

; =============== S U B	R O U T	I N E =======================================


InitGame:				; CODE XREF: BeginGame+BCp
		call	ResetBattleMessages ; Обнуление	всех сообщений во время	полёта
					; Вх: ---
					; Вых: a =#00
					;      b =#00
					;      hl,MissileJammed+9
		call	RestorePilotFromMemory ; Восстановление	данных пилота из памяти
					; Вх:  ---
					; Вых: bc =#0000
					;      hl,de - не определены
		ld	a, (Pilot_CrdXSystem) ;	координата X текущей системы
		ld	(Pilot_CrdXTarget), a ;	координата X малого курсора на большой карте
		ld	a, (Pilot_CrdYSystem) ;	координата Y текущей системы
		ld	(Pilot_CrdYTarget), a ;	+103 (последний	байт для сохранения)
					; координата Y малого курсора на большой карте
		call	SearchPlanetNearCursor ; Поиск ближайшей к курсору планеты, формирование данных	о ней
					;   и установка	её текущей целью
		ld	hl, Amount
		ld	(hl), 0
		push	hl
		call	GenerateAnotherPrice ; генерация цен без кол-ва	на станции
		pop	hl
		ld	(hl), 77h ; 'w'
		ld	hl, plNameDest	; название планеты на которую настроен корабль
		ld	de, PlanetPresent ; название активной планеты
		ld	bc, 8
		ldir
		ld	hl, byte_A96D	; координаты солнца при	вылете со станции
		ld	de, SunCrd	; данные для печати солнца длина 9 байт
					; crd low x planet
		ld	bc, 9
		ldir
		xor	a
		ld	(JumpCountdown), a ; обратный отсчет до	прыжка
					; =#00 отсчёта еще нет
		ret
; End of function InitGame

