		ld	a, (DataOfPlanet1+1)

maps_cng_05:				; DATA XREF: Cmd_O_LocalMap+1Dw
		cp	0
		jr	c, loc_AA68

maps_cng_06:				; DATA XREF: Cmd_O_LocalMap+28w
