		jr	nc, loc_AA68
		ld	a, (DataOfPlanet+1) ; данные для генерации планеты

maps_cng_07:				; DATA XREF: Cmd_O_LocalMap+33w
		cp	0
		jr	c, loc_AA68

maps_cng_08:				; DATA XREF: Cmd_O_LocalMap+3Ew
		cp	0
		jr	nc, loc_AA68

loc_AA63:				; CODE XREF: PrnStarsNameOnMap:loc_AA63p
					; DATA XREF: PrnStarsNameOnMapw
		call	$
		jr	loc_AA6B
