loc_AA68:				; CODE XREF: PrnStarsNameOnMap+Ej
					; PrnStarsNameOnMap+12j ...
		call	NextPlanetData	; модификация данных для генерации планеты
					; вх:  ----
					; вых: hl,de,b,a - ????

loc_AA6B:				; CODE XREF: PrnStarsNameOnMap+22j
