; =============== S U B	R O U T	I N E =======================================

; Расчет координат и печати звезды и адреса в дисплейном файле
; вх:  ---
; вых: c  - координата X печати	звезды
;      b  - координата Y печати	звезды
;      hl - адрес в дисплейном файле
;      a  - номер бита в байте

CalcCrdAdrPrnStar:			; CODE XREF: PrintStarOnLocalMapp
					; PrintNameOnLocalMapp
		ld	c, 61h ; 'a'
		ld	a, (Pilot_CrdXSystem) ;	координата X текущей системы
		ld	b, a
		ld	a, (DataOfPlanet1+1)
		sub	b
		add	a, a
		add	a, a
		add	a, c
		sub	3
		ld	c, a
		ld	d, 60h ; '`'
		ld	a, (Pilot_CrdYSystem) ;	координата Y текущей системы
		ld	b, a
		ld	a, (DataOfPlanet+1) ; данные для генерации планеты
		sub	b
		add	a, a
		neg
		add	a, d
		sub	0Eh
		ld	b, a
		push	bc
		call	22AAh
		pop	bc
		ret
; End of function CalcCrdAdrPrnStar


; =============== S U B	R O U T	I N E =======================================

; Печать одной звезды на локальной карте
; вх:  (DataOfPlanet) -	данные о планете
; вых: (DataOfPlanet) -	данные о следующей планете
;      hl,de,bc,a - ????

PrintStarOnLocalMap:			; DATA XREF: Cmd_O_LocalMap+5Do
		call	CalcCrdAdrPrnStar ; Расчет координат и печати звезды и адреса в	дисплейном файле
					; вх:  ---
					; вых: c  - координата X печати	звезды
					;      b  - координата Y печати	звезды
					;      hl - адрес в дисплейном файле
					;      a  - номер бита в байте
		ld	(loc_AAB5+1), a
		ld	de, DataOfStars	; спрайты для звезд на локальной карте
		ld	a, (DataOfPlanet2+1)
		and	18h
		add	a, e
		ld	e, a
		jr	nc, loc_AAA9
		inc	d

loc_AAA9:				; CODE XREF: PrintStarOnLocalMap+10j
		ld	b, 8

loc_AAAB:				; CODE XREF: PrintStarOnLocalMap+49j
		push	bc
		ld	a, (loc_AAB5+1)
		and	a
		ld	a, (de)
		ld	c, 0
		jr	z, loc_AABD

loc_AAB5:				; DATA XREF: PrintStarOnLocalMap+3w
					; PrintStarOnLocalMap+16r
		ld	b, 1

loc_AAB7:				; CODE XREF: PrintStarOnLocalMap+25j
		srl	a
		rr	c
		djnz	loc_AAB7

loc_AABD:				; CODE XREF: PrintStarOnLocalMap+1Dj
		ld	b, a
		ld	a, (hl)
		xor	b
		ld	(hl), a
		inc	hl
		ld	a, (hl)
		xor	c
		ld	(hl), a
		dec	hl
		ld	a, h
		inc	a
		and	7
		jr	nz, loc_AADC
		ld	a, h
		and	0F8h ; '°'
		ld	h, a
		ld	a, 20h ; ' '
		add	a, l
		ld	l, a
		jr	nc, loc_AADD
		ld	a, 8
		add	a, h
		ld	h, a
		jr	loc_AADD
; ---------------------------------------------------------------------------

loc_AADC:				; CODE XREF: PrintStarOnLocalMap+34j
		inc	h

loc_AADD:				; CODE XREF: PrintStarOnLocalMap+3Ej
					; PrintStarOnLocalMap+44j
		inc	de
		pop	bc
		djnz	loc_AAAB
		jp	NextPlanetData	; модификация данных для генерации планеты
; End of function PrintStarOnLocalMap	; вх:  ----
					; вых: hl,de,b,a - ????
; ---------------------------------------------------------------------------
		db 0
		db 0
byte_AAE6:	db 0			; DATA XREF: PrintNameOnLocalMap+14w

; =============== S U B	R O U T	I N E =======================================

; Печать названия одной	звезды на локальной карте
; вх:  (DataOfPlanet) -	данные о планете
; вых: (DataOfPlanet) -	данные о следующей планете
;      hl,de,bc,a - ????

PrintNameOnLocalMap:			; DATA XREF: Cmd_O_LocalMap+63o
		call	CalcCrdAdrPrnStar ; Расчет координат и печати звезды и адреса в	дисплейном файле
					; вх:  ---
					; вых: c  - координата X печати	звезды
					;      b  - координата Y печати	звезды
					;      hl - адрес в дисплейном файле
					;      a  - номер бита в байте
		push	bc
		call	GeneratePlanetName ; генерация названия	планеты	и подготовка данных для	генерации следующего названия
					; вх:  (DataOfPlanet) -	данные о планете
					; вых: (TempName) - название планеты
					;      (DataOfPlanet) -	данные о следующей планете
					;      hl,de,bc,a - ????
		ld	bc, 9
		ld	hl, TempName	; для генерации	названия планеты
		xor	a
		cpir
		ld	a, c
		xor	7
		inc	a
		ld	(byte_AAE6), a
		pop	bc
		ld	a, c
		rra
		rra
		rra
		and	1Fh
		inc	a
		ld	(CrdXPrnSymbol), a ; Координаты	печати символа
		ld	a, b
		srl	a
		srl	a
		srl	a
		jr	nc, loc_AB13
		inc	a

loc_AB13:				; CODE XREF: PrintNameOnLocalMap+29j
		neg
		add	a, 16h
		ld	(CrdYPrnSymbol), a
		call	loc_AB34
		ret	c
		ld	hl, CrdYPrnSymbol
		dec	(hl)
		ld	a, (hl)
		cp	3
		jr	c, loc_AB2B
		call	loc_AB34
		ret	c

loc_AB2B:				; CODE XREF: PrintNameOnLocalMap+3Ej
		ld	hl, CrdYPrnSymbol
		inc	(hl)
		inc	(hl)
		ld	a, (hl)
		cp	17h
		ret	nc

loc_AB34:				; CODE XREF: PrintNameOnLocalMap+33p
					; PrintNameOnLocalMap+40p
		ld	a, (CrdYPrnSymbol)
		ld	hl, BufferCrdY	; для печати названий планет на	локальной карте
		call	Calc_HLaddA	; Вых: d =0
					;      e=a
		ld	a, (hl)
		and	a
		ret	nz
		ld	a, 0FFh
		ld	(hl), a
		ld	a, 1
		ld	(FlgPrnSym2), a	; флаг печати
					; =1 был перевод строки
		ld	hl, TempName	; для генерации	названия планеты
		jp	PrintMessage_HL	; печать сообщения
; End of function PrintNameOnLocalMap	; вх:  hl - адрес начала сообщения
					; вых: cy=1
					;      a=#00
					;      hl - адрес конца	сообщения
					;      hl,de,bc	- ????

; =============== S U B	R O U T	I N E =======================================

; Печать меню карты галактики

Cmd_I_GlobalMap:			; CODE XREF: RAM:A7E3j
		call	ClsAndPrintRamk	; Очистка экрана с атрибутами #07,
					; прорисовка рамки вокруг всего	экрана,
					; установка начальных координат	печати текста
					; вх:  ---
					; вых: (LLA80D)	- координаты печати
					;      hl,de,bc,a - ????
		ld	a, 18h
		ld	(0C0h),	a
		ld	a, 98h ; 'Ш'
		ld	(CrdYDownGalaxyMap), a ; координата нижней границы карты(влияет	только на отображение курсора на карте)
		ld	a, 10h
		ld	(CursorWidth), a ; ширина курсора
		ld	a, (Pilot_CrdXSystem) ;	координата X текущей системы
		ld	(PrnCrdXCursor), a ; координата	X малого курсора на экране
		ld	a, (Pilot_CrdYSystem) ;	координата Y текущей системы
		srl	a
		add	a, 18h
		ld	(PrnCrdYCursor), a ; координата	Y малого курсора на экране
		call	PrintCursorOnScr ; Печать курсора на экране карты галактики
					; Вх:  (PrnCrdXCursor) - координата X печати [1..#FE]
					;      (PrnCrdYCursor) - координата Y печати
					;      (CursorWidth) - ширина курсора
					; Вых: hl,de,bc,a - не определены
		ld	a, (Pilot_Fuel)	; Топливо
		srl	a
		srl	a
		ld	(RadiusCircleMap), a
		call	PrintCircleMap	; Печать на карте галактики круга радиуса полета на который хватает горючего
					; Вх:  (PrnCrdXCursor) - координаты центра окружности
					;      (RadiusCircleMap) - радиус окружности
					; Вых: a =#00
					;      hl,de,bc	- не определены
		ld	hl, 4060h
		ld	a, 3
		call	ClearZnkLines	; Быстрая очистка нескольких знакоместных строк	экрана в пределах сегмента
					; Вх:  hl - адрес конца	экранной области +2
					;      a  - кол-во строк
		ld	hl, 5100h
		ld	a, 5
		call	ClearZnkLines	; Быстрая очистка нескольких знакоместных строк	экрана в пределах сегмента
					; Вх:  hl - адрес конца	экранной области +2
					;      a  - кол-во строк
		call	PrintRamk
		ld	a, 0Ah
		ld	(CursorWidth), a ; ширина курсора
		call	PrintSmallCursOnMap ; Печать малого курсора на карте глобальной/локальной
					; Вх:  (CursorWidth) - ширина курсора
					;      (Pilot_CrdXTarget),(Pilot_CrdYTarget) - координаты курсора на карте
					; Вых: hl,de,bc,a - не определены
		ld	a, 0C7h	; '╟'
		call	PrintHeaderMap	; печать шапки карты галактики
					;  A - номер сообщения
		ld	a, 17h
		ld	hl, 5A60h
		ld	b, 0A0h	; 'а'
		call	Fill_HL_A_Len_B
		ld	hl, 5060h
		call	PrintHorLine	; печать горизонтальной	линии
					; вх: HL - адрес на экране
		call	CopyGalaxyToPlanet ; копирование данных	о галактике в рабочую область
					; вх:  ----
					; вых: bc=#0000
		ld	b, 0

loc_ABB5:				; CODE XREF: Cmd_I_GlobalMap+6Fj
		push	bc
		call	PrnStarOnGalaxyMap ; Расчет координат и	печать на карте	галактики одной	звезды(точки)
					; вх:  (DataOfPlanet) -	данные о планете
		call	NextPlanetData	; модификация данных для генерации планеты
					; вх:  ----
					; вых: hl,de,b,a - ????
		pop	bc
		djnz	loc_ABB5
		ret
; End of function Cmd_I_GlobalMap


; =============== S U B	R O U T	I N E =======================================

; Быстрая очистка нескольких знакоместных строк	экрана в пределах сегмента
; Вх:  hl - адрес конца	экранной области +2
;      a  - кол-во строк

ClearZnkLines:				; CODE XREF: Cmd_I_GlobalMap+37p
					; Cmd_I_GlobalMap+3Fp
		di
		ld	(SaveSP9), sp
		ld	(SaveA1), a
		ld	c, 8
		ld	de, 0

loc_ABCD:				; CODE XREF: ClearZnkLines+1Bj
		ld	sp, hl
		ld	a, (SaveA1)

loc_ABD1:				; CODE XREF: ClearZnkLines+17j
		ld	b, 10h

loc_ABD3:				; CODE XREF: ClearZnkLines+14j
		push	de
		djnz	loc_ABD3
		dec	a
		jr	nz, loc_ABD1
		inc	h
		dec	c
		jr	nz, loc_ABCD
		ld	sp, (SaveSP9)
		ei
		ret
; End of function ClearZnkLines

; ---------------------------------------------------------------------------
SaveA1:		db 0			; DATA XREF: ClearZnkLines+5w
					; ClearZnkLines+Er
SaveSP9:	dw 0			; DATA XREF: ClearZnkLines+1w
					; ClearZnkLines+1Dr

; =============== S U B	R O U T	I N E =======================================

; Расчет координат и печать на карте галактики одной звезды(точки)
; вх:  (DataOfPlanet) -	данные о планете

PrnStarOnGalaxyMap:			; CODE XREF: Cmd_I_GlobalMap+68p
		ld	a, (DataOfPlanet+1) ; данные для генерации планеты
		srl	a
		xor	7Fh ; ''
		add	a, 18h
		ld	b, a
		ld	a, (DataOfPlanet1+1)
		ld	c, a
		call	22AAh		; расчет экранного адреса
					;   вх B - crdY, C - crdX
					;  вых hl - адрес
					;	A - смещение этой точки	от левой границы байта
		xor	7
		add	a, a
		add	a, a
		add	a, a
		or	0C0h ; '└'
		ld	de,  loc_AC04+1
		ld	(de), a		; корректировка	команды	для установки точки
		ld	b, 0

loc_AC04:				; DATA XREF: PrnStarOnGalaxyMap+18o
		set	1, b
		ld	a, (hl)
		xor	b
		ld	(hl), a
		ret
; End of function PrnStarOnGalaxyMap


; =============== S U B	R O U T	I N E =======================================

; Установка A=0

Set_A_zero:				; CODE XREF: Cmd_O_LocalMap+1Ap
					; Cmd_O_LocalMap+30p
		xor	a
		ret
; End of function Set_A_zero


; =============== S U B	R O U T	I N E =======================================

; Установка A=0FFh

set_A_FFh:				; CODE XREF: Cmd_O_LocalMap+25p
					; Cmd_O_LocalMap+3Bp
		ld	a, 0FFh
		ret
; End of function set_A_FFh

; ---------------------------------------------------------------------------
PlanetData0:	dw 0			; DATA XREF: GenerateInfoPlanet+3w
					; Cmd_P_InfoPlanet+A0o	...
					; 6 байт для генерации данных о	планете
PlanetData1:	dw 0			; DATA XREF: GenerateInfoPlanet+12w
					; Cmd_P_InfoPlanet:PrnDescrPlanetr ...
PlanetData2:	dw 0			; DATA XREF: GenerateInfoPlanet+77w
					; Cmd_P_InfoPlanet+BEr	...
DataOfPlanet:	dw 0			; DATA XREF: GeneratePlanetName+Dr
					; GeneratePlanetName:ModifyPlanetDatar	...
					; данные для генерации планеты
DataOfPlanet1:	dw 0			; DATA XREF: GeneratePlanetName+4Ar
					; GeneratePlanetName+50r ...
DataOfPlanet2:	dw 0			; DATA XREF: GeneratePlanetName:loc_AD90r
					; GeneratePlanetName+56r ...
DataOfPlanetSv:	db 0, 0, 0, 0, 0, 0	; DATA XREF: SavePlanetData+3o
					; RestorePlanetDatao
					; копия	данных для генерации планет
					; выбранная планета
DescrPlanetData:dl 0			; DATA XREF: Cmd_P_InfoPlanet+BBw
					; NextDescrPlanetr ...
InputText:	db 4Ah,	41h, 4Dh, 45h, 53h, 4Fh, 4Eh, 9, 0 ; DATA XREF:	FindPlanetByName+Do
					; Cmd_R_FindPlanetName+4o ...
					; введенный тексто (имя	пилота при выгрузке/загрузке, имя планеты при поиске)
TempName:	db 54h,	45h, 4Dh, 50h, 4Eh, 41h, 4Dh, 45h, 0
					; DATA XREF: PrintNameOnLocalMap+Ao
					; PrintNameOnLocalMap+61o ...
					; для генерации	названия планеты
PlanetPresent:	db 4Ch,	41h, 56h, 45h, 0, 0, 0,	0, 0 ; DATA XREF: InitGame+24o
					; PrintPlanetPresent+3o ...
					; название активной планеты
plNameDest:	db 4Ch,	41h, 56h, 45h, 0, 0, 0,	0, 0 ; DATA XREF: InitGame+21o
					; CopyPlanetName+6o ...
					; название планеты на которую настроен корабль
FuelToPlanet:	dw 0			; DATA XREF: CalcFuelForDistance:loc_AD58w
					; PrintFuelToPlanetr ...
					; требуется топлива для	перелета до планеты
					;   =расстояние*4
					;
PlanetEconomy:	db 0			; DATA XREF: GenerateInfoPlanet+Cw
					; GenerateInfoPlanet+29r ...
					; Economy (экономика)
PlanetGovernment:db 0			; DATA XREF: GenerateInfoPlanet+22w
					; GenerateInfoPlanet+3Dr ...
					; goverment (тип правительства)
PlanetTechLevel:db 0			; DATA XREF: GenerateInfoPlanet+43w
					; Cmd_P_InfoPlanet+38r	...
					; Tech/Level (технический уровень)
PlanetPopulation:db 0			; DATA XREF: GenerateInfoPlanet+54w
					; GenerateInfoPlanet+67r ...
					; population (население) n/10 вида x.x
PlanetGrossProduct:dw 0			; DATA XREF: GenerateInfoPlanet+71w
					; Cmd_P_InfoPlanet+67r
					; Gross	productivity (валовой доход)
					;
		db    0
		db    0
SaveA5:		db 0			; DATA XREF: FindPlanetByName+4w
					; FindPlanetByName:loc_AC96o
SaveHL_2:	dw 0			; DATA XREF: GeneratePlanetName+3w
					; GeneratePlanetName+35r ...
					; для сохранения переменной в п/п GenaratePlanetName

; =============== S U B	R O U T	I N E =======================================

; настройка на следующую галактику
; вх:  ----
; вых: a - номер галактики
;      hl,de - ????

NextGalaxy:
		ld	hl, PilotNumGalaxy ; номер галактики
		ld	a, (hl)
		inc	a
		and	7
		ld	(hl), a
		ld	hl, PilotGalaxyData0 ; данные по галактике
		call	sub_AC6D
		ld	hl, PilotGalaxyData2
		call	sub_AC6D
		ld	hl, PilotGalaxyData4
; End of function NextGalaxy


; =============== S U B	R O U T	I N E =======================================


sub_AC6D:				; CODE XREF: NextGalaxy+Bp
					; NextGalaxy+11p
		ld	e, (hl)
		rlc	e
		ld	(hl), e
		inc	hl
		ld	d, (hl)
		rlc	d
		ld	(hl), d
		ret
; End of function sub_AC6D


; =============== S U B	R O U T	I N E =======================================

; Поиск	планеты	в галактике по имени
; вх:  InputText - имя планеты
; вых: DataOfPlanet - данные планеты +сгенерирована инфа о ней
;      cy =1 планета не	найдена
;	  =0 найдена

FindPlanetByName:			; CODE XREF: Cmd_R_FindPlanetName+11p
		call	CopyGalaxyToPlanet ; копирование данных	о галактике в рабочую область
					; вх:  ----
					; вых: bc=#0000
		xor	a
		ld	(SaveA5), a

loc_AC7E:				; CODE XREF: FindPlanetByName+23j
		call	SavePlanetData	; сохранение рабочей области с данными по галактике
					; вх:  ----
					; вых: bc=#0000
		call	GeneratePlanetName ; генерация названия	планеты	и подготовка данных для	генерации следующего названия
					; вх:  (DataOfPlanet) -	данные о планете
					; вых: (TempName) - название планеты
					;      (DataOfPlanet) -	данные о следующей планете
					;      hl,de,bc,a - ????
		ld	hl, InputText	; введенный тексто (имя	пилота при выгрузке/загрузке, имя планеты при поиске)
		ld	de, TempName	; для генерации	названия планеты

loc_AC8A:				; CODE XREF: FindPlanetByName+1Dj
		ld	b, (hl)
		ld	a, (de)
		cp	b
		jr	nz, loc_AC96
		and	a
		jr	z, loc_AC9F
		inc	hl
		inc	de
		jr	loc_AC8A
; ---------------------------------------------------------------------------

loc_AC96:				; CODE XREF: FindPlanetByName+16j
		ld	hl, SaveA5
		inc	(hl)
		jp	nz, loc_AC7E
		scf
		ret
; ---------------------------------------------------------------------------

loc_AC9F:				; CODE XREF: FindPlanetByName+19j
		call	RestorePlanetData ; восстановление рабочей области с данными по	галактике
					; вх:  ----
					; вых: bc=#0000
		call	PrintSmallCursOnMap ; Печать малого курсора на карте глобальной/локальной
					; Вх:  (CursorWidth) - ширина курсора
					;      (Pilot_CrdXTarget),(Pilot_CrdYTarget) - координаты курсора на карте
					; Вых: hl,de,bc,a - не определены
		call	GenerateInfoPlanet ; Формирование данных о планете (экономика, правительство, технический уровень,
					;   население, валовой доход) и	установка координат малого курсора
		call	PrintSmallCursOnMap ; Печать малого курсора на карте глобальной/локальной
					; Вх:  (CursorWidth) - ширина курсора
					;      (Pilot_CrdXTarget),(Pilot_CrdYTarget) - координаты курсора на карте
					; Вых: hl,de,bc,a - не определены
		call	CopyPlanetName	; Копирование названия планеты в рабочую облась
					;   (TempName)->(PlanetName)
					;
		jp	CalcFuelForJump	; Расчет расхода топлива на прыжок до планеты
; End of function FindPlanetByName

; ---------------------------------------------------------------------------
SaveHL_1:	dw 0			; DATA XREF: SearchPlanetNearCursor+6w
					; SearchPlanetNearCursor+19r ...
					; промежутчная переменная для расчета расстояния до ближайшей планеты от курсора

; =============== S U B	R O U T	I N E =======================================

; Поиск	ближайшей к курсору планеты, формирование данных о ней,	 установка её
;   текущей целью и отрисовка курсора если отображена карта

SearchNearPlanet:			; CODE XREF: Cmd_D_Curs2NearPlanetp
					; Cmd_P_InfoPlanetp ...
		ld	a, (WhatOnScreen) ; Что	изображено на экране
					;  =0..3 в полете номер	обзорного экрана (front, rear, left, right)
					;  =#04	меню покупки товаров
					;  =#05	меню продажи товаров
					;  =#06	меню покупки оборудования
					;  =#07	глобальная карта
					;  =#08	локальная карта
					;  =#09	инфо о планете еще не выведено
					;  =#0A	прайс планеты
					;  =#0B	инфо о пилоте
					;  =#0C	Инвентрь
					;  =#20	инфо о планете
		cp	7
		jr	c, SearchPlanetNearCursor ; Поиск ближайшей к курсору планеты, формирование данных о ней
					;   и установка	её текущей целью
		cp	9
		jr	nc, SearchPlanetNearCursor ; Поиск ближайшей к курсору планеты,	формирование данных о ней
					;   и установка	её текущей целью
		call	PrintSmallCursOnMap ; Печать малого курсора на карте глобальной/локальной
					; Вх:  (CursorWidth) - ширина курсора
					;      (Pilot_CrdXTarget),(Pilot_CrdYTarget) - координаты курсора на карте
					; Вых: hl,de,bc,a - не определены
		call	SearchPlanetNearCursor ; Поиск ближайшей к курсору планеты, формирование данных	о ней
					;   и установка	её текущей целью
		jp	PrintSmallCursOnMap ; Печать малого курсора на карте глобальной/локальной
; End of function SearchNearPlanet	; Вх:  (CursorWidth) - ширина курсора
					;      (Pilot_CrdXTarget),(Pilot_CrdYTarget) - координаты курсора на карте
					; Вых: hl,de,bc,a - не определены

; =============== S U B	R O U T	I N E =======================================

; Поиск	ближайшей к курсору планеты, формирование данных о ней
;   и установка	её текущей целью

SearchPlanetNearCursor:			; CODE XREF: InitGame+12p
					; SearchNearPlanet+5j ...
		call	CopyGalaxyToPlanet ; копирование данных	о галактике в рабочую область
					; вх:  ----
					; вых: bc=#0000
		ld	hl, 0FFFFh
		ld	(SaveHL_1), hl	; промежутчная переменная для расчета расстояния до ближайшей планеты от курсора
		ld	b, 0

loc_ACD2:				; CODE XREF: SearchPlanetNearCursor+2Cj
		push	bc
		ld	a, (DataOfPlanet1+1)
		ld	b, a
		ld	a, (DataOfPlanet+1) ; данные для генерации планеты
		call	CalcDistanceToCursor ; Квадрат расстояния между	курсором и планетой
					; вх:  b - координата Y	планеты
					;      a - координата X	планеты
					; вых: hl  - результат
					;      cy=1 - сумма больше #FFFF
					;      de,bc,a - ????
		jr	c, loc_ACEF
		ex	de, hl
		ld	hl, (SaveHL_1)	; промежутчная переменная для расчета расстояния до ближайшей планеты от курсора
		and	a
		sbc	hl, de
		jr	c, loc_ACEF
		ld	(SaveHL_1), de	; промежутчная переменная для расчета расстояния до ближайшей планеты от курсора
		call	SavePlanetData	; сохранение рабочей области с данными по галактике
					; вх:  ----
					; вых: bc=#0000

loc_ACEF:				; CODE XREF: SearchPlanetNearCursor+16j
					; SearchPlanetNearCursor+1Fj
		call	NextPlanetData	; модификация данных для генерации планеты
					; вх:  ----
					; вых: hl,de,b,a - ????
		pop	bc
		djnz	loc_ACD2
		ld	hl, (SaveHL_1)	; промежутчная переменная для расчета расстояния до ближайшей планеты от курсора
		and	a
		call	CalcFuelForDistance ; Расчет топлива до	планеты
					; вх:  hl  - квадрат расстояния	от планеты до курсора
					;      cy=1 - hl > #FFFF
					; вых: hl,(FuelToPlanet) - необходимо топлива для прыжка
		call	RestorePlanetData ; восстановление рабочей области с данными по	галактике
					; вх:  ----
					; вых: bc=#0000
		call	GenerateInfoPlanet ; Формирование данных о планете (экономика, правительство, технический уровень,
					;   население, валовой доход) и	установка координат малого курсора
		call	GeneratePlanetName ; генерация названия	планеты	и подготовка данных для	генерации следующего названия
					; вх:  (DataOfPlanet) -	данные о планете
					; вых: (TempName) - название планеты
					;      (DataOfPlanet) -	данные о следующей планете
					;      hl,de,bc,a - ????
		call	CopyPlanetName	; Копирование названия планеты в рабочую облась
					;   (TempName)->(PlanetName)
					;

CalcFuelForJump:			; CODE XREF: FindPlanetByName+37j
		ld	a, (Pilot_CrdXSystem) ;	Расчет расхода топлива на прыжок до планеты
		ld	b, a
		ld	a, (Pilot_CrdYSystem) ;	координата Y текущей системы
		call	CalcDistanceToCursor ; Квадрат расстояния между	курсором и планетой
					; вх:  b - координата Y	планеты
					;      a - координата X	планеты
					; вых: hl  - результат
					;      cy=1 - сумма больше #FFFF
					;      de,bc,a - ????
		call	CalcFuelForDistance ; Расчет топлива до	планеты
					; вх:  hl  - квадрат расстояния	от планеты до курсора
					;      cy=1 - hl > #FFFF
					; вых: hl,(FuelToPlanet) - необходимо топлива для прыжка
		and	a
		ret
; End of function SearchPlanetNearCursor


; =============== S U B	R O U T	I N E =======================================

; модификация данных для генерации планеты
; вх:  ----
; вых: hl,de,b,a - ????

NextPlanetData:				; CODE XREF: PrnStarsNameOnMap:loc_AA68p
					; PrintStarOnLocalMap+4Bj ...
		ld	b, 4

loc_AD19:				; CODE XREF: NextPlanetData+7j
		push	bc
		call	ModifyPlanetData ; модификация данных для генерации планеты
		pop	bc
		djnz	loc_AD19
		ret
; End of function NextPlanetData


; =============== S U B	R O U T	I N E =======================================

; Квадрат расстояния между курсором и планетой
; вх:  b - координата Y	планеты
;      a - координата X	планеты
; вых: hl  - результат
;      cy=1 - сумма больше #FFFF
;      de,bc,a - ????

CalcDistanceToCursor:			; CODE XREF: SearchPlanetNearCursor+13p
					; SearchPlanetNearCursor+48p
		push	af
		ld	a, (Pilot_CrdXTarget) ;	координата X малого курсора на большой карте
		call	loc_AD3D
		ld	d, a
		call	Mult_HL_D_A	; умножение hl=d*a
					; вх:  d,a - множители
					; вых: hl  - результат
		pop	bc
		push	hl
		ld	a, (Pilot_CrdYTarget) ;	+103 (последний	байт для сохранения)
					; координата Y малого курсора на большой карте
		call	loc_AD3D
		srl	a
		ld	d, a
		call	Mult_HL_D_A	; умножение hl=d*a
					; вх:  d,a - множители
					; вых: hl  - результат
		pop	de
		add	hl, de
		ret
; ---------------------------------------------------------------------------

loc_AD3D:				; CODE XREF: CalcDistanceToCursor+4p
					; CalcDistanceToCursor+10p
		cp	b
		jr	nc, loc_AD43
		ld	c, b
		ld	b, a
		ld	a, c

loc_AD43:				; CODE XREF: CalcDistanceToCursor+1Dj
		sub	b
		ret
; End of function CalcDistanceToCursor


; =============== S U B	R O U T	I N E =======================================

; Расчет топлива до планеты
; вх:  hl  - квадрат расстояния	от планеты до курсора
;      cy=1 - hl > #FFFF
; вых: hl,(FuelToPlanet) - необходимо топлива для прыжка

CalcFuelForDistance:			; CODE XREF: SearchPlanetNearCursor+32p
					; SearchPlanetNearCursor+4Bp
		jr	c, loc_AD49
		jr	loc_AD4C
; ---------------------------------------------------------------------------

loc_AD49:				; CODE XREF: CalcFuelForDistancej
		ld	hl, 0FFFFh

loc_AD4C:				; CODE XREF: CalcFuelForDistance+2j
		ld	a, h
		or	l
		jr	z, loc_AD58
		call	Sqrt_H_HL	; Извлечение квадратного корня h=sqr(hl)
					; Вх:  hl - число
					; Вых: h  - результат
					;      l  - остаток
					;      a=0
					;      de,bc - не определены
		ld	l, h
		ld	h, 0
		add	hl, hl
		add	hl, hl

loc_AD58:				; CODE XREF: CalcFuelForDistance+9j
		ld	(FuelToPlanet),	hl ; требуется топлива для перелета до планеты
					;   =расстояние*4
					;
		ret
; End of function CalcFuelForDistance


; =============== S U B	R O U T	I N E =======================================

; умножение hl=d*a
; вх:  d,a - множители
; вых: hl  - результат

Mult_HL_D_A:				; CODE XREF: CalcDistanceToCursor+8p
					; CalcDistanceToCursor+16p ...
		ld	e, 0
		ld	b, 8
		ld	hl, 0

loc_AD63:				; CODE XREF: Mult_HL_D_A:loc_AD6Cj
		srl	d
		rr	e
		rl	a
		jr	nc, loc_AD6C
		add	hl, de

loc_AD6C:				; CODE XREF: Mult_HL_D_A+Dj
		djnz	loc_AD63
		ret
; End of function Mult_HL_D_A


; =============== S U B	R O U T	I N E =======================================

; генерация названия планеты и подготовка данных для генерации следующего названия
; вх:  (DataOfPlanet) -	данные о планете
; вых: (TempName) - название планеты
;      (DataOfPlanet) -	данные о следующей планете
;      hl,de,bc,a - ????

GeneratePlanetName:			; CODE XREF: PrintNameOnLocalMap+4p
					; FindPlanetByName+Ap ...
		ld	hl, TempName	; для генерации	названия планеты
		ld	(SaveHL_2), hl	; для сохранения переменной в п/п GenaratePlanetName
		ld	b, 8

loc_AD77:				; CODE XREF: GeneratePlanetName+Bj
		ld	(hl), 0
		inc	hl
		djnz	loc_AD77
		ld	hl, (DataOfPlanet) ; данные для	генерации планеты
		ld	a, l
		and	40h ; '@'
		and	a
		push	af
		call	loc_AD90
		call	loc_AD90
		call	loc_AD90
		pop	af
		jr	z, ModifyPlanetData ; модификация данных для генерации планеты

loc_AD90:				; CODE XREF: GeneratePlanetName+15p
					; GeneratePlanetName+18p ...
		ld	hl, (DataOfPlanet2)
		ld	a, h
		and	1Fh
		and	a
		jr	z, ModifyPlanetData ; модификация данных для генерации планеты
		ld	hl, TxtPairOfChr ; пары	символов для генерации названия	планеты
		add	a, a
		ld	d, 0
		ld	e, a
		add	hl, de
		ld	a, (hl)
		inc	hl
		push	hl
		ld	hl, (SaveHL_2)	; для сохранения переменной в п/п GenaratePlanetName
		ld	(hl), a
		inc	hl
		ex	de, hl
		pop	hl
		ld	a, (hl)
		ex	de, hl
		cp	3Fh ; '?'
		jr	z, loc_ADB3
		ld	(hl), a
		inc	hl

loc_ADB3:				; CODE XREF: GeneratePlanetName+40j
		ld	(SaveHL_2), hl	; для сохранения переменной в п/п GenaratePlanetName

ModifyPlanetData:			; CODE XREF: NextPlanetData+3p
					; GeneratePlanetName+1Fj ...
		ld	hl, (DataOfPlanet) ; модификация данных	для генерации планеты
		ld	de, (DataOfPlanet1)
		add	hl, de
		ex	de, hl
		ld	hl, (DataOfPlanet1)
		ld	(DataOfPlanet),	hl ; данные для	генерации планеты
		ld	hl, (DataOfPlanet2)
		ld	(DataOfPlanet1), hl
		ld	hl, (DataOfPlanet1)
		add	hl, de
		ld	(DataOfPlanet2), hl
		ret
; End of function GeneratePlanetName


; =============== S U B	R O U T	I N E =======================================

; Копирование названия планеты в рабочую облась
;   (TempName)->(PlanetName)
;

CopyPlanetName:				; CODE XREF: FindPlanetByName+34p
					; SearchPlanetNearCursor+3Ep
		ld	bc, 8
		ld	hl, TempName	; для генерации	названия планеты
		ld	de, plNameDest	; название планеты на которую настроен корабль
		ldir
		ret
; End of function CopyPlanetName


; =============== S U B	R O U T	I N E =======================================

; Формирование данных о	планете	(экономика, правительство, технический уровень,
;   население, валовой доход) и	установка координат малого курсора

GenerateInfoPlanet:			; CODE XREF: FindPlanetByName+2Ep
					; SearchPlanetNearCursor+38p
		ld	hl, (DataOfPlanet) ; данные для	генерации планеты
		ld	(PlanetData0), hl ; 6 байт для генерации данных	о планете
		ld	a, h
		ld	(Pilot_CrdYTarget), a ;	+103 (последний	байт для сохранения)
					; координата Y малого курсора на большой карте
		and	7
		ld	(PlanetEconomy), a ; Economy (экономика)
		ld	hl, (DataOfPlanet1)
		ld	(PlanetData1), hl
		ld	a, h
		ld	(Pilot_CrdXTarget), a ;	координата X малого курсора на большой карте
		ld	a, l
		srl	a
		srl	a
		srl	a
		and	7
		ld	(PlanetGovernment), a ;	goverment (тип правительства)
		srl	a
		jr	nz, loc_AE10
		ld	a, (PlanetEconomy) ; Economy (экономика)
		or	2
		ld	(PlanetEconomy), a ; Economy (экономика)

loc_AE10:				; CODE XREF: GenerateInfoPlanet+27j
		ld	a, (PlanetEconomy) ; Economy (экономика)
		xor	7
		and	a
		ld	b, a
		ld	a, h
		and	3
		add	a, b
		ld	b, a
		ld	a, (PlanetGovernment) ;	goverment (тип правительства)
		srl	a
		adc	a, b
		ld	(PlanetTechLevel), a ; Tech/Level (технический уровень)
		add	a, a
		add	a, a
		ld	b, a
		ld	a, (PlanetGovernment) ;	goverment (тип правительства)
		ld	c, a
		ld	a, (PlanetEconomy) ; Economy (экономика)
		adc	a, b
		adc	a, c
		adc	a, 1
		ld	(PlanetPopulation), a ;	population (население) n/10 вида x.x
		ld	a, (PlanetEconomy) ; Economy (экономика)
		xor	7
		adc	a, 3
		ld	d, a
		ld	a, (PlanetGovernment) ;	goverment (тип правительства)
		adc	a, 4
		call	Mult_HL_D_A	; умножение hl=d*a
					; вх:  d,a - множители
					; вых: hl  - результат
		ld	a, (PlanetPopulation) ;	population (население) n/10 вида x.x
		ld	d, l
		call	Mult_HL_D_A	; умножение hl=d*a
					; вх:  d,a - множители
					; вых: hl  - результат
		add	hl, hl
		add	hl, hl
		add	hl, hl
		ld	(PlanetGrossProduct), hl ; Gross productivity (валовой доход)
					;
		ld	hl, (DataOfPlanet2)
		ld	(PlanetData2), hl
		ret
; End of function GenerateInfoPlanet


; =============== S U B	R O U T	I N E =======================================

; печать расстояния до планеты на карте
;

PrintFuelToPlanet:			; CODE XREF: Cmd_D_Curs2NearPlanet+Ep
					; Cmd_P_InfoPlanet+16p
		ld	hl, (FuelToPlanet) ; требуется топлива для перелета до планеты
					;   =расстояние*4
					;
		ld	a, h
		or	l
		jr	z, loc_AE76
		ld	a, 0BFh	; '┐'
		call	PrintMessage1_A_Colon ;	печать сообщения с двоеточием на конце
					; вх:  a - номер собщения
					; вых: hl,de,bc,a - ????
		ld	a, 4
		ld	(DigitsInNumber), a ; ;количество печатаемых знаков числа (дополняется слева пробелами или нулями)
		ld	hl, (FuelToPlanet) ; требуется топлива для перелета до планеты
					;   =расстояние*4
					;
		scf
		call	PrintNumber_HL	; печать числа
					; вх:  hl - печатаемое число
					;      cy=1 - число вида (12345=>1234.5)
					; вых: (LLA88E)=#00
					;      (LLA88D)=#01
					;      a=#01
					;      hl,de,bc	- ????
		call	PrintSymbol_SP	; печать одного	символа
					; (печать сообщения по номеру
					; вх:  номер сообщения после call
					; вых: hl,de,bc,a - ????
					; )
; ---------------------------------------------------------------------------
		db 0C3h
; ---------------------------------------------------------------------------

loc_AE76:				; CODE XREF: PrintFuelToPlanet+5j
		jp	PrnCrd_CRLF	; установка флага регистра печати, сброс координаты X, увеличение координаты Y
; End of function PrintFuelToPlanet	; вх:  ----
					; вых: ----

; =============== S U B	R O U T	I N E =======================================

; копирование данных о галактике в рабочую область
; вх:  ----
; вых: bc=#0000

CopyGalaxyToPlanet:			; CODE XREF: PrnStarsNameOnMap+3p
					; Cmd_I_GlobalMap+62p ...
		ld	hl, PilotGalaxyData0 ; данные по галактике
		ld	de, DataOfPlanet ; данные для генерации	планеты
		jr	loc_AE8F
; End of function CopyGalaxyToPlanet


; =============== S U B	R O U T	I N E =======================================

; сохранение рабочей области с данными по галактике
; вх:  ----
; вых: bc=#0000

SavePlanetData:				; CODE XREF: FindPlanetByName:loc_AC7Ep
					; SearchPlanetNearCursor+25p
		ld	hl, DataOfPlanet ; данные для генерации	планеты
		ld	de, DataOfPlanetSv ; копия данных для генерации	планет
					; выбранная планета
		jr	loc_AE8F
; End of function SavePlanetData


; =============== S U B	R O U T	I N E =======================================

; восстановление рабочей области с данными по галактике
; вх:  ----
; вых: bc=#0000

RestorePlanetData:			; CODE XREF: FindPlanetByName:loc_AC9Fp
					; SearchPlanetNearCursor+35p
		ld	hl, DataOfPlanetSv ; копия данных для генерации	планет
					; выбранная планета
		ld	de, DataOfPlanet ; данные для генерации	планеты

loc_AE8F:				; CODE XREF: CopyGalaxyToPlanet+6j
					; SavePlanetData+6j
		ld	bc, 6
		ldir
		ret
; End of function RestorePlanetData

; ---------------------------------------------------------------------------
SaveA6:		db 0			; DATA XREF: GenerateProductPrice:loc_AEBAw
					; GenerateProductPrice+32r ...

; =============== S U B	R O U T	I N E =======================================

; генерация количества товаров и цен на	станции
; вх:  ----

GenerateProductPrice:			; CODE XREF: sub_D6B3+26p
		ld	a, (RndWord)	; случайное число
		ld	(PilotRnd), a	; 23 ????

GenerateAnotherPrice:			; CODE XREF: InitGame+1Bp
		ld	hl, PilotPlanetProduct ; ;то же	но без установки нового	rnd
		ld	de, ProductPrice ; цены	товаров	на станции
					;  (#B0,#03=#03B0=944=94.4Cr)
					; LLAF0E  rept	  #11
					;	   db	   #00,#00
					;	  endr
					; LLAF30
					;
		exx
		ld	hl, TableBasePrice ; таблица для генерации кол-ва товаров и цен	на станции
					; ds #11,#00,#00,#00,#00
		ld	b, 11h

loc_AEA8:				; CODE XREF: GenerateProductPrice+6Fj
		push	bc
		ld	e, (hl)
		inc	hl
		ld	a, (hl)
		ld	d, a
		and	1Fh
		jr	z, loc_AEBA
		ld	b, a
		ld	a, (PlanetEconomy) ; Economy (экономика)
		ld	c, a
		xor	a

loc_AEB7:				; CODE XREF: GenerateProductPrice+22j
		add	a, c
		djnz	loc_AEB7

loc_AEBA:				; CODE XREF: GenerateProductPrice+19j
		ld	(SaveA6), a
		inc	hl
		ld	b, (hl)
		inc	hl
		ld	c, (hl)
		inc	hl
		ld	a, (PilotRnd)	; 23 ????
		and	c
		add	a, b
		ld	b, a
		ld	a, (SaveA6)
		bit	7, d
		jr	nz, loc_AED2
		inc	a
		neg

loc_AED2:				; CODE XREF: GenerateProductPrice+37j
		add	a, b
		bit	7, a
		jr	z, loc_AED8
		xor	a

loc_AED8:				; CODE XREF: GenerateProductPrice+3Fj
		and	3Fh ; '?'
		push	af
		ld	a, (PilotRnd)	; 23 ????
		and	c
		add	a, e
		ld	b, a
		ld	a, (SaveA6)
		bit	7, d
		jr	z, loc_AEEB
		inc	a
		neg

loc_AEEB:				; CODE XREF: GenerateProductPrice+50j
		add	a, b
		ld	c, a
		ld	b, 0
		sla	c
		rl	b
		sla	c
		rl	b
		push	bc
		exx
		pop	bc
		ld	a, c
		ld	(de), a
		inc	de
		ld	a, b
		ld	(de), a
		inc	de
		pop	af

Amount:					; DATA XREF: InitGame+15o
		ld	(hl), a
		inc	hl
		exx
		pop	bc
		djnz	loc_AEA8
		ld	hl, PilotPlProdAlienIt ; +91
					; =0 станция была уничтожена в рамках миссии
		ld	(hl), b
		ret
; End of function GenerateProductPrice

; ---------------------------------------------------------------------------
unk_AF0C:	db    0			; DATA XREF: sub_B52E+6o
					; Cmd_K_MarketPrice+22o
		db    0
ProductPrice:	db 0BAh, 3Eh		; DATA XREF: GenerateProductPrice+9o
		db 20h,	0C3h		; цены товаров на станции
		db 7, 0BAh		;  (#B0,#03=#03B0=944=94.4Cr)
		db 0CDh, 7		; LLAF0E  rept	  #11
		db 0BAh, 3Eh		;	   db	   #00,#00
		db 1, 32h		;	  endr
		db 0A7h, 0A7h		; LLAF30
		db 0CDh, 25h		;
		db 0AFh, 3Ah
		db 23h,	0A7h
		db 3Ch,	18h
		db 11h,	0AFh
		db 32h,	22h
		db 0A7h, 0C9h
		db 0E1h, 7Eh
		db 23h,	0E5h
		db 32h,	22h
byte_AF30:	db 0			; DATA XREF: PrnOneProductr
					; sub_AFB9+Br ...
					; номер	товара
word_AF31:	dw 0			; DATA XREF: sub_AFB9r	sub_AFB9+4w ...
					; адрес	в таблице количества товаров
word_AF33:	dw 0			; DATA XREF: PrnOneProduct+13r
					; PrnOneProduct+18w ...
					; адрес	в таблице цен товаров
word_AF35:	dw 0			; DATA XREF: PrnOneProduct+2Cr
					; PrnOneProduct+31w ...
					; адрес	в таблице количества товаров
TempCrdPrn:	dw 0			; DATA XREF: SaveCrdPrn+3w sub_B0DEr
					; координаты печати

; =============== S U B	R O U T	I N E =======================================

; звуковой сигнал
; вх:  ----
; вых: ----

FX_Beep:				; CODE XREF: Cmd_R_FindPlanetName+24p
					; Cmd_D_Curs2NearPlanet+11j ...
		ld	a, (FlagsSetUp)	; 0-1,=00 управление SXNMA (LLFC0F)<>0 сброс CS,F,c
					;     =01 управление от	Kempston'а
					;     =10 управление от	курсора	76850
					;     =11 управление от	Sinclair right
					;   2,=1  управление приближено	к реальному (reaction)
					;   3,=1  вкл. инерционность поворота
					;   4,=1  управление инвертировано
					;   5,=1  вверх/вниз инвертировано
					;   6,=1  вкл. перехват	таргонов
					;   7,=1  звук включен
		bit	7, a
		ret	z
		ld	hl, 80h	; 'А'
		ld	de, 60h	; '`'
		jp	3B5h
; End of function FX_Beep


; =============== S U B	R O U T	I N E =======================================

; ожидание нажатия на клавишу
; вх:  ----
; вых: ----

WaitPressKey:				; CODE XREF: InputTextString:loc_B13Ep
					; Cmd_2_BuyCargo+28p ...
		call	Pause_14Int	; Пауза	14h прерывания
		call	ResetPressedKeys ; сброс битов нажатых клавиш
					; вх:  ----
					; вых: b=#00
					;      hl - ????

loc_AF4E:				; CODE XREF: WaitPressKey+Bj
		ld	a, (PressKeyPrnSymbol) ; Печатный символ нажатой клавиши
					;  =#FE	- BackSpace
					;  =#FF	- ничего не нажато
		cp	0FFh
		jr	z, loc_AF4E
		ret
; End of function WaitPressKey


; =============== S U B	R O U T	I N E =======================================

; сброс	битов нажатых клавиш
; вх:  ----
; вых: b=#00
;      hl - ????

ResetPressedKeys:			; CODE XREF: WaitPressKey+3p
					; Cmd_R_FindPlanetName+27j ...
		di
		ld	hl, ControlKey1	; 7,=1 - Y	 -- Cloaking Device
					; 6,=1 - 0	 -- ???
					; 5,=1 - I	 -- Global Map
					; 4,=1 - O	 -- Local Map
					; 3,=1 - P	 -- Planet Info
					; 2,=1 - K	 -- Planet Price
					; 1,=1 - L	 -- Commander Info
					; 0,=1 - Enter	 -- Inventory
		ld	b, 4

loc_AF5C:				; CODE XREF: ResetPressedKeys+9j
		ld	(hl), 0
		inc	hl
		djnz	loc_AF5C
		ei
		ret
; End of function ResetPressedKeys


; =============== S U B	R O U T	I N E =======================================

; печать названия цены и количества товара
; вх:  (LLAF30)	- номер	товара
;      (LLAF33)	- адрес	в таблице цен товаров
;      (LLAF35)	- адрес	в таблице количества товаров
; вых: cy=1 - товара нет
;      hl,de,bc,a - ????

PrnOneProduct:				; CODE XREF: Cmd_2_BuyCargo+71p
					; Cmd_K_MarketPrice:loc_D0ABp
		ld	a, (byte_AF30)	; номер	товара
		add	a, 0D0h	; '╨'
		call	PrintMessage1_A	; Печать сообщения из группы 1 в буфере/на экране
					; вх: A	- номер	сообщения
		call	SetCrdX_SP	; Установка координаты X печати
					; вх:  байт после call - координата X
					; вых: ----
					;
; ---------------------------------------------------------------------------
		db 0Dh
; ---------------------------------------------------------------------------
		call	sub_B06F	; печать строчными буквами t/kg/g/km
					; вх:  (LLAF30)	- номер	сообщения
					;	#00-#0C,#10 - t
					;	#0D,#0E	    - kg
					;	#0F	    - g
					;	#11-#FF	    - km
					; вых: hl,de,bc,a
		call	SetCrdX_SP	; Установка координаты X печати
					; вх:  байт после call - координата X
					; вых: ----
					;
; ---------------------------------------------------------------------------
		db 0Fh
; ---------------------------------------------------------------------------
		ld	hl, (word_AF33)	; адрес	в таблице цен товаров
		inc	hl
		inc	hl
		ld	(word_AF33), hl	; адрес	в таблице цен товаров
		ld	e, (hl)
		inc	hl
		ld	d, (hl)
		ex	de, hl
		scf
		ld	a, 4
		ld	(DigitsInNumber), a ; ;количество печатаемых знаков числа (дополняется слева пробелами или нулями)
		call	PrintNumber_HL	; печать числа
					; вх:  hl - печатаемое число
					;      cy=1 - число вида (12345=>1234.5)
					; вых: (LLA88E)=#00
					;      (LLA88D)=#01
					;      a=#01
					;      hl,de,bc	- ????
		call	SetCrdX_SP	; Установка координаты X печати
					; вх:  байт после call - координата X
					; вых: ----
					;
; ---------------------------------------------------------------------------
		db 17h
; ---------------------------------------------------------------------------
		ld	hl, (word_AF35)	; адрес	в таблице количества товаров
		inc	hl
		ld	a, (hl)
		ld	(word_AF35), hl	; адрес	в таблице количества товаров
		and	a
		jr	nz, loc_AFA5
		call	PrintSymbol_SP	; печать одного	символа
					; (печать сообщения по номеру
					; вх:  номер сообщения после call
					; вых: hl,de,bc,a - ????
					; )
; ---------------------------------------------------------------------------
		db 20h
; ---------------------------------------------------------------------------
		ld	a, 2Dh ; '-'
		call	PrnMsg_A_CRLF	; печать сообщения, на конце LF/CR
					; вх:  a - номер собщения
					; вых: hl,de,bc,a - ????
		scf
		ret
; ---------------------------------------------------------------------------

loc_AFA5:				; CODE XREF: PrnOneProduct+35j
		ld	a, 2
		ld	(DigitsInNumber), a ; ;количество печатаемых знаков числа (дополняется слева пробелами или нулями)
		ld	hl, (word_AF35)	; адрес	в таблице количества товаров
		ld	a, (hl)
		call	PrintNumber_A	; печать числа
		call	sub_B06F	; печать строчными буквами t/kg/g/km
					; вх:  (LLAF30)	- номер	сообщения
					;	#00-#0C,#10 - t
					;	#0D,#0E	    - kg
					;	#0F	    - g
					;	#11-#FF	    - km
					; вых: hl,de,bc,a
		call	PrnCrd_CRLF	; установка флага регистра печати, сброс координаты X, увеличение координаты Y
					; вх:  ----
					; вых: ----
		and	a
		ret
; End of function PrnOneProduct


; =============== S U B	R O U T	I N E =======================================

; печать названия и количества товара
; вх:  (LLAF30)	- номер	товара
;      (LLAF31)	- адрес	в таблице количества товаров
; вых: cy=1 - товара нет
;      hl,de,bc,a - ????

sub_AFB9:				; CODE XREF: sub_B4B0+1Ap
					; Cmd_Ent_Inventory:loc_D2CAp
		ld	hl, (word_AF31)	; адрес	в таблице количества товаров
		inc	hl
		ld	(word_AF31), hl	; адрес	в таблице количества товаров
		ld	a, (hl)
		and	a
		jr	z, loc_AFE1
		ld	a, (byte_AF30)	; номер	товара
		add	a, 0D0h	; '╨'
		call	PrintMessage1_A	; Печать названия товара
		call	SetCrdX_SP	; Установка координаты X печати
					; вх:  байт после call - координата X
					; вых: ----
					;
; ---------------------------------------------------------------------------
		db 0Dh
; ---------------------------------------------------------------------------
		ld	a, 3
		ld	(DigitsInNumber), a ; ;количество печатаемых знаков числа (дополняется слева пробелами или нулями)
		ld	hl, (word_AF31)	; адрес	в таблице количества товаров
		ld	a, (hl)
		call	PrintNumber_A	; печать числа
		call	sub_B06F	; печать строчными буквами t/kg/g/km
					; вх:  (LLAF30)	- номер	сообщения
					;	#00-#0C,#10 - t
					;	#0D,#0E	    - kg
					;	#0F	    - g
					;	#11-#FF	    - km
					; вых: hl,de,bc,a
		and	a
		ret
; ---------------------------------------------------------------------------

loc_AFE1:				; CODE XREF: sub_AFB9+9j
		scf
		ret
; End of function sub_AFB9


; =============== S U B	R O U T	I N E =======================================

; печать сообщения с двоеточием	на конце
; вх:  a - номер собщения
; вых: hl,de,bc,a - ????

PrintMessage2_A_Colon:			; CODE XREF: Cmd_P_InfoPlanet+44p
					; Cmd_P_InfoPlanet+64p	...
		call	PrintMessage2	; Печать сообщения из группы 2 в буфере/на экране
					; вх: a	- номер	сообщения [#01..#00]
					; вых: (LLBA98)=#00 - печатать п/п LLBA9D
		jr	loc_AFEB
; End of function PrintMessage2_A_Colon


; =============== S U B	R O U T	I N E =======================================

; печать сообщения с двоеточием	на конце
; вх:  a - номер собщения
; вых: hl,de,bc,a - ????

PrintMessage1_A_Colon:			; CODE XREF: PrintFuelToPlanet+9p
					; PrnCASHxxxx+2p ...
		call	PrintMessage1_A	; Печать сообщения из группы 1 в буфере/на экране
					; вх: A	- номер	сообщения

loc_AFEB:				; CODE XREF: PrintMessage2_A_Colon+3j
		ld	a, 3Ah ; ':'
		jr	loc_AFF4
; End of function PrintMessage1_A_Colon


; =============== S U B	R O U T	I N E =======================================

; печать сообщения с пробелом на конце
; вх:  a - номер собщения
; вых: hl,de,bc,a - ????

PrintMessage1_A_Space:			; CODE XREF: Cmd_4_BuyEquip+9p
					; Cmd_4_BuyEquip+7Ep ...
		call	PrintMessage1_A	; Печать сообщения из группы 1 в буфере/на экране
					; вх: A	- номер	сообщения
		ld	a, 20h ; ' '

loc_AFF4:				; CODE XREF: PrintMessage1_A_Colon+5j
		jp	PrintMessage1_A	; Печать сообщения из группы 1 в буфере/на экране
; End of function PrintMessage1_A_Space	; вх: A	- номер	сообщения


; =============== S U B	R O U T	I N E =======================================

; печать сообщения, на конце LF/CR
; вх:  a - номер собщения
; вых: hl,de,bc,a - ????

PrnMsg_A_CRLF:				; CODE XREF: PrnOneProduct+3Dp
					; Cmd_2_BuyCargo+55p ...
		call	PrintMessage1_A	; Печать сообщения из группы 1 в буфере/на экране
; End of function PrnMsg_A_CRLF		; вх: A	- номер	сообщения


; =============== S U B	R O U T	I N E =======================================

; установка флага регистра печати, сброс координаты X, увеличение координаты Y
; вх:  ----
; вых: ----

PrnCrd_CRLF:				; CODE XREF: PrintFuelToPlanet:loc_AE76j
					; PrnOneProduct+51p ...
		ld	a, 1
		ld	(FlgPrnSym2), a	; флаг печати
					; =1 был перевод строки
		call	SetZeroPrnCrdX	; Cброс	координаты X
; End of function PrnCrd_CRLF


; =============== S U B	R O U T	I N E =======================================

; Приращение координаты	Y

IncPrnCrdY:				; CODE XREF: PrintSymbol_8x8+Dp
					; DATA XREF: RAM:6FD3o
		ld	a, (CrdYPrnSymbol)
		inc	a
		jr	SetPrnCrdY	; Установка координаты Y с контролем выхода за границы экрана
; End of function IncPrnCrdY		; вх:  a - координата Y
					; вых: ----
					;

; =============== S U B	R O U T	I N E =======================================

; Cброс	координаты X

SetZeroPrnCrdX:				; CODE XREF: PrnCrd_CRLF+5p
					; SetPrnCrdY+Bj ...
		xor	a
		ld	(CrdXPrnSymbol), a ; Координаты	печати символа
		ret
; End of function SetZeroPrnCrdX


; =============== S U B	R O U T	I N E =======================================

; Установка координаты X печати
; вх:  байт после call - координата X
; вых: ----
;

SetCrdX_SP:				; CODE XREF: PrnOneProduct+8p
					; PrnOneProduct+Fp ...
		pop	hl
		ld	a, (hl)
		inc	hl
		push	hl

SetCrdX_A:				; CODE XREF: sub_B616+64p sub_D1A6+5j
		ld	(CrdXPrnSymbol), a ; Установка координаты X печати
		cp	20h ; ' '
		ret	c
		jr	PrnCrd_CRLF	; установка флага регистра печати, сброс координаты X, увеличение координаты Y
; End of function SetCrdX_SP		; вх:  ----
					; вых: ----

; =============== S U B	R O U T	I N E =======================================

; Установка координаты Y с контролем выхода за границы экрана
; вх:  a - координата Y
; вых: ----
;

SetPrnCrdY:				; CODE XREF: IncPrnCrdY+4j
					; Clear2ZnkLine+2p ...
		ld	(CrdYPrnSymbol), a
		cp	18h
		ret	c
		ld	a, 1
		ld	(CrdYPrnSymbol), a
		jr	SetZeroPrnCrdX	; Cброс	координаты X
; End of function SetPrnCrdY


; =============== S U B	R O U T	I N E =======================================


sub_B026:				; CODE XREF: InputTextString+6Dp
					; RAM:loc_B32Bp
		ld	a, (CrdYPrnSymbol)
		ld	b, 0A1h	; 'б'
		cp	15h
		jr	z, loc_B031
		ld	b, 0C1h	; '┴'

loc_B031:				; CODE XREF: sub_B026+7j
		ld	a, (CrdXPrnSymbol) ; Координаты	печати символа
		and	a
		ret	z
		dec	a
		ld	(CrdXPrnSymbol), a ; Координаты	печати символа
		add	a, b
		ld	(loc_B03E+1), a

loc_B03E:				; DATA XREF: sub_B026+15w
		ld	hl, 5000h
		xor	a
		ld	b, 8

loc_B044:				; CODE XREF: sub_B026+20j
		ld	(hl), a
		inc	h
		djnz	loc_B044
		ret
; End of function sub_B026


; =============== S U B	R O U T	I N E =======================================

; new equ PrintMessage1_A
;
; Печать сообщения заглавными буквами
; A - номер сообщения

PrintMessage_A_UpperCase:		; CODE XREF: PrnMess_A_Inidcatorp
					; Cmd_D_Curs2NearPlanet+8p ...
		push	af
		call	PrintSymbol_SP	; установка флагов: Печатать всё заглавными буквами
; ---------------------------------------------------------------------------
		db 6
; ---------------------------------------------------------------------------
		pop	af
		call	PrintMessage1_A	; Печать сообщения
		ld	a, 8
		jp	PrintMessage1_A	; Установка флагов: Каждое слово начинать с заглавной буквы
; End of function PrintMessage_A_UpperCase


; =============== S U B	R O U T	I N E =======================================

; Печать сообщения, индиктора опасности(если в космосе)	и 3CrLf
; A - номер сообщения

PrnMess_A_Inidcator:			; CODE XREF: sub_B4B0+9p
					; PrintHeaderMap+6p ...
		call	PrintMessage_A_UpperCase ; new equ PrintMessage1_A
					;
					; Печать сообщения заглавными буквами
					; A - номер сообщения
		call	PrintIndDanger	; Печать индикатора опасности и	индикатора ракеты
					; Вх:  (IndDanger) - состояние индикатора
					; Вых: b =#00
					;      hl,de,c,a - не определены
		ld	a, 77h ; 'w'
		jp	PrintMessage1_A	; три CRLF
; End of function PrnMess_A_Inidcator


; =============== S U B	R O U T	I N E =======================================

; печать сообщения
; вх:  hl - адрес начала сообщения
; вых: cy=1
;      a=#00
;      hl - адрес конца	сообщения
;      hl,de,bc	- ????

PrintMessage_HL:			; CODE XREF: PrintNameOnLocalMap+64j
					; PrintMessage_HL+Bj ...
		ld	a, (hl)
		cp	0
		scf
		ret	z
		inc	hl
		push	hl
		call	PrintMessage1_A	; Печать сообщения из группы 1 в буфере/на экране
					; вх: A	- номер	сообщения
		pop	hl
		jr	PrintMessage_HL	; печать сообщения
; End of function PrintMessage_HL	; вх:  hl - адрес начала сообщения
					; вых: cy=1
					;      a=#00
					;      hl - адрес конца	сообщения
					;      hl,de,bc	- ????

; =============== S U B	R O U T	I N E =======================================

; печать строчными буквами t/kg/g/km
; вх:  (LLAF30)	- номер	сообщения
;	#00-#0C,#10 - t
;	#0D,#0E	    - kg
;	#0F	    - g
;	#11-#FF	    - km
; вых: hl,de,bc,a

sub_B06F:				; CODE XREF: PrnOneProduct+Cp
					; PrnOneProduct+4Ep ...
		ld	a, 0
		ld	(FlgPrnSym2), a	; флаг печати
					; =1 был перевод строки
		ld	a, (byte_AF30)	; номер	товара
		cp	0Dh
		jr	c, loc_B087
		cp	0Fh
		jr	c, loc_B08B
		jr	z, loc_B090
		cp	11h
		jr	c, loc_B087
		jr	loc_B094
; ---------------------------------------------------------------------------

loc_B087:				; CODE XREF: sub_B06F+Aj sub_B06F+14j
		ld	a, 54h ; 'T'
		jr	loc_B09A
; ---------------------------------------------------------------------------

loc_B08B:				; CODE XREF: sub_B06F+Ej
		ld	a, 4Bh ; 'K'
		call	PrintMessage1_A	; Печать сообщения из группы 1 в буфере/на экране
					; вх: A	- номер	сообщения

loc_B090:				; CODE XREF: sub_B06F+10j
		ld	a, 47h ; 'G'
		jr	loc_B09A
; ---------------------------------------------------------------------------

loc_B094:				; CODE XREF: sub_B06F+16j
		call	PrintSymbol_SP	; печать одного	символа
					; (печать сообщения по номеру
					; вх:  номер сообщения после call
					; вых: hl,de,bc,a - ????
					; )
; ---------------------------------------------------------------------------
		db 4Bh
; ---------------------------------------------------------------------------
		ld	a, 4Dh ; 'M'

loc_B09A:				; CODE XREF: sub_B06F+1Aj sub_B06F+23j
		jp	PrintMessage1_A	; Печать сообщения из группы 1 в буфере/на экране
; End of function sub_B06F		; вх: A	- номер	сообщения


; =============== S U B	R O U T	I N E =======================================


sub_B09D:				; CODE XREF: sub_B3A1+1Cp sub_B501+11p
		ld	a, (byte_AF30)	; номер	товара
		cp	0Dh
		ret	c
		cp	10h
		jr	nz, loc_B0A9
		scf
		ret
; ---------------------------------------------------------------------------

loc_B0A9:				; CODE XREF: sub_B09D+8j
		and	a
		ret
; End of function sub_B09D


