		ret
; End of function SaveCrdPrn


; =============== S U B	R O U T	I N E =======================================

; очиска двух знакоместных линий
; вх:  ----
; вых: b=#00

Clear2ZnkLine:				; CODE XREF: Cmd_R_FindPlanetName+Ej
					; InputTextString+14p ...
		ld	a, 15h
		call	SetPrnCrdY	; Установка координаты Y с контролем выхода за границы экрана
					; вх:  a - координата Y
					; вых: ----
					;
		call	SetZeroPrnCrdX	; Cброс	координаты X
		xor	a
		ld	hl, 50A1h
		call	ClearZnkLine	; Очистка линии	знакомест 8x8 длиной 30
; End of function Clear2ZnkLine		; вх:  hl - адрес в экранной области


; =============== S U B	R O U T	I N E =======================================


sub_B0CB:				; CODE XREF: sub_D42C+Bp
		ld	hl, 50C1h
; End of function sub_B0CB


; =============== S U B	R O U T	I N E =======================================

; Очистка линии	знакомест 8x8 длиной 30
; вх:  hl - адрес в экранной области

ClearZnkLine:				; CODE XREF: Clear2ZnkLine+Cp
		ld	b, 8

loc_B0D0:				; CODE XREF: ClearZnkLine+Dj
		push	bc
		ld	b, 1Eh
		push	hl

loc_B0D4:				; CODE XREF: ClearZnkLine+8j
		ld	(hl), a
		inc	hl
		djnz	loc_B0D4
		pop	hl
		inc	h
		pop	bc
		djnz	loc_B0D0
		ret
; End of function ClearZnkLine


; =============== S U B	R O U T	I N E =======================================

; восстановление координат печати
; вх:  ----
; вых: hl - координаты

sub_B0DE:				; CODE XREF: Cmd_2_BuyCargo:loc_B30Cp
					; sub_B4B0:loc_B4E0p
