SaveA3:		db 0			; DATA XREF: Cmd_R_FindPlanetName+Ar
					; InputTextString+11w ...
					; Длина	введенного имени планеты при поиске
SaveHL2:	dw 0			; DATA XREF: InputTextString+Dw
					; InputTextString+4Fr ...
SaveA4:		db 0			; DATA XREF: InputTextString+24w
					; InputTextString+2Fr

; =============== S U B	R O U T	I N E =======================================

; Поиск	планеты	по её имени

Cmd_R_FindPlanetName:			; CODE XREF: RAM:A807j
		ld	a, 0Eh
		ld	b, 8
		ld	hl, InputText	; введенный тексто (имя	пилота при выгрузке/загрузке, имя планеты при поиске)
		call	InputTextString	; Ввод текстовой строки
					; вх:  a  - ???
					;      b  - макс. длина	вводимой строки
					;      hl - адрес вводимой строки
					;      (CrxXPrnSymbol),(CrxYPrnSymbol) - координаты печати
		ld	a, (SaveA3)	; Длина	введенного имени планеты при поиске
		and	a
		jp	z, Clear2ZnkLine ; очиска двух знакоместных линий
					; вх:  ----
					; вых: b=#00
		call	FindPlanetByName ; Поиск планеты в галактике по	имени
					; вх:  InputText - имя планеты
					; вых: DataOfPlanet - данные планеты +сгенерирована инфа о ней
					;      cy =1 планета не	найдена
					;	  =0 найдена
		jr	nc, loc_B113
		ld	hl, InputText	; введенный тексто (имя	пилота при выгрузке/загрузке, имя планеты при поиске)
		call	PrintMessage_HL	; Печать сообщение планета не найдена
		call	PrintSymbol_SP	; печать одного	символа
					; (печать сообщения по номеру
					; вх:  номер сообщения после call
					; вых: hl,de,bc,a - ????
					; )
; ---------------------------------------------------------------------------
		db 8
; ---------------------------------------------------------------------------
		call	PrintSymbol_SP	; печать одного	символа
					; (печать сообщения по номеру
					; вх:  номер сообщения после call
					; вых: hl,de,bc,a - ????
					; )
; ---------------------------------------------------------------------------
		db 0E1h
; ---------------------------------------------------------------------------
		call	FX_Beep		; звуковой сигнал
					; вх:  ----
					; вых: ----
		jp	ResetPressedKeys ; сброс битов нажатых клавиш
					; вх:  ----
					; вых: b=#00
					;      hl - ????
; ---------------------------------------------------------------------------

loc_B113:				; CODE XREF: Cmd_R_FindPlanetName+14j
		call	PrintSymbol_SP	; печать одного	символа
					; (печать сообщения по номеру
					; вх:  номер сообщения после call
					; вых: hl,de,bc,a - ????
					; )
; ---------------------------------------------------------------------------
		db 8
; ---------------------------------------------------------------------------
		jp	PrnNameFoundedPlanet ; печать имени планеты и расстояния до неё
; End of function Cmd_R_FindPlanetName

; ---------------------------------------------------------------------------
SaveA2:		db 0			; DATA XREF: InputTextStringw
					; InputTextString+1Br
SaveHL1:	dw 0			; DATA XREF: InputTextString+7w
					; InputTextString+Ar

; =============== S U B	R O U T	I N E =======================================

; Ввод текстовой строки
; вх:  a  - ???
;      b  - макс. длина	вводимой строки
;      hl - адрес вводимой строки
;      (CrxXPrnSymbol),(CrxYPrnSymbol) - координаты печати

InputTextString:			; CODE XREF: Cmd_R_FindPlanetName+7p
					; sub_D425+4j
		ld	(SaveA2), a
		ld	a, b
		ld	(var01+1), a
		ld	(SaveHL1), hl
		ld	hl, (SaveHL1)
		ld	(SaveHL2), hl
		xor	a
		ld	(SaveA3), a	; Длина	введенного имени планеты при поиске
		call	Clear2ZnkLine	; очиска двух знакоместных линий
					; вх:  ----
					; вых: b=#00
		call	PrintSymbol_SP	; печать одного	символа
					; (печать сообщения по номеру
					; вх:  номер сообщения после call
					; вых: hl,de,bc,a - ????
					; )
; ---------------------------------------------------------------------------
		db 6			; Печатать всё заглавными буквами
; ---------------------------------------------------------------------------
		ld	a, (SaveA2)
		call	PrintMessage2	; Печать сообщения из группы 2 в буфере/на экране
					; вх: a	- номер	сообщения [#01..#00]
					; вых: (LLBA98)=#00 - печатать п/п LLBA9D

loc_B13E:				; CODE XREF: InputTextString+34j
					; InputTextString+38j ...
		call	WaitPressKey	; ожидание нажатия на клавишу
					; вх:  ----
					; вых: ----
		ld	(SaveA4), a
		cp	0Dh
		jr	z, loc_B197
		cp	0FEh ; '■'
		jr	z, loc_B179
		ld	a, (SaveA4)
		cp	30h ; '0'
		jr	c, loc_B13E
		cp	5Bh ; '['
		jr	nc, loc_B13E
		cp	3Ah ; ':'
		jr	c, loc_B15F
		cp	40h ; '@'
		jr	c, loc_B13E

loc_B15F:				; CODE XREF: InputTextString+3Cj
		ld	d, a
		ld	a, (SaveA3)	; Длина	введенного имени планеты при поиске

var01:					; DATA XREF: InputTextString+4w
		cp	0Ah
		jr	nc, loc_B197
		inc	a
		ld	(SaveA3), a	; Длина	введенного имени планеты при поиске
		ld	a, d
		ld	hl, (SaveHL2)
		ld	(hl), a
		inc	hl
		ld	(SaveHL2), hl
		call	PrintMessage1_A	; Печать сообщения из группы 1 в буфере/на экране
					; вх: A	- номер	сообщения
		jr	loc_B13E
; ---------------------------------------------------------------------------

loc_B179:				; CODE XREF: InputTextString+2Dj
		ld	a, (SaveA3)	; Длина	введенного имени планеты при поиске
		and	a
		jr	z, loc_B13E
		dec	a
		ld	(SaveA3), a	; Длина	введенного имени планеты при поиске
		ld	hl, (SaveHL2)
		dec	hl
		ld	(SaveHL2), hl
		call	sub_B026
		ld	b, 8

loc_B18F:				; CODE XREF: InputTextString+73j
		halt
		djnz	loc_B18F
		call	ResetPressedKeys ; сброс битов нажатых клавиш
					; вх:  ----
					; вых: b=#00
					;      hl - ????
		jr	loc_B13E
; ---------------------------------------------------------------------------

loc_B197:				; CODE XREF: InputTextString+29j
					; InputTextString+48j
		ld	hl, (SaveHL2)
		ld	(hl), 0
		call	PrnCrd_CRLF	; установка флага регистра печати, сброс координаты X, увеличение координаты Y
					; вх:  ----
					; вых: ----
		call	Pause_14Int	; Пауза	14h прерывания

loc_B1A2:				; CODE XREF: InputTextString+8Aj
		ld	a, (PressKeyPrnSymbol) ; Печатный символ нажатой клавиши
					;  =#FE	- BackSpace
					;  =#FF	- ничего не нажато
		cp	0Dh
		jr	z, loc_B1A2
		jp	ResetPressedKeys ; сброс битов нажатых клавиш
; End of function InputTextString	; вх:  ----
					; вых: b=#00
					;      hl - ????

; =============== S U B	R O U T	I N E =======================================

; Позиционирование курсора на ближайшую	к нему планету и печать	её названия и растояния	до неё

Cmd_D_Curs2NearPlanet:			; CODE XREF: RAM:A804j
		call	SearchNearPlanet ; Поиск ближайшей к курсору планеты, формирование данных о ней,  установка её
					;   текущей целью и отрисовка курсора если отображена карта

PrnNameFoundedPlanet:			; CODE XREF: Cmd_R_FindPlanetName+2Ej
		call	Clear2ZnkLine	; очиска двух знакоместных линий
					; вх:  ----
					; вых: b=#00
		ld	a, 3
		call	PrintMessage_A_UpperCase ; new equ PrintMessage1_A
					;
					; Печать сообщения заглавными буквами
					; A - номер сообщения
		call	PrnCrd_CRLF	; установка флага регистра печати, сброс координаты X, увеличение координаты Y
					; вх:  ----
					; вых: ----
		call	PrintFuelToPlanet ; печать расстояния до планеты на карте
					;
		jp	FX_Beep		; звуковой сигнал
; End of function Cmd_D_Curs2NearPlanet	; вх:  ----
					; вых: ----

; =============== S U B	R O U T	I N E =======================================

; Печать малого	курсора	на карте глобальной/локальной
; Вх:  (CursorWidth) - ширина курсора
;      (Pilot_CrdXTarget),(Pilot_CrdYTarget) - координаты курсора на карте
; Вых: hl,de,bc,a - не определены

PrintSmallCursOnMap:			; CODE XREF: Cmd_O_LocalMap+77j
					; Cmd_I_GlobalMap+4Ap ...
		ld	a, (CursorWidth) ; ширина курсора
		cp	0Ah
		jr	z, loc_B211
		ld	a, (Pilot_CrdXSystem) ;	координата X текущей системы
		ld	b, a
		ld	a, (Pilot_CrdXTarget) ;	координата X малого курсора на большой карте
		sub	b
		jr	c, loc_B1DC
		add	a, a
		ret	c
		add	a, a
		ret	c
		ld	b, a
		ld	a, 61h ; 'a'
		add	a, b
		ret	c
		jr	loc_B1E7
; ---------------------------------------------------------------------------

loc_B1DC:				; CODE XREF: PrintSmallCursOnMap+Fj
		neg
		add	a, a
		ret	c
		add	a, a
		ret	c
		ld	b, a
		ld	a, 61h ; 'a'
		sub	b
		ret	c

loc_B1E7:				; CODE XREF: PrintSmallCursOnMap+1Aj
		ld	(PrnCrdXCursor), a ; координата	X малого курсора на экране
		ld	a, (Pilot_CrdYSystem) ;	координата Y текущей системы
		ld	b, a
		ld	a, (Pilot_CrdYTarget) ;	+103 (последний	байт для сохранения)
					; координата Y малого курсора на большой карте
		sub	b
		jr	c, loc_B1FD
		add	a, a
		ret	c
		ld	b, a
		ld	a, 60h ; '`'
		add	a, b
		ret	c
		jr	loc_B206
; ---------------------------------------------------------------------------

loc_B1FD:				; CODE XREF: PrintSmallCursOnMap+32j
		neg
		add	a, a
		ret	c
		ld	b, a
		ld	a, 60h ; '`'
		sub	b
		ret	c

loc_B206:				; CODE XREF: PrintSmallCursOnMap+3Bj
		cp	19h
		ret	c
		cp	0A7h ; 'з'
		ret	nc
		ld	(PrnCrdYCursor), a ; координата	Y малого курсора на экране
		jr	loc_B221
; ---------------------------------------------------------------------------

loc_B211:				; CODE XREF: PrintSmallCursOnMap+5j
		ld	a, (Pilot_CrdXTarget) ;	координата X малого курсора на большой карте
		ld	(PrnCrdXCursor), a ; координата	X малого курсора на экране
		ld	a, (Pilot_CrdYTarget) ;	+103 (последний	байт для сохранения)
					; координата Y малого курсора на большой карте
		srl	a
		add	a, 18h
		ld	(PrnCrdYCursor), a ; координата	Y малого курсора на экране

loc_B221:				; CODE XREF: PrintSmallCursOnMap+4Fj
		jp	PrintCursorOnScr ; Печать курсора на экране карты галактики
; End of function PrintSmallCursOnMap	; Вх:  (PrnCrdXCursor) - координата X печати [1..#FE]
					;      (PrnCrdYCursor) - координата Y печати
					;      (CursorWidth) - ширина курсора
					; Вых: hl,de,bc,a - не определены

; =============== S U B	R O U T	I N E =======================================

; уменьшение координаты	Y и печать малого курсора
; вх:  ----
; вых: (LLA813),(LLA814) - экранные координаты малого курсора

MoveCursorUp:				; CODE XREF: RAM:A7FEj
		call	PrintSmallCursOnMap ; Печать малого курсора на карте глобальной/локальной
					; Вх:  (CursorWidth) - ширина курсора
					;      (Pilot_CrdXTarget),(Pilot_CrdYTarget) - координаты курсора на карте
					; Вых: hl,de,bc,a - не определены
		ld	a, (Pilot_CrdYTarget) ;	+103 (последний	байт для сохранения)
					; координата Y малого курсора на большой карте
		dec	a
		dec	a
		cp	0FEh ; '■'
		jr	c, loc_B231
		xor	a

loc_B231:				; CODE XREF: MoveCursorUp+Aj
		ld	(Pilot_CrdYTarget), a ;	+103 (последний	байт для сохранения)
					; координата Y малого курсора на большой карте
		jr	loc_B256
; End of function MoveCursorUp


; =============== S U B	R O U T	I N E =======================================

; увеличение координаты	Y и печать малого курсора
; вх:  ----
; вых: (LLA813),(LLA814) - экранные координаты малого курсора

MoveCursorDown:				; CODE XREF: RAM:A7FBj
