; Меню покупки товаров

Cmd_2_BuyCargo:				; CODE XREF: RAM:AdrFunctionsj
		ld	a, (PilotExtWeapon) ; +93 наличие доп вооружения
					;   7,=1 - ECM Jammer
					;   6,=1 - Cloaking device
					;   5,=1 - нельзя купить товары(в трюме	беженцы)
					;   4
					;   3 =1 3я миссия была	выполнена
					;   2 =1 - третья миссия выполнена
					;   1 =1 - второя миссия выполнена
					;   0 =1 - первая миссия выполнена
		bit	5, a
		jr	nz, loc_B2BF
		ld	a, (PilotMission1) ; байт первой миссии
					;  =0 миссия не	выдана
					; <>0 1я миссия	выдана
		and	a
		jr	z, loc_B2C7
		ld	de, 5B17h	; Если выдана 1я миссия, предложить спасти беженцев
		ld	hl, 201h
		call	PrintSpecialMessage ; спец. сообщение (беженцы.	пираты,	3я миссия и т.д)
		ld	a, 0B6h	; '╢'
		ld	(PrnCrdXCursor), a ; координата	X малого курсора на экране
		ld	a, 76h ; 'v'
		ld	(PrnCrdYCursor), a ; координата	Y малого курсора на экране
		ld	a, 3Dh ; '='
		ld	(RadiusCircleMap), a
		call	PrintCircleMap	; Печать круга
		call	WaitPressKey	; ожидание нажатия на клавишу
					; вх:  ----
					; вых: ----
		cp	59h ; 'Y'
		jr	nz, loc_B2BF
		ld	(PilotLargeCargo), a ; +49 large cargo bay
					;   =#59 если взята 1я миссия
		xor	a
		ld	(PilotFreeCargo), a ; Оставшаяся грузоподъемность корабля
		ld	hl, PilotCargo	; 24 Наличие груза в корабле (17 байт)
					; +00 Food
		ld	b, 11h

loc_B2B6:				; CODE XREF: Cmd_2_BuyCargo+3Dj
		ld	(hl), a
		inc	hl
		djnz	loc_B2B6
		ld	hl, PilotExtWeapon ; +93 наличие доп вооружения
					;   7,=1 - ECM Jammer
					;   6,=1 - Cloaking device
					;   5,=1 - нельзя купить товары(в трюме	беженцы)
					;   4
					;   3 =1 3я миссия была	выполнена
					;   2 =1 - третья миссия выполнена
					;   1 =1 - второя миссия выполнена
					;   0 =1 - первая миссия выполнена
		set	5, (hl)

loc_B2BF:				; CODE XREF: Cmd_2_BuyCargo+5j
					; Cmd_2_BuyCargo+2Dj
		call	Pause_24Int	; Пауза	24h прерывания
		jp	Cmd_Ent_Inventory ; Печать содержимого трюма
; ---------------------------------------------------------------------------
data_B2C5:	db 11110001b		; DATA XREF: Cmd_2_BuyCargo+58o
		db 11110000b
; ---------------------------------------------------------------------------

loc_B2C7:				; CODE XREF: Cmd_2_BuyCargo+Bj
		call	ClsAndPrintRamk	; Очистка экрана с атрибутами #07,
					; прорисовка рамки вокруг всего	экрана,
					; установка начальных координат	печати текста
					; вх:  ---
					; вых: (LLA80D)	- координаты печати
					;      hl,de,bc,a - ????
		call	SetCrdX_SP	; Установка координаты X печати
					; вх:  байт после call - координата X
					; вых: ----
					;
; ---------------------------------------------------------------------------
		db 10h
; ---------------------------------------------------------------------------
		ld	a, 0FFh
		call	PrnMsg_A_CRLF	; печать сообщения, на конце LF/CR
					; вх:  a - номер собщения
					; вых: hl,de,bc,a - ????
		ld	de, data_B2C5
		call	SetAttrFrom_DE	; установка атрибутов экрана
					; de - адрес строки с механикой	установки
					;      bit 7-3 - колво знакомест по горизонтали	атрибут	=5
					;      bit 2-1 - кол-во	переводов строки без установки атрибутов
					;	       =0 печать двух атрибутов	=7 на 5822 и 5823 и выход
		call	FillAttr_21line	; Заполнение атрибутом =5 третьей снизу(21-й) атрибутной строки
		call	sub_B52E
		ld	hl, PilotPlanetGov ; 74	???
		ld	(word_AF35), hl	; адрес	в таблице количества товаров

loc_B2E5:				; CODE XREF: Cmd_2_BuyCargo+9Bj
		ld	hl, (word_AF31)	; адрес	в таблице количества товаров
		inc	hl
		ld	(word_AF31), hl	; адрес	в таблице количества товаров
		call	PrnOneProduct	; печать названия цены и количества товара
					; вх:  (LLAF30)	- номер	товара
					;      (LLAF33)	- адрес	в таблице цен товаров
					;      (LLAF35)	- адрес	в таблице количества товаров
					; вых: cy=1 - товара нет
					;      hl,de,bc,a - ????
		jr	c, loc_B30F
		call	SaveCrdPrn	; сохранение координат печати
					; вх:  ----
					; вых: hl - координаты

