		push	af		; печать числа
					; вх:  hl - печатаемое число
					;      cy=1 - число вида (12345=>1234.5)
					; вых: (LLA88E)=#00
					;      (LLA88D)=#01
					;      a=#01
					;      hl,de,bc	- ????
		push	hl
		call	PrintPrefixNumber ; печать предваряющих	число нулей или	пробелов
					; вх:  hl - число
					;      (LLA88D)=#00 печатать нули
