					; вых: b=#00
					;      hl,de,c,a - ????
		pop	hl
		ld	a, 1
		ld	(FlgPrnNumber),	a ; =#00 печатать число	с ведущими нулями (иначе с пробелами)
		ld	(SavePrintNumber), hl ;	для хранения числа для печати
