					; вх:  de - какой разряд печатать
					;      (LLB757)	- печатаемое число
					; вых: (LLB757)	- остаток печатаемого числа
					;      hl,de,bc,a - ????
		ld	de, 100
		call	PrintDigitNumber ; печать старшего разряда числа
					; вх:  de - какой разряд печатать
					;      (LLB757)	- печатаемое число
					; вых: (LLB757)	- остаток печатаемого числа
					;      hl,de,bc,a - ????
		ld	de, 0Ah
		call	PrintDigitNumber ; печать старшего разряда числа
					; вх:  de - какой разряд печатать
					;      (LLB757)	- печатаемое число
					; вых: (LLB757)	- остаток печатаемого числа
