; уменьшение денег (от 0 до 999.9)
; вх:  de - количество денег (от 0.1 до	6553.5)
; вых: cy=1 - нехватка денег
;      hl,de,a - ????

DecCASH:				; CODE XREF: sub_B3A1+15p
					; Cmd_4_BuyEquip+B5p
		ld	hl, (PilotCash1) ; деньги пилота (от 0 до 1000)
					;  CASH	0..65535 - 0.0..6553.5
					;
		and	a
		sbc	hl, de
		jr	nc, loc_B895
		ld	hl, (PilotCash2) ; 19-20 деньги	пилота (количество целых тысяч)
					;  CASH	0..65535 - 0000..65535000
					;
		ld	a, l
		or	h
		scf
		ret	z
		dec	hl
		ld	(PilotCash2), hl ; 19-20 деньги	пилота (количество целых тысяч)
					;  CASH	0..65535 - 0000..65535000
					;
		ld	hl, 10000
		and	a
		sbc	hl, de
		ld	de, (PilotCash1) ; деньги пилота (от 0 до 1000)
					;  CASH	0..65535 - 0.0..6553.5
					;
		add	hl, de

loc_B895:				; CODE XREF: DecCASH+6j
		ld	(PilotCash1), hl ; деньги пилота (от 0 до 1000)
					;  CASH	0..65535 - 0.0..6553.5
					;
		and	a
		ret
; End of function DecCASH


