PrnRndPairChr:				; DATA XREF: RAM:6FE3o
		call	SetFlgPrn_xx1	; установка флага регистра печати (первая буква	заглавная)
		call	NextDescrPlanet	; Преобразование переменных для	формирования описания
					; Вх:  ---
					; Вых: a - псевдослучайное случайно число
					;      hl,de - не определены
		and	3

loc_B91F:				; CODE XREF: PrnRndPairChr+22j
		push	af
		call	NextDescrPlanet	; Преобразование переменных для	формирования описания
					; Вх:  ---
					; Вых: a - псевдослучайное случайно число
					;      hl,de - не определены
		and	3Eh ; '>'
		ld	hl, TxtChr4Descr
		ld	d, 0
		ld	e, a
		add	hl, de
		push	hl
		call	sub_B98A
		pop	hl
		inc	hl
		call	sub_B98A
		pop	af
		and	a
		ret	z
		dec	a
		jr	loc_B91F
; End of function PrnRndPairChr


