; =============== S U B	R O U T	I N E =======================================

; печать инфы о	планете

Cmd_P_InfoPlanet:			; CODE XREF: RAM:A7E9j
		call	SearchNearPlanet ; Поиск ближайшей к курсору планеты, формирование данных о ней,  установка её
					;   текущей целью и отрисовка курсора если отображена карта
		call	PrintRamkMenu	; Печать рамки для меню
		ld	de, byte_FC03	; 22 атрибута +2 перевода строки
		call	SetAttrFrom_DE	; установка атрибутов экрана
					; de - адрес строки с механикой	установки
					;      bit 7-3 - колво знакомест по горизонтали	атрибут	=5
					;      bit 2-1 - кол-во	переводов строки без установки атрибутов
					;	       =0 печать двух атрибутов	=7 на 5822 и 5823 и выход
		ld	a, 0A3h	; 'г'
		call	PrnMess_A_Inidcator ; инфо о планете: DATA OF имяпланеты
		ld	a, 3
		call	SetPrnCrdY	; Установка координаты Y с контролем выхода за границы экрана
					; вх:  a - координата Y
					; вых: ----
					;
		call	PrintFuelToPlanet ; печать расстояния до планеты на карте
					;
		call	PrnCrd_CRLF	; установка флага регистра печати, сброс координаты X, увеличение координаты Y
					; вх:  ----
					; вых: ----
		call	PrintEconomyPlanet ; инфо о планете: Economy ...
		ld	a, 0A2h	; 'в'
		call	PrintMessage1_A_Colon ;	инфо о планете:	Government ...
		ld	a, 0B1h	; '▒'
		ld	b, a
		ld	a, (PlanetGovernment) ;	goverment (тип правительства)
		add	a, b
		call	sub_BA5A
		ld	a, 0C4h	; '─'
		call	PrintMessage1_A_Colon ;	инфо о планете:	Tech. level
		ld	a, 3
		ld	(DigitsInNumber), a ; ;количество печатаемых знаков числа (дополняется слева пробелами или нулями)
		ld	a, (PlanetTechLevel) ; Tech/Level (технический уровень)
		inc	a
		call	PrintNumber_A	; инфо о планете: Tech.	level ....
		call	DubleCRLF
		ld	a, 0D7h	; '╫'   ; инфо о планете: population
		call	PrintMessage2_A_Colon ;	печать сообщения с двоеточием на конце
					; вх:  a - номер собщения
					; вых: hl,de,bc,a - ????
		ld	a, (PlanetPopulation) ;	population (население) n/10 вида x.x
		call	PrintPrice_A	; инфо о планете: population ...
		ld	a, 0C6h	; '╞'
		call	sub_BA5A	; инфо о планете: population ... billion
		call	PrintSymbol_SP	; инфо о планете: (
; ---------------------------------------------------------------------------
		db 28h
; ---------------------------------------------------------------------------
		call	PrintTypePopulation ; инфо о планете: ................
		call	PrintSymbol_SP	; печать буквы 'S'
; ---------------------------------------------------------------------------
		db 53h
; ---------------------------------------------------------------------------
		ld	a, 29h ; ')'
		call	sub_BA5A	; инфо о планете: )
		ld	a, 6Fh ; 'o'
		call	PrintMessage2_A_Colon ;	инфо о планете:	Gross productivity
		ld	hl, (PlanetGrossProduct) ; Gross productivity (валовой доход)
					;
		ld	a, 5
		ld	(DigitsInNumber), a ; ;количество печатаемых знаков числа (дополняется слева пробелами или нулями)
		and	a
		call	PrintNumber_HL	; инфо о планете: Gross	productivity nnnnn
		call	PrintSymbol_SP	; печать пробела
; ---------------------------------------------------------------------------
		db 20h
; ---------------------------------------------------------------------------
		call	PrintSymbol_SP	; Печать буквы 'M'
; ---------------------------------------------------------------------------
		db 4Dh
; ---------------------------------------------------------------------------
		ld	a, 0E2h	; 'т'
		call	PrintMessage_A_UpperCase ; печать: CR
		call	DubleCRLF
		ld	a, 0FAh	; '·'
		call	PrintMessage1_A_Colon ;	печать:	Average	radius
		call	PrintRadiusPlanet ; печать: радиуса
		call	PrintSymbol_SP	; Печатаем пробел
; ---------------------------------------------------------------------------
		db 20h
; ---------------------------------------------------------------------------
		ld	a, 11h
		ld	(byte_AF30), a	; номер	товара
		call	sub_B06F	; печать: km
		call	DubleCRLF	; CrLf дважды
		ld	a, (PilotMission3) ; +92 >0 - выдана 3я	миссия
					;  =1 при стыковке будет выдана	3я миссиия ( =1	пора выдавать миссию будет =2 после прыжка)
					;  =2 при стыковке будет выдана	3я миссиия
					;  =3 выдана 3я	миссия (можно уничтожить станцию ракетой) (из станции вылетают таргоны)
					;  =4 выдана 3я	миссия,	корабль	находится в системе с целью (можно уничтожить станцию ракетой) (из станции вылетают таргоны)
					;  =5 3я миссия	выполнена, будет поздравление при стыковке
					;
					;
					;  =4 корабль захватили	пираты,	(сообщить при стыковке)	будет =3 после прыжка
					; 3,=1 станция уничтожена
		and	a
		jr	z, PrnDescrPlanet ; печать описания планеты
		ld	hl, PlanetData0	; если планета первая в	списке генерации
		call	CompareGalaxyData ; Сравнение данных о галактике с HL
					; вх:  hl - адрес данных для сравнения
					; вых: cy =1 не	равны
					;      cy =0 идентичны
		jr	c, PrnDescrPlanet ; печать описания планеты
		ld	a, 3		; атрибут
		ld	hl, 5A61h	; адрес	атрибутной строки
		call	FillAttrLineFrom_HL
		call	FillAttrLineFrom_HL
		ld	a, 0DEh	; '▐'
		jp	PrintMessage2	; Печать сообщения о захвате планеты таргонами
; ---------------------------------------------------------------------------

