; =============== S U B	R O U T	I N E =======================================

; печать символа с учетом флагов регистра
; вх:  a - код символа
;      (LLA80D),(LLA80E) - координаты печати
; вых: hl,de,bc,a - ????

PrintSymbol_A:				; CODE XREF: PrintMessage1_A+Cj
					; sub_BAE7+10j	...
		cp	41h ; 'A'
		jr	c, loc_BB49
		cp	5Bh ; '['
		jr	nc, loc_BB49
		push	af
		ld	a, (FlgPrnSym1)	; флаг печати =1 - печатать заглавными буквами
					;
					; ;флаги регистра печати
					; 1xx все заглавными
					; 2x0 все строчными
					; 2x1 первая буква сообщения заглавная
					;
					; 000 первое слово строчное, остальные с заглавной
					; 001 каждое слово с заглавной
					; 010 каждое слово с заглавной
					; 011 каждое слово с заглавной
					;
		cp	1
		jr	z, loc_BB4F
		ld	a, (FlgPrnSym3)	; флаг печати =1 - первая буква	заглавная
		and	a
		jr	z, loc_BB2F
		xor	a
		ld	(FlgPrnSym3), a	; флаг печати =1 - первая буква	заглавная
		ld	(FlgPrnSym2), a	; флаг печати
					; =1 был перевод строки
		jr	loc_BB4F
; ---------------------------------------------------------------------------

loc_BB2F:				; CODE XREF: PrintSymbol_A+14j
		ld	a, (FlgPrnSym2)	; флаг печати
					; =1 был перевод строки
		cp	1
		jr	nz, loc_BB43
		xor	a
		ld	(FlgPrnSym2), a	; флаг печати
					; =1 был перевод строки
		ld	a, (FlgPrnSym1)	; флаг печати =1 - печатать заглавными буквами
					;
					; ;флаги регистра печати
					; 1xx все заглавными
					; 2x0 все строчными
					; 2x1 первая буква сообщения заглавная
					;
					; 000 первое слово строчное, остальные с заглавной
					; 001 каждое слово с заглавной
					; 010 каждое слово с заглавной
					; 011 каждое слово с заглавной
					;
		cp	2
		jr	z, loc_BB43
		jr	loc_BB4F
; ---------------------------------------------------------------------------

loc_BB43:				; CODE XREF: PrintSymbol_A+24j
					; PrintSymbol_A+2Fj
		pop	af
		add	a, 20h ; ' '
		push	af
		jr	loc_BB4F
; ---------------------------------------------------------------------------

loc_BB49:				; CODE XREF: PrintSymbol_A+2j
					; PrintSymbol_A+6j
		push	af
		ld	a, 1
		ld	(FlgPrnSym2), a	; флаг печати
					; =1 был перевод строки

loc_BB4F:				; CODE XREF: PrintSymbol_A+Ej
					; PrintSymbol_A+1Dj ...
		ld	a, (FlgPrnDescr) ; =1 генерим строку с описанием планеты
		cp	1
		jp	z, PrnSym2MsgDesc ; Печать описания планеты в строку
					; Вх:  a  - код	символа
					;      (CrdXPrnSymbol),(CrdYPrnSymbol) - координаты печати
					; Вых: bc =#0020
					;      hl,de,a - не определены
		pop	af
; End of function PrintSymbol_A


; =============== S U B	R O U T	I N E =======================================

; Печать одного	символа
; Вх:  a - печатный код	символа
; Вых: hl,de,bc,a - не определены

PrintSymbol_8x8:			; CODE XREF: PrintMsgDescr+8p
		push	af
		ld	hl, CrdXPrnSymbol ; Координаты печати символа
		inc	(hl)		; координата X=X+1
		ld	a, (hl)		; проверка координаты X	и перевод строки если надо
		cp	20h ; ' '
		jr	c, loc_BB68	; A - печатный код символа
		ld	a, 1
		ld	(hl), a
		call	IncPrnCrdY	; Приращение координаты	Y

loc_BB68:				; CODE XREF: PrintSymbol_8x8+8j
		pop	af		; A - печатный код символа
		ld	hl, FontInRAM	; шрифт
		sub	20h ; ' '
		ld	c, a
		ld	b, 0
		sla	c
		rl	b
		sla	c
		rl	b
		sla	c
		rl	b
		add	hl, bc
		push	hl

loc_BB7F:				; DATA XREF: PrnTitTxtSpace+Bo
					; Print_ELITE+8o ...
		ld	hl, 4000h
		ld	a, (CrdYPrnSymbol)
		cp	10h
		jp	nc, loc_BB93
		cp	8
		jp	nc, loc_BB9D
		ld	b, a
		jp	loc_BBA4	; рассчитываем адрес печати на экране
; ---------------------------------------------------------------------------

loc_BB93:				; CODE XREF: PrintSymbol_8x8+2Fj
		sub	10h
		ld	b, a
		ld	de, 1000h
		add	hl, de
		jp	loc_BBA4	; рассчитываем адрес печати на экране
; ---------------------------------------------------------------------------

loc_BB9D:				; CODE XREF: PrintSymbol_8x8+34j
		sub	8
		ld	b, a
		ld	de, 800h
		add	hl, de

loc_BBA4:				; CODE XREF: PrintSymbol_8x8+38j
					; PrintSymbol_8x8+42j
		ld	c, 0		; рассчитываем адрес печати на экране
		srl	b		; bc=a*16
		rr	c
		srl	b
		rr	c
		srl	b
		rr	c
		add	hl, bc
		ld	b, 0
		ld	a, (CrdXPrnSymbol) ; Координаты	печати символа
		ld	c, a
		add	hl, bc		; HL - адрес печати
		pop	de		; DE - адрес в шрифте
		ld	b, 8

loc_BBBD:				; CODE XREF: PrintSymbol_8x8+6Bj
		ld	a, (de)
		ld	c, (hl)

loc_BBBF:				; DATA XREF: PrintIndDanger:loc_A511o
					; PrintIndDanger+91o ...
		xor	c
		ld	(hl), a
		inc	h
		inc	de
		djnz	loc_BBBD
		ret
; End of function PrintSymbol_8x8


