					; вых: (LLBA98)=#00 - печатать п/п LLBA9D

; =============== S U B	R O U T	I N E =======================================

; Преобразование переменных для	формирования описания
; Вх:  ---
; Вых: a - псевдослучайное случайно число
;      hl,de - не определены

NextDescrPlanet:			; CODE XREF: PrnRndPairChr+3p
					; PrnRndPairChr+9p ...
		ld	hl, (DescrPlanetData)
		sla	l
		ex	de, hl
		ld	hl, (DescrPlanetData+2)
		adc	hl, de
		ld	a, h
		ld	(DescrPlanetData), hl
		ex	de, hl
		ld	(DescrPlanetData+2), hl
		ret
; End of function NextDescrPlanet


; =============== S U B	R O U T	I N E =======================================

; умножение на 2 с сохранением знака
