Mult_Ax2_sign:				; CODE XREF: CalcNewCrdObj_Pl+14p
					; CalcNewCrdObj_Pl+22p
		ld	c, a
		rl	c
		rra
		rl	c
		rla
		rr	c
		ret
; End of function Mult_Ax2_sign

