					; ClsAndPrintRamk+24r

; =============== S U B	R O U T	I N E =======================================

; Очистка экрана с атрибутами #07,
; прорисовка рамки вокруг всего	экрана,
; установка начальных координат	печати текста
; вх:  ---
; вых: (LLA80D)	- координаты печати
;      hl,de,bc,a - ????

ClsAndPrintRamk:			; CODE XREF: BeginGame+57p PrnCocpitp	...
		di
		ld	(SaveSP3), sp
		ld	sp, 5B00h
		ld	de, 707h
		ld	c, 18h

loc_BCAB:				; CODE XREF: ClsAndPrintRamk+13j
		ld	b, 10h

loc_BCAD:				; CODE XREF: ClsAndPrintRamk+10j
		push	de
		djnz	loc_BCAD
		dec	c
		jp	nz, loc_BCAB
		ld	de, 0
		ld	c, 0C0h	; '└'

loc_BCB9:				; CODE XREF: ClsAndPrintRamk+21j
		ld	b, 10h

loc_BCBB:				; CODE XREF: ClsAndPrintRamk+1Ej
		push	de
		djnz	loc_BCBB
		dec	c
		jp	nz, loc_BCB9
		ld	sp, (SaveSP3)
		ei

PrintRamk:				; CODE XREF: Cmd_I_GlobalMap+42p
					; Cmd_L_PilotInfo:loc_D199j
		ld	b, 0C0h	; '└'
		ld	de, 20h	; ' '
		ld	hl, 4000h

loc_BCCF:				; CODE XREF: ClsAndPrintRamk+36j
		ld	a, (hl)
		or	80h ; 'А'
		ld	(hl), a
		add	hl, de
		djnz	loc_BCCF
		ld	b, 0C0h	; '└'
		ld	hl, 401Fh

loc_BCDB:				; CODE XREF: ClsAndPrintRamk+42j
		ld	a, (hl)
		or	1
		ld	(hl), a
		add	hl, de
		djnz	loc_BCDB
		ld	hl, 4000h
		call	PrintHorLine	; печать горизонтальной	линии
					; вх: HL - адрес на экране
		ld	hl, 57E0h
		call	PrintHorLine	; печать горизонтальной	линии
					; вх: HL - адрес на экране
		xor	a
		ld	l, a
		inc	a
		ld	h, a
		ld	(CrdXPrnSymbol), hl ; Координаты печати	символа
		ret
; End of function ClsAndPrintRamk

