AdrInMsgDescr2:	dw 0			; DATA XREF: PrnPlDestNewCase+1Fr
					; PrnPlDestNewCase+23w	...
LenMsgDescr1:	db 0			; DATA XREF: PrnSym2MsgDesc+23w
					; PrnSym2MsgDesc+38r ...
LenMsgDescr2:	db 0			; DATA XREF: PrnPlDestNewCase:loc_B961o
					; PrnSym2MsgDesc+Fr ...
AdrInMsgDescr1:	dw 0			; DATA XREF: PrnSym2MsgDesc+3Fw
					; PrintMsgDescr:loc_BD75r ...

; =============== S U B	R O U T	I N E =======================================

; Печать описания планеты в строку
; Вх:  a  - код	символа
;      (CrdXPrnSymbol),(CrdYPrnSymbol) - координаты печати
; Вых: bc =#0020
;      hl,de,a - не определены

PrnSym2MsgDesc:				; CODE XREF: PrintSymbol_A+44j
		ld	hl, (AdrInMsgDescr2)
		inc	hl
		ld	(AdrInMsgDescr2), hl
		pop	af
		ld	(hl), a
		cp	2Eh ; '.'
		jp	z, PrintMsgDescr ; Печать сформированной строки
					; Вх:  ---
					; Вых: bc =#0020
					;      hl,de,a - не определены
					;
		ld	b, a
		ld	a, (LenMsgDescr2)
		inc	a
		ld	(LenMsgDescr2),	a
		cp	31
		ret	c
		ld	a, 20h ; ' '
		cp	b
		jp	z, PrintMsgDescr ; Печать сформированной строки
					; Вх:  ---
					; Вых: bc =#0020
					;      hl,de,a - не определены
					;
		call	FindLastSpace	; Поиск	первого	пробела	с конца	строки
					; Вх:  (AdrInMsgDescr2)	- адрес	последнего символа в строке
					; Вых: b - кол-во символов от конца строки до пробела, включая пробел
					;      (AdrInMsgDescr2)	- адрес	последнего пробела в строке
		ld	a, b
		ld	(LenMsgDescr1),	a
		and	a
		jr	z, loc_BD52
		ld	hl, (AdrInMsgDescr2)
		inc	hl
		ld	c, b
		ld	b, 0
		ld	de,  msgDescrLine2+1
		ldir
		ld	hl, msgDescrLine1
		ld	a, (LenMsgDescr1)
		ld	e, a
		ld	d, 0
		add	hl, de
		ld	(AdrInMsgDescr1), hl
		ld	a, (LenMsgDescr1)
		cp	1Fh
		jp	nc, PrintMsgDescr ; Печать сформированной строки
					; Вх:  ---
					; Вых: bc =#0020
					;      hl,de,a - не определены
					;
		ld	hl, (AdrInMsgDescr2)
		ld	b, a

loc_BD4A:				; CODE XREF: PrnSym2MsgDesc+51j
		ld	(hl), 0
		inc	hl
		djnz	loc_BD4A
		ld	a, (LenMsgDescr1)

loc_BD52:				; CODE XREF: PrnSym2MsgDesc+27j
					; PrnSym2MsgDesc+5Fj
		push	af
		call	FindLastSpace	; Поиск	первого	пробела	с конца	строки
					; Вх:  (AdrInMsgDescr2)	- адрес	последнего символа в строке
					; Вых: b - кол-во символов от конца строки до пробела, включая пробел
					;      (AdrInMsgDescr2)	- адрес	последнего пробела в строке
		call	sub_D000	; ищем ноль с адреса (#BCF6)
		pop	af
		dec	a
		jr	nz, loc_BD52
; End of function PrnSym2MsgDesc


; =============== S U B	R O U T	I N E =======================================

; Печать сформированной	строки
; Вх:  ---
; Вых: bc =#0020
;      hl,de,a - не определены
;

PrintMsgDescr:				; CODE XREF: PrnSym2MsgDesc+Bj
					; PrnSym2MsgDesc+1Cj ...
		ld	hl, 28676
		ld	b, 30

loc_BD62:				; CODE XREF: PrintMsgDescr+Ej
		push	bc
		push	hl
		ld	a, (hl)
		call	PrintSymbol_8x8	; Печать одного	символа
					; Вх:  a - печатный код	символа
					; Вых: hl,de,bc,a - не определены
		pop	hl
		inc	hl
		pop	bc
		djnz	loc_BD62
		call	PrnCrd_CRLF	; установка флага регистра печати, сброс координаты X, увеличение координаты Y
					; вх:  ----
					; вых: ----
		ld	a, 0
		ld	(FlgPrnSym2), a	; флаг печати
					; =1 был перевод строки

loc_BD75:				; CODE XREF: ClearDescrMsg+1Aj
		ld	hl, (AdrInMsgDescr1)
		ld	(AdrInMsgDescr2), hl
		ld	hl, msgDescrLine1
		ld	(AdrInMsgDescr1), hl
		ld	a, (LenMsgDescr1)
		ld	(LenMsgDescr2),	a
		xor	a
		ld	(LenMsgDescr1),	a
		ld	b, 1Eh
		ld	c, 20h ; ' '
		ld	hl,  msgDescrLine2+1
		ld	de,  msgDescrLine1+1

loc_BD95:				; CODE XREF: PrintMsgDescr+3Dj
		ld	a, (hl)
		ld	(de), a
		ld	(hl), c
		inc	hl
		inc	de
		djnz	loc_BD95
		ret
; End of function PrintMsgDescr


; =============== S U B	R O U T	I N E =======================================

; Очистка строк	описания и установка переменных
; Вх:  ---
; Вых: bc =#0020
;      hl,de,a - не определены
;

ClearDescrMsg:				; DATA XREF: RAM:6FDBo
		ld	a, 1
		ld	(FlgPrnDescr), a ; =1 генерим строку с описанием планеты
		ld	b, 31
		ld	a, 20h ; ' '
		ld	hl,  msgDescrLine2+1

loc_BDA9:				; CODE XREF: ClearDescrMsg+Ej
		ld	(hl), a
		inc	hl
		djnz	loc_BDA9
		ld	hl, msgDescrLine1
		ld	(AdrInMsgDescr1), hl
		xor	a
		ld	(LenMsgDescr1),	a
		jr	loc_BD75
; End of function ClearDescrMsg


; =============== S U B	R O U T	I N E =======================================

; Завершение печати описания планеты
; Вх:  ---
; Вых: hl,de,bc,a - не определены

CloseDescrMsg:				; DATA XREF: RAM:6FDDo
		ld	a, 0
		ld	(FlgPrnDescr), a ; =1 генерим строку с описанием планеты
		ld	a, (LenMsgDescr2)
		and	a
		call	nz, PrintMsgDescr ; Печать сформированной строки
					; Вх:  ---
					; Вых: bc =#0020
					;      hl,de,a - не определены
					;
		ret
; End of function CloseDescrMsg


; =============== S U B	R O U T	I N E =======================================

; Поиск	первого	пробела	с конца	строки
; Вх:  (AdrInMsgDescr2)	- адрес	последнего символа в строке
; Вых: b - кол-во символов от конца строки до пробела, включая пробел
;      (AdrInMsgDescr2)	- адрес	последнего пробела в строке

FindLastSpace:				; CODE XREF: PrnSym2MsgDesc+1Fp
					; PrnSym2MsgDesc+57p ...
		ld	hl, (AdrInMsgDescr2)
		ld	b, 0

loc_BDCB:				; CODE XREF: FindLastSpace+Aj
		dec	hl
		ld	a, (hl)
		inc	b
		cp	20h ; ' '
		jr	nz, loc_BDCB
		ld	(AdrInMsgDescr2), hl
		ld	de,  msgDescrLine1+1
		and	a
		sbc	hl, de
		ret	nc
		ld	hl, msgDescrLine2
		ld	(AdrInMsgDescr2), hl
		jr	FindLastSpace	; Поиск	первого	пробела	с конца	строки
; End of function FindLastSpace		; Вх:  (AdrInMsgDescr2)	- адрес	последнего символа в строке
					; Вых: b - кол-во символов от конца строки до пробела, включая пробел
					;      (AdrInMsgDescr2)	- адрес	последнего пробела в строке

