; =============== S U B	R O U T	I N E =======================================

; ищем ноль с адреса (#BCF6)

sub_D000:				; CODE XREF: PrnSym2MsgDesc+5Ap
		ld	b, 20h ; ' '
		ld	hl, (AdrInMsgDescr2)

loc_D005:				; CODE XREF: sub_D000+Cj
		ld	a, (hl)
		ld	c, a
		ld	(hl), b
		ld	b, c
		inc	hl
		xor	a
		cp	c
		jr	nz, loc_D005
		ret
; End of function sub_D000


; =============== S U B	R O U T	I N E =======================================

; Используется только в	Cmd_P_PlanetInfo

PrintTypePopulation2:			; CODE XREF: PrintTypePopulation+6j
		ld	a, h
		srl	a
		srl	a
		push	af
		and	7
		cp	3
		jr	nc, loc_D020
		add	a, 0E3h	; 'у'
		call	PrintMessage1_A_Space ;	Сообщение: LARGE

loc_D020:				; CODE XREF: PrintTypePopulation2+Aj
		pop	af
		srl	a
		srl	a
		srl	a
		cp	6
		jr	nc, loc_D030
		add	a, 0E6h	; 'ц'
		call	PrintMessage1_A_Space ;	Сообщение: GREEN

loc_D030:				; CODE XREF: PrintTypePopulation2+1Aj
		ld	hl, (PlanetData0) ; 6 байт для генерации данных	о планете
		ld	a, h
		ld	b, a
		ld	hl, (PlanetData1)
		ld	a, h
		xor	b
		and	7
		push	af
		cp	6
		jr	nc, loc_D046
		add	a, 0ECh	; 'ь'
		call	PrintMessage1_A_Space ;	Сообщение: SLIMY

loc_D046:				; CODE XREF: PrintTypePopulation2+30j
		ld	hl, (PlanetData2)
		ld	a, h
		and	3
		ld	b, a
		pop	af
		add	a, b
		and	7
		add	a, 0F2h	; 'Є'   ; одно из:
					; RODENT
					; FROG
					; LIZARD
					; LOBSTER
					; BIRD
					; HUMANOID
					; FELINE
					; INSECT
					;

loc_D053:				; CODE XREF: PrintTypePopulation+Bj
		jp	PrintMessage1_A	; Печать сообщения из группы 1 в буфере/на экране
; End of function PrintTypePopulation2	; вх: A	- номер	сообщения


; =============== S U B	R O U T	I N E =======================================

; Печать радиуса планеты

PrintRadiusPlanet:			; CODE XREF: Cmd_P_InfoPlanet+88p
		ld	hl, (PlanetData2)
		ld	a, h
		and	0Fh
		add	a, 0Bh
		ld	hl, (PlanetData1)
		ld	l, h
		ld	h, a
		ld	a, 5
		ld	(DigitsInNumber), a ; ;количество печатаемых знаков числа (дополняется слева пробелами или нулями)
		and	a
		jp	PrintNumber_HL	; печать числа
; End of function PrintRadiusPlanet	; вх:  hl - печатаемое число
					;      cy=1 - число вида (12345=>1234.5)
					; вых: (LLA88E)=#00
					;      (LLA88D)=#01
					;      a=#01
					;      hl,de,bc	- ????

; =============== S U B	R O U T	I N E =======================================

; Сравнение данных о галактике с HL
; вх:  hl - адрес данных для сравнения
; вых: cy =1 не	равны
;      cy =0 идентичны

CompareGalaxyData:			; CODE XREF: Cmd_P_InfoPlanet+A3p
					; sub_D6B3+131p
		ld	de, PilotGalaxyData0 ; данные по галактике
		ld	b, 6

loc_D071:				; CODE XREF: CompareGalaxyData+Bj
		ld	a, (de)
		cp	(hl)
		jr	nz, loc_D07B
		inc	de
		inc	hl
		djnz	loc_D071
		and	a
		ret
; ---------------------------------------------------------------------------

loc_D07B:				; CODE XREF: CompareGalaxyData+7j
		scf
		ret
; End of function CompareGalaxyData


; =============== S U B	R O U T	I N E =======================================

; Печать списка	товаров	на планете

Cmd_K_MarketPrice:			; CODE XREF: RAM:A7ECj
		call	PrintRamkMenu	; Печать рамки для меню
		ld	a, 0A7h	; 'з'
		call	PrnMess_A_Inidcator ; Печать заголовка меню
		ld	hl, 310h
		ld	(CrdXPrnSymbol), hl ; Координаты печати	символа
		ld	a, 0FFh
		call	PrnMsg_A_CRLF	; печать сообщения, на конце LF/CR
					; вх:  a - номер собщения
					; вых: hl,de,bc,a - ????
		ld	de, byte_FC0B	; 27 атрибута +2 перевода строки
		call	SetAttrFrom_DE	; установка атрибутов экрана
					; de - адрес строки с механикой	установки
					;      bit 7-3 - колво знакомест по горизонтали	атрибут	=5
					;      bit 2-1 - кол-во	переводов строки без установки атрибутов
					;	       =0 печать двух атрибутов	=7 на 5822 и 5823 и выход
		ld	a, (InFreeSpace) ; <>0 между системами (перехват F)
		and	a
		ret	nz
		xor	a
		ld	(byte_AF30), a	; номер	товара
		ld	hl, unk_AF0C
		ld	(word_AF33), hl	; адрес	в таблице цен товаров
		ld	hl, PilotPlanetGov ; 74	???
		ld	(word_AF35), hl	; адрес	в таблице количества товаров

loc_D0AB:				; CODE XREF: Cmd_K_MarketPrice+38j
		call	PrnOneProduct	; печать названия цены и количества товара
					; вх:  (LLAF30)	- номер	товара
					;      (LLAF33)	- адрес	в таблице цен товаров
					;      (LLAF35)	- адрес	в таблице количества товаров
					; вых: cy=1 - товара нет
					;      hl,de,bc,a - ????
		ld	hl, byte_AF30	; номер	товара
		inc	(hl)
		ld	a, (hl)
		cp	11h
		jr	c, loc_D0AB
		ret
; End of function Cmd_K_MarketPrice

; ---------------------------------------------------------------------------
byte_D0B8:	db 0			; DATA XREF: Cmd_L_PilotInfo+C6w
					; PrintLaserNamer ...

; =============== S U B	R O U T	I N E =======================================

; Печать инфы по кл. 'L'

Cmd_L_PilotInfo:			; CODE XREF: BeginGame+D5p
					; GameMain+34p	...
		ld	a, 0Bh
		ld	(WhatOnScreen),	a ; Что	изображено на экране
					;  =0..3 в полете номер	обзорного экрана (front, rear, left, right)
					;  =#04	меню покупки товаров
					;  =#05	меню продажи товаров
					;  =#06	меню покупки оборудования
					;  =#07	глобальная карта
					;  =#08	локальная карта
					;  =#09	инфо о планете еще не выведено
					;  =#0A	прайс планеты
					;  =#0B	инфо о пилоте
					;  =#0C	Инвентрь
					;  =#20	инфо о планете
		ld	a, 96h ; 'Ц'
		call	PrintMessage2	; Печать сообщения из группы 2 в буфере/на экране
					; вх: a	- номер	сообщения [#01..#00]
					; вых: (LLBA98)=#00 - печатать п/п LLBA9D
		call	PrintIndDanger	; Печать индикатора опасности и	индикатора ракеты
					; Вх:  (IndDanger) - состояние индикатора
					; Вых: b =#00
					;      hl,de,c,a - не определены
		ld	de, data_FB9E
		call	SetAttrFrom_DE	; установка атрибутов экрана
					; de - адрес строки с механикой	установки
					;      bit 7-3 - колво знакомест по горизонтали	атрибут	=5
					;      bit 2-1 - кол-во	переводов строки без установки атрибутов
					;	       =0 печать двух атрибутов	=7 на 5822 и 5823 и выход
		call	SetCrdX_SP	; Установка координаты X печати
					; вх:  байт после call - координата X
					; вых: ----
					;
; ---------------------------------------------------------------------------
		db 6
; ---------------------------------------------------------------------------
		call	PrintSymbol_SP	; печать одного	символа
					; (печать сообщения по номеру
					; вх:  номер сообщения после call
					; вых: hl,de,bc,a - ????
					; )
; ---------------------------------------------------------------------------
		db 7Eh
; ---------------------------------------------------------------------------
		ld	a, 4
		call	SetPrnCrdY	; Установка координаты Y с контролем выхода за границы экрана
					; вх:  a - координата Y
					; вых: ----
					;
		ld	a, 2		; печать назв. текущей планеты
		call	PrintMessage_A	; Печать сообщения ':сообщение'
					;   A -	номер сообщения
		ld	a, 3		; печать названия планеты назначения
		call	PrintMessage_A	; Печать сообщения ':сообщение'
					;   A -	номер сообщения
		ld	a, 6
		call	SetPrnCrdY	; Установка координаты Y с контролем выхода за границы экрана
					; вх:  a - координата Y
					; вых: ----
					;
		call	PrintSymbol_SP	; печать остатка топлива
; ---------------------------------------------------------------------------
		db 5
; ---------------------------------------------------------------------------
		call	PrintSymbol_SP	; печать остатака денег
; ---------------------------------------------------------------------------
		db 7
; ---------------------------------------------------------------------------
		ld	a, 71h ; 'q'
		call	PrintMessage2_A_Colon ;	Печать 'Legal Status'
		call	PrintSymbol_SP	; печать одного	символа
					; (печать сообщения по номеру
					; вх:  номер сообщения после call
					; вых: hl,de,bc,a - ????
					; )
; ---------------------------------------------------------------------------
		db 20h
; ---------------------------------------------------------------------------
		ld	b, 12h
		ld	a, (PilotLegalStatus) ;	Правовой статус	пилота
					;  0 - clean
					;  1..31h offender
					;  32h..FFh fugitiv
		and	a

loc_D0FF:
		jr	z, loc_D107
		cp	32h ; '2'
		jr	c, loc_D106
		inc	b

loc_D106:				; CODE XREF: Cmd_L_PilotInfo+4Aj
		inc	b

loc_D107:				; CODE XREF: Cmd_L_PilotInfo:loc_D0FFj
		ld	a, b
		call	PrnMsg_A_CRLF	; печать правового статуса
		ld	a, 72h ; 'r'
		call	PrintMessage2_A_Colon ;	Печать 'Rating'
		call	PrintSymbol_SP	; печать одного	символа
					; (печать сообщения по номеру
					; вх:  номер сообщения после call
					; вых: hl,de,bc,a - ????
					; )
; ---------------------------------------------------------------------------
		db 20h
; ---------------------------------------------------------------------------
		ld	hl, PilotRating2
		ld	a, (hl)
		and	a
		jr	nz, loc_D123
		dec	hl
		ld	de, byte_D1E2
		ld	b, 15h
		jr	loc_D128
; ---------------------------------------------------------------------------

loc_D123:				; CODE XREF: Cmd_L_PilotInfo+60j
