		db 6Bh
; ---------------------------------------------------------------------------

loc_D2AE:				; CODE XREF: Cmd_Ent_Inventory+27j
		call	PrnCrd_CRLF	; установка флага регистра печати, сброс координаты X, увеличение координаты Y
					; вх:  ----
					; вых: ----
		ld	a, (PilotExtWeapon) ; +93 наличие доп вооружения
					;   7,=1 - ECM Jammer
					;   6,=1 - Cloaking device
					;   5,=1 - нельзя купить товары(в трюме	беженцы)
					;   4
					;   3 =1 3я миссия была	выполнена
					;   2 =1 - третья миссия выполнена
					;   1 =1 - второя миссия выполнена
					;   0 =1 - первая миссия выполнена
		bit	5, a
		jr	z, loc_D2C0
		ld	a, 0Ch
		call	PrintMessage2	; Печать сообщения из группы 2 в буфере/на экране
					; вх: a	- номер	сообщения [#01..#00]
					; вых: (LLBA98)=#00 - печатать п/п LLBA9D
		call	PrnCrd_CRLF	; установка флага регистра печати, сброс координаты X, увеличение координаты Y
					; вх:  ----
					; вых: ----

loc_D2C0:				; CODE XREF: Cmd_Ent_Inventory+3Dj
		xor	a
		ld	(byte_AF30), a	; номер	товара
		ld	hl, PilotRnd	; 23 ????
		ld	(word_AF31), hl	; адрес	в таблице количества товаров

loc_D2CA:				; CODE XREF: Cmd_Ent_Inventory+5Ej
		call	sub_AFB9	; печать названия и количества товара
					; вх:  (LLAF30)	- номер	товара
					;      (LLAF31)	- адрес	в таблице количества товаров
					; вых: cy=1 - товара нет
					;      hl,de,bc,a - ????
		call	nc, PrnCrd_CRLF	; установка флага регистра печати, сброс координаты X, увеличение координаты Y
					; вх:  ----
					; вых: ----
		ld	hl, byte_AF30	; номер	товара
		inc	(hl)
		ld	a, (hl)
		cp	11h
		jr	c, loc_D2CA
		ret
; End of function Cmd_Ent_Inventory

; ---------------------------------------------------------------------------
		db    0
		db    0
Dat_D2DC:	db 1100b		; DATA XREF: MenuSaveLoad+3o
					; атрибуты для меню работы с лентой
					; 1 атрибут + 4перевода	строки
		db 10010b		; 2 атрибута + 2 перевода строки
		db 10010b		; 2 атрибута + 2 перевода строки
		db 10011b		; 2 атрибута + 3 перевода строки
byte_D2E0:	db 10000000b		; 16 атрибутов + 2 атрибута на 5822, 5823
byte_D2E1:	db 0			; DATA XREF: MenuSaveLoad+12w
					; MenuSaveLoad+35r ...
					; =1 сохраненка	загружена
SaveSP7:	db    0			; DATA XREF: MenuSaveLoad+19w
					; MenuSaveLoad:loc_D301r
		db    0

; =============== S U B	R O U T	I N E =======================================

; меню работы с	лентой
;  A =0	игра не	загружена
;  nZ -	сохраненная игра загружена
;  Z  -	не загружена

MenuSaveLoad:				; CODE XREF: BeginGame+50p
					; GameMain+2Ep
		call	ClsAndPrintRamk	; Очистка экрана с атрибутами #07,
					; прорисовка рамки вокруг всего	экрана,
					; установка начальных координат	печати текста
					; вх:  ---
					; вых: (LLA80D)	- координаты печати
					;      hl,de,bc,a - ????
		ld	de, Dat_D2DC	; атрибуты для меню работы с лентой
					; 1 атрибут + 4перевода	строки
		call	SetAttrFrom_DE	; установка атрибутов экрана
					; de - адрес строки с механикой	установки
					;      bit 7-3 - колво знакомест по горизонтали	атрибут	=5
					;      bit 2-1 - кол-во	переводов строки без установки атрибутов
					;	       =0 печать двух атрибутов	=7 на 5822 и 5823 и выход
		call	FillAttr_21line	; Заполнение атрибутом =5 третьей снизу(21-й) атрибутной строки
		ld	a, 1111b
		call	FillAttr_3line	; заполнение атрибутом трех верхних атрибутных строк
					; и рисование линии внизу третьего знакоместа
					; вх: A	- атрибут
		xor	a
		ld	(byte_D2E1), a	; =1 сохраненка	загружена
		inc	a
		call	PrintMessage2	; Печать сообщения из группы 2 в буфере/на экране
					; вх: a	- номер	сообщения [#01..#00]
					; вых: (LLBA98)=#00 - печатать п/п LLBA9D
		ld	(SaveSP7), sp

loc_D301:				; CODE XREF: MenuSaveLoad+2Dj
					; MenuSaveLoad:loc_D3EDj
		ld	sp, (SaveSP7)
		call	WaitPressKey	; ожидание нажатия на клавишу
					; вх:  ----
					; вых: ----
		sub	31h ; '1'
		jr	z, LoadGame
		dec	a
		jp	z, SaveGame
		dec	a
		jr	nz, loc_D301
		call	BeepPause24	; выход	из меню
		call	ResetPressedKeys ; сброс битов нажатых клавиш
					; вх:  ----
					; вых: b=#00
					;      hl - ????
		ld	a, (byte_D2E1)	; =1 сохраненка	загружена
		and	a
		ret	nz
		xor	a
		ret
; ---------------------------------------------------------------------------

LoadGame:				; CODE XREF: MenuSaveLoad+26j
		ld	hl, InputText	; введенный тексто (имя	пилота при выгрузке/загрузке, имя планеты при поиске)
		call	sub_D425

loc_D326:				; CODE XREF: MenuSaveLoad+6Aj
					; MenuSaveLoad+74j
		call	sub_D41B
		scf
		inc	d
		ex	af, af'
		dec	d
		di
		call	562h		; загрузка отложенной
		ei
		jp	nc, sub_D3FF
		ld	a, 1
		ld	(byte_D2E1), a	; =1 сохраненка	загружена
		ld	a, 0D6h	; '╓'
		call	sub_D42C	; что-то печатаем
		ld	hl, InputText	; введенный тексто (имя	пилота при выгрузке/загрузке, имя планеты при поиске)
		ld	de, PilotName	; 1..11	имя пилота
		ld	a, (hl)
		and	a
		jp	z, loc_D3E2
		ld	b, 11

loc_D34C:				; CODE XREF: MenuSaveLoad+72j
		ld	a, (de)
		cp	(hl)
		jr	nz, loc_D326
		or	(hl)
		jp	z, loc_D3E2
		inc	hl
		inc	de
		djnz	loc_D34C
		jr	loc_D326
; ---------------------------------------------------------------------------

SaveGame:				; CODE XREF: MenuSaveLoad+29j
		ld	hl, PilotName	; 1..11	имя пилота
		call	sub_D425
		ld	hl, SunCrd	; данные для печати солнца длина 9 байт
					; crd low x planet
		ld	de, PilotDataOfSun ; данные солнца 9 байт, при сохранени сюда копируются
		ld	bc, 9
		ldir
		ld	a, 2
		call	sub_D42C	; что-то печатаем
		call	WaitPressKey	; ожидание нажатия на клавишу
					; вх:  ----
					; вых: ----
		call	sub_D41B
		call	4C6h
		ld	a, 0
		out	(0FEh),	a
		ei
		jp	nc, loc_D407	; если ошибка
		ld	a, 97h ; 'Ч'
		call	sub_D42C	; что-то печатаем
		ld	hl, 0C01h
		ld	(CrdXPrnSymbol), hl ; Координаты печати	символа
		ld	a, 4		; сообщение Security number
		call	PrintMessage2	; Печать сообщения из группы 2 в буфере/на экране
					; вх: a	- номер	сообщения [#01..#00]
					; вых: (LLBA98)=#00 - печатать п/п LLBA9D
		ld	hl, (PilotRating1) ; генерим код
		rl	l
		ld	e, h
		rl	e
		ld	a, (PilotNumGalaxy) ; номер галактики
		ld	hl, PilotExtWeapon ; +93 наличие доп вооружения
					;   7,=1 - ECM Jammer
					;   6,=1 - Cloaking device
					;   5,=1 - нельзя купить товары(в трюме	беженцы)
					;   4
					;   3 =1 3я миссия была	выполнена
					;   2 =1 - третья миссия выполнена
					;   1 =1 - второя миссия выполнена
					;   0 =1 - первая миссия выполнена
		bit	3, (hl)
		jr	z, loc_D3A5
		set	3, a

loc_D3A5:				; CODE XREF: MenuSaveLoad+BDj
		bit	6, (hl)
		jr	z, loc_D3AB
		set	4, a

loc_D3AB:				; CODE XREF: MenuSaveLoad+C3j
		ld	hl, (PilotCash2) ; 19-20 деньги	пилота (количество целых тысяч)
					;  CASH	0..65535 - 0000..65535000
					;
		rlca
		rlca
		rlca
		ld	d, a
		ld	a, e
		call	sub_D3F0
		ld	a, h
		call	sub_D3F0
		ld	a, l
		call	sub_D3F0
		ld	a, l
		xor	d
		add	a, 3Dh ; '='
		ld	d, a
		xor	e
		add	a, 66h ; 'f'
		ld	e, a
		xor	h
		add	a, 8Fh ; 'П'
		ld	h, a
		xor	l
		add	a, 0C7h	; '╟'
		ld	l, a
		push	de
		and	a
		call	PrintNumber_HL	; печать числа
					; вх:  hl - печатаемое число
					;      cy=1 - число вида (12345=>1234.5)
					; вых: (LLA88E)=#00
					;      (LLA88D)=#01
					;      a=#01
					;      hl,de,bc	- ????
		ld	a, 5
		ld	(DigitsInNumber), a ; ;количество печатаемых знаков числа (дополняется слева пробелами или нулями)
		xor	a
		ld	(FlgPrnNumber),	a ; =#00 печатать число	с ведущими нулями (иначе с пробелами)
		pop	hl
		and	a
		call	PrintNumber_HL	; печать числа
					; вх:  hl - печатаемое число
					;      cy=1 - число вида (12345=>1234.5)
					; вых: (LLA88E)=#00
					;      (LLA88D)=#01
					;      a=#01
					;      hl,de,bc	- ????

loc_D3E2:				; CODE XREF: MenuSaveLoad+63j
					; MenuSaveLoad+6Dj
		ld	hl, PilotName	; 1..11	имя пилота
		ld	de, PilotDataSaved ; для сохранения в памяти последней загруженной игры
		ld	bc, 102
		ldir

loc_D3ED:				; CODE XREF: sub_D3FF+10j sub_D3FF+1Aj
		jp	loc_D301
; End of function MenuSaveLoad


; =============== S U B	R O U T	I N E =======================================


