					; MenuSaveLoad+D3p ...
		ld	b, 8
		ld	c, 0

loc_D3F4:				; CODE XREF: sub_D3F0:loc_D3F8j
		rra
		jr	nc, loc_D3F8
		inc	c

loc_D3F8:				; CODE XREF: sub_D3F0+5j
		djnz	loc_D3F4
		rr	c
		rr	d
		ret
; End of function sub_D3F0


