		halt
		ld	a, (PressKeyPrnSymbol) ; Печатный символ нажатой клавиши
					;  =#FE	- BackSpace
					;  =#FF	- ничего не нажато
		cp	20h ; ' '
		jr	nz, loc_D411

loc_D407:				; CODE XREF: MenuSaveLoad+9Aj
		call	Clear2ZnkLine	; очиска двух знакоместных линий
					; вх:  ----
					; вых: b=#00
		ld	a, 0C7h	; '╟'
		call	sub_D42C
		jr	loc_D3ED
; ---------------------------------------------------------------------------

loc_D411:				; CODE XREF: sub_D3FF+6j
		ld	a, 3
		call	sub_D42C
		call	RestorePilotFromMemory ; Восстановление	данных пилота из памяти
					; Вх:  ---
					; Вых: bc =#0000
					;      hl,de - не определены
		jr	loc_D3ED
; End of function sub_D3FF


