sub_D425:				; CODE XREF: MenuSaveLoad+3Fp
					; MenuSaveLoad+79p
		ld	b, 0Ah
		ld	a, 8
		jp	InputTextString	; Ввод текстовой строки
; End of function sub_D425		; вх:  a  - ???
					;      b  - макс. длина	вводимой строки
					;      hl - адрес вводимой строки
					;      (CrxXPrnSymbol),(CrxYPrnSymbol) - координаты печати

; =============== S U B	R O U T	I N E =======================================


sub_D42C:				; CODE XREF: MenuSaveLoad+58p
					; MenuSaveLoad+89p ...
		push	af
		xor	a
		ld	(FlgPrnSym1), a	; флаг печати =1 - печатать заглавными буквами
					;
					; ;флаги регистра печати
					; 1xx все заглавными
					; 2x0 все строчными
					; 2x1 первая буква сообщения заглавная
					;
					; 000 первое слово строчное, остальные с заглавной
					; 001 каждое слово с заглавной
					; 010 каждое слово с заглавной
					; 011 каждое слово с заглавной
					;
		ld	hl, 1600h
		ld	(CrdXPrnSymbol), hl ; Координаты печати	символа
		call	sub_B0CB
		pop	af
		call	PrintMessage2	; Печать сообщения из группы 2 в буфере/на экране
					; вх: a	- номер	сообщения [#01..#00]
					; вых: (LLBA98)=#00 - печатать п/п LLBA9D
		call	PrnCrd_CRLF	; установка флага регистра печати, сброс координаты X, увеличение координаты Y
					; вх:  ----
					; вых: ----
		jp	FX_Beep		; звуковой сигнал
; End of function sub_D42C		; вх:  ----
					; вых: ----
