msgTimePause:	db 0			; DATA XREF: SetSecondaryMsg+13o
					; пауза	между сообщениями миссий (1й и 3й)
msgTimeLife:	db 0			; DATA XREF: SetPrnMsgOnVS+6o
					; SetPrnMsgOnVS+2Fw ...
					; время	жизни (кол-во кадров печати) сообщения в полёте
					; =#00 ничего печатать не надо
msgBlink:	db 0			; DATA XREF: SetPrnMsgOnVS+Do
					; цикл мигания сообщения в бою
msgCrdX:	db 0			; DATA XREF: SetPrnMsgOnVS+33w
					; SetPrnMsgOnVS+45r
					; координата Y печати сообщения	(в бою бонус/уничтоженное)
msgNumber:	db 0			; DATA XREF: DecEnergyShieldFR:HeavyDamager
					; SetPrnMsgOnVS+37w ...
					; =FD уже что-то уничтожено (номер сообщения) (какой-то	груз)
LastBonusCash:	dw 0			; DATA XREF: AddCashObj+3w
					; SetPrnMsgOnVS:loc_D4F7r
					; денежное вознаграждение за уничтожение в бою
nMsgDamage:	db 0F5h			; DATA XREF: DecEnergyShieldFR:loc_A61Aw
					; SetPrnMsgOnVS:loc_D4E5r
					; номер	ссобщения что повреждено в бою

; =============== S U B	R O U T	I N E =======================================


PrnMsgOnViewScr:			; CODE XREF: GameMain+67p GameMain+86p ...
		xor	a
		ld	(FlgPrnSym1), a	; флаг печати =1 - печатать заглавными буквами
					;
					; ;флаги регистра печати
					; 1xx все заглавными
					; 2x0 все строчными
					; 2x1 первая буква сообщения заглавная
					;
					; 000 первое слово строчное, остальные с заглавной
					; 001 каждое слово с заглавной
					; 010 каждое слово с заглавной
					; 011 каждое слово с заглавной
					;
		ld	a, (WhatOnScreen) ; Что	изображено на экране
					;  =0..3 в полете номер	обзорного экрана (front, rear, left, right)
					;  =#04	меню покупки товаров
					;  =#05	меню продажи товаров
					;  =#06	меню покупки оборудования
					;  =#07	глобальная карта
					;  =#08	локальная карта
					;  =#09	инфо о планете еще не выведено
					;  =#0A	прайс планеты
					;  =#0B	инфо о пилоте
					;  =#0C	Инвентрь
					;  =#20	инфо о планете
		cp	4
		jr	c, PrnTxtOnViewScr ; печать Front view в буфере
		ld	hl, loc_BBBF
		ld	(hl), 0		; nop  печать по ld
		call	SetPrnMsgOnVS	; Печать сообщения на обзорном экране
		ld	hl, loc_BBBF	; xor c	 печать	по xor
		ld	(hl), 0A9h ; 'й'
		ret
; ---------------------------------------------------------------------------

PrnTxtOnViewScr:			; CODE XREF: PrnMsgOnViewScr+9j
		ld	hl,  loc_BB7F+2	; печать Front view в буфере
		set	7, (hl)
		ld	hl, 10Ah
		ld	(CrdXPrnSymbol), hl ; Координаты печати	символа
		ld	a, (WhatOnScreen) ; Что	изображено на экране
					;  =0..3 в полете номер	обзорного экрана (front, rear, left, right)
					;  =#04	меню покупки товаров
					;  =#05	меню продажи товаров
					;  =#06	меню покупки оборудования
					;  =#07	глобальная карта
					;  =#08	локальная карта
					;  =#09	инфо о планете еще не выведено
					;  =#0A	прайс планеты
					;  =#0B	инфо о пилоте
					;  =#0C	Инвентрь
					;  =#20	инфо о планете
		add	a, 60h ; '`'
		call	PrintMessage1_A	; Печать сообщения из группы 1 в буфере/на экране
					; вх: A	- номер	сообщения
		ld	a, 0AFh	; 'п'
		call	PrnMsg_A_CRLF	; печать сообщения, на конце LF/CR
					; вх:  a - номер собщения
					; вых: hl,de,bc,a - ????
		call	SetPrnMsgOnVS	; Печать сообщения на обзорном экране
		ld	hl,  loc_BB7F+2
		res	7, (hl)
		ret
; End of function PrnMsgOnViewScr


; =============== S U B	R O U T	I N E =======================================

; Печать сообщения на обзорном экране

SetPrnMsgOnVS:				; CODE XREF: PrnMsgOnViewScr+10p
					; PrnMsgOnViewScr+31p
		call	PrnCountdownJump ; Печать обратного отсчета перед прыжком
		call	PrintIndDanger	; Печать индикатора опасности и	индикатора ракеты
					; Вх:  (IndDanger) - состояние индикатора
					; Вых: b =#00
					;      hl,de,c,a - не определены
		ld	hl, msgTimeLife	; время	жизни (кол-во кадров печати) сообщения в полёте
					; =#00 ничего печатать не надо
		ld	a, (hl)
		and	a
		jr	nz, PrnMsgOnVS	; Печать сообщения в полёте
					; вх:  hl - адрес времени жизни	сообщения
		ld	hl, msgBlink	; цикл мигания сообщения в бою
		inc	(hl)
		bit	0, (hl)
		jr	nz, SetSecondaryMsg ; установка	второстепенных сообщений
		ld	b, 9
		ld	hl, MissileJammed ; 7,=1 ракету	не получилось запустить
					; 6-0,=	координата Y печти сообщения
					;
					; +1 номер сообщения

loc_D4A0:				; CODE XREF: SetPrnMsgOnVS+20j
		bit	7, (hl)
		jr	nz, loc_D4A9
		inc	hl
		inc	hl
		djnz	loc_D4A0
		ret
; ---------------------------------------------------------------------------

loc_D4A9:				; CODE XREF: SetPrnMsgOnVS+1Cj
		res	7, (hl)
		ld	c, (hl)
		inc	hl
		ld	b, (hl)

SetMsg4PrnViewScr:			; CODE XREF: GoJump+5Fj
		push	bc
		call	FX_Beep		; звуковой сигнал
					; вх:  ----
					; вых: ----
		pop	bc

loc_D4B3:				; CODE XREF: SetSecondaryMsg:loc_D54Dj
		ld	a, 0Eh
		ld	(msgTimeLife), a ; время жизни (кол-во кадров печати) сообщения	в полёте
					; =#00 ничего печатать не надо

loc_D4B8:				; CODE XREF: GoJump+56p
		ld	a, c
		ld	(msgCrdX), a	; координата Y печати сообщения	(в бою бонус/уничтоженное)
		ld	a, b
		ld	(msgNumber), a	; =FD уже что-то уничтожено (номер сообщения) (какой-то	груз)
		ret
; ---------------------------------------------------------------------------

PrnMsgOnVS:				; CODE XREF: SetPrnMsgOnVS+Bj
		dec	(hl)		; Печать сообщения в полёте
					; вх:  hl - адрес времени жизни	сообщения
		cp	4
		ret	c
		ld	a, (WhatOnScreen) ; Что	изображено на экране
					;  =0..3 в полете номер	обзорного экрана (front, rear, left, right)
					;  =#04	меню покупки товаров
					;  =#05	меню продажи товаров
					;  =#06	меню покупки оборудования
					;  =#07	глобальная карта
					;  =#08	локальная карта
					;  =#09	инфо о планете еще не выведено
					;  =#0A	прайс планеты
					;  =#0B	инфо о пилоте
					;  =#0C	Инвентрь
					;  =#20	инфо о планете
		cp	4
		ret	nc
		ld	a, (msgCrdX)	; координата Y печати сообщения	(в бою бонус/уничтоженное)
		ld	l, a
		ld	h, 0Eh
		ld	(CrdXPrnSymbol), hl ; Координаты печати	символа
		ld	a, (msgNumber)	; =FD уже что-то уничтожено (номер сообщения) (какой-то	груз)
		cp	0FDh ; '¤'
		jr	z, loc_D4E5
		cp	0E2h ; 'т'
		jr	z, loc_D4F7

loc_D4DF:				; CODE XREF: SetPrnMsgOnVS+6Fj
					; SetPrnMsgOnVS+78j
		ld	a, (msgNumber)	; =FD уже что-то уничтожено (номер сообщения) (какой-то	груз)
		jp	PrnMsg_A_CRLF	; печать сообщения, на конце LF/CR
					; вх:  a - номер собщения
					; вых: hl,de,bc,a - ????
; ---------------------------------------------------------------------------

loc_D4E5:				; CODE XREF: SetPrnMsgOnVS+53j
		ld	a, (nMsgDamage)	; номер	ссобщения что повреждено в бою
		cp	73h ; 's'
		jr	z, loc_D4F2
		ld	hl, 0A80Dh
		inc	(hl)
		inc	(hl)
		inc	(hl)

loc_D4F2:				; CODE XREF: SetPrnMsgOnVS+64j
		call	PrintMessage1_A	; Печать сообщения из группы 1 в буфере/на экране
					; вх: A	- номер	сообщения
		jr	loc_D4DF
; ---------------------------------------------------------------------------

loc_D4F7:				; CODE XREF: SetPrnMsgOnVS+57j
		ld	hl, (LastBonusCash) ; денежное вознаграждение за уничтожение в бою
		scf
		call	PrintNumber_HL	; печать числа
					; вх:  hl - печатаемое число
					;      cy=1 - число вида (12345=>1234.5)
					; вых: (LLA88E)=#00
					;      (LLA88D)=#01
					;      a=#01
					;      hl,de,bc	- ????
		jr	loc_D4DF
; End of function SetPrnMsgOnVS


; =============== S U B	R O U T	I N E =======================================

; установка второстепенных сообщений

SetSecondaryMsg:			; CODE XREF: SetPrnMsgOnVS+13j
		ld	a, (ShieldUnit4) ;   +0	- текущее значение
					;   -1 - отображенное на экране
		cp	9Fh ; 'Я'
		jr	c, loc_D550
		ld	a, (FuelScoopsOn) ; <>0	рядом с	солнцен, работает fuel scoops
		and	a
		jr	nz, loc_D53E
		ld	a, (AutoDocking) ; <>0(=#01) включена стыковка
		and	a
		jr	nz, loc_D539	; b - номер сообщения DOCKING COMPUTER ON
		ld	hl, msgTimePause ; пауза между сообщениями миссий (1й и	3й)
		ld	a, (hl)
		and	a
		jr	nz, loc_D532
		ld	a, 46h ; 'F'
		ld	(hl), a
		ld	a, (PilotMission3) ; +92 >0 - выдана 3я	миссия
					;  =1 при стыковке будет выдана	3я миссиия ( =1	пора выдавать миссию будет =2 после прыжка)
					;  =2 при стыковке будет выдана	3я миссиия
					;  =3 выдана 3я	миссия (можно уничтожить станцию ракетой) (из станции вылетают таргоны)
					;  =4 выдана 3я	миссия,	корабль	находится в системе с целью (можно уничтожить станцию ракетой) (из станции вылетают таргоны)
					;  =5 3я миссия	выполнена, будет поздравление при стыковке
					;
					;
					;  =4 корабль захватили	пираты,	(сообщить при стыковке)	будет =3 после прыжка
					; 3,=1 станция уничтожена
		dec	a
		jr	z, loc_D534	; b - номер сообщения MAYDAY! xxxx Invaded!
		ld	a, (PilotMission1) ; байт первой миссии
					;  =0 миссия не	выдана
					; <>0 1я миссия	выдана
		and	a
		ret	z
		ld	a, (PilotMission1_1) ; =1 - выдана(взята) 1я миссия
		and	a
		ret	nz
		ld	bc, 0C202h	; b - номер сообщения MAYDAY! Coriolis In Dander!
		jr	loc_D54D
; ---------------------------------------------------------------------------

loc_D532:				; CODE XREF: SetSecondaryMsg+18j
		dec	(hl)
		ret
; ---------------------------------------------------------------------------

loc_D534:				; CODE XREF: SetSecondaryMsg+21j
		ld	bc, 0F03h	; b - номер сообщения MAYDAY! xxxx Invaded!
		jr	loc_D54D
; ---------------------------------------------------------------------------

loc_D539:				; CODE XREF: SetSecondaryMsg+11j
		ld	bc, 7B05h	; b - номер сообщения DOCKING COMPUTER ON
		jr	loc_D54D
; ---------------------------------------------------------------------------

loc_D53E:				; CODE XREF: SetSecondaryMsg+Bj
		ld	a, (PilotFuelScoops) ; FuelScoops
		and	a
		ret	z
		ld	a, (Pilot_Fuel)	; Топливо
		inc	a
		call	SetPilotFuel	; Установка топлива
					; Вх:  a - новое значение Fuel
					; Вых: b - не определен
		ld	bc, 0A008h	; b - номер сообщения FUEL SCOOPS ON
					; с - координата Y печати

loc_D54D:				; CODE XREF: SetSecondaryMsg+30j
					; SetSecondaryMsg+37j ...
		jp	loc_D4B3
; ---------------------------------------------------------------------------

loc_D550:				; CODE XREF: SetSecondaryMsg+5j
		xor	a
		ld	(CloakingDeviceOn), a ;	 =1 включен Cloaking Device
					;  =1 расход энергии при использовании
		ld	l, 7
		ld	a, (WhatOnScreen) ; Что	изображено на экране
					;  =0..3 в полете номер	обзорного экрана (front, rear, left, right)
					;  =#04	меню покупки товаров
					;  =#05	меню продажи товаров
					;  =#06	меню покупки оборудования
					;  =#07	глобальная карта
					;  =#08	локальная карта
					;  =#09	инфо о планете еще не выведено
					;  =#0A	прайс планеты
					;  =#0B	инфо о пилоте
					;  =#0C	Инвентрь
					;  =#20	инфо о планете
		cp	4
		call	c, SetAtrViewScr ; печать атрибутов обзорного экрана
					; вх:  l - атрибут
					; вых: b=#00
					;      a=#00
					;      hl - ????
		ld	bc, 640Ah
		jr	loc_D54D
; End of function SetSecondaryMsg


; =============== S U B	R O U T	I N E =======================================

; Обнуление всех сообщений во время полёта
; Вх: ---
; Вых: a =#00
;      b =#00
;      hl,MissileJammed+9

ResetBattleMessages:			; CODE XREF: InitVarLaunch+3p
					; InitGamep ...
		ld	b, 9
		ld	hl, MissileJammed ; 7,=1 ракету	не получилось запустить
					; 6-0,=	координата Y печти сообщения
					;
					; +1 номер сообщения

loc_D568:				; CODE XREF: ResetBattleMessages+9j
		res	7, (hl)
		inc	hl
		inc	hl
		djnz	loc_D568
		xor	a
		ld	(msgNumber), a	; =FD уже что-то уничтожено (номер сообщения) (какой-то	груз)
		ret
; End of function ResetBattleMessages

; ---------------------------------------------------------------------------
JumpCountdown:	db 0			; DATA XREF: InitGame+38w GoJump+11r ...
					; обратный отсчет до прыжка
					; =#00 отсчёта еще нет

; =============== S U B	R O U T	I N E =======================================

; обработка клавиш гиперперехода G, H

GoJump:					; CODE XREF: GameMain:loc_72A2p
		ld	hl, ControlKey2	; 7,=1 - CapsS	-- Pause
					; 6,=1 - J	-- Jump	Drive
					; 5,=1 - G	-- Galactic Hyper Drive
					; 4,=1 - H	-- Hyper Drive
					; 3,=1 - 4	-- Right View/Equip Ship
					; 2,=1 - 3	-- Left	View/Sell Cargo
					; 1,=1 - 2	-- Rear	View/Buy Cargo
					; 0,=1 - 1	-- Front View/Launch
		ld	a, (hl)
		and	110000b
		ret	z
		ld	b, a
		ld	a, (hl)
		and	11001111b
		ld	(hl), a
		ld	a, 1
		ld	(byte_7C39), a	; =#01 нажата G	или H (прыжок)
		ld	a, (JumpCountdown) ; обратный отсчет до	прыжка
					; =#00 отсчёта еще нет
		and	a
		ret	nz
		ld	a, (IndDanger)	; <>0 в	полете (он же цвет индикатора опасности)
					; =0 пристыкован
					; =#04=%00 000 100 вылет со станции, в полёте (зелёный)
					; =#63=%01 100 011 4й энергоблок не полный (мигающий красный))
					; =#02=%00 000 010 один	из щитов front/rear пустой (красный)
					; =#06=%00 000 110 что-то рядом	(желтый)
		and	a
		jr	z, JumpDocked	; пристыкован, прыжок невозможен
		bit	5, b
		jr	z, loc_D5A6	; гиперпрыжок
		bit	4, b
		ret	z
		ld	a, (PilotGyperdrive) ; 58 гипердрайв
		and	a
		ret	z		; нет гипердрайва
		ld	a, 2
		ld	(JumpDocking), a ; =1 межпланетный прыжок/стыковка
					; =2 межгалактический прыжок
		ld	bc, 7406h
		jr	loc_D5C2
; ---------------------------------------------------------------------------

loc_D5A6:				; CODE XREF: GoJump+1Ej
		call	SearchNearPlanet ; гиперпрыжок
		ld	hl, (FuelToPlanet) ; требуется топлива для перелета до планеты
					;   =расстояние*4
					;
		ld	a, h
		and	a
		jr	nz, loc_D5D0	; нехватает топлива на прыжок
		ld	a, l
		and	a
		ret	z
		ld	b, a
		ld	a, (Pilot_Fuel)	; Топливо
		sub	b
		jr	c, loc_D5D0	; нехватает топлива на прыжок
		ld	a, 1
		ld	(JumpDocking), a ; =1 межпланетный прыжок/стыковка
					; =2 межгалактический прыжок
		ld	bc, 0C005h	; координаты печать цифр обратного отсчета

loc_D5C2:				; CODE XREF: GoJump+30j
		ld	a, 15h
		ld	(JumpCountdown), a ; обратный отсчет до	прыжка
					; =#00 отсчёта еще нет
		ld	(msgTimeLife), a ; время жизни (кол-во кадров печати) сообщения	в полёте
					; =#00 ничего печатать не надо
		call	loc_D4B8
		jp	FX_Beep		; звуковой сигнал
					; вх:  ----
					; вых: ----
; ---------------------------------------------------------------------------

loc_D5D0:				; CODE XREF: GoJump+3Aj GoJump+44j
		ld	bc, 0C106h	; нехватает топлива на прыжок
		jp	SetMsg4PrnViewScr
; ---------------------------------------------------------------------------

JumpDocked:				; CODE XREF: GoJump+1Aj
		call	ClsAndPrintRamk	; пристыкован, прыжок невозможен
		ld	hl, 70Bh
		ld	(CrdXPrnSymbol), hl ; Координаты печати	символа
		ld	a, 1
		ld	(FlgPrnSym1), a	; флаг печати =1 - печатать заглавными буквами
					;
					; ;флаги регистра печати
					; 1xx все заглавными
					; 2x0 все строчными
					; 2x1 первая буква сообщения заглавная
					;
					; 000 первое слово строчное, остальные с заглавной
					; 001 каждое слово с заглавной
					; 010 каждое слово с заглавной
					; 011 каждое слово с заглавной
					;
		ld	a, 0CDh	; '═'
		call	PrintMessage2	; Печать сообщения из группы 2 в буфере/на экране
					; вх: a	- номер	сообщения [#01..#00]
					; вых: (LLBA98)=#00 - печатать п/п LLBA9D
		call	FX_Beep		; звуковой сигнал
					; вх:  ----
					; вых: ----
		call	Pause_24Int	; Пауза	24h прерывания
		call	ResetPressedKeys ; сброс битов нажатых клавиш
					; вх:  ----
					; вых: b=#00
					;      hl - ????
		jp	Cmd_L_PilotInfo	; Печать инфы по кл. 'L'
; End of function GoJump


; =============== S U B	R O U T	I N E =======================================

; Печать обратного отсчета перед прыжком

PrnCountdownJump:			; CODE XREF: SetPrnMsgOnVSp
		ld	hl, JumpCountdown ; обратный отсчет до прыжка
					; =#00 отсчёта еще нет
		ld	a, (hl)
		and	a
		ret	z
		dec	(hl)
		jr	z, HyperspaceBegin ; сам прыжок
		ld	b, a
		ld	a, 2
		ld	(DigitsInNumber), a ; ;количество печатаемых знаков числа (дополняется слева пробелами или нулями)
		ld	hl, 101h
		ld	(CrdXPrnSymbol), hl ; Координаты печати	символа
		ld	a, b
		srl	a
		jp	PrintNumber_A	; печать числа
; ---------------------------------------------------------------------------

HyperspaceBegin:			; CODE XREF: PrnCountdownJump+7j
		call	ResetBattleMessages ; сам прыжок
		ld	a, (JumpDocking) ; =1 межпланетный прыжок/стыковка
					; =2 межгалактический прыжок
		sub	2
		jr	nz, sub_D65A	; прыжок к другой планете

loc_D61A:				; CODE XREF: sub_D65A+4j
		xor	a		; межгалактический прыжок
		ld	(PilotMission3), a ; +92 >0 - выдана 3я	миссия
					;  =1 при стыковке будет выдана	3я миссиия ( =1	пора выдавать миссию будет =2 после прыжка)
					;  =2 при стыковке будет выдана	3я миссиия
					;  =3 выдана 3я	миссия (можно уничтожить станцию ракетой) (из станции вылетают таргоны)
					;  =4 выдана 3я	миссия,	корабль	находится в системе с целью (можно уничтожить станцию ракетой) (из станции вылетают таргоны)
					;  =5 3я миссия	выполнена, будет поздравление при стыковке
					;
					;
					;  =4 корабль захватили	пираты,	(сообщить при стыковке)	будет =3 после прыжка
					; 3,=1 станция уничтожена
		ld	a, (PilotMission1) ; байт первой миссии
					;  =0 миссия не	выдана
					; <>0 1я миссия	выдана
		and	a
		jr	z, loc_D62B
		xor	a
		ld	(PilotMission1), a ; байт первой миссии
					;  =0 миссия не	выдана
					; <>0 1я миссия	выдана
		ld	(PilotMission1_1), a ; =1 - выдана(взята) 1я миссия

loc_D62B:				; CODE XREF: PrnCountdownJump+2Dj
		ld	(PilotGyperdrive), a ; 58 гипердрайв
		ld	a, (PilotNumGalaxy) ; номер галактики
		inc	a
		ld	(byte_9237), a	; номер	текущей	галактики? дробная часть цены топлива
		and	111b
		ld	(PilotNumGalaxy), a ; номер галактики
		ld	hl, PilotGalaxyData0 ; данные по галактике
		call	NextGalaxyData	; Изменение байт для следующей галактики
					; Вх:  ---
					; Вых: b =#00
					;      a - номер галактики
					;      hl - не определен
		call	NextGalaxyData	; Изменение байт для следующей галактики
					; Вх:  ---
					; Вых: b =#00
					;      a - номер галактики
					;      hl - не определен
		call	NextGalaxyData	; Изменение байт для следующей галактики
					; Вх:  ---
					; Вых: b =#00
					;      a - номер галактики
					;      hl - не определен
		xor	a
		ld	(PilotLegalStatus), a ;	Правовой статус	пилота
					;  0 - clean
					;  1..31h offender
					;  32h..FFh fugitiv
		call	SearchNearPlanet ; Поиск ближайшей к курсору планеты, формирование данных о ней,  установка её
					;   текущей целью и отрисовка курсора если отображена карта
		jr	sub_D6B3	; Гиперпрыжок
; End of function PrnCountdownJump


; =============== S U B	R O U T	I N E =======================================

; Изменение байт для следующей галактики
; Вх:  ---
; Вых: b =#00
;      a - номер галактики
;      hl - не определен

NextGalaxyData:				; CODE XREF: PrnCountdownJump+48p
					; PrnCountdownJump+4Bp	...
		ld	e, (hl)
		rlc	e
		ld	(hl), e
		inc	hl
		ld	d, (hl)
		rlc	d
		ld	(hl), d
		inc	hl
		ret
; End of function NextGalaxyData


; =============== S U B	R O U T	I N E =======================================

; прыжок к другой планете

sub_D65A:				; CODE XREF: PrnCountdownJump+23j
		ld	a, (PilotMission1) ; байт первой миссии
					;  =0 миссия не	выдана
					; <>0 1я миссия	выдана
		and	a
		jr	nz, loc_D61A	; межгалактический прыжок
		ld	a, (FuelToPlanet) ; требуется топлива для перелета до планеты
					;   =расстояние*4
					;
		ld	b, a
		ld	a, (Pilot_Fuel)	; Топливо
		sub	b
		ld	c, a
		call	SetPilotFuel	; Установка топлива
					; Вх:  a - новое значение Fuel
					; Вых: b - не определен
		ld	a, 46h ; 'F'
		sub	c
		ld	b, a
		ld	a, (PlanetEconomy) ; Economy (экономика)
		add	a, a
		add	a, b
		ld	(byte_9237), a	; номер	текущей	галактики? дробная часть цены топлива
		ld	hl, PilotLegalStatus ; Правовой	статус пилота
					;  0 - clean
					;  1..31h offender
					;  32h..FFh fugitiv
		srl	(hl)
		ld	a, (FlagsSetUp)	; 0-1,=00 управление SXNMA (LLFC0F)<>0 сброс CS,F,c
					;     =01 управление от	Kempston'а
					;     =10 управление от	курсора	76850
					;     =11 управление от	Sinclair right
					;   2,=1  управление приближено	к реальному (reaction)
					;   3,=1  вкл. инерционность поворота
					;   4,=1  управление инвертировано
					;   5,=1  вверх/вниз инвертировано
					;   6,=1  вкл. перехват	таргонов
					;   7,=1  звук включен
		bit	6, a
		jr	nz, loc_D68B
		ld	a, (RndWord)	; случайное число
		cp	0F9h ; '∙'
		jr	nz, sub_D6B3	; Гиперпрыжок

loc_D68B:				; CODE XREF: sub_D65A+28j
		inc	a
		ld	(InFreeSpace), a ; <>0 между системами (перехват F)
		ld	hl, Pilot_CrdXSystem ; координата X текущей системы
		ld	de, Pilot_CrdXTarget ; координата X малого курсора на большой карте
		ld	a, (de)
		add	a, (hl)
		rra
		ld	(hl), a
		ld	(de), a
		ld	hl, Pilot_CrdYSystem ; координата Y текущей системы
		ld	de, Pilot_CrdYTarget ; +103 (последний байт для	сохранения)
					; координата Y малого курсора на большой карте
		ld	a, (de)
		add	a, (hl)
		rr	a
		ld	(hl), a
		ld	(de), a
		xor	a
		ld	(CoriolisNear),	a ; <>0	вблизи станции,	можно стыковаться
		ld	(PlanetPresent), a ; название активной планеты
		ld	(plNameDest), a	; название планеты на которую настроен корабль
		jp	loc_D814
; End of function sub_D65A


