; Гиперпрыжок

sub_D6B3:				; CODE XREF: PrnCountdownJump+58j
					; sub_D65A+2Fj
		xor	a
		ld	(InFreeSpace), a ; <>0 между системами (перехват F)
		ld	hl, PlanetData0	; 6 байт для генерации данных о	планете
		ld	de, PilotPlanetData ; ?????
		ld	bc, 6
		ldir
		ld	hl, plNameDest	; название планеты на которую настроен корабль
		ld	de, PlanetPresent ; название активной планеты
		ld	bc, 8
		ldir
		ld	a, (PlanetTechLevel) ; Tech/Level (технический уровень)
		ld	(PilotPlanetTechLvl), a	; 73 ???
		ld	a, (PlanetGovernment) ;	goverment (тип правительства)
		ld	(PilotPlanetGov), a ; 74 ???
		call	GenerateProductPrice ; генерация количества товаров и цен на станции
					; вх:  ----
		ld	b, 12h
		xor	a
		ld	hl, SunCrd	; данные для печати солнца длина 9 байт
					; crd low x planet

loc_D6E2:				; CODE XREF: sub_D6B3+31j
		ld	(hl), a
		inc	hl
		djnz	loc_D6E2
		ld	a, 0FFh
		ld	(J_Drive_Coriolis), a ;	=0 J недоступен
		ld	hl, (PlanetData0) ; 6 байт для генерации данных	о планете
		ld	de, (PlanetData1)
		ld	bc, (PlanetData2)
		ld	a, b
		and	83h ; 'Г'
		or	1
		ld	(SunCrdX_hi), a	; crd high X sun
		ld	a, c
		and	83h ; 'Г'
		or	1
		ld	(SunCrdY_hi), a	; crd high Y sun
		ld	a, d
		or	e
		and	7
		add	a, 4
		or	81h ; 'Б'
		ld	(SunCrdZ_hi), a	; crd high Z sun
		ld	a, l
		and	83h ; 'Г'
		or	1
		ld	(PlanetCrdX_hi), a ; crd high x	planet
		ld	a, e
		and	83h ; 'Г'
		or	1
		ld	(PlanetCrdY_hi), a ; crd high y	planet
		ld	a, h
		or	l
		and	7
		add	a, 3
		ld	(PlanetCrdZ_hi), a ; crd high z	planet
		push	bc
		ld	bc, 9
		ld	hl, PlanetCrd	; Координаты планеты в пространстве
		ld	de, objCoriolis	; длина	27h
		ldir
		pop	bc
		ld	a, (PlanetCrdZ_hi) ; crd high z	planet
		ld	hl, byte_604F
		srl	c
		jr	c, loc_D747
		ld	a, (PlanetCrdX_hi) ; crd high x	planet
		ld	hl, byte_6049

loc_D747:				; CODE XREF: sub_D6B3+8Cj
		set	7, (hl)
		ld	b, a
		and	7Fh ; ''
		srl	c
		jr	c, loc_D760
		cp	1
		jr	nz, loc_D75C
		ld	d, a
		ld	a, b
		xor	80h ; 'А'
		ld	b, a
		ld	a, d
		jr	loc_D75D
