		ld	(de), a

loc_D7B4:				; CODE XREF: sub_D6B3+E1j sub_D6B3+E4j
		ld	a, (Pilot_CrdXTarget) ;	координата X малого курсора на большой карте
		ld	(Pilot_CrdXSystem), a ;	координата X текущей системы
		ld	a, (Pilot_CrdYTarget) ;	+103 (последний	байт для сохранения)
					; координата Y малого курсора на большой карте
		ld	(Pilot_CrdYSystem), a ;	координата Y текущей системы
		ld	a, (PilotNumGalaxy) ; номер галактики
		and	a
		jr	z, loc_D814
		ld	hl, byte_606E	;  7,=1	миссия 3 выполнена
		bit	7, (hl)
		res	7, (hl)
		jr	nz, loc_D7AC
		ld	hl, PilotMission3 ; +92	>0 - выдана 3я миссия
					;  =1 при стыковке будет выдана	3я миссиия ( =1	пора выдавать миссию будет =2 после прыжка)
					;  =2 при стыковке будет выдана	3я миссиия
					;  =3 выдана 3я	миссия (можно уничтожить станцию ракетой) (из станции вылетают таргоны)
					;  =4 выдана 3я	миссия,	корабль	находится в системе с целью (можно уничтожить станцию ракетой) (из станции вылетают таргоны)
					;  =5 3я миссия	выполнена, будет поздравление при стыковке
					;
					;
					;  =4 корабль захватили	пираты,	(сообщить при стыковке)	будет =3 после прыжка
					; 3,=1 станция уничтожена
		ld	a, (hl)
		and	a
		jr	z, loc_D7EE
		dec	a
		jr	nz, loc_D7DC
		inc	(hl)
		jr	loc_D7E1
; ---------------------------------------------------------------------------

loc_D7DC:				; CODE XREF: sub_D6B3+124j
		cp	3
		jr	nz, loc_D7E1
		ld	(hl), a

