					; sub_D6B3+12Bj
		ld	hl, PilotPlanetData ; ?????
		call	CompareGalaxyData ; Сравнение данных о галактике с HL
					; вх:  hl - адрес данных для сравнения
					; вых: cy =1 не	равны
					;      cy =0 идентичны
		jr	c, loc_D7EE
		ld	a, 4

loc_D7EB:				; CODE XREF: sub_D6B3+FBj
		ld	(PilotMission3), a ; +92 >0 - выдана 3я	миссия
					;  =1 при стыковке будет выдана	3я миссиия ( =1	пора выдавать миссию будет =2 после прыжка)
					;  =2 при стыковке будет выдана	3я миссиия
					;  =3 выдана 3я	миссия (можно уничтожить станцию ракетой) (из станции вылетают таргоны)
					;  =4 выдана 3я	миссия,	корабль	находится в системе с целью (можно уничтожить станцию ракетой) (из станции вылетают таргоны)
					;  =5 3я миссия	выполнена, будет поздравление при стыковке
					;
					;
					;  =4 корабль захватили	пираты,	(сообщить при стыковке)	будет =3 после прыжка
					; 3,=1 станция уничтожена

loc_D7EE:				; CODE XREF: sub_D6B3+121j
					; sub_D6B3+134j
		ld	hl, (JumpCounter) ; 16-17 Счетчик прыжков в том	числе и	межгалактических
					; byte_A872 bit	0-2,=??0 и low =20h..FFh - выдать 1ю миссию
					; byte_A872 bit	0-2,=?01 и low =80h..FFh - выдать 2ю миссию
					; byte_A872 bit	0-2,=011 и low =FEh..FFh - выдать 3ю миссию
		inc	hl
		ld	(JumpCounter), hl ; 16-17 Счетчик прыжков в том	числе и	межгалактических
					; byte_A872 bit	0-2,=??0 и low =20h..FFh - выдать 1ю миссию
					; byte_A872 bit	0-2,=?01 и low =80h..FFh - выдать 2ю миссию
					; byte_A872 bit	0-2,=011 и low =FEh..FFh - выдать 3ю миссию
		ld	de, PilotExtWeapon ; +93 наличие доп вооружения
					;   7,=1 - ECM Jammer
					;   6,=1 - Cloaking device
					;   5,=1 - нельзя купить товары(в трюме	беженцы)
					;   4
					;   3 =1 3я миссия была	выполнена
					;   2 =1 - третья миссия выполнена
					;   1 =1 - второя миссия выполнена
					;   0 =1 - первая миссия выполнена
		ld	a, (de)
		rrca			; bit 0
		jr	nc, loc_D832	; выдать 1ю миссию
		rrca			; bit 1
		jr	nc, loc_D849	; выдать 2ю миссию
		rrca			; bit 2
		jr	nc, loc_D853	; выдать 3ю миссию

loc_D802:				; CODE XREF: sub_D6B3+182j
					; sub_D6B3+199j ...
		ld	hl, RndWord	; случайное число
		ld	a, (PilotPlanetGov) ; 74 ???
		xor	0FFh
		and	7
		cp	(hl)
		jr	c, loc_D814
		ld	hl, byte_6065	; кориолис+#1D
					; =0 станция не	вращается, значит захвачена пиратами
		res	7, (hl)

loc_D814:				; CODE XREF: sub_D65A+56j
					; sub_D6B3+111j ...
		ld	a, 1
		ld	(FlgJumpDocking), a ; =1 запрет	на обработку нажатий клавиш
					;   включено при: стыковке
					;   работает п/п отрисовки концентрический кругов
					;
					; 0,Flg_Interrupts
		xor	a
		ld	(WhatOnScreen),	a ; Что	изображено на экране
					;  =0..3 в полете номер	обзорного экрана (front, rear, left, right)
					;  =#04	меню покупки товаров
					;  =#05	меню продажи товаров
					;  =#06	меню покупки оборудования
					;  =#07	глобальная карта
					;  =#08	локальная карта
					;  =#09	инфо о планете еще не выведено
					;  =#0A	прайс планеты
					;  =#0B	инфо о пилоте
					;  =#0C	Инвентрь
					;  =#20	инфо о планете
		ld	(Temperature), a ;   +0	- текущее значение
					;   -1 - отображенное на экране
		ld	(FuelScoopsOn),	a ; <>0	рядом с	солнцен, работает fuel scoops
		ld	(Missile1), a	; =0 ракета не нацелена
					; =1 ракета готова к захвату цели
					; =2 ракета на что-то нацелена
		ld	(PilotMission2), a ; =3	asp из 2й миссии уничтожен/в пространстве есть контейнер с шапкой-невидимкой
					; =2 у asp невидимость выключена
					; =1 выдана 2й миссия
					; =0 при движении на J
		ld	(byte_7C39), a	; =#01 нажата G	или H (прыжок)
		ld	a, 0A0h	; 'а'
		ld	(Altitude), a	;   +0 - текущее значение
					;   -1 - отображенное на экране
		ret
; ---------------------------------------------------------------------------

loc_D832:				; CODE XREF: sub_D6B3+147j
		ld	a, l
		cp	20h ; ' '
		jr	c, loc_D802
		ex	de, hl
