; Обнуление топлива
; Вх:  ---
; Вых: b,a - не	определены

SetFuelZero:				; CODE XREF: DecEnergyShieldFR+3Dj
					; RAM:A897j ...
		ld	a, (Pilot_Fuel)	; Топливо
		and	a
		ret	z
		ld	hl, NoFuel	; 7,=1 - топлива было обнулено
		set	7, (hl)
		xor	a
; End of function SetFuelZero


; =============== S U B	R O U T	I N E =======================================

; Установка топлива
; Вх:  a - новое значение Fuel
; Вых: b - не определен

SetPilotFuel:				; CODE XREF: Cmd_4_BuyEquip+D1p
					; SetSecondaryMsg+47p ...
		cp	47h ; 'G'
		jr	c, loc_D873
		ld	a, 46h ; 'F'

loc_D873:				; CODE XREF: SetPilotFuel+2j
		ld	(Pilot_Fuel), a	; Топливо
		add	a, a
		ld	b, a
		srl	a
		srl	a
		srl	a
		add	a, b
		ld	(Fuel),	a	; топливо
					;   +0 - текущее значение
					;   -1 - отображенное на экране
		ret
; End of function SetPilotFuel

