CursorWidth:	db 0			; DATA XREF: Cmd_O_LocalMap+4Dw
					; Cmd_O_LocalMap+74w ...
					; ширина курсора
CrdYUpGalaxyMap:db 0			; DATA XREF: PrintCursorOnScr+125r
					; н используется всегда	=00
					; координата верхней границы карты(влияет только на отображение	курсора	на карте)
CrdYDownGalaxyMap:db 0			; DATA XREF: Cmd_O_LocalMap+48w
					; Cmd_I_GlobalMap+Aw ...
					; координата нижней границы карты(влияет только	на отображение курсора на карте)

; =============== S U B	R O U T	I N E =======================================

; Печать курсора на экране карты галактики
; Вх:  (PrnCrdXCursor) - координата X печати [1..#FE]
;      (PrnCrdYCursor) - координата Y печати
;      (CursorWidth) - ширина курсора
; Вых: hl,de,bc,a - не определены

PrintCursorOnScr:			; CODE XREF: Cmd_O_LocalMap+5Ap
					; Cmd_I_GlobalMap+22p ...
		ld	a, (CursorWidth) ; ширина курсора
		srl	a
		ld	b, a
		ld	a, (PrnCrdXCursor) ; координата	X малого курсора на экране
		sub	b
		jr	c, loc_D8C8	; курсор выходит за левую границу
		jr	z, loc_D8C8	; курсор выходит за левую границу
		ld	d, a		; курсор весь на экране
		ld	a, (PrnCrdYCursor) ; координата	Y малого курсора на экране
		ld	c, a
