MoveAllObjects:				; CODE XREF: GameMain+52p GameMain+89p ...
		ld	a, (PilotMission3) ; +92 >0 - выдана 3я	миссия
					;  =1 при стыковке будет выдана	3я миссиия ( =1	пора выдавать миссию будет =2 после прыжка)
					;  =2 при стыковке будет выдана	3я миссиия
					;  =3 выдана 3я	миссия (можно уничтожить станцию ракетой) (из станции вылетают таргоны)
					;  =4 выдана 3я	миссия,	корабль	находится в системе с целью (можно уничтожить станцию ракетой) (из станции вылетают таргоны)
					;  =5 3я миссия	выполнена, будет поздравление при стыковке
					;
					;
					;  =4 корабль захватили	пираты,	(сообщить при стыковке)	будет =3 после прыжка
					; 3,=1 станция уничтожена
		cp	4
		jr	nz, loc_DA29
		ld	hl, byte_6069	;  2,=1	кориолис агрессивна
		set	2, (hl)

loc_DA29:				; CODE XREF: MoveAllObjects+5j
		ld	a, (TypeOfPrint) ; коррекция п/п печати	в зависимости от расстояния до солнца
					;  =#00	or c
					; <>#00	xor c
		and	a
		ld	a, 0B1h	; '▒'   ; or c
		jr	z, loc_DA33	; коррекция п/п	печати линии
		ld	a, 0A9h	; 'й'   ; xor c

loc_DA33:				; CODE XREF: MoveAllObjects+12j
		ld	(loc_F203), a	; коррекция п/п	печати линии
		ld	(loc_F231), a
		ld	(loc_F27E), a
		ld	(loc_F252), a
		ld	a, (FrameCounter) ; счетчик появления корабля????
					; счетчик кадров
		dec	a
		ld	(FrameCounter),	a ; счетчик появления корабля????
					; счетчик кадров
		ld	b, a
		ld	a, (CoriolisNear) ; <>0	вблизи станции,	можно стыковаться
		and	a
		jr	nz, loc_DA5F
		ld	a, (InFreeSpace) ; <>0 между системами (перехват F)
		and	a
		jr	nz, loc_DA5F
		ld	a, (nMissileObj) ; кол-во ракет	в пространстве
					; >=4 случайные	корабли	не появляются
		cp	4
		jr	nc, loc_DA5F
		ld	a, b
		and	a
		call	z, CallFunctionObj ; set rnd ship

loc_DA5F:				; CODE XREF: MoveAllObjects+2Ej
					; MoveAllObjects+34j ...
		xor	a
		ld	(DamageEnergyUnit), a ;	урон энергоблокам
		ld	(DamageRearShield), a ;	урон задним щитам
		ld	(DamageFrontShield), a ; урон передним щитам
		ld	(ObjInTarget), a ; <>0 в прицеле что-то	есть (номер объекта???)
		ld	(FlgCoriolisNear), a ; <>0 есть	рядом станция
		ld	(FlgObjNear), a	; <>0 есть рядом какой-то объект
		ld	(J_Drive_Ready4), a ; =1 рядом объект блокирующий J drive
					; <>0 J	недоступен
		ld	c, a		; с=0
		ld	ix, objCoriolis	; длина	27h
		ld	de, 27h	; '''
		ld	b, 6		; c=0

loc_DA7F:				; CODE XREF: MoveAllObjects:loc_DA8Ej
		add	ix, de
		ld	a, (ix+22h)
		and	a
		jr	z, loc_DA8E	; next
		bit	6, (ix+20h)
		jr	z, loc_DA8E	; next (не ракета)
		inc	c

loc_DA8E:				; CODE XREF: MoveAllObjects+68j
					; MoveAllObjects+6Ej
		djnz	loc_DA7F
		ld	a, c		; a,c кол-во ракет
