		push	hl
		pop	iy		; iy адрес данных объекта
		ld	a, (ix+20h)
		and	30h ; '0'
		jr	z, loc_DB71	; ????
		sub	20h ; ' '
		jp	nz, loc_DBA3	; ????
		res	5, (ix+20h)
		ld	(ix+1Eh), a	; =0
