loc_DB43:				; CODE XREF: MoveAllObjects+102j
					; MoveAllObjects+10Dj ...
		xor	a		; уничтожаем объект
		ld	(ix+22h), a
		call	OffTargetMissiles ; Объект исчез из пространства (уничтожен/улетел). Снять ракету с нацеливания	и
					;   уничтожить выпущенные в этот объект	ракеты
					; Вх:  ix - адрес слота	уничтоженного объекта
					;      (InverseNumSlotIX) - его	обратный номер в списке	слотов
					; Вых: de = LenSlotObj
					;      b =#00
					;      hl,a - не определены
		ld	d, (iy+9)
		ld	e, (iy+8)
		call	AddCashObj	; Увеличение суммы денег
					; Вх:  de - количество денег (от 0.1 до	6553.5)
					; Вых: hl,de - не определены
		ld	d, (iy+16h)
		ld	e, (iy+15h)
		srl	d
		rr	e
		call	IncBattleRating	; Увеличение боевого рейтинга
					; Вх:  de - приращение рейтинга
					; Вых: hl,de - не определены
		ld	a, (ix+21h)
		and	60h ; '`'
		jr	z, loc_DBBE	; следующий объект
		ld	a, (PilotLegalStatus) ;	Правовой статус	пилота
					;  0 - clean
					;  1..31h offender
					;  32h..FFh fugitiv
		or	40h ; '@'
		ld	(PilotLegalStatus), a ;	Правовой статус	пилота
					;  0 - clean
					;  1..31h offender
					;  32h..FFh fugitiv
		jr	loc_DBBE	; следующий объект
; ---------------------------------------------------------------------------

loc_DB71:				; CODE XREF: MoveAllObjects+EBj
		ld	a, b		; b - обратный номер слота объекта, адрес слота	которого в IX
					; c - счетчик появления	корабля????
		xor	c
		and	0Fh
		bit	6, (ix+20h)
		jr	z, loc_DB8B	; объект не управляется
		bit	0, (ix+26h)
		jr	z, loc_DB86	; не ракета
