		jr	loc_DB8B
; ---------------------------------------------------------------------------

loc_DB86:				; CODE XREF: MoveAllObjects+162j
		and	3
		call	z, ReactionObject ; Реакция объекта на игрока. Запуск ракет, кораблей, спасательной капсулы т.п.
					; Вх:  ix - адрес слота	объекта
					;      iy - адрес данных объекта
					; Вых: hl,de,bc,a - не определены

loc_DB8B:				; CODE XREF: MoveAllObjects+15Cj
					; MoveAllObjects+167j
		call	ReCalcCrdObj	; Пересчет координат объекта
					; Вх:  ix - адрес начала слота объекта
					;      (InverseNumSlotIX) - его	обратный номер в списке	слотов
					; Вых: hl,de,bc,a - не определены
		call	CorrAxirY_SKO	; Выравнивание оси Y под ортогональность оси X
					; Вх:  ix - адрес слота	объекта
					; Вых: ix=ix+2
					;      iy=iy+2
					; Вых: hl,de,bc,a - не определены
		push	ix
		ld	de, 9
		add	ix, de
		call	CorrAxisVector	; x=x*l	 y=y*l	z=z*l, ix=ix+6
		call	CorrAxisVector	; x=x*l	 y=y*l	z=z*l, ix=ix+6
		call	CorrAxisVector	; x=x*l	 y=y*l	z=z*l, ix=ix+6
		pop	ix

loc_DBA3:				; CODE XREF: MoveAllObjects+EFj
		call	CollisionWithObj ; Проверка столкновения объекта с игроком, и его обработка
					; Вх:  ix - адрес слота	объекта
					;      iy - адрес данных объекта
					; Вых: hl,de,bc,a - не определены
		call	PrnObjIfVisible	; Обсчет видимости и печать объекта
					; Вх:  ix - адрес слота	объекта
					;      iy - адрес данных объекта
					;      (sp) - обратный номер объекта
					; Вых: hl,de,bc,a - не определены
		res	3, (ix+20h)
		ld	a, (ix+20h)
		and	30h ; '0'
		cp	10h
		jr	nz, loc_DBBE	; следующий объект
		set	5, (ix+20h)
		res	4, (ix+20h)

loc_DBBE:				; CODE XREF: MoveAllObjects+86j
					; MoveAllObjects+148j ...
		pop	af		; следующий объект
		ld	de, 27h	; '''
		add	ix, de
		dec	a
		jp	nz, loc_DA9A
		xor	a
		ld	(EnergyBombUsed), a ; <>0, =1, =#FF взорвана энергобомба
					;
		ld	a, (J_Drive_Ready4) ; =1 рядом объект блокирующий J drive
					; <>0 J	недоступен
		and	a
		ret	nz
		ld	(PlayerPirate),	a ; =1 игрок атаковал мирного торговца/станцию/полицию.	включаем агрессию
					;
					;
					; =0 станция не	агрессивна
					; =0 мало энергии выключаем шапку невидимку
					; =0 шапка невидимка выключена
					; =1, если 6-7,(ix+#21)<>00
					; =1 рядом аггресивны объект
		ret
; End of function MoveAllObjects


; =============== S U B	R O U T	I N E =======================================

; Вычисление длины вектора и нормализация вектора
; Вх:  ix - адрес длин вектора по каждой оси
; Вых: de=sqrt(dX^2+dY^2+dZ^2) длина вектора
;      (ix) - нормализованные координаты вектора
;      a =#00

CalcLenVector:				; CODE XREF: MoveObject+Cp
		push	ix
		call	Sqr_HL_wordAdrIX ; Возведение в	квадрат
					; вх:  HL = high(word(ix+0/1)^2)
		push	hl
		call	Sqr_HL_wordAdrIX ; Возведение в	квадрат
					; вх:  HL = high(word(ix+0/1)^2)
		push	hl
		call	Sqr_HL_wordAdrIX ; Возведение в	квадрат
					; вх:  HL = high(word(ix+0/1)^2)
		pop	de
		add	hl, de
		pop	de
		add	hl, de
		pop	ix		; hl=dX^2+dY^2+dZ^2
		call	Sqrt_H_HL	; Извлечение квадратного корня h=sqr(hl)
					; Вх:  hl - число
					; Вых: h  - результат
					;      l  - остаток
					;      a=0
					;      de,bc - не определены
		ex	de, hl		; de=sqrt(dX^2+dY^2+dZ^2)
		push	ix
		call	CaclNormalVector ; dX =	dX / sqrt(dX^2+dY^2+dZ^2) / 2
					;
		call	CaclNormalVector ; dY =	dY / sqrt(dX^2+dY^2+dZ^2) / 2
					;
		call	CaclNormalVector ; dZ =	dZ / sqrt(dX^2+dY^2+dZ^2) / 2
					;
		pop	ix
		ret
; End of function CalcLenVector


; =============== S U B	R O U T	I N E =======================================

; Возведение в квадрат
; вх:  HL = high(word(ix+0/1)^2)

Sqr_HL_wordAdrIX:			; CODE XREF: CalcLenVector+2p
					; CalcLenVector+6p ...
		ld	b, (ix+1)
		ld	c, (ix+0)
		res	7, b
		push	ix
		ld	ix, 0
		call	Mult_HL_B_C	; Приближенное табличное умножение HL=B*C
					; считает: ((b+c)/2)^2 - ((b-c)/2)^2
					; должно:  ((b+c)^2 - (b-c)^2)/4
		xor	a
		ld	d, a
		add	hl, hl
		rl	d
		ld	e, h
		add	ix, de
		ld	h, l
		ld	l, a
		push	hl
		ld	h, 0BEh	; '╛'
		ld	l, b
		ld	e, (hl)
		inc	h
		ld	d, (hl)
		dec	h
		add	ix, de
		ld	l, c
		ld	e, (hl)
		inc	h
		ld	d, (hl)
		pop	hl
		add	hl, de
		jr	nc, loc_DC29
		inc	ix

loc_DC29:				; CODE XREF: Sqr_HL_wordAdrIX+2Bj
		ex	(sp), ix
		pop	hl
		inc	ix
		inc	ix
		ret
; End of function Sqr_HL_wordAdrIX


; =============== S U B	R O U T	I N E =======================================

; Нормализация вектора
; Вх:  ix - адрес переменной dX/dY/dZ
;      de - длина вектора (делитель)
;      a =#00
; Вых: (ix) - координата нормализированного вектора
;      ix=ix+2
;      bc - не определен
;      a =#00

CaclNormalVector:			; CODE XREF: CalcLenVector+19p
					; CalcLenVector+1Cp ...
		ld	h, (ix+1)
		ld	l, (ix+0)
		push	hl
		res	7, h
		call	Div_BC_HLAdivDE	; Деление числа	с фиксированной	точкой hl.a/de
					; Вх:  hla - делимое
					;	de - делитель
					; Вых: b.c - =hl.a/de
		srl	b
		rr	c		; b.c =	hl.a/de/2
		pop	hl
		bit	7, h
		jr	z, loc_DC48
		set	7, b

loc_DC48:				; CODE XREF: CaclNormalVector+13j
		ld	(ix+0),	c
		ld	(ix+1),	b
		inc	ix
		inc	ix
		ret
; End of function CaclNormalVector


; =============== S U B	R O U T	I N E =======================================

; Извлечение квадратного корня h=sqr(hl)
; Вх:  hl - число
; Вых: h  - результат
;      l  - остаток
;      a=0
;      de,bc - не определены

Sqrt_H_HL:				; CODE XREF: CalcLenVectorCrd:loc_8AAFp
					; CalcLenVectorCrd:loc_8ABDp ...
		ld	a, h
		cp	10h
		jr	nc, loc_DC7A
		and	a
		jr	z, loc_DC6C
		ld	b, 4

loc_DC5D:				; CODE XREF: Sqrt_H_HL+Bj
		add	hl, hl
		djnz	loc_DC5D
		call	loc_DC7A
		srl	h
		rr	l
		srl	h
		rr	l
		ret
; ---------------------------------------------------------------------------

loc_DC6C:				; CODE XREF: Sqrt_H_HL+6j
		ld	h, l
		ld	l, a
		call	loc_DC7A
		ld	b, 4

loc_DC73:				; CODE XREF: Sqrt_H_HL+24j
		srl	h
		rr	l
		djnz	loc_DC73
		ret
; ---------------------------------------------------------------------------

loc_DC7A:				; CODE XREF: Sqrt_H_HL+3j Sqrt_H_HL+Dp ...
		xor	a
		push	hl
		push	hl
		srl	h
		rr	l
		rra
		ld	de, 8000h
		call	loc_DC97
		pop	de
		call	loc_DC8D
		pop	de

loc_DC8D:				; CODE XREF: Sqrt_H_HL+36p
		rr	h
		rr	l
		ex	de, hl
		srl	h
		rr	l
		rra

loc_DC97:				; CODE XREF: Sqrt_H_HL+32p
		push	de
		call	Div_BC_HLAdivDE	; Деление числа	с фиксированной	точкой hl.a/de
					; Вх:  hla - делимое
					;	de - делитель
					; Вых: b.c - =hl.a/de
		srl	b
		rr	c
		xor	a
		pop	hl
		add	hl, bc
		ret
; End of function Sqrt_H_HL


; =============== S U B	R O U T	I N E =======================================

; Приведение вектора к нормальному (корреция небольшой погрешности вычислений)
; Вх:  ix - адрес начала вектора
; Вых: ix=ix+6
;      hl,de,bc,a - не определены

CorrAxisVector:				; CODE XREF: MoveAllObjects+17Bp
					; MoveAllObjects+17Ep ...
		ld	h, 0BFh	; '┐'
		ld	l, (ix+1)	; hl адрес таблицы квадратов (старшие байты)
		sla	l
		ld	a, (hl)
		ld	l, (ix+3)
		sla	l
		add	a, (hl)
		ld	l, (ix+5)
		sla	l
		add	a, (hl)
		sra	a
		sra	a		; hi(dx)^2+hi(dy)^2+hi(dz)^2
		neg
		xor	80h ; 'А'
		ld	b, a
		call	sub_DCC6
		call	sub_DCC6
; End of function CorrAxisVector


; =============== S U B	R O U T	I N E =======================================


sub_DCC6:				; CODE XREF: CorrAxisVector+1Dp
		ld	c, (ix+1)
		sla	c
		call	Mult_HL_B_C	; Приближенное табличное умножение HL=B*C
					; считает: ((b+c)/2)^2 - ((b-c)/2)^2
					; должно:  ((b+c)^2 - (b-c)^2)/4
		sla	h
		sla	(ix+1)
		rr	h
		ld	(ix+1),	h
		inc	ix
		inc	ix
		ret
; End of function sub_DCC6

; ---------------------------------------------------------------------------
AngleLR4Calc:	db 0			; DATA XREF: ReCalcCrdObj+2Bw
					; ReCalcCrdObj:loc_DD3Dw ...
					; угол поворота	корабля
					; 7,n знак
					; #00.#0F
AngleDU4Calc:	db 0			; DATA XREF: ReCalcCrdObj:loc_DD5Dw
					; RotateAxisSCOr ...
					; угол поворота	вверх/вниз
					; 7,n знак
					; #00.#0F

; =============== S U B	R O U T	I N E =======================================

; Пересчет координат объекта
; Вх:  ix - адрес начала слота объекта
;      (InverseNumSlotIX) - его	обратный номер в списке	слотов
; Вых: hl,de,bc,a - не определены

ReCalcCrdObj:				; CODE XREF: CalcCrdCoriolis:loc_77B0p
					; MoveAllObjects:loc_DB8Bp
		call	CalcNewCrdObj_Pl ; Изменение координат объекта от перемещения игрока
					; вх:  ix - адрес начала слота объекта
					; вых: hl.a - crd Z
		bit	2, (ix+26h)
		jr	nz, loc_DCEE	; проверка удалённости объкта по Z
		ld	a, l		; проверка удалённости объкта по Z
		cp	60h ; '`'
		jr	nc, loc_DCF3	; объект удалился далеко, обираем его из пространства

loc_DCEE:				; CODE XREF: ReCalcCrdObj+7j
		ld	a, h		; проверка удалённости объкта по Z
		and	7Fh ; ''
		jr	z, loc_DCFA	; проверка удалённости объкта по X

loc_DCF3:				; CODE XREF: ReCalcCrdObj+Cj
					; ReCalcCrdObj+1Fj ...
		xor	a		; объект удалился далеко, обираем его из пространства
		ld	(ix+22h), a
		jp	OffTargetMissiles ; Объект исчез из пространства (уничтожен/улетел). Снять ракету с нацеливания	и
					;   уничтожить выпущенные в этот объект	ракеты
					; Вх:  ix - адрес слота	уничтоженного объекта
					;      (InverseNumSlotIX) - его	обратный номер в списке	слотов
					; Вых: de = LenSlotObj
					;      b =#00
					;      hl,a - не определены
; ---------------------------------------------------------------------------

loc_DCFA:				; CODE XREF: ReCalcCrdObj+11j
