					; вых: ix=ix+6
					;      de=#0006
					;      bc,a - не определены
		call	RotateAxisSCO	; поворот вектора оси СКО на заданные углы
					; вх:  ix - адрес вектора оси СКО
					; вых: ix=ix+6
					;      de=#0006
					;      bc,a - не определены
		call	RotateAxisSCO	; поворот вектора оси СКО на заданные углы
					; вх:  ix - адрес вектора оси СКО
					; вых: ix=ix+6
					;      de=#0006
					;      bc,a - не определены
		pop	ix
		ld	a, (ix+1Dh)
		ld	b, a
