loc_DD3D:				; CODE XREF: ReCalcCrdObj+4Cj
					; ReCalcCrdObj+59j
		ld	(AngleLR4Calc),	a ; угол поворота корабля
					; 7,n знак
					; #00.#0F
		ld	a, (ix+1Eh)
		ld	b, a
		bit	7, a
		jr	nz, loc_DD53
		and	0Fh
		ld	a, 0
		jr	z, loc_DD5D
