loc_DD53:				; CODE XREF: ReCalcCrdObj+66j
		ld	a, 8
		bit	6, (ix+1Eh)
		jr	z, loc_DD5D
		add	a, 80h ; 'А'

loc_DD5D:				; CODE XREF: ReCalcCrdObj+6Cj
					; ReCalcCrdObj+79j ...
		ld	(AngleDU4Calc),	a ; угол поворота вверх/вниз
					; 7,n знак
					; #00.#0F
		push	ix
