					; вх:  ix - адрес координаты первого вектора оси СКО
					; вых: ix=ix+2
					;      de,bc,a - не определены
		call	RotateCrdNSCO	; поворот одноименных координат	векторов осей СКО на заданные углы
					; вх:  ix - адрес координаты первого вектора оси СКО
					; вых: ix=ix+2
					;      de,bc,a - не определены
		call	RotateCrdNSCO	; поворот одноименных координат	векторов осей СКО на заданные углы
					; вх:  ix - адрес координаты первого вектора оси СКО
