; =============== S U B	R O U T	I N E =======================================

; изменение глобальных координат объекта от его	скорости
; вх:  ix=iy адрес описания объекта
;      c  - скорость объекта (ix+oSpeed)
; вых: hl,de,a - не определены

CalcNewCrdObjSpeed:			; CODE XREF: ReCalcCrdObj+BDp
					; ReCalcCrdObj+C0p ...
		push	bc
		ld	d, (ix+0Ah)
		ld	e, (ix+9)
		call	CaclDeltaCrdObj	; вычисление приращения	для глобальной координаты объекта
					;   high((d.e *	speed*4)/#100+#FF)
					;  =34b
					;  =389/425t
					; вх:  de - координата n оси X СКО
					;      c  - скорость объекта (ix+oSpeed)
					; вых: d.e - приращение	глобальной координаты объекта
		ld	a, (iy+2)
		ld	h, (iy+1)
		ld	l, (iy+0)
		call	CrdNAddDeltaCrd	; приращение координаты	bh.l = ah.l + d.e
					; вх:  ah.l - координата (7,a =	знак)
					;      d.e - приращение	координаты (7,d	= знак)
					; вых: bh.l - новая координата (7,b - новый знак)
		ld	(iy+2),	b
		ld	(iy+1),	h
		ld	(iy+0),	l
		inc	iy
		inc	iy
		inc	iy
		inc	ix
		inc	ix
		pop	bc
		ret
; End of function CalcNewCrdObjSpeed


; =============== S U B	R O U T	I N E =======================================

; вычисление приращения	для глобальной координаты объекта
;   high((d.e *	speed*4)/#100+#FF)
;  =34b
;  =389/425t
; вх:  de - координата n оси X СКО
;      c  - скорость объекта (ix+oSpeed)
; вых: d.e - приращение	глобальной координаты объекта

CaclDeltaCrdObj:			; CODE XREF: CalcNewCrdObjSpeed+7p
		sla	d
		rl	c
		rl	c
		srl	d
		ld	hl, 0
		ld	b, 6

loc_DDE3:				; CODE XREF: CaclDeltaCrdObj:loc_DDECj
		srl	d
		rr	e
		sla	c
		jr	nc, loc_DDEC
		add	hl, de

loc_DDEC:				; CODE XREF: CaclDeltaCrdObj+13j
		djnz	loc_DDE3
		ld	de, 0FFh
		add	hl, de
		ld	e, h
		sla	c
		rr	d
		ret
; End of function CaclDeltaCrdObj


; =============== S U B	R O U T	I N E =======================================

; приращение координаты	bh.l = ah.l + d.e
; вх:  ah.l - координата (7,a =	знак)
;      d.e - приращение	координаты (7,d	= знак)
; вых: bh.l - новая координата (7,b - новый знак)

CrdNAddDeltaCrd:			; CODE XREF: CalcNewCrdObjSpeed+13p
		ld	b, a
		ld	c, d
		xor	c
		res	7, d
		jr	nz, loc_DE01
		add	hl, de
		ret
; ---------------------------------------------------------------------------

loc_DE01:				; CODE XREF: CrdNAddDeltaCrd+5j
		sbc	hl, de
		ret	nc
		add	hl, de
		ex	de, hl
		and	a
		sbc	hl, de
		ld	b, c
		ret
; End of function CrdNAddDeltaCrd


; =============== S U B	R O U T	I N E =======================================

; поворот вектора оси СКО на заданные углы
; вх:  ix - адрес вектора оси СКО
; вых: ix=ix+6
;      de=#0006
;      bc,a - не определены

RotateAxisSCO:				; CODE XREF: ReCalcCrdObj+35p
					; ReCalcCrdObj+38p ...
		ld	a, (AngleDU4Calc) ; угол поворота вверх/вниз
					; 7,n знак
					; #00.#0F
		xor	80h ; 'А'
		sra	a
		res	6, a
		ld	c, a
		ld	b, (ix+3)
		ld	d, (ix+5)
		call	CalcNewCrdNAxis	; Вычисление новой координаты оси системы координат объекта
					; Вх:  a,c - угол поворота
					;      b   - координата	Y/ оси СКП
					;      d   - координата	Z/ оси СКП
					; Вых: a = crd(d) + crd(b) * angle(c)*2	 (с учётом знаков)
					;      7,a - знак
					;      de,bc - не определены
		ld	(ix+5),	a
		ld	a, (AngleLR4Calc) ; угол поворота корабля
					; 7,n знак
					; #00.#0F
		xor	80h ; 'А'
		ld	c, a
		ld	b, (ix+3)
		ld	d, (ix+1)
		call	CalcNewCrdNAxis	; Вычисление новой координаты оси системы координат объекта
					; Вх:  a,c - угол поворота
					;      b   - координата	Y/ оси СКП
					;      d   - координата	Z/ оси СКП
					; Вых: a = crd(d) + crd(b) * angle(c)*2	 (с учётом знаков)
					;      7,a - знак
					;      de,bc - не определены
		ld	(ix+1),	a
		ld	a, (AngleLR4Calc) ; угол поворота корабля
					; 7,n знак
					; #00.#0F
		ld	c, a
		ld	b, (ix+1)
		ld	d, (ix+3)
		call	CalcNewCrdNAxis	; Вычисление новой координаты оси системы координат объекта
					; Вх:  a,c - угол поворота
					;      b   - координата	Y/ оси СКП
					;      d   - координата	Z/ оси СКП
					; Вых: a = crd(d) + crd(b) * angle(c)*2	 (с учётом знаков)
					;      7,a - знак
					;      de,bc - не определены
		ld	(ix+3),	a
		ld	a, (AngleDU4Calc) ; угол поворота вверх/вниз
					; 7,n знак
					; #00.#0F
		sra	a
		res	6, a
		ld	c, a
		ld	b, (ix+5)
		ld	d, (ix+3)
		call	CalcNewCrdNAxis	; Вычисление новой координаты оси системы координат объекта
					; Вх:  a,c - угол поворота
					;      b   - координата	Y/ оси СКП
					;      d   - координата	Z/ оси СКП
					; Вых: a = crd(d) + crd(b) * angle(c)*2	 (с учётом знаков)
					;      7,a - знак
					;      de,bc - не определены
		ld	(ix+3),	a
		ld	de, 6
		add	ix, de
		ret
; End of function RotateAxisSCO


; =============== S U B	R O U T	I N E =======================================

; Вычисление новой координаты оси системы координат объекта
; Вх:  a,c - угол поворота
;      b   - координата	Y/ оси СКП
;      d   - координата	Z/ оси СКП
; Вых: a = crd(d) + crd(b) * angle(c)*2	 (с учётом знаков)
;      7,a - знак
;      de,bc - не определены

CalcNewCrdNAxis:			; CODE XREF: RotateAxisSCO+10p
					; RotateAxisSCO+22p ...
		push	de
		xor	b
		sla	b
		res	7, c
		ld	e, a
		call	Mult_A_hiB_C	; a=((b+c)/2)^2-((b-c)/2)^2
		pop	bc
		ld	c, a
		ld	a, e
		xor	b
		sla	b
		rr	e
		sla	c
		rla
		ld	a, b
		jr	c, loc_DE7D
		add	a, c
		jp	nc, loc_DE84
		ld	a, 0FFh
		jr	loc_DE84
; ---------------------------------------------------------------------------

loc_DE7D:				; CODE XREF: CalcNewCrdNAxis+16j
		sub	c
		jr	nc, loc_DE84
		neg
		rl	e

loc_DE84:				; CODE XREF: CalcNewCrdNAxis+19j
					; CalcNewCrdNAxis+1Ej ...
		rl	e
		rra
		ret
; End of function CalcNewCrdNAxis


; =============== S U B	R O U T	I N E =======================================

; поворот одноименных координат	векторов осей СКО на заданные углы
