					; 7,n знак
					; #00.#0F
		ld	c, a
		ld	b, (ix+16h)
		ld	d, (ix+10h)
		call	CalcNewCrdNAxis	; Вычисление новой координаты оси системы координат объекта
					; Вх:  a,c - угол поворота
					;      b   - координата	Y/ оси СКП
					;      d   - координата	Z/ оси СКП
					; Вых: a = crd(d) + crd(b) * angle(c)*2	 (с учётом знаков)
					;      7,a - знак
					;      de,bc - не определены
		ld	(ix+10h), a
		ld	a, (AngleDU4Calc) ; угол поворота вверх/вниз
					; 7,n знак
					; #00.#0F
		ld	c, a
		ld	b, (ix+0Ah)
		ld	d, (ix+10h)
		call	CalcNewCrdNAxis	; Вычисление новой координаты оси системы координат объекта
					; Вх:  a,c - угол поворота
					;      b   - координата	Y/ оси СКП
					;      d   - координата	Z/ оси СКП
					; Вых: a = crd(d) + crd(b) * angle(c)*2	 (с учётом знаков)
					;      7,a - знак
					;      de,bc - не определены
