; =============== S U B	R O U T	I N E =======================================

; Изменение координат объекта от перемещения игрока
; вх:  ix - адрес начала слота объекта
; вых: hl.a - crd Z

CalcNewCrdObj_Pl:			; CODE XREF: CalcCrdSunPlanet+4p
					; CalcCrdSunPlanet+Bj ...
		ld	a, (HighAngleDU) ; старший байт	угла поворота
					; 7,n знак (верх/вниз)
					; #00..#0F
		xor	80h ; 'А'
		ld	c, a
		ld	de, 3
		ld	hl, 6
		call	CalcNewCrdNobj	; crdZ=crdY*-angleDU/#100+crdZ
		ld	a, (HighAngleLR) ; старший байт	угла поворота
					; 7,n знак (лево/право)
					; #00..#0F
		xor	80h ; 'А'
		call	Mult_Ax2_sign	; умножение на 2 с сохранением знака
					; вх:  a - число
					; вых: c=a*2, 7,c=7,a
		ld	de, 3
		ld	h, d
		ld	l, d
		call	CalcNewCrdNobj	; crdX=crdY*-angleLR*2/#100+crdX
		ld	a, (HighAngleLR) ; старший байт	угла поворота
					; 7,n знак (лево/право)
					; #00..#0F
		call	Mult_Ax2_sign	; умножение на 2 с сохранением знака
					; вх:  a - число
					; вых: c=a*2, 7,c=7,a
		ld	hl, 3
		ld	d, h
		ld	e, h
		call	CalcNewCrdNobj	; crdY=crdX*angleLR*2/#100+crdY
		ld	a, (HighAngleDU) ; старший байт	угла поворота
					; 7,n знак (верх/вниз)
					; #00..#0F
		ld	c, a
		ld	hl, 3
		ld	de, 6
		call	CalcNewCrdNobj	; crdY=crdZ*angleDU/#100+crdY
		ld	a, (HighDeltaSpeed) ; старший байт скорости
					; #00..#1F
		inc	a		; коррекция координаты Z от скорости
		add	a, a
		ld	b, a
		ld	h, (ix+8)
		ld	l, (ix+7)
		ld	a, (ix+6)
		bit	7, h
		jr	z, loc_DF2D
		add	a, b
		ld	(ix+6),	a
		ret	nc
		inc	hl
		bit	7, h
		jr	nz, loc_DF3F
		ld	hl, 7FFFh
		jr	loc_DF3A
; ---------------------------------------------------------------------------

loc_DF2D:				; CODE XREF: CalcNewCrdObj_Pl+4Bj
		sub	b
		ld	(ix+6),	a
		ret	nc
		dec	hl
		bit	7, h
		jr	z, loc_DF3F
		ld	hl, 8000h

loc_DF3A:				; CODE XREF: CalcNewCrdObj_Pl+5Aj
		neg
		ld	(ix+6),	a

loc_DF3F:				; CODE XREF: CalcNewCrdObj_Pl+55j
					; CalcNewCrdObj_Pl+64j
		ld	(ix+8),	h
		ld	(ix+7),	l
		ret
; End of function CalcNewCrdObj_Pl


; =============== S U B	R O U T	I N E =======================================

; Вычисление новой координаты объекта по элементу вектора перемещения игрока
; Вх:  ix - адрес начала координат объекта
;      hl =0/3/6 координата X/Y/Z
;      de =0/3/6 координата X/Y/Z
;      c  - угол поворота
; Вых: crd(hl) = crd(de) * c/#100 + crd(hl) (с учётом знаков)
;      hi(crd(de))*c + med(crd(de))*c/#100 + low(crd(de))*c/#10000 + crd(hl)

CalcNewCrdNobj:				; CODE XREF: CalcNewCrdObj_Pl+Cp
					; CalcNewCrdObj_Pl+1Cp	...
		push	ix
		push	ix
		ex	(sp), iy
		add	ix, de
		ex	de, hl
		add	iy, de
		ld	a, (ix+2)
		ld	d, (ix+1)
		ld	e, (ix+0)
		ld	b, a
		xor	c
		and	80h ; 'А'
		push	af
		res	7, c
		res	7, b
		push	de
		call	Mult_HL_B_C	; Приближенное табличное умножение HL=B*C
					; считает: ((b+c)/2)^2 - ((b-c)/2)^2
					; должно:  ((b+c)^2 - (b-c)^2)/4
		pop	de
		push	hl
		ld	b, d
		push	de
		call	Mult_HL_B_C	; Приближенное табличное умножение HL=B*C
					; считает: ((b+c)/2)^2 - ((b-c)/2)^2
					; должно:  ((b+c)^2 - (b-c)^2)/4
		pop	de
		ld	b, e
		ld	a, l
		ld	l, h
		ld	h, 0
		pop	de
		add	hl, de
		ld	e, a
		push	hl
		call	Mult_A_hiB_C	; a=((b+c)/2)^2-((b-c)/2)^2
		add	a, e
		pop	hl
		jr	nc, loc_DF80
		inc	hl

loc_DF80:				; CODE XREF: CalcNewCrdNobj+37j
		ld	b, a
		ld	a, h
		ld	h, l
		ld	l, b
		pop	bc
		ld	c, b
		ld	b, (iy+2)
		ld	d, (iy+1)
		ld	e, (iy+0)
		push	af
		ld	a, b
		xor	c
		rlc	c
		rlc	c
		rla
		rr	c
		rrc	c
		srl	a
		ld	b, a
		pop	af
		bit	6, c
		jr	nz, loc_DFAE
		add	a, a
		sla	c
		rra
		add	a, b
		add	hl, de
		jr	nc, loc_DFCF
		inc	a
		jr	loc_DFCF
; ---------------------------------------------------------------------------

loc_DFAE:				; CODE XREF: CalcNewCrdNobj+5Bj
		and	a
		ex	de, hl
		sbc	hl, de
		jr	nc, loc_DFB5
		inc	a

loc_DFB5:				; CODE XREF: CalcNewCrdNobj+6Cj
		ld	d, a
		ld	a, b
		sub	d
		ld	b, a
		jr	nc, loc_DFC8
		cpl
		ld	b, a
		ld	a, c
		xor	80h ; 'А'
		ld	c, a
		ex	de, hl
		and	a
		ld	hl, 0
		sbc	hl, de

loc_DFC8:				; CODE XREF: CalcNewCrdNobj+73j
		ld	a, b
		rla
		sla	c
		rra
		xor	80h ; 'А'

loc_DFCF:				; CODE XREF: CalcNewCrdNobj+63j
					; CalcNewCrdNobj+66j
		ld	(iy+2),	a
		ld	(iy+1),	h
		ld	(iy+0),	l
		pop	iy
		pop	ix
		ret
; End of function CalcNewCrdNobj


