; Вых: hl,de,bc,a - не определены

PrnObjIfVisible:			; CODE XREF: MoveAllObjects+189p
		ld	a, (WhatOnScreen) ; Что	изображено на экране
					;  =0..3 в полете номер	обзорного экрана (front, rear, left, right)
					;  =#04	меню покупки товаров
					;  =#05	меню продажи товаров
					;  =#06	меню покупки оборудования
					;  =#07	глобальная карта
					;  =#08	локальная карта
					;  =#09	инфо о планете еще не выведено
					;  =#0A	прайс планеты
					;  =#0B	инфо о пилоте
					;  =#0C	Инвентрь
					;  =#20	инфо о планете
		ld	b, a
		cp	4
		ret	nc		; выход, если не обзорный экран
		push	ix
		pop	hl
		bit	1, a
		jr	nz, loc_E01A	; left/right
		ld	de, 6		; front/rear
		add	hl, de

loc_E01A:				; CODE XREF: PrnObjIfVisible+Cj
		ld	e, (hl)
		inc	hl
		ld	d, (hl)
		inc	hl
