		srl	a
		xor	b
		rrca
		xor	c
		and	80h ; 'А'
		ret	nz
		ld	(DistanceToObj), de ; расстояние до объекта по оси обзорного экрана
		ld	h, 0
		ld	l, (iy+1)	; расстояние до	столкновения
		push	hl
		and	a
		sbc	hl, de
		jr	c, loc_E038	; de - расстояние до объекта по	оси обзорного экрана
					; (sp)	- расстояние до	столкновения
		pop	hl		; слишком близко.
		ret
; ---------------------------------------------------------------------------

loc_E038:				; CODE XREF: PrnObjIfVisible+2Cj
		push	de		; de - расстояние до объекта по	оси обзорного экрана
					; (sp)	- расстояние до	столкновения
		push	de
		bit	1, b
		jr	nz, loc_E063	; left/right
		ex	de, hl
		ld	d, (ix+1)
		ld	e, (ix+0)
		xor	a
