		pop	hl
		ld	d, (ix+4)
		ld	e, (ix+3)
		xor	a
		ld	c, a
		call	Div_C_DEc_HLa	; Деление: 0.c=cde/ahl (dec>hla	-> c=#FF)
					; Вх:  de.с - делимое
					;      hl.a - делитель
					; Вых: 0.c=dec/hla
					;	 cde>ahl -> c=#FF
					;      hl,de,b,a - не определены
		ld	a, c
		ld	(CrdYProjection), a ; координата Y проекции объекта
		ld	b, (ix+2)
		jr	loc_E086
; ---------------------------------------------------------------------------

loc_E063:				; CODE XREF: PrnObjIfVisible+34j
		ex	de, hl
