		ld	e, (ix+6)
		xor	a
		ld	c, a
		call	Div_C_DEc_HLa	; Деление: 0.c=cde/ahl (dec>hla	-> c=#FF)
					; Вх:  de.с - делимое
					;      hl.a - делитель
					; Вых: 0.c=dec/hla
					;	 cde>ahl -> c=#FF
					;      hl,de,b,a - не определены
		ld	a, c
		ld	(CrdXProjection), a ; координата X проекции объекта
		pop	hl
		ld	d, (ix+4)
		ld	e, (ix+3)
		xor	a
		ld	c, a
		call	Div_C_DEc_HLa	; Деление: 0.c=cde/ahl (dec>hla	-> c=#FF)
					; Вх:  de.с - делимое
					;      hl.a - делитель
					; Вых: 0.c=dec/hla
					;	 cde>ahl -> c=#FF
					;      hl,de,b,a - не определены
		ld	a, c
