		ld	(CrdXYsign), a	; знаки	координат проекции объекта
		pop	hl
		pop	de
		xor	a
		ld	c, a
		call	Div_C_DEc_HLa	; Деление: 0.c=cde/ahl (dec>hla	-> c=#FF)
					; Вх:  de.с - делимое
					;      hl.a - делитель
					; Вых: 0.c=dec/hla
					;	 cde>ahl -> c=#FF
					;      hl,de,b,a - не определены
		ld	h, c
