objPrnObj:				; CODE XREF: PrnObjIfVisible+10Dj
		push	iy
		call	CalcMatrixRotate ; Построение матрицы поворота СКО
					; Вх:  ix - адрес слота	описания объекта
					; Вых: iy=MatrixRotate
					;      hl,de,bc,a - не определены
		pop	iy
