		ld	(PointTablCrdPrn), a ; указатель на текущую запись в таблице печатных координат	вершин
		call	CalcVisibleVerges ; Построение таблицы видимости граней	по нормалям
					; Вх:  ix - адрес слота	описания объекта
					;      iy - адрес данных объекта
					;      (MatrixRotate) -	матрица	поворота СКО
					; Вых: (MatrixRotate+#12) - матрица произведений координаты вектора на элемент
					;	 матрицы поворота
					;      (VergesVisible) - таблица видимости граней по нормалям
					;      hl,de,bc,a - не определены
		call	MakeTablPrnCrdVertex ; Построение таблицы печатных координат видимых вершин объекта
