; =============== S U B	R O U T	I N E =======================================

; Установка значений для печати	взрыва объекта
; Вх:  ---
; Вых: hl,de,bc,a - не определены

objDestroyed:				; CODE XREF: PrnObjIfVisible+F6j
		ld	a, (CrdXProjection) ; координата X проекции объекта
		ld	(ix+1Ch), a
		ld	a, (CrdYProjection) ; координата Y проекции объекта
		ld	(ix+1Dh), a
		ld	a, (RadiusBlast) ; радиус окружности при печати	взрыва
		ld	(ix+1Fh), a
		ld	a, (WhatOnScreen) ; Что	изображено на экране
					;  =0..3 в полете номер	обзорного экрана (front, rear, left, right)
					;  =#04	меню покупки товаров
					;  =#05	меню продажи товаров
					;  =#06	меню покупки оборудования
					;  =#07	глобальная карта
					;  =#08	локальная карта
					;  =#09	инфо о планете еще не выведено
					;  =#0A	прайс планеты
					;  =#0B	инфо о пилоте
					;  =#0C	Инвентрь
					;  =#20	инфо о планете
		bit	0, a
		ld	a, (CrdXYsign)	; знаки	координат проекции объекта
		jr	z, loc_E1F2
		xor	2

loc_E1F2:				; CODE XREF: objDestroyed+1Aj
		ld	c, a
		xor	a
		rr	c
		rla
		rr	c
		rla
		xor	3
		add	a, 0Ch
		ld	(ix+1Eh), a
		set	5, (ix+20h)
		ret
; End of function objDestroyed


