; Построение таблицы печатных координат	видимых	вершин объекта
; Вх:  ix - адрес слота	объекта
;      iy - адрес данных объекта
; Вых: bc=#0006
;      a=#00
;      hl,de - не определены

MakeTablPrnCrdVertex:			; CODE XREF: objPrnObj+25p
		push	iy
		push	iy
		ld	a, (iy+3)	; a кол-во вершин
		ex	(sp), ix
		ld	d, (iy+0Dh)
		ld	e, (iy+0Ch)
		add	ix, de		; ix адрес начала вершин
		ld	iy, MatrixRotate

loc_E306:				; CODE XREF: CalcPrnCrdVertex+156j
		push	af
		ld	a, (PointTablCrdPrn) ; указатель на текущую запись в таблице печатных координат	вершин
		add	a, 3
		ld	(PointTablCrdPrn), a ; указатель на текущую запись в таблице печатных координат	вершин
		ld	a, (ix+3)
		and	1Fh
		cp	1Fh
		jr	z, loc_E31F
		ld	b, a
		ld	a, (DistanceToObj) ; расстояние	до объекта по оси обзорного экрана
		cp	b
		jr	nc, loc_E330

loc_E31F:				; CODE XREF: MakeTablPrnCrdVertex+25j
		ld	a, (ix+4)
		call	TestVergesVisible ; Проверка видимости грани
					; Вх:  a =#nm -	два номера грани
					; Вых: a=1/0 грань видима/невидима
					;      z=1 - грань невидима
					;      hl,de,b - не определены
		jr	nz, loc_E32D
		ld	a, (ix+5)
		call	TestVergesVisible ; Проверка видимости грани
					; Вх:  a =#nm -	два номера грани
					; Вых: a=1/0 грань видима/невидима
					;      z=1 - грань невидима
					;      hl,de,b - не определены

loc_E32D:				; CODE XREF: MakeTablPrnCrdVertex+34j
		jp	nz, CalcPrnCrdVertex ; расчёт печатных координат вершины
					; вх:  ix - адрес вершины
					;      (sp-2) -	адрес слота объекта

loc_E330:				; CODE XREF: MakeTablPrnCrdVertex+2Cj
