; =============== S U B	R O U T	I N E =======================================

; Поворот одной	координаты вершины
; Вх:  ix - адрес начала координат вершины
;      iy =MatrixRotate+n адрес	строки в матрице поворота
; Вых: (MatrixRotate+#12) - матрица произведений координаты вершины на элемент
;	 матрицы поворота
;      hl - новая координата вершины (умножение	координаты на строку матрицы
;	  поворота)
;      iy=iy+6
;      b=#00
;      de,c,a -	не определены

RotateCrdN_Vertex:			; CODE XREF: CalcPrnCrdVertex+21p
					; CalcPrnCrdVertex+2Ap	...
		ld	a, (VisiblePrevVertex) ; видимость предыдущей вершины
					;   <>0	предыдущая вершина не видна
		and	a
		jr	nz, loc_E3B4
		ld	a, (ix+0)
		cp	(ix-6)
		jr	nz, loc_E3B4
		ld	a, (ix+1)
		cp	(ix-5)
		jr	nz, loc_E3B4
		ld	a, (ix+2)
		cp	(ix-4)
		jr	nz, loc_E3B4
		ld	a, (ix+3)
		xor	(ix-3)
		ld	b, a
		ld	l, (iy+12h)
		ld	h, (iy+13h)
		ld	e, (iy+14h)
		ld	d, (iy+15h)
		xor	h
		and	80h ; 'А'
		ld	h, a
		ld	(iy+13h), h
		rl	b
		ld	a, b
		xor	d
		and	80h ; 'А'
		ld	d, a
		ld	(iy+15h), d
		call	AddSign_L_E	; Сложение с учётом знака
					; Вх:  hl - первое слагаемое #00..#FF (7,h знак)
					;      de - второе слагаемое #00..#FF (7,d знак)
					; Вых: a - сумма
					;      7,h - знак
					;      cy =1 переполнение суммы
		ld	l, a
		ld	e, (iy+16h)
		ld	d, (iy+17h)
		ld	a, b
		rla
		xor	d
		and	80h ; 'А'
		ld	d, a
		ld	(iy+17h), d
		call	AddSign_L_E	; Сложение с учётом знака
					; Вх:  hl - первое слагаемое #00..#FF (7,h знак)
					;      de - второе слагаемое #00..#FF (7,d знак)
					; Вых: a - сумма
					;      7,h - знак
					;      cy =1 переполнение суммы
		ld	l, a
		ld	de, 6
		add	iy, de
		jp	loc_E40C
; ---------------------------------------------------------------------------

loc_E3B4:				; CODE XREF: RotateCrdN_Vertex+4j
					; RotateCrdN_Vertex+Cj	...
		ld	b, (ix+0)
		call	MultCrdNMatrixEl ; Умножение координаты	на элемент матрицы с учетом коэффициента увеличения
					;   координат вершины
					; Вх:  b - abs(crd N) вершины
					;      iy =MatrixRotate+n адрес	элемента в матрице поворота
					;      (VertexIncFactor) - коэффициент увеличения координат вершины
					; Вых: hl = 0.b*2^(VertexIncFactor) * 0.MatrixElement
					;      bc,a - не определены
		ld	a, (ix+3)
		xor	(iy+1)
		rla
		rr	h
		ld	(iy+12h), l
		ld	(iy+13h), h
		ex	de, hl
		inc	iy
		inc	iy
		ld	b, (ix+1)
		call	MultCrdNMatrixEl ; Умножение координаты	на элемент матрицы с учетом коэффициента увеличения
					;   координат вершины
					; Вх:  b - abs(crd N) вершины
					;      iy =MatrixRotate+n адрес	элемента в матрице поворота
					;      (VertexIncFactor) - коэффициент увеличения координат вершины
					; Вых: hl = 0.b*2^(VertexIncFactor) * 0.MatrixElement
					;      bc,a - не определены
		ld	a, (ix+3)
		rla
		xor	(iy+1)
		rla
		rr	h
		ld	(iy+12h), l
		ld	(iy+13h), h
		call	AddSign_L_E	; Сложение с учётом знака
					; Вх:  hl - первое слагаемое #00..#FF (7,h знак)
					;      de - второе слагаемое #00..#FF (7,d знак)
					; Вых: a - сумма
					;      7,h - знак
					;      cy =1 переполнение суммы
		ld	l, a
		ex	de, hl
		inc	iy
		inc	iy
		ld	b, (ix+2)
		call	MultCrdNMatrixEl ; Умножение координаты	на элемент матрицы с учетом коэффициента увеличения
					;   координат вершины
					; Вх:  b - abs(crd N) вершины
					;      iy =MatrixRotate+n адрес	элемента в матрице поворота
					;      (VertexIncFactor) - коэффициент увеличения координат вершины
					; Вых: hl = 0.b*2^(VertexIncFactor) * 0.MatrixElement
					;      bc,a - не определены
		ld	a, (ix+3)
		rla
		rla
		xor	(iy+1)
		rla
		rr	h
		ld	(iy+12h), l
		ld	(iy+13h), h
		call	AddSign_L_E	; Сложение с учётом знака
					; Вх:  hl - первое слагаемое #00..#FF (7,h знак)
					;      de - второе слагаемое #00..#FF (7,d знак)
					; Вых: a - сумма
					;      7,h - знак
					;      cy =1 переполнение суммы
		ld	l, a
		inc	iy
		inc	iy

loc_E40C:				; CODE XREF: RotateCrdN_Vertex+5Ej
		ld	a, (VertexIncFactor) ; максимально-возможный коэффициент увеличения координат вершины
		ld	b, a
		xor	a
		ld	c, h
		res	7, h

loc_E414:				; CODE XREF: RotateCrdN_Vertex+C6j
		srl	h
		rr	l
		rra
		djnz	loc_E414
		jr	nc, loc_E41E
		inc	hl

loc_E41E:				; CODE XREF: RotateCrdN_Vertex+C8j
		bit	7, c
		ret	z
		set	7, h
		ret
; End of function RotateCrdN_Vertex


; =============== S U B	R O U T	I N E =======================================

; Сложение с учётом знака
; Вх:  hl - первое слагаемое #00..#FF (7,h знак)
;      de - второе слагаемое #00..#FF (7,d знак)
; Вых: a - сумма
;      7,h - знак
;      cy =1 переполнение суммы

AddSign_L_E:				; CODE XREF: RotateCrdN_Vertex+42p
					; RotateCrdN_Vertex+55p ...
		ld	a, h
		xor	d
		rla
		jr	c, loc_E42C
		ld	a, l
		add	a, e
		ret
; ---------------------------------------------------------------------------

loc_E42C:				; CODE XREF: AddSign_L_E+3j
		ld	a, l
		sub	e
		ret	nc
		neg
		and	a
		ld	h, d
		ret
; End of function AddSign_L_E


; =============== S U B	R O U T	I N E =======================================

; a=((b+c)/2)^2-((b-c)/2)^2

Mult_A_hiB_C:				; CODE XREF: CalcNewCrdNAxis+7p
					; CalcNewCrdNobj+32p ...
		ld	a, b
		sub	c
		jr	nc, loc_E43A
		neg

loc_E43A:				; CODE XREF: Mult_A_hiB_C+2j
		srl	a
		ld	h, 0BFh	; '┐'
		ld	l, a
		ld	d, (hl)
		ld	a, b
		add	a, c
		rra
		ld	l, a
		ld	a, (hl)
		sub	d
		ret
; End of function Mult_A_hiB_C


; =============== S U B	R O U T	I N E =======================================

; Умножение координаты на элемент матрицы с учетом коэффициента	увеличения
;   координат вершины
; Вх:  b - abs(crd N) вершины
;      iy =MatrixRotate+n адрес	элемента в матрице поворота
;      (VertexIncFactor) - коэффициент увеличения координат вершины
