		push	bc
		ld	a, (ix+0)
		cp	1Fh
		jr	z, loc_E747
		ld	c, a
		ld	a, (DistanceToObj) ; расстояние	до объекта по оси обзорного экрана
		cp	c
		jr	nc, loc_E76D	; следующее ребро

