					;      a - знаки координат
					;      z =1 вершина печатается
					;      hl- не определен
		jr	nz, loc_E76D	; следующее ребро
		ld	c, a
		push	de
		ld	a, (ix+2)
		call	GetPrnCrdVertex	; Получение печатных координат вершины из таблицы по номеру
					; Вх:  a - номер вершины
