; =============== S U B	R O U T	I N E =======================================

; Вычисление расстояния	по одной оси
; Вх:  hl - координата X/Y/Z первого объекта (7,h знак)
;      de - координата X/Y/Z второго объекта (7,d знак)
; Вых: 7,h =1 координата первого объекта левее
;	hl - расстояние	по заданной оси/2
;      de,bc,a - не определены

CalcDeltaCrd:				; CODE XREF: sub_712C+Cj
					; MoveMissile+A8p
		ld	a, d
		xor	80h ; 'А'
		ld	d, a
; End of function CalcDeltaCrd


; =============== S U B	R O U T	I N E =======================================

; Сложение с учётом знака
; Вх:  hl - первое слагаемое (7,h знак)
;      de - второе слагаемое (7,d знак)
; Вых: hl - сумма/2 (7,h знак)
;      de,bc,a - не определены

AddSign_HL_DE:				; CODE XREF: ScalarMultVectors16_8+27p
					; ScalarMultVectors16_8+33j
		ld	a, h
		xor	d
		ld	b, h
		ld	c, d
		res	7, h
		res	7, d
		and	80h ; 'А'
		jr	nz, loc_E903
		add	hl, de
		jr	loc_E90D
; ---------------------------------------------------------------------------

loc_E903:				; CODE XREF: AddSign_HL_DE+Aj
		sbc	hl, de
		jr	nc, loc_E90D
		add	hl, de
		ex	de, hl
		and	a
		sbc	hl, de
		ld	b, c

loc_E90D:				; CODE XREF: AddSign_HL_DE+Dj
					; AddSign_HL_DE+11j
		srl	h
		rr	l
		bit	7, b
		ret	z
		set	7, h
		ret
; End of function AddSign_HL_DE

; ---------------------------------------------------------------------------
AdrSlotObj:	dw 0			; DATA XREF: CalcVisibleVerges+9w
					; CalcVisibleVerges+43r
					; адрес	описания объекта в пространстве
IY_dFactor:	db 0			; DATA XREF: CalcVisibleVerges+1Aw
					; RotateCrdN_Normal+19r
					; (iy+#13)
AddNormalCrdX:	dw 0			; DATA XREF: CalcVisibleVerges+4Dw
					; CalcVisibleVerges+65o
					; сумма	векторов нормали и вектора(координат) объекта
AddNormalCrdY:	dw 0			; DATA XREF: CalcVisibleVerges+56w
AddNormalCrdZ:	dw 0			; DATA XREF: CalcVisibleVerges+5Fw
NormalCrdX:	db 0			; DATA XREF: CalcVisibleVerges+4Aw
					; CalcVisibleVerges+69o
					; вектор нормали с учётом поворота СКО
NormalCrdY:	db 0			; DATA XREF: CalcVisibleVerges+53w
NormalCrdZ:	db 0			; DATA XREF: CalcVisibleVerges+5Cw

; =============== S U B	R O U T	I N E =======================================

; Построение таблицы видимости граней по нормалям
; Вх:  ix - адрес слота	описания объекта
;      iy - адрес данных объекта
;      (MatrixRotate) -	матрица	поворота СКО
; Вых: (MatrixRotate+#12) - матрица произведений координаты вектора на элемент
;	 матрицы поворота
;      (VergesVisible) - таблица видимости граней по нормалям
;      hl,de,bc,a - не определены

CalcVisibleVerges:			; CODE XREF: objPrnObj+22p
		push	ix
		push	iy
		push	iy
		ex	(sp), ix	; ix=iy
		pop	hl		; hl=ix
		ld	(AdrSlotObj), hl ; адрес описания объекта в пространстве
		ld	d, (ix+11h)
		ld	e, (ix+10h)	; de смещение до нормалей
		add	ix, de		; ix=адрес начала нормалей
		ld	de, VergesVisible ; видимость граней
					; =0 не	видна (нормаль направлена от игрока)
		ld	a, (iy+13h)
		ld	(IY_dFactor), a	; (iy+#13)
		ld	a, (iy+5)
		and	a
		ld	iy, MatrixRotate
		jr	nz, loc_E94E	; a  - кол-во нормалей
					; de =#E2AC
					; ix адрес начала нормалей
					; iy =#E2BC
		inc	a
		ld	(de), a
		jr	loc_E9A9	; выход
; ---------------------------------------------------------------------------

loc_E94E:				; CODE XREF: CalcVisibleVerges+25j
					; CalcVisibleVerges+84j
		push	af		; a  - кол-во нормалей
					; de =#E2AC
					; ix адрес начала нормалей
					; iy =#E2BC
		push	de
		ld	a, (ix+3)
		and	1Fh
		cp	1Fh
		jr	z, loc_E964
		ld	b, a
		ld	a, (DistanceToObj) ; расстояние	до объекта по оси обзорного экрана
		cp	b
		jr	c, loc_E964
		pop	de
		xor	a
		jr	loc_E99E	; следующая грань
; ---------------------------------------------------------------------------

loc_E964:				; CODE XREF: CalcVisibleVerges+34j
					; CalcVisibleVerges+3Bj
		push	iy
		ld	hl, (AdrSlotObj) ; адрес описания объекта в пространстве
		push	hl
		call	RotateCrdN_Normal ; Вх:	 ix - адрес начала координат нормали
					;      iy =MatrixRotate+n адрес	строки в матрице поворота
					;      (sp) - адрес координаты объекта
					; Вых: (MatrixRotate+#12) - матрица произведений координаты вектора на элемент
					;	 матрицы поворота
					;      hl - сумма координат вектора объекта и нормали
					;      a - повернутая координата n нормали (7,a=sign)
					;      (sp)=(sp)+3
					;      iy=iy+6
					;      b=#00
					;      de,c - не определены
		ld	(NormalCrdX), a	; вектор нормали с учётом поворота СКО
		ld	(AddNormalCrdX), hl ; сумма векторов нормали и вектора(координат) объекта
		call	RotateCrdN_Normal ; Вх:	 ix - адрес начала координат нормали
					;      iy =MatrixRotate+n адрес	строки в матрице поворота
					;      (sp) - адрес координаты объекта
					; Вых: (MatrixRotate+#12) - матрица произведений координаты вектора на элемент
					;	 матрицы поворота
					;      hl - сумма координат вектора объекта и нормали
					;      a - повернутая координата n нормали (7,a=sign)
					;      (sp)=(sp)+3
					;      iy=iy+6
					;      b=#00
					;      de,c - не определены
		ld	(NormalCrdY), a
		ld	(AddNormalCrdY), hl
		call	RotateCrdN_Normal ; Вх:	 ix - адрес начала координат нормали
					;      iy =MatrixRotate+n адрес	строки в матрице поворота
					;      (sp) - адрес координаты объекта
					; Вых: (MatrixRotate+#12) - матрица произведений координаты вектора на элемент
					;	 матрицы поворота
					;      hl - сумма координат вектора объекта и нормали
					;      a - повернутая координата n нормали (7,a=sign)
					;      (sp)=(sp)+3
					;      iy=iy+6
					;      b=#00
					;      de,c - не определены
		ld	(NormalCrdZ), a
		ld	(AddNormalCrdZ), hl
		pop	hl
		push	ix
		ld	iy, AddNormalCrdX ; сумма векторов нормали и вектора(координат)	объекта
		ld	ix, NormalCrdX	; вектор нормали с учётом поворота СКО
		call	ScalarMultVectors16_8 ;	Скалярное произведение векторов
					; Вх:  iy - адрес начала первого вектора (вектор начала	СКО + вектор нормали)
					;      ix - адрес начала второго вектора (вектор нормали в СКО)
					; Вых: h.l = crdZ1*crdZ2 + crdY1*crdY2 + crdX1*crdX2
					;      de,bc,a - не определены
		pop	ix
		pop	iy
		pop	de
		xor	a
		sla	h
		jr	nc, loc_E99E	; следующая грань
		inc	a

loc_E99E:				; CODE XREF: CalcVisibleVerges+3Fj
					; CalcVisibleVerges+78j
		ld	(de), a		; следующая грань
		inc	de
		ld	bc, 4
		add	ix, bc
		pop	af
		dec	a
		jr	nz, loc_E94E	; a  - кол-во нормалей
					; de =#E2AC
					; ix адрес начала нормалей
					; iy =#E2BC

loc_E9A9:				; CODE XREF: CalcVisibleVerges+29j
		pop	iy		; выход
		pop	ix
		ret
; End of function CalcVisibleVerges


; =============== S U B	R O U T	I N E =======================================

; Скалярное произведение векторов
; Вх:  iy - адрес начала первого вектора (вектор начала	СКО + вектор нормали)
;      ix - адрес начала второго вектора (вектор нормали в СКО)
; Вых: h.l = crdZ1*crdZ2 + crdY1*crdY2 + crdX1*crdX2
;      de,bc,a - не определены

ScalarMultVectors16_8:			; CODE XREF: CalcVisibleVerges+6Dp
		ld	e, (iy+1)
		ld	c, (iy+0)
		ld	a, (ix+0)
		call	Mult_HL_EC_A	; умножение: h.l = e.c * 0.a * 2 (7,h -	знак)
		push	hl
		ld	e, (iy+3)
		ld	c, (iy+2)
		ld	a, (ix+1)
		call	Mult_HL_EC_A	; умножение: h.l = e.c * 0.a * 2 (7,h -	знак)
		push	hl
		ld	e, (iy+5)
		ld	c, (iy+4)
		ld	a, (ix+2)
		call	Mult_HL_EC_A	; умножение: h.l = e.c * 0.a * 2 (7,h -	знак)
		pop	de
		call	AddSign_HL_DE	; Сложение с учётом знака
					; Вх:  hl - первое слагаемое (7,h знак)
					;      de - второе слагаемое (7,d знак)
					; Вых: hl - сумма/2 (7,h знак)
					;      de,bc,a - не определены
		adc	hl, hl
		bit	7, b
		jr	z, loc_E9E0
		set	7, h

loc_E9E0:				; CODE XREF: ScalarMultVectors16_8+2Ej
		pop	de
		jp	AddSign_HL_DE	; Сложение с учётом знака
; End of function ScalarMultVectors16_8	; Вх:  hl - первое слагаемое (7,h знак)
					;      de - второе слагаемое (7,d знак)
					; Вых: hl - сумма/2 (7,h знак)
					;      de,bc,a - не определены

; =============== S U B	R O U T	I N E =======================================

; умножение: h.l = e.c * 0.a * 2 (7,h -	знак)

Mult_HL_EC_A:				; CODE XREF: ScalarMultVectors16_8+9p
					; ScalarMultVectors16_8+16p ...
		ld	b, a
		sla	b
		and	80h ; 'А'
		xor	e
		ld	e, a
		call	Mult_A_hiB_C	; a=((b+c)/2)^2-((b-c)/2)^2
		ld	d, e
		ld	e, a
		ld	c, d
		res	7, c
		push	de
		call	Mult_HL_B_C	; Приближенное табличное умножение HL=B*C
					; считает: ((b+c)/2)^2 - ((b-c)/2)^2
					; должно:  ((b+c)^2 - (b-c)^2)/4
		pop	de
		ld	a, d
		ld	d, 0
		add	hl, de
		add	hl, hl
		rla
		rr	h
		rr	l
		ret
; End of function Mult_HL_EC_A


; =============== S U B	R O U T	I N E =======================================

; Вх:  ix - адрес начала координат нормали
;      iy =MatrixRotate+n адрес	строки в матрице поворота
;      (sp) - адрес координаты объекта
; Вых: (MatrixRotate+#12) - матрица произведений координаты вектора на элемент
;	 матрицы поворота
;      hl - сумма координат вектора объекта и нормали
;      a - повернутая координата n нормали (7,a=sign)
;      (sp)=(sp)+3
;      iy=iy+6
;      b=#00
;      de,c - не определены

RotateCrdN_Normal:			; CODE XREF: CalcVisibleVerges+47p
					; CalcVisibleVerges+50p ...
		call	RotateCrdN	; Поворот одной	координаты вектора
					; Вх:  ix - адрес начала координат вектора (нормали)
					;      iy =MatrixRotate+n адрес	строки в матрице поворота
					; Вых: (MatrixRotate+#12) - матрица произведений координаты вектора на элемент
					;	 матрицы поворота
					;      hl - новая координата вектора (умножение	вектора	на строку матрицы поворота)
					;      iy=iy+6
					;      de = #0006
					;      bc,a - не определены
		pop	bc
		ex	(sp), ix
		ld	e, (ix+0)	; ade координата n
		ld	d, (ix+1)
		ld	a, (ix+2)
		inc	ix
		inc	ix
		inc	ix
		ex	(sp), ix
		push	bc
		ld	c, a
		ld	a, (IY_dFactor)	; (iy+#13)
		sla	l
		push	hl
		ld	b, a
		inc	b

loc_EA24:				; CODE XREF: RotateCrdN_Normal+23j
		srl	l
		djnz	loc_EA24
		rl	l
		ld	a, c
		xor	h
		sla	h
		rla
		jr	c, loc_EA34
		add	hl, de
		jr	loc_EA43
; ---------------------------------------------------------------------------

loc_EA34:				; CODE XREF: RotateCrdN_Normal+2Cj
		ex	de, hl
		and	a
		sbc	hl, de
		jr	nc, loc_EA43
		add	hl, de
		ex	de, hl
		and	a
		sbc	hl, de
		ld	a, c
		xor	80h ; 'А'
		ld	c, a

loc_EA43:				; CODE XREF: RotateCrdN_Normal+2Fj
					; RotateCrdN_Normal+35j
		sla	c
		rr	h
		rr	l
		pop	de
		ld	a, e
		rl	d
		rra
		ret
; End of function RotateCrdN_Normal

