; =============== S U B	R O U T	I N E =======================================

; Проверка столкновения	объекта	с игроком, и его обработка
; Вх:  ix - адрес слота	объекта
;      iy - адрес данных объекта
; Вых: hl,de,bc,a - не определены

CollisionWithObj:			; CODE XREF: MoveAllObjects:loc_DBA3p
		ld	a, (PlayerGameOver) ; <>0 энергоблоки пустые
					; игрок	уничтожен
		and	a
		ret	nz
		ld	d, 0
		ld	e, (iy+1)
		bit	0, (ix+26h)
		jr	z, loc_EA69
		ld	a, (ix+25h)
		and	a
		jr	nz, loc_EA69
		ld	d, 1		; d=1, это ракета и запущена она по игроку

loc_EA69:				; CODE XREF: CollisionWithObj+Ej
					; CollisionWithObj+14j
		bit	1, (ix+26h)
		jr	z, loc_EA71
		ld	e, 0B4h	; '┤'

loc_EA71:				; CODE XREF: CollisionWithObj+1Cj
		ld	l, (ix+0)
		ld	h, (ix+1)
		sbc	hl, de
		ret	nc		; по оси X до столкновения далеко
		and	a
		ld	l, (ix+3)
		ld	h, (ix+4)
		sbc	hl, de
		ret	nc		; по оси Y до столкновения далеко
		and	a
		ld	l, (ix+6)
		ld	h, (ix+7)
		sbc	hl, de
		ret	nc		; по оси Z до столкновения далеко
		ld	a, (ix+8)
		and	7Fh ; ''
		ret	nz
		bit	1, (ix+26h)
		jr	z, loc_EAD8	; столкновение с объектом???
		bit	7, (ix+5)	; объект выше оси Y
		jp	z, objCollision	; уничтожаем объект (врезаемся)
		ld	a, (PilotFuelScoops) ; объект ниже оси Y, подбираем груз
		and	a
		jp	z, objCollision	; уничтожаем объект (врезаемся)
		xor	a		; подбираем контейнер
		ld	(ix+22h), a
		call	OffTargetMissiles ; Объект исчез из пространства (уничтожен/улетел). Снять ракету с нацеливания	и
					;   уничтожить выпущенные в этот объект	ракеты
					; Вх:  ix - адрес слота	уничтоженного объекта
					;      (InverseNumSlotIX) - его	обратный номер в списке	слотов
					; Вых: de = LenSlotObj
					;      b =#00
					;      hl,a - не определены
		ld	a, (PilotFreeCargo) ; Оставшаяся грузоподъемность корабля
		and	a
		jr	z, objCollision	; уничтожаем объект (врезаемся)
		ld	a, (iy+0)
		and	0F0h ; 'Ё'
		jr	z, loc_EAC3
		rrca
		rrca
		rrca
		rrca
		inc	a
		jr	loc_EAD5
; ---------------------------------------------------------------------------

loc_EAC3:				; CODE XREF: CollisionWithObj+69j
		ld	a, (PilotMission2) ; =3	asp из 2й миссии уничтожен/в пространстве есть контейнер с шапкой-невидимкой
					; =2 у asp невидимость выключена
					; =1 выдана 2й миссия
					; =0 при движении на J
		sub	3
		jr	nz, loc_EAD0
		ld	(PilotMission2), a ; =3	asp из 2й миссии уничтожен/в пространстве есть контейнер с шапкой-невидимкой
					; =2 у asp невидимость выключена
					; =1 выдана 2й миссия
					; =0 при движении на J
		dec	a		; A=#FF	собрали	Cloaking device
		jr	loc_EAD5
; ---------------------------------------------------------------------------

loc_EAD0:				; CODE XREF: CollisionWithObj+77j
		call	IntRnd_A2	; случайное число
					;  A - результат
		and	111b

loc_EAD5:				; CODE XREF: CollisionWithObj+70j
					; CollisionWithObj+7Dj
		jp	AddFoundCargo	; Добавить найденный контейнер к грузу
					; Вх:  a - тип груза в контейнере
					;	=#FF cloaking device
					;	=0..16 груз
					; Вых: hl,de,b,a - не определены
; ---------------------------------------------------------------------------

loc_EAD8:				; CODE XREF: CollisionWithObj+47j
		bit	2, (ix+26h)	; столкновение с объектом???
		jr	z, objCollision	; уничтожаем объект (врезаемся)
		bit	7, (ix+0Eh)
		jr	z, killPlayer	; игрок	уничтожен
		bit	7, (ix+8)
		jr	nz, killPlayer	; игрок	уничтожен
		bit	2, (ix+21h)
		jr	nz, killPlayer	; игрок	уничтожен
		ld	a, (ix+0Ah)
		add	a, a
		cp	0DCh ; '▄'
		jr	nc, killPlayer	; игрок	уничтожен
		ld	b, a
		ld	a, (ix+0Ch)
		add	a, a
		cp	0DCh ; '▄'
		jr	nc, killPlayer	; игрок	уничтожен
		cp	3Ch ; '<'
		jr	nc, loc_EB10	; урон щитам при столкновении, в зависимости от	скорости
		ld	a, b
		cp	3Ch ; '<'
		jr	nc, loc_EB10	; урон щитам при столкновении, в зависимости от	скорости
		ld	a, 1
		ld	(ManualDocking), a ; =0	при вылете с планеты
					; <>0 начата ручная стыковка????
		ret
; ---------------------------------------------------------------------------

loc_EB10:				; CODE XREF: CollisionWithObj+B2j
					; CollisionWithObj+B7j
		ld	hl, nBeepFX	; урон щитам при столкновении, в зависимости от	скорости
		set	6, (hl)
