; =============== S U B	R O U T	I N E =======================================

; Объект исчез из пространства (уничтожен/улетел). Снять ракету	с нацеливания и
;   уничтожить выпущенные в этот объект	ракеты
; Вх:  ix - адрес слота	уничтоженного объекта
;      (InverseNumSlotIX) - его	обратный номер в списке	слотов
; Вых: de = LenSlotObj
;      b =#00
;      hl,a - не определены

OffTargetMissiles:			; CODE XREF: MoveAllObjects+12Ap
					; ReCalcCrdObj+17j ...
		ld	a, (InverseNumSlotIX) ;	обратный номер слота объекта, адрес слота которого в IX	(возможно в прицеле)
					;
		ld	h, a
		push	iy
		ld	iy, objCoriolis	; длина	27h
		ld	de, 27h	; '''
		ld	b, 7

loc_EB74:				; CODE XREF: OffTargetMissiles:loc_EB8Cj
		add	iy, de
		ld	a, (iy+22h)
		and	a
		jr	z, loc_EB8C
		ld	a, (iy+25h)	; если ракета нацелена на уничтоженную ракету, то эту ракету тоже уничтожить
		cp	h
		jr	nz, loc_EB8C
		bit	0, (ix+26h)	; вероятно ошибка, должно быть bit 0,(iy+26h)
		jr	z, loc_EB8C
		set	4, (iy+20h)	; если уничтоженный объект - ракета

loc_EB8C:				; CODE XREF: OffTargetMissiles+15j
					; OffTargetMissiles+1Bj ...
		djnz	loc_EB74
		pop	iy
		ld	a, (Missile1)	; =0 ракета не нацелена
					; =1 ракета готова к захвату цели
					; =2 ракета на что-то нацелена
		cp	2
		ret	nz
		ld	a, (nObjMissile) ;  =0 было включено нацеливание ракеты
					; <>0 обратный номер объекта на	который	нацелена ракета	(8 - 0й	слот)
		sub	h
		ret	nz
		ld	(Missile1), a	; =0 ракета не нацелена
					; =1 ракета готова к захвату цели
					; =2 ракета на что-то нацелена
		ld	hl, UntargetMissile ; 7,=1 ракета снята	с нацеливания (не игроком)
		set	7, (hl)
		ret
; End of function OffTargetMissiles


