		ld	a, (TempLaser)	; остывание лазера
		cp	2
		jr	nc, loc_EBD8
		ld	a, 2

loc_EBD8:				; CODE XREF: FireLaser+Dj
		sub	2
		ld	(TempLaser), a	; температура лазера
					;   +0 - текущее значение
					;   -1 - отображенное на экране
					; >#90 не стреляем
		ld	hl, ControlKey3	; 7,=1 - C     -- Docking Computer
					; 6,=1 - Q     -- Escape Pod
					; 5,=1 - W     -- Energy Bomb
					; 4,=1 - E     -- ECM System
					; 3,=1 - U     -- UnTarget
					; 2,=1 - F     -- Fire Missile
					; 1,=1 - T     -- Target Missile
					; 0,=1 - A     -- Fure Laser
		bit	0, (hl)
		ret	z
		res	0, (hl)
		cp	90h ; 'Р'
		ret	nc		; перегрев лазера
		ld	b, a		; температура лазера
		ld	a, (WhatOnScreen) ; Что	изображено на экране
					;  =0..3 в полете номер	обзорного экрана (front, rear, left, right)
					;  =#04	меню покупки товаров
					;  =#05	меню продажи товаров
					;  =#06	меню покупки оборудования
					;  =#07	глобальная карта
					;  =#08	локальная карта
					;  =#09	инфо о планете еще не выведено
					;  =#0A	прайс планеты
					;  =#0B	инфо о пилоте
					;  =#0C	Инвентрь
					;  =#20	инфо о планете
		ld	hl, PilotFrontLaser ; 42 FrontLaser
		ld	d, 0
		ld	e, a
		add	hl, de
		ld	a, (hl)
		and	a
		ret	z
		ld	e, c
		ld	c, a
		dec	a
		jr	nz, loc_EBFD
		ld	d, 1		; приращение температуры

