Process_LaserECM2:			; CODE XREF: Process_LaserECM+4j
		xor	a
		ld	(HighAngleDU), a ; старший байт	угла поворота
					; 7,n знак (верх/вниз)
					; #00..#0F
		ld	(HighDeltaSpeed), a ; старший байт скорости
					; #00..#1F
		ret
; End of function Process_LaserECM2


; =============== S U B	R O U T	I N E =======================================

; Обработка лазера игрока и системы ECM
; Вх:  ---
; Вых: ix,hl,de,bc,a - не определены

Process_LaserECM:			; CODE XREF: GameMain+55p GameMain+8Cp ...
		ld	a, (PlayerGameOver) ; <>0 энергоблоки пустые
					; игрок	уничтожен
		and	a
		jr	nz, Process_LaserECM2
		ld	a, (WhatOnScreen) ; Что	изображено на экране
					;  =0..3 в полете номер	обзорного экрана (front, rear, left, right)
					;  =#04	меню покупки товаров
					;  =#05	меню продажи товаров
					;  =#06	меню покупки оборудования
					;  =#07	глобальная карта
					;  =#08	локальная карта
					;  =#09	инфо о планете еще не выведено
					;  =#0A	прайс планеты
					;  =#0B	инфо о пилоте
					;  =#0C	Инвентрь
					;  =#20	инфо о планете
		cp	4
		ret	nc
		ld	hl, PilotFrontLaser ; 42 FrontLaser
		ld	d, 0
		ld	e, a
		add	hl, de
		ld	a, (hl)
		and	a
		jr	z, loc_ED83
		ld	hl, 800h
		ld	de, 1000h
		ld	c, 0Ah
		call	PrnLineInBuf_clip ; печать линии в буфере???
					; 0-1,c	квадрант печати	первой точки
					; 2-3,c	квадрант печати	второй точки
					; hl - координаты первой точки (x1y1)
					; de - координаты второй точки (x2y2)
		ld	hl, 800h
		ld	de, 1000h
		ld	c, e
		call	PrnLineInBuf_clip ; печать линии в буфере???
					; 0-1,c	квадрант печати	первой точки
					; 2-3,c	квадрант печати	второй точки
					; hl - координаты первой точки (x1y1)
					; de - координаты второй точки (x2y2)
		ld	hl, 10h
		ld	de, 8
		ld	c, d
		call	PrnLineInBuf_clip ; печать линии в буфере???
					; 0-1,c	квадрант печати	первой точки
					; 2-3,c	квадрант печати	второй точки
					; hl - координаты первой точки (x1y1)
					; de - координаты второй точки (x2y2)
		ld	hl, 10h
		ld	de, 8
		ld	c, 5
		call	PrnLineInBuf_clip ; печать линии в буфере???
					; 0-1,c	квадрант печати	первой точки
					; 2-3,c	квадрант печати	второй точки
					; hl - координаты первой точки (x1y1)
					; de - координаты второй точки (x2y2)
		call	FireLaser	; Выстрел игроком из лазера
					; Вх:  ---
					; Вых: ix,hl,de,bc,a - не определены

loc_ED83:				; CODE XREF: Process_LaserECM+15j
		ld	a, (PilotExtWeapon) ; +93 наличие доп вооружения
					;   7,=1 - ECM Jammer
					;   6,=1 - Cloaking device
					;   5,=1 - нельзя купить товары(в трюме	беженцы)
					;   4
					;   3 =1 3я миссия была	выполнена
					;   2 =1 - третья миссия выполнена
					;   1 =1 - второя миссия выполнена
					;   0 =1 - первая миссия выполнена
		bit	7, a
		jr	z, loc_ED90
		ld	a, (PilotMission3) ; +92 >0 - выдана 3я	миссия
					;  =1 при стыковке будет выдана	3я миссиия ( =1	пора выдавать миссию будет =2 после прыжка)
					;  =2 при стыковке будет выдана	3я миссиия
					;  =3 выдана 3я	миссия (можно уничтожить станцию ракетой) (из станции вылетают таргоны)
					;  =4 выдана 3я	миссия,	корабль	находится в системе с целью (можно уничтожить станцию ракетой) (из станции вылетают таргоны)
					;  =5 3я миссия	выполнена, будет поздравление при стыковке
					;
					;
					;  =4 корабль захватили	пираты,	(сообщить при стыковке)	будет =3 после прыжка
					; 3,=1 станция уничтожена
		cp	4
		ret	z

loc_ED90:				; CODE XREF: Process_LaserECM+49j
		ld	hl, ControlKey3	; 7,=1 - C     -- Docking Computer
					; 6,=1 - Q     -- Escape Pod
					; 5,=1 - W     -- Energy Bomb
					; 4,=1 - E     -- ECM System
					; 3,=1 - U     -- UnTarget
					; 2,=1 - F     -- Fire Missile
					; 1,=1 - T     -- Target Missile
					; 0,=1 - A     -- Fure Laser
		ld	b, (hl)
		res	4, (hl)
		ld	a, (PilotECMSystem) ; ECM System
					; 7,=1 система включена
		ld	c, a
		ld	a, (TimeWorkECM) ; оставшееся время работы системы
					; =0 ECM выключена
					;
		and	a
		jp	z, ECM_On	; включени ECM системы,	если доступно
		dec	a
		ld	(TimeWorkECM), a ; оставшееся время работы системы
					; =0 ECM выключена
					;
		jr	nz, loc_EDA9
		res	7, c

loc_EDA9:				; CODE XREF: Process_LaserECM+66j
		ld	hl, nBeepFX	; какой	звук надо включить
					; =#00 звуков нет(не звучат)
					;  0,=1	взорвана энерго	бомба
					;  1,=1	запущена ракета
					;  2,=1	врезаемся в объект/объект уничтожен
					;  3,=1	выстрел	из лазера
					;  4,=1	выстрелили из дазера
					;  5,=1	ECM работает
					;  6,=1	попадание из лазера по игроку/повреждения при стыковке
					;  7,=1
		set	5, (hl)
		ld	a, c
		and	a
		ret	z
		ld	(PilotECMSystem), a ; ECM System
					; 7,=1 система включена
		ld	a, (DamageEnergyUnit) ;	урон энергоблокам
		inc	a
		ld	(DamageEnergyUnit), a ;	урон энергоблокам
		ret
; End of function Process_LaserECM

