; Умножение c=high(a*c+#80)

Mult_C_hiAmulCadd80:			; CODE XREF: PrnLineInBuf_clip+23Dp
					; PrnLineInBuf_clip+27Bp
		push	de
		push	hl
		ld	b, a

loc_F0C1:				; Приближенное табличное умножение HL=B*C
		call	Mult_HL_B_C	; считает: ((b+c)/2)^2 - ((b-c)/2)^2
					; должно:  ((b+c)^2 - (b-c)^2)/4
