; Расчет коэффициента изменения	координаты при печати линии
; Вх:  a - меньшая разность координат
;      b - большая разность координат
; Вых: c - коэффициент приращения по меньшей оси

CalcDeltaCrdLine:			; CODE XREF: PrnLineInBuf_clip+243p
					; PrnLineInBuf_clip+281p ...
		ld	c, 0FEh	; '■'
		push	de
		ld	e, 0
		call	CalcDeltaCrdLine2 ; Расчет коэффициента	изменения координаты при печати	линии
					; Вх:  a - меньшая разность координат
					;      b - большая разность координат
					;      c=#FE
					;      e=#00
					; Вых: c - коэффициент приращения по меньшей оси
		pop	de
		ret
; End of function CalcDeltaCrdLine


; =============== S U B	R O U T	I N E =======================================

; Вычисление адреса для	печати и данных	для установки первой точки
; Вх:  de - координаты второй точки (x2y2)
;      7,b =1 длина линии по X	> #FF
;	   =0 длина линии по X =< #FF
;      6,b =1 длина линии по Y	> #FF
;	   =0 длина линии по Y =< #FF
;      4,b =1 dX >= dY
;      4,b =0 dX <  dY
;      3,b =1 координата X2 левее координаты X1
;	   =0 координата X2 правее координаты X1
;      2,b =1 координата Y2 ниже координаты Y1
;	   =0 координата Y2 выше координаты Y1
;      c - коэффициент приращения координаты по	меньшей	оси
; Вых: d' - байт для установки точки
;      e' - коэффициент приращения координаты по меньшей оси
;      hl' - адрес печати на экране/в буфере
;      b' - количество точек в первом знакоместе по Y
;      a,c' - не определен
;      другие регистры не изменяются

CalcFirstAdr4Line:			; CODE XREF: PrnLineInBuf_clip+83p
					; PrnLineInBuf_clip+90p ...
		push	bc
		push	bc
		push	de
		exx
		pop	bc
		pop	de
		bit	1, d
		jr	nz, loc_F0E5
		ld	a, 7Fh ; ''
