		sub	b

loc_F0E8:				; CODE XREF: CalcFirstAdr4Line+Dj
		ld	b, a
		bit	0, d
		jr	z, loc_F0F2
		ld	a, 3Fh ; '?'
		add	a, c
		jr	loc_F0F5
; ---------------------------------------------------------------------------

loc_F0F2:				; CODE XREF: CalcFirstAdr4Line+15j
		ld	a, 3Fh ; '?'
		sub	c

