; =============== S U B	R O U T	I N E =======================================

; Печать линии с обрезанием по краю экрана
; Вх:  de - координаты второй точки (x2y2)
;	  точка	на экране, от неё начинается печать
;      4,b =1 dX >= dY
;      4,b =0 dX <  dY
;      3,b =1 координата X2 левее координаты X1
;	   =0 координата X2 правее координаты X1
;      2,b =1 координата Y2 ниже координаты Y1
;	   =0 координата Y2 выше координаты Y1
;      1,b - знак x2
;      0,b - знак y2
;      c - коэффициент приращения координаты по	меньшей	оси
;      hl' - адрес печати на экране/в буфере
;      b' - количество точек в первом знакоместе по Y
;      c' - байт для установки точки
;      e' - коэффициент приращения координаты по меньшей оси
; Вых: линия напечатана

PrnLine_OneCrdClip:			; CODE XREF: PrnLineInBuf_clip+86j
					; PrnLineInBuf_clip+267j ...
		push	bc
		ld	hl, 8040h
		ld	a, b
		rra
		rra
		and	3
		sla	b
		sla	b
		or	b
		xor	3
		and	0Fh
		ld	b, a
		call	CalcVars4Line	; Определение разности координат и направления печати
					; Вх:  hl - координаты первой точки (x1y1)
					;      de - координаты второй точки (x2y2)
					;      0,b - знак y1
					;      1,b - знак x1
					;      2,b - знак y2
					;      3,b - знак x2
					; Вых: 7,b =1 длина линии по X	> #FF
					;	   =0 длина линии по X =< #FF
					;      6,b =1 длина линии по Y	> #FF
					;	   =0 длина линии по Y =< #FF
					;      4,b =1 dX >= dY
					;      4,b =0 dX <  dY
					;      3,b =1 координата X2 левее координаты X1
					;	   =0 координата X2 правее координаты X1
					;      2,b =1 координата Y2 ниже координаты Y1
					;	   =0 координата Y2 выше координаты Y1
					;      1,b - знак x2
					;      0,b - знак y2
					;      c - коэффициент приращения координаты по	меньшей	оси
					;      h - разность координат по X
					;      l - разность координат по Y
		pop	de
		ld	a, b
		xor	d
		and	10h
		jr	z, loc_F14F
		ld	c, 0FFh

loc_F14F:				; CODE XREF: PrnLine_OneCrdClip+1Bj
