		jp	z, ModifyAndPrnLine ; модификация п/п печати и печать линии
		ld	a, l
		jr	loc_F169
; ---------------------------------------------------------------------------

loc_F15F:				; CODE XREF: PrnLine_OneCrdClip+21j
		ld	a, e
		sub	c
		ld	a, l
