					; Вх:  a - меньшая разность координат
					;      b - большая разность координат
					; Вых: c - коэффициент приращения по меньшей оси
		ld	a, c
		jp	ModifyAndPrnLine ; модификация п/п печати и печать линии
; End of function PrnLine_OneCrdClip


; =============== S U B	R O U T	I N E =======================================

; Определение разности координат и направления печати
; Вх:  hl - координаты первой точки (x1y1)
;      de - координаты второй точки (x2y2)
;      0,b - знак y1
;      1,b - знак x1
;      2,b - знак y2
;      3,b - знак x2
; Вых: 7,b =1 длина линии по X	> #FF
;	   =0 длина линии по X =< #FF
