;	   =0 координата X2 правее координаты X1
;      2,b =1 координата Y2 ниже координаты Y1
;	   =0 координата Y2 выше координаты Y1
;      1,b - знак x2
;      0,b - знак y2
;      c - коэффициент приращения координаты по	меньшей	оси
;      h - разность координат по X
;      l - разность координат по Y

CalcVars4Line:				; CODE XREF: PrnLineInBuf_clip+80p
					; PrnLineInBuf_clip+8Dp ...
		ld	a, b
		srl	a
		srl	a
		xor	b
		add	a, a
		add	a, a
		add	a, a
		add	a, a
		or	b
		or	3
		ld	b, a
		res	5, b
		and	20h ; ' '
		ld	a, d
		jr	z, loc_F195
		bit	3, b
		jr	z, loc_F190
		set	5, b

loc_F190:				; CODE XREF: CalcVars4Line+17j
		add	a, h
		jr	nc, loc_F1A8
		jr	loc_F1AA
; ---------------------------------------------------------------------------

loc_F195:				; CODE XREF: CalcVars4Line+13j
		sub	h
		jr	c, loc_F1A0
		bit	3, b
		jr	z, loc_F1A8
		set	5, b
		jr	loc_F1A8
; ---------------------------------------------------------------------------

loc_F1A0:				; CODE XREF: CalcVars4Line+21j
		neg
		bit	3, b
		jr	nz, loc_F1A8
		set	5, b

loc_F1A8:				; CODE XREF: CalcVars4Line+1Cj
					; CalcVars4Line+25j ...
		res	1, b

loc_F1AA:				; CODE XREF: CalcVars4Line+1Ej
		ld	h, a
		bit	4, b
		ld	a, e
		res	4, b
		jr	z, loc_F1BD
		bit	2, b
		jr	z, loc_F1B8
		set	4, b

loc_F1B8:				; CODE XREF: CalcVars4Line+3Fj
		add	a, l
		jr	nc, loc_F1D0
		jr	loc_F1D2
; ---------------------------------------------------------------------------

loc_F1BD:				; CODE XREF: CalcVars4Line+3Bj
		sub	l
		jr	c, loc_F1C8
		bit	2, b
		jr	z, loc_F1D0
		set	4, b
		jr	loc_F1D0
; ---------------------------------------------------------------------------

loc_F1C8:				; CODE XREF: CalcVars4Line+49j
		neg
		bit	2, b
		jr	nz, loc_F1D0
		set	4, b

loc_F1D0:				; CODE XREF: CalcVars4Line+44j
					; CalcVars4Line+4Dj ...
		res	0, b

loc_F1D2:				; CODE XREF: CalcVars4Line+46j
		ld	l, a
		ld	c, l
		rrc	b
		rr	c
		ld	a, h
		rrc	b
		rra
		cp	c
		jr	c, loc_F1EA
		set	4, b
		push	bc
		bit	7, b
		jr	z, loc_F1F4
		ld	b, a
		ld	a, c
		jr	loc_F1FA
; ---------------------------------------------------------------------------

loc_F1EA:				; CODE XREF: CalcVars4Line+68j
		res	4, b
		push	bc
		bit	6, b
		jr	z, loc_F1F8
		ld	b, c
		jr	loc_F1FA
; ---------------------------------------------------------------------------

loc_F1F4:				; CODE XREF: CalcVars4Line+6Fj
		ld	a, l
		ld	b, h
		jr	loc_F1FA
; ---------------------------------------------------------------------------

loc_F1F8:				; CODE XREF: CalcVars4Line+7Aj
		ld	a, h
		ld	b, l

loc_F1FA:				; CODE XREF: CalcVars4Line+73j
					; CalcVars4Line+7Dj ...
		call	CalcDeltaCrdLine ; Расчет коэффициента изменения координаты при	печати линии
					; Вх:  a - меньшая разность координат
					;      b - большая разность координат
					; Вых: c - коэффициент приращения по меньшей оси
		ld	a, c
		pop	bc
		ld	c, a
		ret
; End of function CalcVars4Line


