; =============== S U B	R O U T	I N E =======================================

; вх: А	- бит 3-0 номер	функции-обработчика?
; =0 SetRndShip
; =1 Set3_4Targons
; =2 SetObjMissile
; =3 *not used
; =4 ShipSetShip
; =5 Set2Alloys
; =6 SetCargo
; =7 SetShipEscapePod
; =8 Set2Minerals
; =9 SetShip4Intro
;
;	  бит 7-4 номер	=0 - slave
;			=1 - alloys
;			=2 - контейнер
;			=3 - alien items
;			=4 - астероид
;			=5 - астероид
;			=6 - полисмен
;			=7 - кобра
;			=8 - питон
;			=9 - питон
;			=A - кобра
;			=B - асп
;			=C - ферделанс
;			=D - таргон
;			=E - сидевиндер
;			=F - крайт
;

CallFunctionObj:			; CODE XREF: BeginGame+26p
					; BeginGame+77p ...
		ld	c, a
		srl	c
		srl	c
		srl	c
		srl	c
		and	0Fh
		jp	z, SetRndShip	; a = #x0
		dec	a
		jp	z, Set3_4Targons ; 3-0 =1
		dec	a
		jp	z, SetObjMissile ; Запуск ракеты
					; a = #x2
					;      x =0 запускает противник
					;	<>0 игрок
		dec	a
		ret	z		; 3-0 =3
		dec	a
		jp	z, ShipSetShip	; a = #x4
					;      x - номер корабля
		dec	a
		jp	z, Set2Alloys	; 3-0 =5
		dec	a
		jp	z, SetCargo	; 3-0 =6
		dec	a
		jp	z, SetCobra_EscPod ; 3-0 =7
		dec	a
		jp	z, Set2Minerals	; 3-0 =8
		dec	a
		jp	z, SetShip4Intro ; 3-0 =9
		ret			; 3-0 =A..F
; End of function CallFunctionObj


; =============== S U B	R O U T	I N E =======================================

; Установка объекта в слот
; Вх:  a - номер объекта
