; Вых: a=#00

SetObjInSlot:				; CODE XREF: ShipSetObject+Ap
					; SetPlayerObjSlotp ...
		ld	hl, AdrDataShips
		ld	b, a
		and	3Fh ; '?'
		add	a, a
		add	a, a
		add	a, l
		ld	l, a
		jr	nc, loc_F308
		inc	h

loc_F308:				; CODE XREF: SetObjInSlot+Aj
		inc	hl
		ld	e, (hl)
		inc	hl
		ld	d, (hl)
		push	de
		pop	iy		; iy адрес данных объекта
		ld	(ix+24h), d
		ld	(ix+23h), e
		push	ix
		pop	de
		ld	bc, 1Fh
		ld	hl, PatternObject ; +0 Шаблон слота объекта в пространстве
		ldir
		ld	a, (iy+7)
		ld	(ix+22h), a
		ld	a, (iy+12h)
		ld	c, a
		and	6Fh ; 'o'
		ld	(ix+21h), a
		ld	a, (iy+0Ah)
		and	7
		rla
		rl	c
		rra
		ld	(ix+20h), a
		ld	a, (iy+6)
		srl	a
		ld	(ix+1Bh), a
		ld	a, 7Eh ; '~'
		ld	(ix+25h), a
		xor	a
		ld	(ix+26h), a
		set	6, (ix+20h)
		bit	2, (ix+21h)
		jr	nz, loc_F366
		call	IntRnd_A2	; случайное число
					;  A - результат
		and	7
		ld	(ix+1),	a
		call	IntRnd_A2	; случайное число
					;  A - результат
		and	7
		ld	(ix+4),	a

loc_F366:				; CODE XREF: SetObjInSlot+59j
		call	IntRnd_A2	; случайное число
					;  A - результат
		ld	(ix+0),	a
		call	IntRnd_A2	; случайное число
					;  A - результат
		ld	(ix+3),	a
		call	IntRnd_A2	; случайное число
					;  A - результат
		rra
		rr	(ix+2)
		rra
		rr	(ix+5)
		xor	a
		ret
; End of function SetObjInSlot


; =============== S U B	R O U T	I N E =======================================

; Установка объекта в слот по координатам другого объекта (Запуск кораблём
;   противника объекта,	наследует координаты, СКО и скорость от	родителя)
; Вх:  a - номер объекта
;      ix  адрес слота объекта
; Вых: Z=1 успешно, -> ix - адрес слота	установленного объекта
;		       bc =#0000
;

ShipSetObject:				; CODE XREF: SetObjMissile+32p
					; ShipSetShip+28p ...
		ld	c, a
		push	ix
		call	FindSlot4Obj	; Поиск	свободного слота для установки объекта
					; Вх:  ---
					; Вых: z=1 свободный слот найден -> ix - его адрес
					;      de =LenSlotObj
					;      b,a - не	определены
		pop	hl
		ret	nz
		push	hl
		ld	a, c
		call	SetObjInSlot	; Установка объекта в слот
					; Вх:  a - номер объекта
					;      ix  адрес слота объекта
					; Вых: a=#00
		pop	hl
		push	ix
		pop	de
		ld	bc, 1Bh
		ldir
		xor	a
		ret
; End of function ShipSetObject


; =============== S U B	R O U T	I N E =======================================

; Поиск	свободного слота для установки объекта
