		ld	(ix+7),	a
		rra
		rra
		rra
		and	1
		ld	(ix+1),	a
		xor	a
		ld	(ix+4),	a
		call	RndDirectionObj	; Генерация случайного направление движения объекта
					; Вх:  ix - адрес слота	объекта
