;	 =1 Viper
;	 =2 Cobra/Python
;	 =3 taglet
;	 =4 Targon
;	 =5 Sidewinder/Krait
;	 >5 ничего не ставим
;      ix - адрес слота	объекта	родителя
; Вых: z=1 успешно
;	   ix -	адрес слота установленного корабля
;      iy - адрес слота	родителя
;      hl,de,bc,a - не поределены

ShipSetShip:				; CODE XREF: CallFunctionObj+19j
		ld	a, 8
		dec	c		; A=8, viper
		jr	z, loc_F470	; Set Viper
		call	IntRnd_A2	; случайное число
					;  A - результат
		and	1
		add	a, 9		; a=9/10, cobra/python
		dec	c
		jr	z, loc_F470	; Set Cobra/Python
		ld	a, 12h		; a=18,	targlet
		dec	c
		jr	z, loc_F470	; Set taglet
		ld	a, 0Fh		; a=15,	thargon
		dec	c
		jr	z, loc_F470	; Set Targon
		dec	c
		ret	nz		; >5, корабли
		call	IntRnd_A2	; случайное число
					;  A - результат
		bit	0, a
		ld	a, 10h		; a=16,	sidewinder
		jr	z, loc_F470	; a - номер объета
		ld	a, 11h		; a=17,	krait

