					; ShipSetShip+Dj ...
		push	ix		; a - номер объета
		call	ShipSetObject	; Установка объекта в слот по координатам другого объекта (Запуск кораблём
					;   противника объекта,	наследует координаты, СКО и скорость от	родителя)
					; Вх:  a - номер объекта
