; Вых: hl,de,bc,a - не определены

ReactionObject:				; CODE XREF: MoveAllObjects+16Bp
		ld	a, (iy+7)	; max энергия объекта
		ld	c, (ix+22h)	; текущая энергия
		inc	c
		cp	0F0h ; 'Ё'
		jr	c, loc_F741	; максимальная энергия >=#F0 текущая эн. +4
					; максимальная энергия <#F0  текущая эн. +1
		inc	c
		inc	c
		inc	c

loc_F741:				; CODE XREF: ReactionObject+9j
