					; =2 у asp невидимость выключена
					; =1 выдана 2й миссия
					; =0 при движении на J
		ld	a, b
		cp	50h ; 'P'
		ld	a, (hl)
		jr	c, loc_F759	; энергия <#50
		cp	2
		jr	nz, loc_F759
		dec	(hl)

