; Проверка нахождения объекта в	заданном радиусе от игрока
; Вх:  de - радиус
; Вых: cy =1  в	радиусе
;	  =0 за	пределами

TestObjInRadius:			; CODE XREF: DirectObject+14p
					; DirectObject+21p
		ld	h, (ix+1)
		ld	l, (ix+0)
		and	a
		sbc	hl, de
		ret	nc
		ld	h, (ix+4)
		ld	l, (ix+3)
		and	a
		sbc	hl, de
		ret	nc
		ld	h, (ix+7)
		ld	l, (ix+6)
		inc	d
		inc	d
		and	a
		sbc	hl, de
		ret
; End of function TestObjInRadius


