		call	HL_CrdNdiv4	; преобразование координаты без	изменения знака
					; вх:  ix - адрес координаты
					; вых: hl = CrdN / 4
					;      ix=ix+3
		ld	(deltaCrdZ), hl	; расстояние по	Z / 4
					; 7,=z знак
		pop	ix
		set	5, (ix+26h)
		jr	MoveObject1
; ---------------------------------------------------------------------------

MoveObjToPlayer:			; CODE XREF: DirectObject+3Cj
					; DirectObject+47j ...
		push	ix		; обработка попадания ракеты в игрока
		call	HL_CrdNdiv4_InvSign ; преобразование координаты	с изменением знака
					; вх:  ix - адрес координаты
					; вых: hl = -1 * CrdN /	4
					;      ix=ix+3
		ld	(deltaCrdX), hl	; расстояние по	X / 4
					; 7,=x знак
		call	HL_CrdNdiv4_InvSign ; преобразование координаты	с изменением знака
					; вх:  ix - адрес координаты
					; вых: hl = -1 * CrdN /	4
					;      ix=ix+3
		ld	(deltaCrdY), hl	; расстояние по	Y / 4
					; 7,=x знак
		call	HL_CrdNdiv4_InvSign ; преобразование координаты	с изменением знака
					; вх:  ix - адрес координаты
					; вых: hl = -1 * CrdN /	4
					;      ix=ix+3
		ld	(deltaCrdZ), hl	; расстояние по	Z / 4
					; 7,=z знак
		pop	ix
		res	5, (ix+26h)

MoveObject1:				; CODE XREF: DirectObject+67j
					; MoveMissile+7Fj
		jp	MoveObject	; Движение объекта. Установка углов поворота, ускорения, скорости и выстрел из
; End of function DirectObject		;    лазера
					; Вх:  ix - адрес слота	объекта
					;      iy - адрес данных объекта
					;      (deltaCrdX) - вектор относительно которого считаем
					; Вых: hl,de,bc,a - не определены

; =============== S U B	R O U T	I N E =======================================

; Обработка ракеты, движение попадание
; Вх:  ix - адрес слота	ракеты
; Вх:  ix - адрес слота	объекта
;      iy - адрес данных объекта
; Вых: hl,de,bc,a - не определены

MoveMissile:				; CODE XREF: MoveAllObjects+164p
		ld	a, (TimeWorkECM) ; оставшееся время работы системы
					; =0 ECM выключена
					;
		and	a
		jr	z, loc_F937	; Уничтожение цели ракетой
		res	6, (ix+20h)	; если ECM работает, ракету уничтожить
		set	4, (ix+20h)
		ret
; ---------------------------------------------------------------------------

loc_F937:				; CODE XREF: MoveMissile+4j
		ld	a, (ix+25h)	; Уничтожение цели ракетой
		and	a
		jr	z, MoveObjToPlayer ; обработка попадания ракеты	в игрока
		push	iy
		ld	iy, objCoriolis-27h ; длина 27h
		ld	de, 27h	; '''
		sub	0Ah
		cpl
		ld	b, a		; преобразование обратного номера

loc_F94A:				; CODE XREF: MoveMissile+24j
		add	iy, de
		djnz	loc_F94A
		push	ix
		push	iy		; ix адрес слота ракеты
					; iy адрес слота-цели ракеты
		call	loc_F9B2	; расстояние по	X
		ld	(deltaCrdX), hl	; расстояние по	X / 4
					; 7,=x знак
		call	loc_F9B2	; расстояние по	Y
		ld	(deltaCrdY), hl	; расстояние по	Y / 4
					; 7,=x знак
		call	loc_F9B2	; расстояние по	Z
		ld	(deltaCrdZ), hl	; расстояние по	Z / 4
					; 7,=z знак
		pop	iy
		pop	ix
		call	loc_F9AA	; проверка расстояния hl < 003F
					; вх:  hl - расстояние
					; вых: z=0 в радиусе
					;      z=1 далеко
		jr	nz, loc_F9A5	; далеко
		ld	hl, (deltaCrdY)	; расстояние по	Y / 4
					; 7,=x знак
		call	loc_F9AA	; проверка расстояния hl < 003F
					; вх:  hl - расстояние
					; вых: z=0 в радиусе
					;      z=1 далеко
		jr	nz, loc_F9A5	; далеко
		ld	hl, (deltaCrdX)	; расстояние по	X / 4
					; 7,=x знак
		call	loc_F9AA	; проверка расстояния hl < 003F
					; вх:  hl - расстояние
					; вых: z=0 в радиусе
					;      z=1 далеко
		jr	nz, loc_F9A5	; далеко
		bit	2, (iy+26h)
		jr	z, loc_F99A	; уничтожается ракетой
		ld	hl, PilotMission3 ; +92	>0 - выдана 3я миссия
					;  =1 при стыковке будет выдана	3я миссиия ( =1	пора выдавать миссию будет =2 после прыжка)
					;  =2 при стыковке будет выдана	3я миссиия
					;  =3 выдана 3я	миссия (можно уничтожить станцию ракетой) (из станции вылетают таргоны)
					;  =4 выдана 3я	миссия,	корабль	находится в системе с целью (можно уничтожить станцию ракетой) (из станции вылетают таргоны)
					;  =5 3я миссия	выполнена, будет поздравление при стыковке
					;
					;
					;  =4 корабль захватили	пираты,	(сообщить при стыковке)	будет =3 после прыжка
					; 3,=1 станция уничтожена
		ld	a, (hl)
		cp	4
		jr	nz, loc_F99E	; уничтожаем ракету
		set	3, (hl)
		dec	l
		xor	a
		ld	(hl), a
		ld	de, 0FFFFh
		call	IncBattleRating	; Увеличение боевого рейтинга
					; Вх:  de - приращение рейтинга
					; Вых: hl,de - не определены
		set	7, (iy+26h)

loc_F99A:				; CODE XREF: MoveMissile+59j
		set	4, (iy+20h)	; уничтожаем цель ракеты

loc_F99E:				; CODE XREF: MoveMissile+61j
		pop	iy		; уничтожаем ракету
		set	4, (ix+20h)
		ret
; ---------------------------------------------------------------------------

loc_F9A5:				; CODE XREF: MoveMissile+43j
					; MoveMissile+4Bj ...
		pop	iy
		jp	MoveObject1
; ---------------------------------------------------------------------------

loc_F9AA:				; CODE XREF: MoveMissile+40p
					; MoveMissile+48p ...
		add	hl, hl		; проверка расстояния hl < 003F
					; вх:  hl - расстояние
					; вых: z=0 в радиусе
					;      z=1 далеко
		ld	a, h
		and	a
		ret	nz
		ld	a, l
		and	0C0h ; '└'
		ret
; ---------------------------------------------------------------------------

loc_F9B2:				; CODE XREF: MoveMissile+2Ap
					; MoveMissile+30p ...
		ld	l, (iy+0)
		ld	h, (iy+1)
		ld	c, (iy+2)
		ld	e, (ix+0)
		ld	d, (ix+1)
		ld	b, (ix+2)
		sla	c
		rr	h
		rr	l
		sla	b
		rr	d
		rr	e
		call	CalcDeltaCrd	; Вычисление расстояния	по одной оси
					; Вх:  hl - координата X/Y/Z первого объекта (7,h знак)
					;      de - координата X/Y/Z второго объекта (7,d знак)
					; Вых: 7,h =1 координата первого объекта левее
					;	hl - расстояние	по заданной оси/2
					;      de,bc,a - не определены
		ld	de, 3
		add	ix, de
		add	iy, de
		ret
; End of function MoveMissile


; =============== S U B	R O U T	I N E =======================================

; преобразование координаты с изменением знака
; вх:  ix - адрес координаты
; вых: hl = -1 * CrdN /	4
;      ix=ix+3

HL_CrdNdiv4_InvSign:			; CODE XREF: DirectObject+6Bp
					; DirectObject+71p ...
		ld	a, (ix+2)
		xor	80h ; 'А'
		jr	loc_F9E5
; End of function HL_CrdNdiv4_InvSign


; =============== S U B	R O U T	I N E =======================================

; преобразование координаты без	изменения знака
; вх:  ix - адрес координаты
; вых: hl = CrdN / 4
;      ix=ix+3

HL_CrdNdiv4:				; CODE XREF: DirectObject+4Fp
					; DirectObject+55p ...
		ld	a, (ix+2)

loc_F9E5:				; CODE XREF: HL_CrdNdiv4_InvSign+5j
		ld	l, (ix+0)
		ld	h, (ix+1)
		srl	h
		rr	l
		rla
		rr	h
		rr	l
		ld	de, 3
		add	ix, de
		ret
; End of function HL_CrdNdiv4


; =============== S U B	R O U T	I N E =======================================

; Движение объекта. Установка углов поворота, ускорения, скорости и выстрел из
;    лазера
; Вх:  ix - адрес слота	объекта
;      iy - адрес данных объекта
;      (deltaCrdX) - вектор относительно которого считаем
; Вых: hl,de,bc,a - не определены

MoveObject:				; CODE XREF: DirectObject:MoveObject1j
		push	iy
		ld	iy, deltaCrdX	; расстояние по	X / 4
					; 7,=x знак
		push	ix
		ld	ix, deltaCrdX	; расстояние по	X / 4
					; 7,=x знак
		call	CalcLenVector	; Вычисление длины вектора и нормализация вектора
					; Вх:  ix - адрес длин вектора по каждой оси
					; Вых: de=sqrt(dX^2+dY^2+dZ^2) длина вектора
					;      (ix) - нормализованные координаты вектора
					;      a =#00
		pop	ix
		ld	(LenVector), de	; длина	вектора
		push	ix
		ld	de, 9
		add	ix, de		; ix+#09
		call	ScalarMultVectors ; Cкалярное произведение двух	векторов со сменой направления одного вектора
					; Вх:  ix - адрес начала вектора оси СКО
					;      iy - адрес начала координат второго вектора (нормализированного вектора)
					; Вых: a - результат
					;	7,a - новый знак
		ld	de, 6
		add	ix, de		; ix+#0F
		ld	h, a
		push	hl
		call	ScalarMultVectors ; Cкалярное произведение двух	векторов со сменой направления одного вектора
					; Вх:  ix - адрес начала вектора оси СКО
					;      iy - адрес начала координат второго вектора (нормализированного вектора)
					; Вых: a - результат
					;	7,a - новый знак
		pop	hl
		ld	l, a
		push	hl
		ld	de, 6
		add	ix, de		; ix+#15
		call	ScalarMultVectors ; Cкалярное произведение двух	векторов со сменой направления одного вектора
					; Вх:  ix - адрес начала вектора оси СКО
					;      iy - адрес начала координат второго вектора (нормализированного вектора)
					; Вых: a - результат
					;	7,a - новый знак
		pop	hl
		pop	ix
		pop	iy
		ld	d, a
		and	7Fh ; ''
		jr	z, loc_FA5A
		ld	c, a
		srl	c
		srl	c
		srl	c
		adc	a, c
		srl	a
		srl	a
		cp	0Fh
		jr	c, loc_FA4A
		ld	a, 0Fh

loc_FA4A:				; CODE XREF: MoveObject+4Cj
		ld	b, a
		ld	a, d
		xor	l
		and	80h ; 'А'
		rra
		or	b
		ld	(ix+1Dh), a
		and	3Fh ; '?'
		cp	4
		jr	nc, loc_FA78

loc_FA5A:				; CODE XREF: MoveObject+3Cj
		ld	a, h
		bit	7, a
		jr	z, loc_FA6E
		and	7Fh ; ''
		add	a, 50h ; 'P'
		srl	a
		cpl
		add	a, 68h ; 'h'
		srl	a
		cp	40h ; '@'
		jr	c, loc_FA70

loc_FA6E:				; CODE XREF: MoveObject+63j
		ld	a, 3Fh ; '?'

loc_FA70:				; CODE XREF: MoveObject+72j
		sla	l
		rra
		srl	a
		ld	(ix+1Eh), a

loc_FA78:				; CODE XREF: MoveObject+5Ej
		xor	a
		bit	7, (ix+25h)
		jr	z, loc_FA81
		ld	a, 2

loc_FA81:				; CODE XREF: MoveObject+83j
		ld	(ix+1Ch), a
		ret	nz
		ld	de, (LenVector)	; длина	вектора
		ld	a, d
		sla	h
		jr	nc, loc_FAF9
		ld	b, 0Ah
		bit	0, (ix+26h)
		jr	z, loc_FA98
		ld	b, 2

loc_FA98:				; CODE XREF: MoveObject+9Aj
		cp	b
		jr	c, loc_FAA5
		ld	b, 1
		cp	10h
		jr	nc, loc_FAA2
		inc	b

loc_FAA2:				; CODE XREF: MoveObject+A5j
		ld	(ix+1Ch), b

loc_FAA5:				; CODE XREF: MoveObject+9Fj
		bit	2, (ix+21h)
		ret	z
		ld	a, (ix+8)
		xor	(ix+0Eh)
		and	80h ; 'А'
		ret	z
		ld	b, (iy+2)
		ld	a, (PilotRating2) ; если еще не	было ни	одного RoC, делим пополам шанс
		and	a
		jr	nz, loc_FABE
		srl	b

loc_FABE:				; CODE XREF: MoveObject+C0j
		call	IntRnd_A2	; случайное число
					;  A - результат
		cp	b
		ret	nc
		ld	a, (ix+26h)
		and	0Fh
		ret	nz
		ld	a, d
		cp	0Ch
		ret	nc
		sla	h
		ret	nc
		set	3, (ix+20h)
		ld	a, d
		cp	4
		jr	c, loc_FADC
		sla	h
		ret	nc

loc_FADC:				; CODE XREF: MoveObject+DDj
		ld	hl, nBeepFX	; какой	звук надо включить
					; =#00 звуков нет(не звучат)
					;  0,=1	взорвана энерго	бомба
					;  1,=1	запущена ракета
					;  2,=1	врезаемся в объект/объект уничтожен
					;  3,=1	выстрел	из лазера
					;  4,=1	выстрелили из дазера
					;  5,=1	ECM работает
					;  6,=1	попадание из лазера по игроку/повреждения при стыковке
					;  7,=1
		set	6, (hl)
		bit	7, (ix+8)
		jr	z, loc_FAF0
		ld	a, (DamageRearShield) ;	урон задним щитам
		add	a, 7
		ld	(DamageRearShield), a ;	урон задним щитам
		ret
; ---------------------------------------------------------------------------

loc_FAF0:				; CODE XREF: MoveObject+EBj
		ld	a, (DamageFrontShield) ; урон передним щитам
		add	a, 7
		ld	(DamageFrontShield), a ; урон передним щитам
		ret
; ---------------------------------------------------------------------------

loc_FAF9:				; CODE XREF: MoveObject+92j
		ld	b, 0Bh
		bit	0, (ix+26h)
		jr	z, loc_FB03
		ld	b, 3

loc_FB03:				; CODE XREF: MoveObject+105j
		cp	b
		ret	c
		ld	b, 0FFh
		cp	12h
		jr	c, loc_FB0C
		dec	b

loc_FB0C:				; CODE XREF: MoveObject+10Fj
		ld	(ix+1Ch), b
		ret
; End of function MoveObject


; =============== S U B	R O U T	I N E =======================================

; Умножение hl = -1 * high((a*2) * (b*2))
; Вх:  b - первый множитель, 7,b - знак
;      a - второй множитель, 7,a - знак
; Вых: l,a = high((a*2)	* (b*2))
;	l,a = high((a*2) * (b*2))
;	7,h - знак

Mult_HL_A2_B2:				; CODE XREF: ScalarMultVectors+6p
					; ScalarMultVectors+10p ...
		ld	c, a
		xor	b
		xor	80h ; 'А'
		sla	b
		sla	c
		push	af
		call	Mult_A_hiB_C	; a=((b+c)/2)^2-((b-c)/2)^2
		pop	hl
		ld	l, a
		ret
; End of function Mult_HL_A2_B2


; =============== S U B	R O U T	I N E =======================================

; Cкалярное произведение двух векторов со сменой направления одного вектора
; Вх:  ix - адрес начала вектора оси СКО
;      iy - адрес начала координат второго вектора (нормализированного вектора)
; Вых: a - результат
;	7,a - новый знак

ScalarMultVectors:			; CODE XREF: CorrAxirY_SKO+Fp
					; MoveObject+1Cp ...
		ld	b, (ix+1)
		ld	a, (iy+1)
		call	Mult_HL_A2_B2	; (crdXv/2) * (cos(a)/2)
		push	hl
		ld	b, (ix+3)
		ld	a, (iy+3)
		call	Mult_HL_A2_B2	; Умножение hl = -1 * high((a*2) * (b*2))
					; Вх:  b - первый множитель, 7,b - знак
					;      a - второй множитель, 7,a - знак
					; Вых: l,a = high((a*2)	* (b*2))
					;	l,a = high((a*2) * (b*2))
					;	7,h - знак
		push	hl
		ld	b, (ix+5)
		ld	a, (iy+5)
		call	Mult_HL_A2_B2	; Умножение hl = -1 * high((a*2) * (b*2))
					; Вх:  b - первый множитель, 7,b - знак
					;      a - второй множитель, 7,a - знак
					; Вых: l,a = high((a*2)	* (b*2))
					;	l,a = high((a*2) * (b*2))
					;	7,h - знак
		pop	de
		call	AddSign_L_E	; Сложение с учётом знака
					; Вх:  hl - первое слагаемое #00..#FF (7,h знак)
					;      de - второе слагаемое #00..#FF (7,d знак)
					; Вых: a - сумма
					;      7,h - знак
					;      cy =1 переполнение суммы
		jr	nc, loc_FB44
		ld	a, 0FFh

loc_FB44:				; CODE XREF: ScalarMultVectors+21j
		pop	de
		ld	l, a
		call	AddSign_L_E	; Сложение с учётом знака
					; Вх:  hl - первое слагаемое #00..#FF (7,h знак)
					;      de - второе слагаемое #00..#FF (7,d знак)
					; Вых: a - сумма
					;      7,h - знак
					;      cy =1 переполнение суммы
		jr	nc, loc_FB4D
		ld	a, 0FFh

loc_FB4D:				; CODE XREF: ScalarMultVectors+2Aj
		rl	h
		rra
		ret
; End of function ScalarMultVectors

