ScanKeysSymbols:db 20h,	0Dh, 50h, 30h, 31h, 51h, 41h, 0	; DATA XREF: SetBitControlKey+Do
		db 1, 4Ch, 4Fh,	39h, 32h, 57h, 53h, 5Ah	; таблица символов клавиш
		db 4Dh,	4Bh, 49h, 38h, 33h, 45h, 44h, 58h
		db 4Eh,	4Ah, 55h, 37h, 34h, 52h, 46h, 43h
		db 42h,	48h, 59h, 36h, 35h, 54h, 47h, 56h

; =============== S U B	R O U T	I N E =======================================

; опрос	клавиатуры

ScanKeys:				; CODE XREF: Interrupts+10p
		xor	a
		ld	(byte_FC15), a	; что-то связанное с cursor и sinclair joy
