ScanKeysContinue:			; CODE XREF: ScanKeys+1Ej
		dec	d
		jp	nz, loc_FB86
		ld	a, (ControlKeyMove) ; 7,=1 -	     --	не используется
					; 6,=1 -	 -- не используется
					; 5,=1 - SymbolS -- Decrease Speed
					; 4,=1 - Space	 -- Increase Speed
					; 3,=1 - S	 -- Up
					; 2,=1 - X	 -- Down
					; 1,=1 - M	 -- Right
					; 0,=1 - N	 -- Left
		and	1111b
		ld	d, a
		ld	a, (FlagsSetUp)	; 0-1,=00 управление SXNMA (LLFC0F)<>0 сброс CS,F,c
					;     =01 управление от	Kempston'а
					;     =10 управление от	курсора	76850
					;     =11 управление от	Sinclair right
					;   2,=1  управление приближено	к реальному (reaction)
					;   3,=1  вкл. инерционность поворота
					;   4,=1  управление инвертировано
					;   5,=1  вверх/вниз инвертировано
					;   6,=1  вкл. перехват	таргонов
					;   7,=1  звук включен
		ld	e, a
		and	11b
		jr	z, loc_FC69
		dec	a
		jr	nz, loc_FC43
		ld	bc, 0FF1Fh
		in	a, (c)
		bit	4, a
		jr	z, loc_FC39
		ld	hl, ControlKey3	; 7,=1 - C     -- Docking Computer
					; 6,=1 - Q     -- Escape Pod
					; 5,=1 - W     -- Energy Bomb
					; 4,=1 - E     -- ECM System
					; 3,=1 - U     -- UnTarget
					; 2,=1 - F     -- Fire Missile
					; 1,=1 - T     -- Target Missile
					; 0,=1 - A     -- Fure Laser
		set	0, (hl)

