; End of function ScanKeysContinue


; =============== S U B	R O U T	I N E =======================================

; Установка нажатой клавиши по таблице
; вх:  d - номер полуряда
;      e - обратный номер клавиши в полуряде
; вых: (PressKeyPrnSymbol) - символ нажатой клавиши
;      (ControlKeys) - установлен соответствующий бит

SetBitControlKey:			; CODE XREF: ScanKeys+18p
		push	bc
		push	af
		ld	a, 5
		sub	e
		add	a, a
		add	a, a
		add	a, a
		add	a, d
		dec	a
		ld	b, a
		sla	b
		ld	hl, ScanKeysSymbols ; таблица символов клавиш
		add	a, l
		jr	nc, loc_FCD4
		inc	h

loc_FCD4:				; CODE XREF: SetBitControlKey+11j
		ld	l, a
		ld	a, (hl)
		ld	(PressKeyPrnSymbol), a ; Печатный символ нажатой клавиши
					;  =#FE	- BackSpace
					;  =#FF	- ничего не нажато
		ld	hl, TablBitPressKey ; таблица соответствий кодов клавиш	битам
					;   +0 номер байта в списке клавиш управления
					;   +1 бит нажатой клавиши
		ld	a, l
		add	a, b
		ld	l, a
		ld	a, (hl)
		inc	hl
		ld	b, (hl)
		ld	hl, ControlKey1	; 7,=1 - Y	 -- Cloaking Device
					; 6,=1 - 0	 -- ???
					; 5,=1 - I	 -- Global Map
					; 4,=1 - O	 -- Local Map
					; 3,=1 - P	 -- Planet Info
					; 2,=1 - K	 -- Planet Price
					; 1,=1 - L	 -- Commander Info
					; 0,=1 - Enter	 -- Inventory
		add	a, l
		ld	l, a
		ld	a, (hl)
		or	b
		ld	(hl), a
		pop	af
		pop	bc
		ret
; End of function SetBitControlKey

