; =============== S U B	R O U T	I N E =======================================

; Обработка нажатия клавиш управления: повороты	и скорость
; Вх:  ----
; Вых: (AngleLeftRight), (AngleUpDown) новые углы поворота
;      (DeltaSpeed) новая скорость

KeyCtrl_Move:				; CODE XREF: Interrupts+13p
		ld	a, (WhatOnScreen) ; Что	изображено на экране
					;  =0..3 в полете номер	обзорного экрана (front, rear, left, right)
					;  =#04	меню покупки товаров
					;  =#05	меню продажи товаров
					;  =#06	меню покупки оборудования
					;  =#07	глобальная карта
					;  =#08	локальная карта
					;  =#09	инфо о планете еще не выведено
					;  =#0A	прайс планеты
					;  =#0B	инфо о пилоте
					;  =#0C	Инвентрь
					;  =#20	инфо о планете
		cp	4
		ret	nc
		ld	a, (ControlKeyMove) ; 7,=1 -	     --	не используется
					; 6,=1 -	 -- не используется
					; 5,=1 - SymbolS -- Decrease Speed
					; 4,=1 - Space	 -- Increase Speed
					; 3,=1 - S	 -- Up
					; 2,=1 - X	 -- Down
					; 1,=1 - M	 -- Right
					; 0,=1 - N	 -- Left
		ld	b, a
		ld	a, (FlagsSetUp)	; 0-1,=00 управление SXNMA (LLFC0F)<>0 сброс CS,F,c
					;     =01 управление от	Kempston'а
					;     =10 управление от	курсора	76850
					;     =11 управление от	Sinclair right
					;   2,=1  управление приближено	к реальному (reaction)
					;   3,=1  вкл. инерционность поворота
					;   4,=1  управление инвертировано
					;   5,=1  вверх/вниз инвертировано
					;   6,=1  вкл. перехват	таргонов
					;   7,=1  звук включен
		ld	c, a
		ld	hl, (AngleLeftRight) ; угол поворота
					; 7,n знак (лево/право)
					; #0000..#0FFF
		bit	0, b
		jr	nz, loc_FE41
		bit	1, b
		jr	nz, loc_FE2E
		bit	3, c
		jr	z, loc_FE7A
		ld	de, 3Ch	; '<'
		and	a
		sbc	hl, de
		bit	6, h
		jr	z, loc_FE7A
		ld	hl, 0
		jp	loc_FE7A
; ---------------------------------------------------------------------------

loc_FE2E:				; CODE XREF: KeyCtrl_Move+17j
		ld	a, h
		and	7Fh ; ''
		or	l
		jr	nz, loc_FE3A
		ld	hl, 0FFh
		jp	loc_FE7A
; ---------------------------------------------------------------------------

loc_FE3A:				; CODE XREF: KeyCtrl_Move+31j
		bit	7, h
		jr	z, loc_FE55
		jp	loc_FE63
; ---------------------------------------------------------------------------

loc_FE41:				; CODE XREF: KeyCtrl_Move+13j
		bit	1, b
		jr	nz, loc_FE7A
		ld	a, h
		and	7Fh ; ''
		or	l
		jr	nz, loc_FE51
		ld	hl, 80FFh
		jp	loc_FE7A
; ---------------------------------------------------------------------------

loc_FE51:				; CODE XREF: KeyCtrl_Move+48j
		bit	7, h
		jr	z, loc_FE63

loc_FE55:				; CODE XREF: KeyCtrl_Move+3Bj
		ld	de, 0FFh
		add	hl, de
		bit	4, h
		jr	z, loc_FE7A
		and	a
		sbc	hl, de
		jp	loc_FE7A
; ---------------------------------------------------------------------------

loc_FE63:				; CODE XREF: KeyCtrl_Move+3Dj
					; KeyCtrl_Move+52j
		bit	2, c
		jr	z, loc_FE6D
		ld	hl, 0
		jp	loc_FE7A
; ---------------------------------------------------------------------------

loc_FE6D:				; CODE XREF: KeyCtrl_Move+64j
		ld	de, 0FFh
		and	a
		sbc	hl, de
		bit	6, h
		jr	z, loc_FE7A
		ld	hl, 0

loc_FE7A:				; CODE XREF: KeyCtrl_Move+1Bj
					; KeyCtrl_Move+25j ...
		ld	(AngleLeftRight), hl ; угол поворота
					; 7,n знак (лево/право)
					; #0000..#0FFF
		ld	hl, (AngleUpDown) ; угол поворота вверх/вниз
		bit	2, b
		jr	nz, loc_FEAF
		bit	3, b
		jr	nz, loc_FE9C
		bit	3, c
		jr	z, loc_FEE8
		ld	de, 24h	; '$'
		and	a
		sbc	hl, de
		bit	6, h
		jr	z, loc_FEE8
		ld	hl, 0
		jp	loc_FEE8
; ---------------------------------------------------------------------------

loc_FE9C:				; CODE XREF: KeyCtrl_Move+85j
		ld	a, h
		and	7Fh ; ''
		or	l
		jr	nz, loc_FEA8
		ld	hl, 66h	; 'f'
		jp	loc_FEE8
; ---------------------------------------------------------------------------

loc_FEA8:				; CODE XREF: KeyCtrl_Move+9Fj
		bit	7, h
		jr	z, loc_FEC3
		jp	loc_FED1
; ---------------------------------------------------------------------------

loc_FEAF:				; CODE XREF: KeyCtrl_Move+81j
		bit	3, b
		jr	nz, loc_FEE8
		ld	a, h
		and	7Fh ; ''
		or	l
		jr	nz, loc_FEBF
		ld	hl, 8066h
		jp	loc_FEE8
; ---------------------------------------------------------------------------

loc_FEBF:				; CODE XREF: KeyCtrl_Move+B6j
		bit	7, h
		jr	z, loc_FED1

loc_FEC3:				; CODE XREF: KeyCtrl_Move+A9j
		ld	de, 66h	; 'f'
		add	hl, de
		bit	4, h
		jr	z, loc_FEE8
		and	a
		sbc	hl, de
		jp	loc_FEE8
; ---------------------------------------------------------------------------

loc_FED1:				; CODE XREF: KeyCtrl_Move+ABj
					; KeyCtrl_Move+C0j
		bit	2, c
		jr	z, loc_FEDB
		ld	hl, 0
		jp	loc_FEE8
; ---------------------------------------------------------------------------

loc_FEDB:				; CODE XREF: KeyCtrl_Move+D2j
		ld	de, 66h	; 'f'
		and	a
		sbc	hl, de
		bit	6, h
		jr	z, loc_FEE8
		ld	hl, 0

loc_FEE8:				; CODE XREF: KeyCtrl_Move+89j
					; KeyCtrl_Move+93j ...
		ld	(AngleUpDown), hl ; угол поворота
					; 7,n знак (лево/право)
					; #0000..#0FFF
		ld	hl, (DeltaSpeed) ; изменение скорости
		ld	de, 0A0h ; 'а'
		bit	4, b
		jr	nz, loc_FF00
		bit	5, b
		jr	z, loc_FF1D
		and	a
		sbc	hl, de
		jr	KeyCtrl_Move_2
; ---------------------------------------------------------------------------
		jr	Interrupts	; обработка прерываний
; ---------------------------------------------------------------------------

loc_FF00:				; CODE XREF: KeyCtrl_Move+F2j
		bit	5, b
		jr	nz, loc_FF1D
		add	hl, de
		jp	loc_FF16
; ---------------------------------------------------------------------------
AngleLeftRight:	dw 0			; DATA XREF: InitSpeedAngle+2o
					; KeyCtrl_Move+Er ...
					; угол поворота
					; 7,n знак (лево/право)
					; #0000..#0FFF
AngleUpDown:	dw 0			; DATA XREF: KeyCtrl_Move+7Cr
					; KeyCtrl_Move:loc_FEE8w
					; угол поворота
					; 7,n знак (лево/право)
					; #0000..#0FFF
DeltaSpeed:	dw 0			; DATA XREF: UseEscapePod+25w
					; KeyCtrl_Move+EAr ...
					; скорость
					; #0000..#1FFF
; ---------------------------------------------------------------------------

KeyCtrl_Move_2:				; CODE XREF: KeyCtrl_Move+FBj
		jr	nc, loc_FF1D
		ld	hl, 0
		jp	loc_FF1D
; ---------------------------------------------------------------------------

loc_FF16:				; CODE XREF: KeyCtrl_Move+104j
		bit	5, h
		jr	z, loc_FF1D
		and	a
		sbc	hl, de

loc_FF1D:				; CODE XREF: KeyCtrl_Move+F6j
					; KeyCtrl_Move+101j ...
		ld	(DeltaSpeed), hl ; скорость
					; #0000..#1FFF
		xor	a
		ld	(ControlKeyMove), a ; 7,=1 -	     --	не используется
					; 6,=1 -	 -- не используется
					; 5,=1 - SymbolS -- Decrease Speed
					; 4,=1 - Space	 -- Increase Speed
					; 3,=1 - S	 -- Up
					; 2,=1 - X	 -- Down
					; 1,=1 - M	 -- Right
					; 0,=1 - N	 -- Left
		ret
; End of function KeyCtrl_Move


; =============== S U B	R O U T	I N E =======================================


Interrupts:				; CODE XREF: KeyCtrl_Move+FDj
		di
		ld	(SaveSP1), sp
		ld	sp, 0FFBFh
		push	hl
		push	de
		push	bc
		push	af
		push	ix
		push	iy
		call	ScanKeys	; опрос	клавиатуры
		call	KeyCtrl_Move	; Обработка нажатия клавиш управления: повороты	и скорость
					; Вх:  ----
					; Вых: (AngleLeftRight), (AngleUpDown) новые углы поворота
					;      (DeltaSpeed) новая скорость
		call	sub_9082	; вывод	звука
		pop	iy
		pop	ix
		pop	af
		pop	bc
		pop	de
		pop	hl
		ld	sp, (SaveSP1)
		ei
		ret
; End of function Interrupts


; =============== S U B	R O U T	I N E =======================================


Interrupts_ON:				; CODE XREF: BeginGame+16p
		ld	a, 0FDh	; '¤'
		ld	i, a
		im	2
		ret
; End of function Interrupts_ON


; =============== S U B	R O U T	I N E =======================================


IM1_ON:
		im	1
		ret
